# --- Helper Functions ---
def calculate_expected_work_days(
    work_days_json: str, 
    start_date: datetime, 
    end_date: datetime,
    vacation_start: Optional[datetime] = None,
    vacation_end: Optional[datetime] = None
) -> int:
    """
    Calcula quantos dias o colaborador deveria trabalhar baseado na escala,
    descontando dias de férias se houver sobreposição.
    
    Args:
        work_days_json: JSON string com dias da semana
        start_date: Data inicial do período
        end_date: Data final do período (exclusiva, geralmente)
        vacation_start: Início das férias
        vacation_end: Fim das férias
    
    Returns:
        Número de dias esperados de trabalho
    """
    # Default fallback: Segunda a Sábado (6 dias)
    default_work_days = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"]
    
    try:
        if work_days_json and work_days_json.strip():
            work_days = json.loads(work_days_json)
            if not work_days:  # Empty list
                work_days = default_work_days
        else:
            work_days = default_work_days
    except (json.JSONDecodeError, TypeError):
        work_days = default_work_days
    
    # Mapeamento de dias da semana (weekday() retorna 0=Monday, 6=Sunday)
    day_map = {
        "Monday": 0,
        "Tuesday": 1,
        "Wednesday": 2,
        "Thursday": 3,
        "Friday": 4,
        "Saturday": 5,
        "Sunday": 6
    }
    
    # Converter work_days para números
    work_day_numbers = {day_map[day] for day in work_days if day in day_map}
    
    # Contar dias no período
    expected_days = 0
    current_date = start_date
    
    # Normalize vacation dates per day comparison (ignoring time)
    v_start_date = vacation_start.date() if vacation_start else None
    v_end_date = vacation_end.date() if vacation_end else None
    
    while current_date < end_date:
        # Check Vacation
        is_vacation = False
        if v_start_date and v_end_date:
            curr_d = current_date.date()
            if v_start_date <= curr_d <= v_end_date:
                is_vacation = True
        
        # Só conta se for dia de trabalho E não estiver de férias
        if not is_vacation and current_date.weekday() in work_day_numbers:
            expected_days += 1
        current_date += timedelta(days=1)
    
    return expected_days


# --- Shift Date Helpers ---
def _get_reference_datetime(reference: Optional[datetime] = None) -> datetime:
    tz = ZoneInfo("America/Sao_Paulo")
    if reference:
        return reference.astimezone(tz)
    return datetime.now(tz)


def _env_flag(name: str) -> bool:
    return os.getenv(name, "").strip().lower() in {"1", "true", "yes", "on"}


def _env_matches(name: str, *values: str) -> bool:
    current = os.getenv(name, "").strip().lower()
    return current in {value.strip().lower() for value in values}


def _format_hhmm_sao_paulo(value: Optional[datetime], expected_date: Optional[str] = None) -> Optional[str]:
    """
    Formata datetime para HH:MM no fuso America/Sao_Paulo.
    Para registros legados sem timezone, tenta inferir se o valor estava em UTC.
    """
    if not isinstance(value, datetime):
        return None
    tz_sp = ZoneInfo("America/Sao_Paulo")
    try:
        if value.tzinfo:
            return value.astimezone(tz_sp).strftime("%H:%M")

        # Registros antigos podem ter sido salvos sem tz. Testa dois cenários:
        # 1) naive já era horário local; 2) naive era UTC e precisa converter.
        local_dt = value.replace(tzinfo=tz_sp)
        utc_dt = value.replace(tzinfo=ZoneInfo("UTC")).astimezone(tz_sp)

        if expected_date:
            local_date = local_dt.strftime("%Y-%m-%d")
            utc_date = utc_dt.strftime("%Y-%m-%d")
            if utc_date == expected_date and local_date != expected_date:
                return utc_dt.strftime("%H:%M")
            if local_date == expected_date and utc_date != expected_date:
                return local_dt.strftime("%H:%M")

        now_sp = datetime.now(tz_sp)
        chosen = utc_dt if abs((utc_dt - now_sp).total_seconds()) < abs((local_dt - now_sp).total_seconds()) else local_dt
        return chosen.strftime("%H:%M")
    except Exception:
        try:
            return value.strftime("%H:%M")
        except Exception:
            return None


def _auto_close_stale_delivery_sessions() -> int:
    """
    Fecha automaticamente sessões de entrega abertas em dias anteriores ao dia atual (SP),
    marcando paradas pendentes como devolução automática.
    Retorna a quantidade de sessões fechadas.
    """
    tz_sp = ZoneInfo("America/Sao_Paulo")
    now_sp = datetime.now(tz_sp)
    today_str = now_sp.strftime("%Y-%m-%d")
    week_ago_str = (now_sp.date() - timedelta(days=7)).strftime("%Y-%m-%d")
    closed_count = 0

    with Session(engine) as session:
        stale_sessions = session.exec(
            select(models.DeliverySession)
            .where(models.DeliverySession.status == "open")
            .where(models.DeliverySession.date >= week_ago_str)
            .where(models.DeliverySession.date < today_str)
            .order_by(desc(models.DeliverySession.date), desc(models.DeliverySession.id))
        ).all()

        if not stale_sessions:
            return 0

        for ds_old in stale_sessions:
            pending_routes = session.exec(
                select(models.Route)
                .where(models.Route.type == "delivery")
                .where(models.Route.employee_id == ds_old.employee_id)
                .where(models.Route.date == ds_old.date)
                .where(models.Route.delivery_status.in_(["pendente", "iniciada", "reaberta"]))
            ).all()

            for r in pending_routes:
                # Regra de ouro: sem devolução registrada = entregue (concluída)
                r.delivery_status = "entregue"
                r.delivery_finished_at = now_sp.strftime("%H:%M") if now_sp else None
                r.delivery_returned_at = None
                r.delivery_return_reason = None
                r.delivery_return_photo_url = None
                r.delivery_return_category = None
                r.valor_devolucao = None
                r.devolucao_volume = None
                session.add(r)

            ds_old.status = "closed"
            ds_old.ended_at = now_sp
            if ds_old.km_return is None and ds_old.km_departure is not None:
                ds_old.km_return = ds_old.km_departure
            session.add(ds_old)
            closed_count += 1

        session.commit()

    return closed_count


async def _auto_close_stale_delivery_sessions_loop():
    """
    Loop de manutenção: roda em background e garante fechamento automático
    contínuo de sessões antigas, independentemente de usuário abrir o app.
    """
    while True:
        try:
            closed = _auto_close_stale_delivery_sessions()
            if closed > 0:
                logger.info(f"[DeliveryAutoClose] Sessões antigas fechadas automaticamente: {closed}")
        except Exception as e:
            logger.error(f"[DeliveryAutoClose] Falha no fechamento automático: {e}")
        await asyncio.sleep(300)  # 5 min


def get_effective_shift_date(shift: str, reference: Optional[datetime] = None) -> date:
    ref = _get_reference_datetime(reference)
    if (shift or "").strip().lower() == "noite":
        if ref.hour >= 18:
            return ref.date()
        if ref.hour < 6:
            return (ref - timedelta(days=1)).date()
    return ref.date()


def normalize_shift_date(date_str: Optional[str], shift: str, reference: Optional[datetime] = None) -> Optional[str]:
    if not date_str:
        return date_str
    if (shift or "").strip().lower() != "noite":
        return date_str

    ref = _get_reference_datetime(reference)
    if not (0 <= ref.hour < 6):
        return date_str

    try:
        provided = datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError:
        return date_str

    if provided == ref.date():
        return (ref - timedelta(days=1)).date().strftime("%Y-%m-%d")

    return date_str


def normalize_shift(value: Optional[str]) -> str:
    """Normalize shift labels (ex.: Manha/Manhã -> manha)."""
    if not value:
        return ""
    normalized = unicodedata.normalize("NFD", str(value))
    cleaned = "".join(ch for ch in normalized if not unicodedata.combining(ch))
    # Remove caracteres residuais de encoding quebrado (ex.: Manhã/ManhĂŁ)
    alnum_only = "".join(ch for ch in cleaned.lower().strip() if "a" <= ch <= "z")
    return alnum_only


def shift_display_label(normalized: str) -> str:
    """Retorna rótulo em português para exibição (evita duplicatas e encoding)."""
    if not normalized:
        return "Outro"
    n = normalized.strip().lower()
    if n.startswith("manha"):
        return "Manhã"
    if n.startswith("tard"):
        return "Tarde"
    if n.startswith("noit"):
        return "Noite"
    return normalized.strip().title() if normalized else "Outro"


def delivery_route_matches_leader_shift(
    route: Any,
    shift_norm: str,
    employee_by_id: Dict[int, Any],
) -> bool:
    """Rota de entrega no painel do líder: bate pelo shift da rota ou, se vazio, pelo work_shift do motorista."""
    rs = normalize_shift(getattr(route, "shift", None))
    if rs == shift_norm:
        return True
    eid = getattr(route, "employee_id", None)
    if not rs and eid:
        emp = employee_by_id.get(int(eid))
        if emp and normalize_shift(getattr(emp, "work_shift", None)) == shift_norm:
            return True
    return False


def _load_employee_name_maps(
    session: Session,
    include_fired: bool = True,
) -> tuple[Dict[int, str], Dict[str, int]]:
    """Retorna mapas leves de colaboradores para evitar carregar modelos completos quando só id/nome bastam."""
    query = select(models.Employee.id, models.Employee.name)
    if not include_fired:
        query = query.where(models.Employee.status != "fired")

    id_to_name: Dict[int, str] = {}
    name_to_id: Dict[str, int] = {}
    for employee_id, employee_name in session.exec(query).all():
        if employee_id is None:
            continue
        emp_id = int(employee_id)
        clean_name = str(employee_name or "").strip()
        id_to_name[emp_id] = clean_name
        if clean_name:
            name_to_id[clean_name.lower()] = emp_id
    return id_to_name, name_to_id


