def _db_readiness_gate_prefers_html(request: Request) -> bool:
    """Navegador em páginas normais: HTML 503 com auto-retry; APIs / fetch JSON continuam com JSON."""
    if request.method != "GET":
        return False
    path = request.url.path or ""
    if path.startswith("/api/"):
        return False
    accept = (request.headers.get("accept") or "").lower()
    return "text/html" in accept


def _db_startup_failed_response(request: Request) -> JSONResponse | HTMLResponse:
    """Após timeout ou exceção no startup: mensagem explícita (não o texto genérico de 'inicializando')."""
    payload = {
        "detail": (
            "Não foi possível preparar a base de dados. No Render, confira DATABASE_URL, "
            "se o Postgres permite conexões externas e os logs do serviço. "
            "Variável opcional: STARTUP_DB_TIMEOUT (segundos, padrão 120)."
        )
    }
    if _db_readiness_gate_prefers_html(request):
        body = """<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Erro na base de dados</title>
  <style>
    body { font-family: system-ui, sans-serif; margin: 0; min-height: 100dvh; display: flex; align-items: center; justify-content: center;
      background: #1c1917; color: #e7e5e4; padding: 1.5rem; text-align: center; }
    .box { max-width: 26rem; }
    h1 { font-size: 1.1rem; font-weight: 600; margin: 0 0 0.75rem; color: #fecaca; }
    p { margin: 0; font-size: 0.9rem; line-height: 1.55; color: #a8a29e; }
    code { font-size: 0.78rem; color: #d6d3d1; }
  </style>
</head>
<body>
  <div class="box">
    <h1>Falha ao ligar à base de dados</h1>
    <p>O arranque (migrações ou <code>create_all</code>) falhou ou excedeu o tempo limite. Isto não é “aguarde mais um pouco”: é preciso corrigir a configuração.</p>
    <p style="margin-top:1rem">No painel Render: <strong>DATABASE_URL</strong>, região do Postgres, SSL e firewall. Depois veja os <strong>logs</strong> do Web Service.</p>
  </div>
</body>
</html>"""
        return HTMLResponse(status_code=503, content=body)
    return JSONResponse(status_code=503, content=payload)


@app.middleware("http")
async def db_readiness_gate(request: Request, call_next):
    if _path_bypasses_db_readiness(request.url.path):
        return await call_next(request)
    if getattr(request.app.state, "db_startup_failed", False):
        return _db_startup_failed_response(request)
    if getattr(request.app.state, "db_ready", True) is not False:
        return await call_next(request)
    # Raiz: 200 em vez de 503 — evita ruído no DevTools e nos logs do Render para GET /.
    # Não exigir "text/html" no Accept: health checks / proxies às vezes enviam */* ou cabeçalho mínimo.
    if request.method == "GET" and (request.url.path or "") == "/":
        accept_root = (request.headers.get("accept") or "").lower()
        json_only_root = "application/json" in accept_root and "text/html" not in accept_root
        if not json_only_root:
            body = """<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta http-equiv="refresh" content="3; url=/">
  <title>A iniciar…</title>
  <style>
    body { font-family: system-ui, sans-serif; margin: 0; min-height: 100dvh; display: flex; align-items: center; justify-content: center;
      background: #0f172a; color: #e2e8f0; padding: 1.5rem; text-align: center; }
    .box { max-width: 22rem; }
    h1 { font-size: 1.1rem; font-weight: 600; margin: 0 0 0.75rem; color: #f8fafc; }
    p { margin: 0; font-size: 0.9rem; line-height: 1.5; color: #94a3b8; }
    .hint { margin-top: 1rem; font-size: 0.75rem; color: #64748b; }
  </style>
</head>
<body>
  <div class="box">
    <h1>Serviço a iniciar</h1>
    <p>A base de dados e as migrações estão a ficar prontas. Quando terminar, esta página passa a redirecionar para o painel.</p>
    <p class="hint">Atualização automática a cada 3 segundos. Pode usar F5.</p>
  </div>
</body>
</html>"""
            return HTMLResponse(status_code=200, content=body)
    if _db_readiness_gate_prefers_html(request):
        body = """<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta http-equiv="refresh" content="4">
  <title>Inicializando…</title>
  <style>
    body { font-family: system-ui, sans-serif; margin: 0; min-height: 100dvh; display: flex; align-items: center; justify-content: center;
      background: #0f172a; color: #e2e8f0; padding: 1.5rem; text-align: center; }
    .box { max-width: 22rem; }
    h1 { font-size: 1.1rem; font-weight: 600; margin: 0 0 0.75rem; color: #f8fafc; }
    p { margin: 0; font-size: 0.9rem; line-height: 1.5; color: #94a3b8; }
    .hint { margin-top: 1rem; font-size: 0.75rem; color: #64748b; }
  </style>
</head>
<body>
  <div class="box">
    <h1>Serviço a iniciar</h1>
    <p>O servidor acabou de acordar (por exemplo após inatividade no alojamento). A base de dados e as migrações estão a ficar prontas.</p>
    <p class="hint">Esta página atualiza automaticamente em poucos segundos. Pode também atualizar manualmente (F5).</p>
  </div>
</body>
</html>"""
        return HTMLResponse(
            status_code=503,
            content=body,
            headers={"Retry-After": "4"},
        )
    return JSONResponse(
        status_code=503,
        content={"detail": "Serviço inicializando; tente novamente em instantes."},
        headers={"Retry-After": "2"},
    )


# --- Middleware: Anti-Cache (Force Fresh Data) ---
@app.middleware("http")
async def add_no_cache_header(request: Request, call_next):
    response = await call_next(request)
    # Apply to API and Smart Flow HTML pages to prevent "stale" state
    if (
        request.url.path.startswith("/api/")
        or request.url.path.startswith("/smart-flow")
        or request.url.path.startswith("/lider")
        or request.url.path.startswith("/routine/report")
        or request.url.path.startswith("/mobile")
        or request.url.path.startswith("/portaria")
    ):
        response.headers["Cache-Control"] = "no-cache, no-store, must-revalidate"
        response.headers["Pragma"] = "no-cache"
        response.headers["Expires"] = "0"
    content_type = response.headers.get("content-type")
    media_type = (content_type or response.media_type or "").lower()
    if ("text/html" in media_type or "application/json" in media_type or "text/plain" in media_type) and "charset=" not in (content_type or ""):
        base = (content_type or response.media_type or "text/html").split(";")[0].strip()
        response.headers["Content-Type"] = f"{base}; charset=utf-8"
    return response

# --- Global Exception Handler ---
@app.middleware("http")
async def global_exception_handler(request: Request, call_next):
    try:
        response = await call_next(request)
        return response
    except Exception as e:
        # HTTPException não pode ser re-lançada aqui: o ASGI pode transformar em 500.
        # Usar o handler oficial (303 com Location, 404, etc.).
        from starlette.exceptions import HTTPException as StarletteHTTPException
        if isinstance(e, StarletteHTTPException):
            from fastapi.exception_handlers import http_exception_handler
            return await http_exception_handler(request, e)

        # Banco indisponível (offline, DNS, Render pausado) → 503 em vez de 500
        oe = e if isinstance(e, OperationalError) else (e.__cause__ if hasattr(e, "__cause__") and e.__cause__ else None)
        if isinstance(e, OperationalError) or (oe and type(oe).__name__ == "OperationalError"):
            err_str = str(oe or e).lower()
            if "could not translate host" in err_str or "connection refused" in err_str or "timeout" in err_str or "name or service not known" in err_str:
                logger.warning("DB indisponível [503]: %s", str(e)[:200])
                if "application/json" in request.headers.get("accept", "") or request.url.path.startswith("/api/"):
                    return JSONResponse(
                        status_code=503,
                        content={"error": "Banco de dados indisponível. Verifique sua conexão ou aguarde o banco inicializar."}
                    )
                return JSONResponse(
                    status_code=503,
                    content="Banco de dados indisponível. Verifique sua conexão.",
                    media_type="text/plain"
                )

        import traceback
        import uuid

        trace_id = str(uuid.uuid4())[:8]
        error_msg = str(e)
        stack_trace = traceback.format_exc()

        # Log Full Trace (Removed emoji to prevent UnicodeEncodeError on Windows)
        logger.error(f"[500] {request.method} {request.url} | Trace: {trace_id} | Error: {error_msg}\n{stack_trace}")

        # Determine Response Type
        accept = request.headers.get("accept", "")

        if "application/json" in accept or request.url.path.startswith("/api/"):
            return JSONResponse(
                status_code=500,
                content={
                    "error": "Erro Interno do Servidor",
                    "detail": error_msg if LOG_LEVEL == logging.DEBUG else "Contate o suporte.",
                    "trace_id": trace_id
                }
            )

        return templates.TemplateResponse("error_500.html", {
            "request": request,
            "error_detail": error_msg if LOG_LEVEL == logging.DEBUG else None,
            "trace_id": trace_id
        }, status_code=500)

# --- Informativo: imagens ---
# Produção (Render): definir INFORMATIVO_MEDIA_ROOT=/var/data (Persistent Disk) e montar o disco nesse caminho.
# Ficheiros ficam em {INFORMATIVO_MEDIA_ROOT}/informativo/ e URL pública /media/informativo/… (sobrevive a redeploy).
# Sem isso, upload cai em static/uploads/informativo (efémero no Render) — usar URL externa para comunicados permanentes.
_INFORMATIVO_MEDIA_ROOT_ENV = (os.getenv("INFORMATIVO_MEDIA_ROOT") or "").strip()
INFORMATIVO_MEDIA_ROOT = os.path.normpath(_INFORMATIVO_MEDIA_ROOT_ENV) if _INFORMATIVO_MEDIA_ROOT_ENV else ""
if INFORMATIVO_MEDIA_ROOT:
    INFORMATIVO_IMAGE_DIR = os.path.join(INFORMATIVO_MEDIA_ROOT, "informativo")
    INFORMATIVO_UPLOAD_PUBLIC_PREFIX = "/media/informativo"
else:
    _INFORMATIVO_DIR_ENV = (os.getenv("INFORMATIVO_IMAGE_DIR") or "").strip()
    INFORMATIVO_IMAGE_DIR = (
        os.path.normpath(_INFORMATIVO_DIR_ENV)
        if _INFORMATIVO_DIR_ENV
        else os.path.join(str(BASE_DIR), "static", "uploads", "informativo")
    )
    INFORMATIVO_UPLOAD_PUBLIC_PREFIX = "/static/uploads/informativo"
try:
    os.makedirs(INFORMATIVO_IMAGE_DIR, exist_ok=True)
except OSError:
    pass
_DEFAULT_INFORMATIVO_STATIC = os.path.normpath(
    os.path.join(str(BASE_DIR), "static", "uploads", "informativo")
)

# PNG 1×1 transparente: quando o ficheiro não existe (ex.: Render sem disco persistente), evita 404 no browser e avisos no console.
_INFORMATIVO_MISSING_PNG = bytes.fromhex(
    "89504e470d0a1a0a0000000d49484452000000010000000108060000001f15c489"
    "0000000a49444154789c63000100000500001d0d210000000049454e44ae426082"
)


def _safe_informativo_upload_filename(name: str) -> bool:
    if not name or len(name) > 220:
        return False
    if "/" in name or "\\" in name or ".." in name:
        return False
    allowed = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-")
    if not all(c in allowed for c in name):
        return False
    low = name.lower()
    return low.endswith((".png", ".jpg", ".jpeg", ".webp", ".gif"))


def _informativo_legacy_static_disk_path(filename: str) -> str:
    """Caminho no disco para URLs /static/uploads/informativo/… (nunca o volume /var/data quando esse volume é só para /media)."""
    if INFORMATIVO_MEDIA_ROOT:
        return os.path.join(_DEFAULT_INFORMATIVO_STATIC, filename)
    return os.path.join(INFORMATIVO_IMAGE_DIR, filename)


@app.get("/static/uploads/informativo/{filename}", include_in_schema=False)
async def serve_informativo_upload_image(filename: str):
    """Serve imagens de comunicados para URLs legadas /static/uploads/informativo/…"""
    import mimetypes

    name = (filename or "").strip()
    if not _safe_informativo_upload_filename(name):
        return Response(content=_INFORMATIVO_MISSING_PNG, media_type="image/png")
    path = _informativo_legacy_static_disk_path(name)
    if os.path.isfile(path):
        mt = mimetypes.guess_type(path)[0] or "application/octet-stream"
        return FileResponse(path, media_type=mt)
    return Response(content=_INFORMATIVO_MISSING_PNG, media_type="image/png")

