# Helper function to get user display name
def get_user_display_name(request: Request, session: Session = None) -> tuple[str, str]:
    """
    Returns (display_name, initials) for the current user.
    If session is provided, tries to get Employee name from linked User.
    Otherwise, uses email as fallback.
    """
    user = get_current_user(request)
    if not user:
        return ("Usuário", "US")
    
    if isinstance(user, dict) and user.get("type") == "user":
        user_id = user.get("id")
        if user_id and session:
            try:
                db_user = session.get(models.User, user_id)
                if db_user and db_user.employee_id:
                    employee = session.get(models.Employee, db_user.employee_id)
                    if employee:
                        name = employee.name
                        initials = "".join([n[0].upper() for n in name.split()[:2]]) if name else "US"
                        return (name, initials[:2])
            except Exception:
                pass
        
        # Fallback to email
        email = user.get("email", "")
        if email:
            name = email.split("@")[0].replace(".", " ").title()
            initials = "".join([n[0].upper() for n in name.split()[:2]]) if name else "US"
            return (name, initials[:2])
    
    return ("Usuário", "US")

def format_user_label(user) -> str:
    """Converte o usuário logado em um rótulo legível para eventos e logs."""
    try:
        if isinstance(user, dict):
            email = user.get("email")
            if email:
                return email
            name = user.get("name")
            if name:
                return name
            user_id = user.get("id")
            if user_id:
                return str(user_id)
            role = user.get("role")
            if role:
                return role
            return "usuário"

        email = getattr(user, "email", None)
        if email:
            return email
        username = getattr(user, "username", None)
        if username:
            return username
        full_name = getattr(user, "name", None)
        if full_name:
            return full_name
        return str(user)
    except Exception:
        return "usuário"

# --- Custom Filters ---
def fmt_br(val):
    if val is None: return "0,0"
    try:
        return f"{float(val):,.1f}".replace(",", "X").replace(".", ",").replace("X", ".")
    except:
        return str(val)

def fmt_br_int(val):
    if val is None: return "0"
    try:
        return f"{int(val):,.0f}".replace(",", ".")
    except:
        return str(val)

def fmt_br_pct(val):
    if val is None:
        return "0%"
    try:
        num = float(val)
        if num <= 1:
            num *= 100
        return f"{num:,.0f}%".replace(",", ".")
    except:
        return f"{val}%"

def fmt_br_2(val):
    if val is None:
        return "0,00"
    try:
        return f"{float(val):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
    except Exception:
        return str(val)

def fmt_br_duracao(val):
    """Duração em minutos (padrão BR): 0-60 → 'X min'; >60 → 'H:MM hr'."""
    if val is None:
        return "--"
    try:
        m = int(round(float(val)))
        if m < 0:
            m = 0
        if m <= 60:
            return f"{m} min"
        h, mn = m // 60, m % 60
        return f"{h}:{mn:02d} hr"
    except Exception:
        return "--"


def fmt_br_datetime(val):
    """Formata datetime em fuso America/Sao_Paulo como dd/mm/yyyy HH:MM."""
    if val is None:
        return "—"
    try:
        tz_sp = ZoneInfo("America/Sao_Paulo")
        if hasattr(val, "tzinfo") and val.tzinfo is not None:
            local = val.astimezone(tz_sp)
        else:
            # Naive: assumir UTC (comum em banco)
            utc = val.replace(tzinfo=ZoneInfo("UTC"))
            local = utc.astimezone(tz_sp)
        return local.strftime("%d/%m/%Y %H:%M")
    except Exception:
        return str(val) if val else "—"


def fmt_br_date(val):
    """Data em dd/mm/yyyy (str YYYY-MM-DD, date ou datetime)."""
    if val is None:
        return "—"
    try:
        if isinstance(val, datetime):
            return val.strftime("%d/%m/%Y")
        if isinstance(val, str) and len(val.strip()) >= 10:
            d = datetime.strptime(val.strip()[:10], "%Y-%m-%d").date()
            return d.strftime("%d/%m/%Y")
        if hasattr(val, "year") and hasattr(val, "month") and hasattr(val, "day") and not isinstance(val, datetime):
            return val.strftime("%d/%m/%Y")
    except Exception:
        pass
    return str(val) if val else "—"


def fmt_nb_br(nb):
    """NB numérico com separador de milhar (padrão BR); texto alfanumérico sem alterar."""
    if nb is None or str(nb).strip() == "":
        return "—"
    s = str(nb).strip()
    digits = s.replace(".", "").replace(",", "")
    if digits.isdigit() and len(digits) <= 12:
        try:
            return fmt_br_int(int(digits))
        except Exception:
            pass
    return s


templates.env.filters["fmt_br"] = fmt_br
templates.env.filters["fmt_br_int"] = fmt_br_int
templates.env.filters["fmt_br_pct"] = fmt_br_pct
templates.env.filters["fmt_br_2"] = fmt_br_2
templates.env.filters["fmt_br_duracao"] = fmt_br_duracao
templates.env.filters["fmt_br_datetime"] = fmt_br_datetime
templates.env.filters["fmt_br_date"] = fmt_br_date
templates.env.filters["fmt_nb_br"] = fmt_nb_br

