def tv_abbrev_name(val: Optional[str]) -> str:
    """TV/cartões: primeiro nome + inicial útil do sobrenome."""
    s = (val or "").strip()
    if not s:
        return "—"
    parts = s.split()
    if len(parts) == 1:
        return parts[0]
    particles = frozenset({"da", "de", "do", "dos", "das", "e"})
    sig = [p for p in parts if p.lower() not in particles]
    if len(sig) < 2:
        sig = parts
    if len(sig) == 1:
        return sig[0]
    ini = sig[1][0].upper() if sig[1] else ""
    return f"{sig[0]} {ini}." if ini else sig[0]


templates.env.filters["tv_abbrev_name"] = tv_abbrev_name

# --- Auth Helpers (Local + Google) ---
PASSWORD_ITERATIONS = 120_000

def normalize_email(value: str) -> str:
    return (value or "").strip().lower()

def hash_password(password: str) -> str:
    salt = secrets.token_bytes(16)
    dk = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, PASSWORD_ITERATIONS)
    return "pbkdf2_sha256${}${}${}".format(
        PASSWORD_ITERATIONS,
        base64.b64encode(salt).decode("ascii"),
        base64.b64encode(dk).decode("ascii")
    )

def verify_password(password: str, stored_hash: str) -> bool:
    if not stored_hash:
        return False
    try:
        algo, iterations_str, salt_b64, hash_b64 = stored_hash.split("$", 3)
        if algo != "pbkdf2_sha256":
            return False
        iterations = int(iterations_str)
        salt = base64.b64decode(salt_b64.encode("ascii"))
        expected = base64.b64decode(hash_b64.encode("ascii"))
        candidate = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, iterations)
        return hmac.compare_digest(candidate, expected)
    except Exception:
        return False

def hash_reset_token(token: str) -> str:
    digest = hashlib.sha256()
    digest.update(token.encode("utf-8"))
    digest.update(SECRET_KEY.encode("utf-8"))
    return digest.hexdigest()

def is_google_enabled() -> bool:
    return bool(GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET)

