async def _save_informativo_image(file: UploadFile) -> str:
    os.makedirs(INFORMATIVO_IMAGE_DIR, exist_ok=True)
    raw_name = (file.filename or "").strip()
    if not raw_name:
        raise ValueError("Arquivo inválido.")
    ext = os.path.splitext(raw_name)[1].lower()
    if ext not in (".jpg", ".jpeg", ".png", ".webp"):
        raise ValueError("Formato inválido. Use JPG, PNG ou WEBP.")
    content = await file.read()
    if not content:
        raise ValueError("Arquivo vazio.")
    if len(content) > INFORMATIVO_MAX_IMAGE_SIZE:
        raise ValueError("Imagem excede 8MB.")
    safe_name = f"informativo_{datetime.now(ZoneInfo('America/Sao_Paulo')).strftime('%Y%m%d%H%M%S')}_{secrets.token_hex(4)}{ext}"
    file_path = os.path.join(INFORMATIVO_IMAGE_DIR, safe_name)
    with open(file_path, "wb") as fp:
        fp.write(content)
    return f"{INFORMATIVO_UPLOAD_PUBLIC_PREFIX}/{safe_name}"


async def _save_informativo_audio(file: UploadFile) -> str:
    os.makedirs(INFORMATIVO_AUDIO_DIR, exist_ok=True)
    raw_name = (file.filename or "").strip()
    if not raw_name:
        raise ValueError("Arquivo inválido.")
    ext = os.path.splitext(raw_name)[1].lower()
    if ext not in (".mp3", ".ogg", ".wav", ".m4a"):
        raise ValueError("Formato inválido. Use MP3, OGG, WAV ou M4A.")
    content = await file.read()
    if not content:
        raise ValueError("Arquivo vazio.")
    if len(content) > INFORMATIVO_MAX_AUDIO_SIZE:
        raise ValueError("Áudio excede 20MB.")
    safe_name = f"informativo_audio_{datetime.now(ZoneInfo('America/Sao_Paulo')).strftime('%Y%m%d%H%M%S')}_{secrets.token_hex(4)}{ext}"
    file_path = os.path.join(INFORMATIVO_AUDIO_DIR, safe_name)
    with open(file_path, "wb") as fp:
        fp.write(content)
    return f"/static/uploads/informativo_audio/{safe_name}"


def _normalize_informativo_image_url(raw_url: Optional[str]) -> str:
    value = (raw_url or "").strip()
    if not value:
        return ""
    parsed = urlparse(value)
    path = (parsed.path or "").strip()
    lower = value.lower()
    if lower.startswith("data:"):
        return value

    # Compatibilidade com registros legados: valor salvo só com nome do arquivo.
    if "/" not in value and "\\" not in value:
        path = f"/static/uploads/informativo/{value.lstrip('/')}"
        value = path
    elif value.startswith("static/"):
        path = f"/{value}"
        value = path
    elif path and parsed.scheme in ("http", "https"):
        # Mantém URL externa, mas normaliza para verificar assets locais publicados por URL absoluta.
        value = value
    elif path:
        value = path

    check_path = path or value
    if check_path.startswith("/static/uploads/informativo/"):
        filename = os.path.basename(check_path.split("?", 1)[0])
        if not filename:
            return ""
        return f"/static/uploads/informativo/{filename}"
    if check_path.startswith("/media/informativo/"):
        filename = os.path.basename(check_path.split("?", 1)[0])
        if not filename:
            return ""
        return f"/media/informativo/{filename}"

    out = value
    if out and not out.lower().startswith(("http://", "https://", "data:")) and not out.startswith("/"):
        if "uploads/informativo/" in out.replace("\\", "/"):
            out = "/" + out.lstrip("/")
        elif out.startswith("static/"):
            out = "/" + out

    return out


def resolve_informativo_bulletin_image_url(raw_url: Optional[str]) -> Optional[str]:
    """Normaliza uma única string (legado: misturava URL externa e path local)."""
    normalized = _normalize_informativo_image_url(raw_url)
    return normalized if normalized else None


def _normalize_bulletin_external_url(raw: Optional[str]) -> Optional[str]:
    """Apenas https, http ou data URI — valor do campo image_url (externo)."""
    v = (raw or "").strip()[:500]
    if not v:
        return None
    low = v.lower()
    if low.startswith("data:"):
        return v
    p = urlparse(v)
    if p.scheme in ("http", "https") and p.netloc:
        return v
    return None


def _legacy_upload_path_from_image_url_field(raw: Optional[str]) -> Optional[str]:
    """Se image_url guarda só path de upload (registros antigos), devolve path normalizado."""
    if _normalize_bulletin_external_url(raw):
        return None
    n = _normalize_informativo_image_url(raw or "")
    if not n:
        return None
    if n.startswith("/static/uploads/informativo/") or n.startswith("/media/informativo/"):
        return n
    return None


def _is_local_informativo_asset_url(url: Optional[str]) -> bool:
    if not url:
        return False
    u = url.split("?", 1)[0].strip()
    return u.startswith("/static/uploads/informativo/") or u.startswith("/media/informativo/")


def resolve_bulletin_display_image(b: Any) -> Optional[str]:
    """URL exibida no painel/admin: image_url externa primeiro; senão upload (uploaded_image_path ou legado em image_url)."""
    if b is None:
        return None
    if isinstance(b, str):
        return resolve_informativo_bulletin_image_url(b)
    ext: Optional[str] = None
    upl_norm: Optional[str] = None
    legacy_from_url: Optional[str] = None
    if isinstance(b, dict):
        ext = _normalize_bulletin_external_url(b.get("image_url"))
        upl_raw = b.get("uploaded_image_path")
        if upl_raw:
            u = _normalize_informativo_image_url(str(upl_raw))
            upl_norm = u if u else None
        if not ext:
            legacy_from_url = _legacy_upload_path_from_image_url_field(b.get("image_url"))
    else:
        ext = _normalize_bulletin_external_url(getattr(b, "image_url", None))
        upl_raw = getattr(b, "uploaded_image_path", None)
        if upl_raw:
            u = _normalize_informativo_image_url(str(upl_raw))
            upl_norm = u if u else None
        if not ext:
            legacy_from_url = _legacy_upload_path_from_image_url_field(getattr(b, "image_url", None))
    if ext:
        return ext
    for cand in (upl_norm, legacy_from_url):
        if cand:
            return cand
    return None


def _bulletin_has_local_path_record(b: Any) -> bool:
    if b is None:
        return False
    if isinstance(b, dict):
        if (str(b.get("uploaded_image_path") or "").strip()):
            return True
        return bool(_legacy_upload_path_from_image_url_field(b.get("image_url")))
    if (str(getattr(b, "uploaded_image_path", None) or "").strip()):
        return True
    return bool(_legacy_upload_path_from_image_url_field(getattr(b, "image_url", None)))


def informativo_local_upload_file_missing(resolved_image_url: Optional[str]) -> bool:
    """True se a URL é ficheiro servido por este app mas o path no disco não existe."""
    if not resolved_image_url:
        return False
    u = resolved_image_url.split("?", 1)[0].strip()
    fn = os.path.basename(u)
    if not fn or ".." in fn.replace("\\", "/"):
        return True
    if u.startswith("/media/informativo/"):
        path = os.path.join(INFORMATIVO_IMAGE_DIR, fn)
        return not os.path.isfile(path)
    if u.startswith("/static/uploads/informativo/"):
        path = _informativo_legacy_static_disk_path(fn)
        return not os.path.isfile(path)
    return False


def _tpl_resolve_bulletin_image(b: Any) -> Optional[str]:
    """Jinja: aceita InformativeBulletin, dict com image_url/uploaded_image_path ou string.

    Uploads locais sem ficheiro no disco (ex.: deploy sem volume) não devolvem URL — o GET
    legado responde 200 com PNG 1×1 transparente, o que quebraria o onerror do <img> e deixaria
    o cartão com faixa em branco; omitir a tag evita isso.
    """
    url = resolve_bulletin_display_image(b)
    if not url:
        return None
    if _is_local_informativo_asset_url(url) and informativo_local_upload_file_missing(url):
        return None
    return url


templates.env.globals["resolve_bulletin_image"] = _tpl_resolve_bulletin_image


def resolve_equipment(session: Session, code: str) -> models.TranspalletEquipment:
    equipment = session.exec(
        select(models.TranspalletEquipment).where(models.TranspalletEquipment.code == code)
    ).first()
    if not equipment:
        equipment = models.TranspalletEquipment(code=code, status="available")
        session.add(equipment)
        session.commit()
        session.refresh(equipment)
    return equipment

def block_equipment(session: Session, equipment: models.TranspalletEquipment, reason: str, checklist_id: Optional[int]):
    equipment.status = "blocked"
    equipment.blocked_reason = reason
    equipment.blocked_at = datetime.now()
    equipment.last_checklist_id = checklist_id
    session.add(equipment)

def release_equipment(session: Session, equipment: models.TranspalletEquipment, released_by: str):
    equipment.status = "available"
    equipment.released_by = released_by
    equipment.released_at = datetime.now()
    session.add(equipment)

def ensure_user_auth_schema():
    inspector = inspect(engine)
    if "user" not in inspector.get_table_names():
        return
    existing = {col["name"] for col in inspector.get_columns("user")}
    missing = {
        "role": "VARCHAR(32)",
        "is_active": "BOOLEAN",
        "employee_id": "INTEGER",
        "allowed_pages": "TEXT",
        "google_sub": "VARCHAR(255)",
        "reset_token_hash": "VARCHAR(255)",
        "reset_token_expires_at": "TIMESTAMP",
        "created_at": "TIMESTAMP",
        "updated_at": "TIMESTAMP"
    }
    table_name = "\"user\""
    added_is_active = False
    added_role = False
    added_allowed_pages = False
    with engine.begin() as conn:
        for col_name, col_type in missing.items():
            if col_name in existing:
                continue
            conn.execute(text(f"ALTER TABLE {table_name} ADD COLUMN {col_name} {col_type}"))
            if col_name == "is_active":
                added_is_active = True
            if col_name == "role":
                added_role = True
            if col_name == "allowed_pages":
                added_allowed_pages = True
        if "is_active" in existing or added_is_active:
            conn.execute(text(f"UPDATE {table_name} SET is_active = TRUE WHERE is_active IS NULL"))
        if "role" in existing or added_role:
            conn.execute(text(f"UPDATE {table_name} SET role = 'admin' WHERE role IS NULL"))
    if "allowed_pages" in existing or added_allowed_pages:
        with engine.begin() as conn:
            conn.execute(text(f"UPDATE {table_name} SET allowed_pages = '[]' WHERE allowed_pages IS NULL"))

