def _load_active_employee_user_options(session: Session) -> tuple[List[Dict[str, Any]], Dict[int, Dict[str, Any]]]:
    """Carrega somente os campos usados nas telas de gestão de usuários."""
    rows = session.exec(
        select(
            models.Employee.id,
            models.Employee.name,
            models.Employee.registration_id,
        )
        .where(models.Employee.status != "fired")
        .order_by(models.Employee.name)
    ).all()

    employees: List[Dict[str, Any]] = []
    employee_map: Dict[int, Dict[str, Any]] = {}
    for employee_id, employee_name, registration_id in rows:
        if employee_id is None:
            continue
        item = {
            "id": int(employee_id),
            "name": str(employee_name or ""),
            "registration_id": str(registration_id or ""),
        }
        employees.append(item)
        employee_map[item["id"]] = item
    return employees, employee_map

# --- Auth Helper Functions ---
def get_current_user(request: Request):
    auth_user_id = request.session.get("auth_user_id")
    if auth_user_id:
        return {
            "type": "user",
            "id": auth_user_id,
            "role": request.session.get("auth_user_role"),
            "email": request.session.get("auth_user_email")
        }

    legacy_user = request.session.get("user")
    if legacy_user:
        return {"type": "user", "id": None, "role": "admin", "email": str(legacy_user)}

    # Support for Mobile Employee Session
    user_id = request.session.get("user_id")
    if user_id:
        return {"type": "employee", "id": user_id}
    return None

def require_login(request: Request):
    user = get_current_user(request)
    path = request.url.path

    # Not logged in at all
    if not user:
        if path.startswith("/mobile"):
             raise HTTPException(status_code=status.HTTP_303_SEE_OTHER, headers={"Location": "/mobile/login"})
        raise HTTPException(status_code=status.HTTP_303_SEE_OTHER, headers={"Location": "/login"})

    # Logged in, check permissions
    if isinstance(user, dict) and user.get("type") == "user":
        role = (user.get("role") or "").lower()
        if role == "leader":
            allowed_keys = request.session.get("allowed_pages")
            if isinstance(allowed_keys, list):
                allowed_keys = [str(k) for k in allowed_keys if str(k) in PAGE_KEYS]
            else:
                allowed_keys = parse_allowed_pages(allowed_keys)
            allowed_prefixes = allowed_prefixes_for(allowed_keys)
            if not any(path.startswith(prefix) for prefix in allowed_prefixes):
                raise HTTPException(status_code=403, detail="Acesso negado.")
        return user

    # User is Employee (dict) -> RESTRICTED TO /mobile ONLY (+ /escala para API da Escala)
    if isinstance(user, dict) and user.get("type") == "employee":
        if not path.startswith("/mobile") and not path.startswith("/static") and not path.startswith("/api") and not path.startswith("/escala"):
            # Trying to access Desktop/Admin page -> Redirect to Mobile Dashboard
            # e.g. /smart-flow, /employees, /
            print(f"ðŸâ€â€™ Access Denied: Mobile User {user.get('id')} tried to access {path}")
            raise HTTPException(status_code=status.HTTP_303_SEE_OTHER, headers={"Location": "/mobile/dashboard"})

    return user

def require_mobile_module(employee, module: str):
    if module == "separation":
        allowed = _has_mobile_delivery_driver_access(employee)
    elif module == "checklist":
        allowed = _has_mobile_checklist_access(employee)
    elif module == "gatehouse":
        allowed = _has_mobile_gatehouse_access(employee)
    else:
        raise HTTPException(status_code=400, detail="Módulo inválido.")

    if not allowed:
        raise HTTPException(status_code=403, detail="Acesso não liberado para este módulo")
    return True

def _has_mobile_flags(employee) -> bool:
    if not employee:
        return False
    return bool(
        getattr(employee, "mobile_access", False)
        or getattr(employee, "mobile_access_returns", False)
        or getattr(employee, "mobile_access_helper", False)
        or getattr(employee, "mobile_access_separation", False)
        or getattr(employee, "mobile_access_checklist", False)
        or getattr(employee, "mobile_access_admin_start", False)
        or getattr(employee, "mobile_access_gatehouse", False)
        or getattr(employee, "mobile_access_escala", False)
    )


def _has_explicit_mobile_module_flags(employee) -> bool:
    if not employee:
        return False
    return bool(
        getattr(employee, "mobile_access_separation", False)
        or getattr(employee, "mobile_access_checklist", False)
        or getattr(employee, "mobile_access_admin_start", False)
        or getattr(employee, "mobile_access_returns", False)
        or getattr(employee, "mobile_access_helper", False)
        or getattr(employee, "mobile_access_gatehouse", False)
        or getattr(employee, "mobile_access_escala", False)
    )


def _normalized_employee_role(employee) -> str:
    if not employee:
        return ""
    role_value = str(getattr(employee, "role", "") or "").strip()
    return (
        unicodedata.normalize("NFKD", role_value)
        .encode("ascii", "ignore")
        .decode()
        .upper()
    )


def _is_delivery_driver_role(employee) -> bool:
    role_value = _normalized_employee_role(employee)
    return ("MOTORISTA" in role_value) and ("AJUDANTE" not in role_value)


def _is_delivery_helper_role(employee) -> bool:
    role_value = _normalized_employee_role(employee)
    return "AJUDANTE DE MOTORISTA" in role_value


def _is_gatehouse_role(employee) -> bool:
    role_value = _normalized_employee_role(employee)
    return ("PORTEIRO" in role_value) or ("PORTARIA" in role_value)


def _use_mobile_role_fallback(employee) -> bool:
    if not employee:
        return False
    return (
        not _has_explicit_mobile_module_flags(employee)
        and (_is_delivery_driver_role(employee) or _is_delivery_helper_role(employee))
    )


def _has_mobile_delivery_driver_access(employee) -> bool:
    if not employee:
        return False
    return bool(
        getattr(employee, "mobile_access_separation", False)
        or (_use_mobile_role_fallback(employee) and _is_delivery_driver_role(employee))
    )


def _has_mobile_delivery_helper_access(employee) -> bool:
    if not employee:
        return False
    return bool(
        getattr(employee, "mobile_access_helper", False)
        or (_use_mobile_role_fallback(employee) and _is_delivery_helper_role(employee))
    )


def _has_mobile_delivery_history_access(employee) -> bool:
    if not employee:
        return False
    return bool(
        _has_mobile_delivery_driver_access(employee)
        or getattr(employee, "mobile_access_admin_start", False)
        or _has_mobile_delivery_helper_access(employee)
    )


def _has_mobile_checklist_access(employee) -> bool:
    if not employee:
        return False
    return bool(
        getattr(employee, "mobile_access_checklist", False)
        or (_use_mobile_role_fallback(employee) and _is_delivery_driver_role(employee))
    )


def _has_mobile_returns_access(employee) -> bool:
    if not employee:
        return False
    return bool(
        getattr(employee, "mobile_access_returns", False)
        or getattr(employee, "mobile_access_admin_start", False)
        or _has_mobile_delivery_driver_access(employee)
    )


def _has_mobile_gatehouse_access(employee) -> bool:
    if not employee:
        return False
    return bool(
        getattr(employee, "mobile_access_gatehouse", False)
        or (
            not _has_explicit_mobile_module_flags(employee)
            and _is_gatehouse_role(employee)
        )
    )


def _has_mobile_escala_access(employee) -> bool:
    if not employee:
        return False
    return bool(getattr(employee, "mobile_access_escala", False))


def _build_mobile_hub_access_flags(employee) -> Dict[str, bool]:
    explicit_mode = _has_explicit_mobile_module_flags(employee)
    if explicit_mode:
        delivery_driver = bool(getattr(employee, "mobile_access_separation", False))
        delivery_helper = bool(getattr(employee, "mobile_access_helper", False))
        checklist = bool(getattr(employee, "mobile_access_checklist", False))
        admin_start = bool(getattr(employee, "mobile_access_admin_start", False))
        returns = bool(getattr(employee, "mobile_access_returns", False))
        gatehouse = bool(getattr(employee, "mobile_access_gatehouse", False))
        escala = bool(getattr(employee, "mobile_access_escala", False))
    else:
        delivery_driver = _has_mobile_delivery_driver_access(employee)
        delivery_helper = _has_mobile_delivery_helper_access(employee)
        checklist = _has_mobile_checklist_access(employee)
        admin_start = bool(getattr(employee, "mobile_access_admin_start", False))
        returns = _has_mobile_returns_access(employee)
        gatehouse = _has_mobile_gatehouse_access(employee)
        escala = _has_mobile_escala_access(employee)

    helper_only = delivery_helper and not (delivery_driver or admin_start)
    history = False  # Módulo Histórico de Entregas desabilitado
    delivery_overview = delivery_driver or delivery_helper

    return {
        "explicit_mode": explicit_mode,
        "delivery_driver": delivery_driver,
        "delivery_helper": delivery_helper,
        "helper_only": helper_only,
        "checklist": checklist,
        "checklist_nav": checklist and not helper_only,
        "admin_start": admin_start,
        "returns": returns,
        "returns_kpi": delivery_overview and returns,
        "gatehouse": gatehouse,
        "escala": escala,
        "history": history,
        "delivery_overview": delivery_overview,
    }


def _is_mobile_allowed(employee) -> bool:
    if not employee:
        return False
    status_value = str(getattr(employee, "status", "") or "").strip().lower()
    if status_value != "active":
        return False
    if _has_mobile_flags(employee):
        return True
    return bool(_use_mobile_role_fallback(employee) or _has_mobile_gatehouse_access(employee))

def require_roles(request: Request, allowed_roles: set):
    user = require_login(request)
    actor_label = format_user_label(user)
    if isinstance(user, dict) and user.get("type") == "user":
        if (user.get("role") or "").lower() not in allowed_roles:
            raise HTTPException(status_code=403, detail="Acesso negado.")
        return user
    raise HTTPException(status_code=403, detail="Acesso negado.")

