def _parse_br_float_form(val: Any) -> Optional[float]:
    """Parse float a partir de formulário (aceita 1.234,56 ou 1234.56)."""
    if val is None:
        return None
    s = str(val).strip()
    if not s:
        return None
    s = s.replace(" ", "")
    if "," in s and "." in s:
        s = s.replace(".", "").replace(",", ".")
    elif "," in s:
        s = s.replace(",", ".")
    try:
        return float(s)
    except ValueError:
        return None


def _format_br_pct_form(val: Any) -> str:
    """Percentual para exibição em campo (vírgula como separador decimal)."""
    if val is None:
        return ""
    try:
        x = float(val)
    except (TypeError, ValueError):
        return ""
    s = f"{x:.6f}".rstrip("0").rstrip(".")
    return s.replace(".", ",")


def _format_br_money_form(val: Any) -> str:
    """Valor monetário: milhar com ponto, decimais com vírgula (ex.: 1.234,56)."""
    if val is None:
        return ""
    try:
        x = float(val)
    except (TypeError, ValueError):
        return ""
    s = f"{x:,.2f}"
    return s.replace(",", "X").replace(".", ",").replace("X", ".")


def _is_operational_route_devolucao(route: Any) -> bool:
    """Conta apenas devoluções operacionais reais no painel TV."""
    return normalized_delivery_status(route) == "devolucao"


def _employee_ids_for_informativo_devolucao_kpi(session: Session) -> List[int]:
    """Motoristas/empregados ativos (não demitidos) para agregar rotas e devoluções no índice mensal."""
    try:
        raw = session.exec(
            select(models.Employee.id).where(models.Employee.status != "fired")
        ).all()
    except Exception:
        return []
    out: List[int] = []
    for item in raw or []:
        if item is None:
            continue
        try:
            eid = int(item[0]) if isinstance(item, (list, tuple)) else int(item)
        except (TypeError, ValueError, IndexError):
            continue
        out.append(eid)
    return out


def _month_date_range_str(year: int, month: int) -> Tuple[str, str]:
    start = date(year, month, 1)
    if month == 12:
        end = date(year, 12, 31)
    else:
        end = date(year, month + 1, 1) - timedelta(days=1)
    return start.strftime("%Y-%m-%d"), end.strftime("%Y-%m-%d")


def _last_calendar_day_date(year: int, month: int) -> date:
    _, last = calendar.monthrange(year, month)
    return date(year, month, last)


def _receita_mensal_delivery_sistema(session: Session, year: int, month: int) -> Optional[float]:
    """
    Receita (R$) para meta 2%: soma de valor_financeiro das rotas type=delivery com Route.date
    entre o 1º dia útil do mês (calendário comercial) e o fim do período —
    último dia do mês se o mês já passou; se for o mês corrente, até hoje (inclusive).
    """
    from utils.business_calendar import first_business_day_of_month

    today = date.today()
    if year > today.year or (year == today.year and month > today.month):
        return None
    end_d = _last_calendar_day_date(year, month)
    if year == today.year and month == today.month:
        end_d = min(end_d, today)
    start_d = first_business_day_of_month(year, month)
    if start_d > end_d:
        return None
    ms = start_d.strftime("%Y-%m-%d")
    me = end_d.strftime("%Y-%m-%d")
    try:
        routes = session.exec(
            select(models.Route)
            .where(models.Route.type == "delivery")
            .where(models.Route.date >= ms)
            .where(models.Route.date <= me)
        ).all()
    except Exception:
        return None
    total = sum(float(getattr(r, "valor_financeiro", None) or 0.0) for r in (routes or []))
    return round(float(total), 2)


def _kpi_devolucao_mes_romaneio_calendario(
    session: Session, month_start_str: str, month_end_str: str
) -> tuple[float, int]:
    """Soma R$ e quantidade de devoluções no mês civil (data_romaneio entre 1º e último dia), empresa inteira."""
    try:
        q = (
            select(models.Devolucao)
            .where(models.Devolucao.data_romaneio >= month_start_str)
            .where(models.Devolucao.data_romaneio <= month_end_str)
        )
        devs = session.exec(q).all()
    except Exception:
        return 0.0, 0
    filtered = [d for d in devs if not getattr(d, "duplicate_of_id", None)]
    total_v = float(sum(float(getattr(d, "valor", 0) or 0.0) for d in filtered))
    return total_v, int(len(filtered))


def _devolucao_mensal_system_month_values(session: Session, year: int, month: int) -> Dict[str, Optional[float]]:
    """
    KPIs só do sistema para o índice mensal:
    - %: critério canônico (devoluções ÷ rotas concluídas) sobre rotas type=delivery com Route.date
      no mês civil (1º ao último dia).
    - Valor R$: soma Devolucao.valor com data_romaneio nesse mesmo intervalo civil.
    - Receita R$: soma Route.valor_financeiro das entregas com Route.date do 1º dia útil do mês
      até o último dia do mês (mês fechado) ou até hoje (mês corrente).
    """
    ms, me = _month_date_range_str(year, month)
    try:
        routes_month = session.exec(
            select(models.Route)
            .where(models.Route.type == "delivery")
            .where(models.Route.date >= ms)
            .where(models.Route.date <= me)
        ).all()
    except Exception:
        routes_month = []
    try:
        p_raw = pct_devolucao_sobre_rotas_concluidas(routes_month)
        p = round(float(p_raw), 2)
    except Exception:
        p = None
    try:
        valor_v, _cnt = _kpi_devolucao_mes_romaneio_calendario(session, ms, me)
        v = round(float(valor_v), 2)
    except Exception:
        v = None
    try:
        rec = _receita_mensal_delivery_sistema(session, year, month)
    except Exception:
        rec = None
    return {"pct": p, "valor": v, "receita": rec}


def _devolucao_mensal_kpi_payload(session: Session, year: int) -> Dict[str, Any]:
    """Dados para o gráfico de índice de devolução mensal (meta 2% com base na receita informada)."""
    try:
        rows = session.exec(
            select(models.InformativeMonthlyReturn).where(models.InformativeMonthlyReturn.year == year)
        ).all()
    except Exception:
        rows = []
    by_m = {r.month: r for r in rows}
    labels = ["Jan", "Fev", "Mar", "Abr", "Mai", "Jun", "Jul", "Ago", "Set", "Out", "Nov", "Dez"]
    pct: List[Optional[float]] = []
    valor_dev: List[Optional[float]] = []
    meta_valor: List[Optional[float]] = []
    receita_m: List[Optional[float]] = []
    for m in range(1, 13):
        r = by_m.get(m)
        use_sys = bool(r and getattr(r, "use_system_kpi", False))
        if use_sys:
            sysv = _devolucao_mensal_system_month_values(session, year, m)
            p = sysv.get("pct")
            v = sysv.get("valor")
            rec = sysv.get("receita")
        else:
            p = float(r.pct_devolucao) if r and r.pct_devolucao is not None else None
            v = float(r.valor_devolucao) if r and r.valor_devolucao is not None else None
            rec = float(r.receita) if r and r.receita is not None else None
        mv = round(rec * 0.02, 2) if rec is not None and rec > 0 else None
        pct.append(round(p, 2) if p is not None else None)
        valor_dev.append(round(v, 2) if v is not None else None)
        meta_valor.append(mv)
        receita_m.append(round(rec, 2) if rec is not None else None)
    return {
        "year": year,
        "labels": labels,
        "pct": pct,
        "valor_devolucao": valor_dev,
        "receita_mensal": receita_m,
        "meta_valor_2pct": meta_valor,
        "meta_pct": [2.0] * 12,
    }


def _informative_carousel_interval_ms(session: Session) -> int:
    """Intervalo do carrossel de avisos no /dashboard (4–120 s → ms)."""
    try:
        c = session.get(models.InformativePanelConfig, 1)
        if c is not None:
            sec = int(getattr(c, "carousel_interval_seconds", None) or 8)
            sec = max(4, min(120, sec))
            return sec * 1000
    except Exception:
        pass
    return 8000


def _informative_audio_config(session: Session) -> Dict[str, Any]:
    try:
        c = session.get(models.InformativePanelConfig, 1)
        if c is None:
            return {"enabled": False, "url": "", "playlist": [], "youtube_url": "", "volume": 0.35}
        volume_raw = int(getattr(c, "audio_volume", 35) or 35)
        volume_raw = max(0, min(100, volume_raw))
        primary_url = (getattr(c, "audio_url", None) or "").strip()
        raw_playlist = (getattr(c, "audio_playlist", None) or "").strip()
        playlist: List[str] = []
        if primary_url:
            playlist.append(primary_url)
        if raw_playlist:
            for line in raw_playlist.splitlines():
                item = (line or "").strip()
                if item and item not in playlist:
                    playlist.append(item[:500])
        return {
            "enabled": bool(getattr(c, "audio_enabled", False)),
            "url": primary_url,
            "playlist": playlist,
            "youtube_url": (getattr(c, "audio_youtube_url", None) or "").strip(),
            "volume": round(volume_raw / 100.0, 2),
        }
    except Exception:
        return {"enabled": False, "url": "", "playlist": [], "youtube_url": "", "volume": 0.35}


def _dashboard_data_source_caption() -> str:
    """Texto curto para o /dashboard: de onde vêm os dados (evita confusão SQLite vazio vs Postgres)."""
    src = (os.environ.get("ACTIVE_DATABASE_SOURCE") or "").strip().lower()
    if src in ("local", "local_forced"):
        return ""
    if src == "render":
        return ""
    return ""


def _build_informativo_extras(
    session: Session,
    selected_date: date,
    selected_date_str: str,
    employees_all: List[Any],
    dashboard_payload: Dict[str, Any],
    routes_today_total: int,
    routes_today_completed: int,
    tonnage_delivered_kg: float,
    tonnage_total_kg: float,
    motorista_ids_scope: Optional[List[int]] = None,
) -> Dict[str, Any]:
    """Dados do painel Informativo: aniversários, férias, ranking devolução, avisos, comparativo de meses."""
    from utils.business_calendar import competence_date_str

    month_start = selected_date.replace(day=1)
    if selected_date.month == 12:
        next_month_start = selected_date.replace(year=selected_date.year + 1, month=1, day=1)
    else:
        next_month_start = selected_date.replace(month=selected_date.month + 1, day=1)
    month_start_str = month_start.strftime("%Y-%m-%d")
    month_end_str = (next_month_start - timedelta(days=1)).strftime("%Y-%m-%d")
    prev_month_end = month_start - timedelta(days=1)
    prev_month_start = prev_month_end.replace(day=1)
    prev_month_start_str = prev_month_start.strftime("%Y-%m-%d")
    prev_month_end_str = prev_month_end.strftime("%Y-%m-%d")

    emp_active = [e for e in employees_all if (getattr(e, "status", None) or "").lower() != "fired"]
    emp_by_id = {e.id: e for e in emp_active if e.id is not None}

    birthdays_souza_pinto: List[Dict[str, Any]] = []
    birthdays_exemplar: List[Dict[str, Any]] = []
    for e in emp_active:
        if not e.birthday:
            continue
        bday = e.birthday.date()
        if bday.month != selected_date.month:
            continue
        lbl = cost_center_display_label(e.cost_center)
        entry = {
            "name": e.name,
            "day": bday.day,
            "is_today": bday.day == selected_date.day,
        }
        if lbl == "Souza Pinto":
            birthdays_souza_pinto.append(entry)
        elif lbl == "Exemplar":
            birthdays_exemplar.append(entry)
    birthdays_souza_pinto.sort(key=lambda x: x["day"])
    birthdays_exemplar.sort(key=lambda x: x["day"])

    vac_active = []
    vac_upcoming = []
    for e in emp_active:
        if not e.vacation_start or not e.vacation_end:
            continue
        vs = e.vacation_start.date()
        ve = e.vacation_end.date()
        if vs <= selected_date <= ve:
            vac_active.append({
                "name": e.name,
                "until": ve.strftime("%d/%m/%Y"),
                "days_left": (ve - selected_date).days + 1,
            })
        elif vs > selected_date:
            vac_upcoming.append({
                "name": e.name,
                "start": vs.strftime("%d/%m/%Y"),
                "in_days": (vs - selected_date).days,
            })
    vac_upcoming.sort(key=lambda x: x["in_days"])

    devs_curr_q = (
        select(models.Devolucao)
        .where(models.Devolucao.data_romaneio >= (prev_month_start - timedelta(days=10)).strftime("%Y-%m-%d"))
        .where(models.Devolucao.data_romaneio <= (next_month_start + timedelta(days=10)).strftime("%Y-%m-%d"))
    )
    if motorista_ids_scope:
        devs_curr_q = devs_curr_q.where(models.Devolucao.motorista_id.in_(motorista_ids_scope))
    from utils.business_calendar import competence_date_str
    devs_curr_raw = session.exec(devs_curr_q).all()
    devs_curr = []
    for d in devs_curr_raw:
        comp = competence_date_str(getattr(d, "data_entrega", None) or getattr(d, "data_romaneio", None)) or str(getattr(d, "data_romaneio", "") or "")[:10]
        if month_start_str <= comp <= month_end_str:
            devs_curr.append(d)
    try:
        resumo_mes = consolidado_avaliar_resumo(
            session,
            month_start_str,
            month_end_str,
            use_competence_window=True,
        )
    except Exception:
        resumo_mes = {"data": [], "data_ajudantes": []}

    rows_m = list(resumo_mes.get("data") or [])
    rows_h = list(resumo_mes.get("data_ajudantes") or [])

    def _short_name_first_and_initial(raw_name: Optional[str]) -> str:
        txt = str(raw_name or "").strip()
        if not txt:
            return ""
        parts = [p for p in txt.split() if p]
        if not parts:
            return ""
        first = parts[0]
        if len(parts) == 1:
            return first
        second = parts[1]
        # Mantém identificadores técnicos legíveis (ex.: "Motorista #713"),
        # evitando truncar para "Motorista #".
        if first.lower() in {"motorista", "ajudante"} and second.startswith("#"):
            return txt
        return f"{first} {second[0].upper()}"

    motorista_ids_from_rows: set[int] = set()
    for row in rows_m:
        try:
            mid = int(row.get("motorista_id") or 0)
        except (TypeError, ValueError):
            mid = 0
        if mid > 0:
            motorista_ids_from_rows.add(mid)

    ajudante_ids_from_rows: set[int] = set()
    for row in rows_h:
        try:
            hid = int(row.get("ajudante_id") or 0)
        except (TypeError, ValueError):
            hid = 0
        if hid > 0:
            ajudante_ids_from_rows.add(hid)

    all_rank_ids = motorista_ids_from_rows | ajudante_ids_from_rows
    employee_name_by_id: Dict[int, str] = {}
    if all_rank_ids:
        try:
            emps_rank = session.exec(select(models.Employee).where(models.Employee.id.in_(list(all_rank_ids)))).all()
        except Exception:
            emps_rank = []
        for emp in emps_rank:
            try:
                eid = int(getattr(emp, "id", 0) or 0)
            except (TypeError, ValueError):
                eid = 0
            if eid <= 0:
                continue
            employee_name_by_id[eid] = str(getattr(emp, "name", "") or "").strip()

    scope_set = {int(x) for x in motorista_ids_scope} if motorista_ids_scope else None

    devolucao_ranking = []
    for row in rows_m:
        mid = row.get("motorista_id")
        if scope_set is not None:
            try:
                if int(mid) not in scope_set:
                    continue
            except (TypeError, ValueError):
                continue
        try:
            mid_int = int(mid) if mid is not None else 0
        except (TypeError, ValueError):
            mid_int = 0
        emp_m = emp_by_id.get(mid_int)
        if not emp_m or not _is_delivery_driver_role(emp_m):
            continue
        row_name = (row.get("motorista_name") or "").strip()
        resolved_name = row_name or employee_name_by_id.get(mid_int, "")
        devolucao_ranking.append({
            "motorista_id": mid_int,
            "name": _short_name_first_and_initial(resolved_name) or (f"Motorista #{mid}" if mid else "—"),
            "pct_ajustado": float(row.get("pct_ajustado") or 0),
            "valor_ajustado": float(row.get("valor_ajustado") or 0),
            "premio": float(_return_rate_to_prize(float(row.get("pct_ajustado") or 0.0))),
            "pct_original": float(row.get("pct_original") or 0),
            "valor_original": float(row.get("valor_original") or 0),
        })

    # Ajudantes: sempre listar todos com devolução no mês (mesmo com filtro de motorista/CC no painel).
    # Filtrar por helper_ids_scoped removia nomes de quem só aparecia com motoristas fora do recorte.
    devolucao_ranking_helper = []
    for row in rows_h:
        hid = row.get("ajudante_id")
        try:
            hid_int = int(hid) if hid is not None else 0
        except (TypeError, ValueError):
            hid_int = 0
        emp_h = emp_by_id.get(hid_int)
        role_h = _normalized_employee_role(emp_h)
        if not emp_h or not role_h.startswith("AJUDANTE"):
            continue
        row_name = (row.get("ajudante_name") or "").strip()
        resolved_name = row_name or employee_name_by_id.get(hid_int, "")
        devolucao_ranking_helper.append({
            "ajudante_id": hid_int,
            "name": _short_name_first_and_initial(resolved_name) or (f"Ajudante #{hid}" if hid else "—"),
            "pct_ajustado": float(row.get("pct_ajustado") or 0),
            "valor_ajustado": float(row.get("valor_ajustado") or 0),
            "premio": float(_return_rate_to_prize(float(row.get("pct_ajustado") or 0.0))),
            "pct_original": float(row.get("pct_original") or 0),
            "valor_original": float(row.get("valor_original") or 0),
        })
    devolucao_ranking.sort(
        key=lambda x: ((x.get("name") or "").casefold(), int(x.get("motorista_id") or 0))
    )
    devolucao_ranking_helper.sort(
        key=lambda x: ((x.get("name") or "").casefold(), int(x.get("ajudante_id") or 0))
    )

    devs_prev_q = (
        select(models.Devolucao)
        .where(models.Devolucao.data_romaneio >= (prev_month_start - timedelta(days=10)).strftime("%Y-%m-%d"))
        .where(models.Devolucao.data_romaneio <= (prev_month_end + timedelta(days=10)).strftime("%Y-%m-%d"))
    )
    if motorista_ids_scope:
        devs_prev_q = devs_prev_q.where(models.Devolucao.motorista_id.in_(motorista_ids_scope))
    devs_prev_raw = session.exec(devs_prev_q).all()
    devs_prev = []
    for d in devs_prev_raw:
        comp = competence_date_str(getattr(d, "data_entrega", None) or getattr(d, "data_romaneio", None)) or str(getattr(d, "data_romaneio", "") or "")[:10]
        if prev_month_start_str <= comp <= prev_month_end_str:
            devs_prev.append(d)
    prev_valor = sum(float(d.valor or 0) for d in devs_prev)
    curr_valor = sum(float(d.valor or 0) for d in devs_curr)

    # Janela estendida para classificar por competência operacional na virada de mês.
    window_start = (prev_month_start - timedelta(days=10)).strftime("%Y-%m-%d")
    window_end = (next_month_start + timedelta(days=10)).strftime("%Y-%m-%d")
    routes_window_q = (
        select(models.Route)
        .where(models.Route.type == "delivery")
        .where(models.Route.date >= window_start)
        .where(models.Route.date <= window_end)
    )
    if motorista_ids_scope:
        routes_window_q = routes_window_q.where(models.Route.employee_id.in_(motorista_ids_scope))
    routes_window = session.exec(routes_window_q).all()

    routes_prev = []
    routes_curr_m = []
    for r in routes_window:
        comp = competence_date_str(getattr(r, "date", None)) or str(getattr(r, "date", "") or "")[:10]
        if prev_month_start_str <= comp <= prev_month_end_str:
            routes_prev.append(r)
        if month_start_str <= comp <= month_end_str:
            routes_curr_m.append(r)

    pct_prev = pct_devolucao_sobre_rotas_concluidas(routes_prev)
    pct_curr = pct_devolucao_sobre_rotas_concluidas(routes_curr_m)
    delta_pp = round(float(pct_prev) - float(pct_curr), 1)

    dd_board = dashboard_payload.get("devolucao_dia") or {}
    if isinstance(dd_board, dict) and "pct" in dd_board:
        devolucao_hoje_pct = round(float(dd_board.get("pct") or 0), 1)
    else:
        q_today = (
            select(models.Route)
            .where(models.Route.type == "delivery")
            .where(models.Route.date == selected_date_str)
        )
        if motorista_ids_scope:
            q_today = q_today.where(models.Route.employee_id.in_(motorista_ids_scope))
        routes_hoje = session.exec(q_today).all()
        devolucao_hoje_pct = pct_devolucao_sobre_rotas_concluidas(routes_hoje)

    bulletins = []
    try:
        bulletins = session.exec(
            select(models.InformativeBulletin)
            .where(models.InformativeBulletin.is_active == True)
            .order_by(models.InformativeBulletin.sort_order, models.InformativeBulletin.id)
        ).all()
    except Exception:
        bulletins = []
    bulletin_list = [
        {
            "id": b.id,
            "title": b.title,
            "body": b.body or "",
            "image_url": (getattr(b, "image_url", None) or "") or "",
            "uploaded_image_path": (getattr(b, "uploaded_image_path", None) or "") or "",
            "link_url": (getattr(b, "link_url", None) or "").strip(),
        }
        for b in bulletins
    ]

    progress_pct = 0.0
    if routes_today_total > 0:
        progress_pct = round(100.0 * routes_today_completed / routes_today_total, 1)

    devolucao_mensal_kpi = _devolucao_mensal_kpi_payload(session, selected_date.year)

    return {
        "birthdays_souza_pinto": birthdays_souza_pinto,
        "birthdays_exemplar": birthdays_exemplar,
        "vacation_active": vac_active,
        "vacation_upcoming": vac_upcoming,
        "devolucao_ranking": devolucao_ranking,
        "devolucao_ranking_motoristas": devolucao_ranking,
        "devolucao_ranking_ajudantes": devolucao_ranking_helper,
        "bulletins": bulletin_list,
        "devolucao_compare": {
            "prev_month_label": prev_month_start.strftime("%m/%Y"),
            "curr_month_label": month_start.strftime("%m/%Y"),
            "prev_valor": round(prev_valor, 2),
            "curr_valor": round(curr_valor, 2),
            "prev_pct_rotas": pct_prev,
            "curr_pct_rotas": pct_curr,
        },
        "devolucao_hoje_pct": devolucao_hoje_pct,
        "devolucao_mes_delta_pp": delta_pp,
        "tonnage_today": {
            "routes_total": routes_today_total,
            "routes_completed": routes_today_completed,
            "progress_pct": progress_pct,
            "delivered_kg": round(tonnage_delivered_kg, 2),
            "total_kg": round(tonnage_total_kg, 2),
        },
        "carousel_interval_ms": _informative_carousel_interval_ms(session),
        "audio": _informative_audio_config(session),
        "devolucao_mensal_kpi": devolucao_mensal_kpi,
    }


def _kpi_devolucao_mes_registros(
    session: Session,
    month_start_str: str,
    month_end_str: str,
    motorista_ids: Optional[List[int]],
) -> tuple[float, int]:
    """Soma e quantidade na tabela Devolucao no mês por competência operacional."""
    from utils.business_calendar import competence_date_str

    if not motorista_ids:
        return 0.0, 0
    d0 = datetime.strptime(month_start_str, "%Y-%m-%d").date()
    d1 = datetime.strptime(month_end_str, "%Y-%m-%d").date()
    window_start = (d0 - timedelta(days=10)).strftime("%Y-%m-%d")
    window_end = (d1 + timedelta(days=10)).strftime("%Y-%m-%d")
    q = (
        select(models.Devolucao)
        .where(models.Devolucao.data_romaneio >= window_start)
        .where(models.Devolucao.data_romaneio <= window_end)
        .where(models.Devolucao.motorista_id.in_(motorista_ids))
    )
    devs = session.exec(q).all()
    filtered = []
    for d in devs:
        if getattr(d, "duplicate_of_id", None):
            continue
        comp = competence_date_str(getattr(d, "data_entrega", None) or getattr(d, "data_romaneio", None)) or str(getattr(d, "data_romaneio", "") or "")[:10]
        if month_start_str <= comp <= month_end_str:
            filtered.append(d)
    total_v = float(sum(float(getattr(d, "valor", 0) or 0.0) for d in filtered))
    cnt = int(len(filtered))
    return total_v, cnt


def _pct_devolucao_financeiro_sistema(valor_devolvido: float, routes_delivery: List[Any]) -> tuple[Optional[float], float]:
    """% valor devolvido sobre soma de valor_financeiro das rotas de entrega (só linhas com valor_financeiro preenchido)."""
    base = sum(
        float(getattr(r, "valor_financeiro", None) or 0)
        for r in routes_delivery
        if getattr(r, "valor_financeiro", None) is not None
    )
    if base <= 0:
        return None, 0.0
    return round(100.0 * float(valor_devolvido or 0) / base, 2), round(base, 2)


def _infer_shift_name(now_br: datetime) -> str:
    hhmm = now_br.hour * 60 + now_br.minute
    # 05:00 - 13:20
    if (5 * 60) <= hhmm < (13 * 60 + 20):
        return "Manha"
    # 12:00 - 20:20
    if (12 * 60) <= hhmm < (20 * 60 + 20):
        return "Tarde"
    # 18:00 - 06:00
    return "Noite"


@app.get("/dashboard", response_class=HTMLResponse)
@app.get("/dashboard/tv", response_class=HTMLResponse)
@app.get("/dashboard/tv-fire", response_class=HTMLResponse)
async def dashboard_entry(
    request: Request,
    cost_center: Optional[str] = None,
    date_ref: Optional[str] = None,
    session: Session = Depends(get_session),
):
    user = get_current_user(request)
    if not user:
        return RedirectResponse(url="/login", status_code=303)
    if isinstance(user, dict) and user.get("type") == "employee":
        return RedirectResponse(url="/mobile/dashboard", status_code=303)

    request_path = request.url.path.rstrip("/")
    is_tv = request_path.endswith("/tv")
    is_tv_fire = request_path.endswith("/tv-fire")
    is_tv_like = is_tv or is_tv_fire
    if is_tv_like:
        cost_center = cost_center or "Todos"

    now_br = datetime.now(ZoneInfo("America/Sao_Paulo"))
    selected_cost_center = parse_cost_center_filter(cost_center)

    selected_date = now_br.date()
    if date_ref:
        try:
            selected_date = datetime.strptime(date_ref, "%Y-%m-%d").date()
        except Exception:
            pass
    selected_date_str = selected_date.strftime("%Y-%m-%d")

    employees_all = session.exec(
        select(models.Employee).where(models.Employee.status != "fired")
    ).all()
    employees = [e for e in employees_all if employee_matches_cost_center(e, selected_cost_center)]
    employee_by_id = {e.id: e for e in employees if e.id is not None}
    employee_ids = set(employee_by_id.keys())

    employee_id_list = list(employee_ids)
    if employee_id_list:
        routines = session.exec(
            select(models.EmployeeRoutine)
            .where(models.EmployeeRoutine.date == selected_date_str)
            .where(models.EmployeeRoutine.employee_id.in_(employee_id_list))
        ).all()
    else:
        routines = []
    routine_by_employee = {r.employee_id: r for r in routines}

    # Cost centers summary (Empresa / Centro de Custo)
    cost_centers_summary = {}
    cost_center_options = ["Todos"]
    for emp in employees_all:
        lbl = cost_center_display_label(emp.cost_center)
        if lbl not in cost_centers_summary:
            cost_centers_summary[lbl] = {"headcount": 0, "target": 0, "away": 0}
        away = 1 if (emp.status or "").lower() in {"away", "vacation", "sick", "day_off"} else 0
        cost_centers_summary[lbl]["headcount"] += max(0, 1 - away)
        cost_centers_summary[lbl]["away"] += away
        cost_centers_summary[lbl]["target"] = cost_centers_summary[lbl]["headcount"]
    cost_center_options.extend(sorted(k for k in cost_centers_summary.keys() if k and k != "Sem Centro"))
    if "Sem Centro" in cost_centers_summary:
        cost_center_options.append("Sem Centro")

    # Delivery routes for selected day (filter by employee cost_center)
    if employee_id_list:
        routes = session.exec(
            select(models.Route)
            .where(models.Route.type == "delivery")
            .where(models.Route.date == selected_date_str)
            .where(models.Route.employee_id.in_(employee_id_list))
        ).all()
    else:
        routes = []
    client_ids = list({r.client_id for r in routes if r.client_id is not None})
    clients = session.exec(select(models.Client).where(models.Client.id.in_(client_ids))).all() if client_ids else []
    client_by_id = {c.id: c for c in clients if c.id is not None}

    completed_statuses = {"entregue", "devolucao"}
    completed_routes = [r for r in routes if (r.delivery_status or "").lower() in completed_statuses]
    total_tonnage = float(sum(float(r.tonnage or 0.0) for r in routes))
    completed_count = len(completed_routes)

    durations_hours = []
    for r in completed_routes:
        d = route_duration_minutes(r)
        if d and d > 0:
            durations_hours.append(d / 60.0)
    total_hours = sum(durations_hours)
    avg_kgh = (total_tonnage / total_hours) if total_hours > 0 else 0.0

    # Faltas/atestados from routine (fallback to employee status when absent routine not present)
    ausentes = []
    atestados = []
    for e in employees:
        routine = routine_by_employee.get(e.id)
        r_status = (routine.routine if routine else "").lower()
        e_status = (e.status or "").lower()

        if r_status == "absent" or e_status == "away":
            ausentes.append({"name": e.name, "full_name": e.name, "cost_center": cost_center_display_label(e.cost_center) or "-", "status": "Falta"})
        if r_status == "sick" or e_status == "sick":
            atestados.append({"name": e.name, "full_name": e.name, "cost_center": cost_center_display_label(e.cost_center) or "-", "status": "Atestado"})

    # HR cards
    birthdays = []
    for e in employees:
        if not e.birthday:
            continue
        bday = e.birthday.date()
        if bday.month == selected_date.month:
            birthdays.append({
                "name": e.name,
                "day": bday.day,
                "is_today": bday.day == selected_date.day,
            })
    birthdays.sort(key=lambda x: x["day"])

    experience_expiring = []
    for e in employees:
        if not e.admission_date:
            continue
        adm = e.admission_date.date()
        for marker, label in ((45, "45 Dias"), (90, "90 Dias")):
            dt = adm + timedelta(days=marker)
            delta = (dt - selected_date).days
            if 0 <= delta <= 30:
                experience_expiring.append({
                    "name": e.name,
                    "full_name": e.name,
                    "date": dt.strftime("%d/%m"),
                    "days": delta,
                    "type": label,
                })
    experience_expiring.sort(key=lambda x: x["days"])

    active_vacation = []
    upcoming_vacation = []
    for e in employees:
        if not e.vacation_start or not e.vacation_end:
            continue
        vs = e.vacation_start.date()
        ve = e.vacation_end.date()
        if vs <= selected_date <= ve:
            active_vacation.append({
                "name": e.name,
                "end_date": ve.strftime("%d/%m"),
                "days_left": f"{(ve - selected_date).days + 1}d",
            })
        elif vs > selected_date:
            delta_d = (vs - selected_date).days
            upcoming_vacation.append({
                "name": e.name,
                "full_name": e.name,
                "cost_center": cost_center_display_label(e.cost_center) or "-",
                "shift": cost_center_display_label(e.cost_center) or "-",
                "start_date": vs.strftime("%Y-%m-%d"),
                "start_in": f"{delta_d}d",
                "days_until": f"{delta_d}d",
            })
    upcoming_vacation.sort(key=lambda x: int(str(x["start_in"]).replace("d", "")))

    # Live delivery cards grouped by driver (todos os motoristas com rota no dia)
    employee_by_id_all = {e.id: e for e in employees_all if e.id is not None}
    all_emp_ids_with_routes = list({r.employee_id for r in routes})
    live_buckets = {}
    for emp_id in all_emp_ids_with_routes:
        emp = employee_by_id.get(emp_id) or employee_by_id_all.get(emp_id)
        if not emp:
            continue
        live_buckets[emp_id] = {"employee_name": emp.name, "photo_url": emp.photo_url, "routes": []}
    for r in routes:
        st = (r.delivery_status or "").lower()
        if st not in {"pendente", "iniciada", "entregue", "devolucao"}:
            continue
        bucket = live_buckets.get(r.employee_id)
        if not bucket:
            continue
        d_m = route_duration_minutes(r) or 0
        client_name = client_by_id.get(r.client_id).name if client_by_id.get(r.client_id) else f"Cliente #{r.client_id}"
        oe = iniciada_elapsed_wall_minutes(r, selected_date, now_br)
        start_display = (r.delivery_started_at or r.start_time or "--:--") if st == "iniciada" else "--:--"
        rd = {
            "client": client_name,
            "start_time": start_display,
            "duration_mins": d_m,
            "tonnage": float(r.tonnage or 0.0),
            "delivery_status": st,
        }
        if oe is not None:
            rd["open_elapsed_minutes"] = oe
        bucket["routes"].append(rd)
    sessions_today = session.exec(
        select(models.DeliverySession)
        .where(models.DeliverySession.date == selected_date_str)
        .where(models.DeliverySession.employee_id.in_(all_emp_ids_with_routes))
    ).all() if all_emp_ids_with_routes else []
    session_closed_by_emp = {s.employee_id: (s.status or "").lower() == "closed" for s in sessions_today}
    session_open_by_emp = {s.employee_id for s in sessions_today if (s.status or "").lower() == "open"}
    session_plate_by_emp = {}
    for s in sessions_today:
        if s.employee_id and (getattr(s, "vehicle_plate", None) or "").strip():
            session_plate_by_emp.setdefault(s.employee_id, (s.vehicle_plate or "").strip())
    session_helpers_by_emp = {s.employee_id: _parse_session_helpers(s.helpers_json) for s in sessions_today if getattr(s, "helpers_json", None)}
    for emp_id, bucket in live_buckets.items():
        emp_routes = [r for r in routes if r.employee_id == emp_id]
        bucket["employee_id"] = emp_id
        bucket["total_deliveries"] = len(emp_routes)
        bucket["completed_deliveries"] = len(
            [r for r in emp_routes if (r.delivery_status or "").lower() in ("entregue", "devolucao")]
        )
        bucket["plate"] = next(
            (r.delivery_vehicle_plate or "").strip() or None
            for r in emp_routes if (r.delivery_vehicle_plate or "").strip()
        ) if emp_routes else None
        if not bucket["plate"] and session_plate_by_emp.get(emp_id):
            bucket["plate"] = session_plate_by_emp[emp_id]
        helper_ids = []
        for r in emp_routes:
            helper_ids.extend(_parse_route_helper_ids(getattr(r, "delivery_helpers_json", None)))
        route_helper_names = list(dict.fromkeys(
            (employee_by_id_all.get(hid).name if employee_by_id_all.get(hid) else None) or f"Ajudante #{hid}"
            for hid in helper_ids if hid
        ))
        bucket["helper_count"] = len(route_helper_names)
        bucket["helper_names"] = route_helper_names[:3]
        if not bucket.get("helper_names") and session_helpers_by_emp.get(emp_id):
            session_helper_names = [str(name).strip() for name in (session_helpers_by_emp.get(emp_id) or []) if str(name or "").strip()]
            bucket["helper_count"] = len(session_helper_names)
            bucket["helper_names"] = session_helper_names[:3]
        bucket["total_kg"] = round(sum(float(r.tonnage or 0.0) for r in emp_routes), 2)
        open_routes_count = len([r for r in emp_routes if (r.delivery_status or "").lower() == "iniciada"])
        finished_times = [(r.delivery_finished_at or r.end_time or "") for r in emp_routes if (r.delivery_status or "").lower() in ("entregue", "devolucao") and (r.delivery_finished_at or r.end_time)]
        last_finished_at = max(finished_times, key=lambda t: (t or "00:00")) if finished_times else None
        minutes_without_open = 0
        if open_routes_count == 0 and last_finished_at:
            try:
                parts = str(last_finished_at).strip().split(":")
                h, m = int(parts[0]), int(parts[1]) if len(parts) > 1 else 0
                finished_dt = datetime(now_br.year, now_br.month, now_br.day, h, m, 0, tzinfo=ZoneInfo("America/Sao_Paulo"))
                minutes_without_open = max(0, int((now_br - finished_dt).total_seconds() // 60))
            except Exception:
                pass
        bucket["minutes_without_open_client"] = minutes_without_open
        has_delivery_started = any((r.delivery_status or "").lower() in ("iniciada", "entregue", "devolucao") for r in emp_routes)
        session_started = emp_id in session_open_by_emp
        has_started = has_delivery_started or session_started
        all_delivered = bucket["total_deliveries"] > 0 and bucket["completed_deliveries"] == bucket["total_deliveries"]
        route_ended = session_closed_by_emp.get(emp_id, False)
        if route_ended:
            bucket["route_state"] = "closed"
        elif not has_started:
            bucket["route_state"] = "not_started"
        elif has_started and not has_delivery_started:
            bucket["route_state"] = "route_started"
        elif all_delivered:
            bucket["route_state"] = "all_delivered"
        else:
            bucket["route_state"] = "in_progress"
        bucket["route_ended"] = route_ended
        _emp_ws = employee_by_id.get(emp_id) or employee_by_id_all.get(emp_id)
        bucket["work_shift"] = (getattr(_emp_ws, "work_shift", None) or "Manhã").strip()
        bucket.update(
            compute_delivery_projection(
                bucket,
                now_br,
                operation_start_hour=DELIVERY_OPERATION_START_HOUR,
                operation_end_hour=DELIVERY_OPERATION_END_HOUR,
                baseline_crew_size=DELIVERY_BASE_CREW_SIZE,
                attention_buffer_minutes=DELIVERY_ATTENTION_BUFFER_MINUTES,
            )
        )

    def _live_sort_key(x):
        state = x.get("route_state") or "in_progress"
        open_count = (x.get("total_deliveries") or 0) - (x.get("completed_deliveries") or 0)
        alert_level = str(x.get("route_alert_level") or "ok").strip().lower()
        alert_rank = 0 if alert_level == "critico" else 1 if alert_level == "atencao" else 2
        delay = int(x.get("projected_finish_delay_minutes") or 0)
        if state == "closed":
            return (4, 0, 0, 0)
        if state == "not_started":
            return (3, alert_rank, -delay, -open_count)
        if state == "all_delivered":
            return (3, 0, 0, -open_count)
        if state == "route_started":
            return (1, alert_rank, -delay, -open_count)
        return (1, alert_rank, -delay, -open_count)

    live_separation = list(live_buckets.values())
    live_separation.sort(key=_live_sort_key)
    rotas_paradas_count = sum(1 for b in live_separation if (b.get("route_state") or "") == "not_started")
    # Ativas = ainda entregando ou só iniciou; concluídas (100% ou sessão encerrada) saem das ativas
    rotas_ativas_count = sum(
        1 for b in live_separation if (b.get("route_state") or "") in ("in_progress", "route_started")
    )
    rotas_concluidas_count = sum(
        1 for b in live_separation if (b.get("route_state") or "") in ("closed", "all_delivered")
    )
    _tv_shift_kv = tv_shift_alert_counts(live_separation, now_br)

    # Alertas tempo real: clientes com parada iniciada há mais de 20 minutos (só rotas iniciadas via mobile)
    alerts_clients_over_20min = []
    for r in routes:
        if (r.delivery_status or "").lower() != "iniciada" or r.driver_lat_start is None:
            continue
        started_at_str = r.delivery_started_at or r.start_time
        if not started_at_str or started_at_str.strip() in ("", "00:00"):
            continue
        try:
            parts = str(started_at_str).strip().split(":")
            h, m = int(parts[0]), int(parts[1]) if len(parts) > 1 else 0
            started_dt = datetime(
                selected_date.year, selected_date.month, selected_date.day, h, m, 0,
                tzinfo=ZoneInfo("America/Sao_Paulo"),
            )
            elapsed_seconds = (now_br - started_dt).total_seconds()
            elapsed_mins = int(elapsed_seconds // 60)
            if elapsed_mins < 20:
                continue
            client_name = (client_by_id.get(r.client_id).name if client_by_id.get(r.client_id) else None) or f"Cliente #{r.client_id}"
            emp = employee_by_id.get(r.employee_id)
            driver_name = emp.name if emp else f"Motorista #{r.employee_id}"
            alerts_clients_over_20min.append({
                "client_name": client_name,
                "driver_name": driver_name,
                "minutes": elapsed_mins,
                "route_id": r.id,
                "started_at": started_at_str,
                "plate": (r.delivery_vehicle_plate or "").strip() or None,
            })
        except Exception:
            continue
    alerts_clients_over_20min.sort(key=lambda x: -x["minutes"])

    selected_headcount = sum(1 for e in employees if (e.status or "").lower() not in {"away", "vacation", "sick", "day_off"})
    selected_target = selected_headcount

    # Devolução no dia (para painel TV e alertas) — critério canônico (% rotas concluídas)
    routes_devolucao = [r for r in routes if _is_operational_route_devolucao(r)]
    n_dev_dia, n_done_dia = counts_devolucao_rotas_concluidas(routes)
    devolucao_items = []
    dev_clients_by_driver: Dict[str, List[str]] = {}
    dev_driver_order: List[str] = []
    for r in routes_devolucao:
        c = client_by_id.get(r.client_id)
        emp = employee_by_id.get(r.employee_id)
        c_name = c.name if c else f"Cliente #{r.client_id}"
        driver_name = emp.name if emp else f"Motorista #{r.employee_id}"
        fancy = getattr(c, "fancy_name", "") if c else ""
        address = getattr(c, "address", "") if c else ""
        neighborhood = getattr(c, "neighborhood", "") if c else ""
        city = getattr(c, "city", "") if c else ""
        cep = getattr(c, "cep", "") if c else ""
        kg = round(float(getattr(r, "devolucao_volume", None) or r.tonnage or 0), 2)
        valor = round(float(getattr(r, "valor_devolucao", None) or 0), 2)
        devolucao_items.append({
            "route_id": r.id,
            "client_name": c_name,
            "fancy_name": fancy,
            "address": address,
            "neighborhood": neighborhood,
            "city": city,
            "cep": cep,
            "kg": kg,
            "valor": valor,
            "date": getattr(r, "date", selected_date_str),
            "driver_name": driver_name,
        })
        if driver_name not in dev_clients_by_driver:
            dev_driver_order.append(driver_name)
            dev_clients_by_driver[driver_name] = []
        dev_clients_by_driver[driver_name].append(c_name)
    items_by_driver = [
        {"driver_name": driver_name, "clients": dev_clients_by_driver[driver_name]}
        for driver_name in dev_driver_order
    ]

    devolucao_dia = {
        "count": n_dev_dia,
        "total_kg": round(sum(float(getattr(r, "devolucao_volume", None) or r.tonnage or 0) for r in routes_devolucao), 2),
        "total_valor": round(sum(float(getattr(r, "valor_devolucao", None) or 0) for r in routes_devolucao), 2),
        "total_entregas": n_done_dia,
        "pct": pct_devolucao_sobre_rotas_concluidas(routes),
        "items_by_driver": items_by_driver,
        "items_list": devolucao_items,
    }
    month_start = selected_date.replace(day=1)
    if selected_date.month == 12:
        next_month_start = selected_date.replace(year=selected_date.year + 1, month=1, day=1)
    else:
        next_month_start = selected_date.replace(month=selected_date.month + 1, day=1)
    month_start_str = month_start.strftime("%Y-%m-%d")
    month_end_str = (next_month_start - timedelta(days=1)).strftime("%Y-%m-%d")
    from utils.business_calendar import competence_date_str
    window_start = (month_start - timedelta(days=10)).strftime("%Y-%m-%d")
    window_end = (next_month_start + timedelta(days=10)).strftime("%Y-%m-%d")
    routes_month_window = session.exec(
        select(models.Route)
        .where(models.Route.type == "delivery")
        .where(models.Route.date >= window_start)
        .where(models.Route.date <= window_end)
        .where(models.Route.employee_id.in_(employee_ids))
    ).all()
    routes_month = []
    for r in routes_month_window:
        comp = competence_date_str(getattr(r, "date", None)) or str(getattr(r, "date", "") or "")[:10]
        if month_start_str <= comp <= month_end_str:
            routes_month.append(r)
    _, n_done_mes = counts_devolucao_rotas_concluidas(routes_month)
    mes_valor_reg, mes_cnt_reg = _kpi_devolucao_mes_registros(
        session, month_start_str, month_end_str, employee_id_list if employee_id_list else None
    )
    devolucao_mes = {
        "count": mes_cnt_reg,
        "total_entregas": n_done_mes,
        "total_valor": round(mes_valor_reg, 2),
        "pct": pct_devolucao_sobre_rotas_concluidas(routes_month),
    }

    clientes_alto_indice = []
    if is_tv:
        # Só rota do dia: paradas de hoje ainda não entregues (pendente/iniciada) e com alto índice de devolução (30d).
        pending_today = [
            (r.client_id, r.employee_id)
            for r in routes
            if r.client_id is not None
            and r.employee_id is not None
            and (r.delivery_status or "").strip().lower() not in ("entregue", "devolucao")
        ]
        date_30d_ago = (selected_date - timedelta(days=30)).strftime("%Y-%m-%d")
        devolucoes_30d = session.exec(
            select(models.Devolucao)
            .where(models.Devolucao.data_romaneio >= date_30d_ago)
            .where(models.Devolucao.data_romaneio <= selected_date_str)
            .order_by(desc(models.Devolucao.data_romaneio), desc(models.Devolucao.id))
        ).all()
        client_dev_count = {}
        for d in devolucoes_30d:
            cid = d.client_id
            client_dev_count[cid] = client_dev_count.get(cid, 0) + 1
        client_name_today = {
            c.id: (getattr(c, "name", None) or getattr(c, "razao_social", None) or f"Cliente #{c.id}")
            for c in clients
        }
        seen_pair = set()
        for cid, driver_id in pending_today:
            if (cid, driver_id) in seen_pair or client_dev_count.get(cid, 0) < 2:
                continue
            seen_pair.add((cid, driver_id))
            emp = employee_by_id.get(driver_id)
            clientes_alto_indice.append({
                "client_name": client_name_today.get(cid) or f"Cliente #{cid}",
                "driver_name": emp.name if emp else f"Motorista #{driver_id}",
                "count": client_dev_count[cid],
            })
        clientes_alto_indice.sort(key=lambda x: -x["count"])
        clientes_alto_indice = clientes_alto_indice[:10]

    tonnage_delivered_today = float(sum(float(r.tonnage or 0.0) for r in completed_routes))
    dashboard_payload = {
        "cost_centers_summary": cost_centers_summary,
        "devolucao_dia": devolucao_dia,
        "devolucao_mes": devolucao_mes,
        "kpi": {
            "tonnage": round(total_tonnage, 2),
            "avg_kgh": round(avg_kgh, 1),
            "completed_routes_count": completed_count,
            "routes_total": len(routes),
            "headcount": selected_headcount,
            "target_headcount": selected_target,
            "rotas_paradas": rotas_paradas_count,
            "rotas_ativas": rotas_ativas_count,
            "rotas_concluidas": rotas_concluidas_count,
        },
        "alerts": {
            "ausentes": ausentes,
            "atestados": atestados,
            "vacations_upcoming": upcoming_vacation,
            "clients_over_20min": alerts_clients_over_20min,
        },
        "hr": {
            "birthdays": birthdays,
            "experience_expiring": experience_expiring,
            "vacation": active_vacation,
        },
        "live_separation": live_separation,
    }
    if is_tv_like:
        dashboard_payload["clientes_alto_indice_devolucao"] = clientes_alto_indice
        dashboard_payload["tv_shift_alerts"] = {
            "atencao": _tv_shift_kv["atencao"],
            "critico": _tv_shift_kv["critico"],
        }
        dashboard_payload["operational_shift"] = _tv_shift_kv["operational_shift"]

    informativo_ctx: Optional[Dict[str, Any]] = None
    if not is_tv_like:
        informativo_ctx = _build_informativo_extras(
            session,
            selected_date,
            selected_date_str,
            employees_all,
            dashboard_payload,
            len(routes),
            completed_count,
            tonnage_delivered_today,
            total_tonnage,
            motorista_ids_scope=employee_id_list if employee_id_list else None,
        )

    template_name = "dashboard_informativo.html"
    if is_tv_fire:
        template_name = "dashboard_tv_fire.html"
    elif is_tv:
        template_name = "dashboard_tv.html"
    return templates.TemplateResponse(
        template_name,
        {
            "request": request,
            "dashboard": dashboard_payload,
            "informativo": informativo_ctx or {},
            "current_cost_center": selected_cost_center or "Todos",
            "cost_center_options": cost_center_options,
            "current_date": selected_date_str,
            "data_source_caption": _dashboard_data_source_caption() if not is_tv_like else "",
        },
    )


@app.get("/api/dashboard/tv-data", response_class=JSONResponse)
async def api_dashboard_tv_data(
    request: Request,
    date_ref: Optional[str] = Query(None, alias="date"),
    cost_center: Optional[str] = None,
    session: Session = Depends(get_session),
):
    """Payload JSON do dashboard para painel TV (atualização parcial a cada 1 min)."""
    def _s(v: Any) -> str:
        return str(v or "").strip()

    def _sl(v: Any) -> str:
        return _s(v).lower()

    def _sf(v: Any) -> float:
        try:
            n = float(v or 0.0)
            return n if math.isfinite(n) else 0.0
        except Exception:
            return 0.0

    user = get_current_user(request)
    if not user:
        return JSONResponse(
            {"error": "Não autorizado"},
            status_code=401,
            headers={"Cache-Control": "no-store, max-age=0"},
        )
    no_store_headers = {"Cache-Control": "no-store, max-age=0", "Pragma": "no-cache"}
    try:
        now_br = datetime.now(ZoneInfo("America/Sao_Paulo"))
        selected_date = now_br.date()
        if date_ref:
            try:
                selected_date = datetime.strptime(date_ref, "%Y-%m-%d").date()
            except Exception:
                pass
        selected_date_str = selected_date.strftime("%Y-%m-%d")
        selected_cc = parse_cost_center_filter(cost_center or "Todos")
        employees_all = session.exec(select(models.Employee).where(models.Employee.status != "fired")).all()
        employees = [e for e in employees_all if employee_matches_cost_center(e, selected_cc)]
        employee_ids = list({e.id for e in employees if e.id is not None})
        employee_by_id = {e.id: e for e in employees if e.id is not None}
        if not employee_ids:
            return JSONResponse(
                {
                    "date": selected_date_str,
                    "cost_center": selected_cc or "Todos",
                    "dashboard": {
                        "kpi": {"rotas_paradas": 0, "rotas_ativas": 0, "rotas_concluidas": 0},
                        "alerts": {"clients_over_20min": []},
                        "live_separation": [],
                        "devolucao_dia": {},
                        "devolucao_mes": {},
                        "cost_centers_summary": {},
                        "tv_shift_alerts": {"atencao": 0, "critico": 0},
                        "operational_shift": operational_shift_br(now_br),
                    },
                },
                headers=no_store_headers,
            )

        routes = session.exec(
            select(models.Route)
            .where(models.Route.type == "delivery")
            .where(models.Route.date == selected_date_str)
            .where(models.Route.employee_id.in_(employee_ids))
        ).all()
        client_ids = list({r.client_id for r in routes if r.client_id is not None})
        clients = session.exec(select(models.Client).where(models.Client.id.in_(client_ids))).all() if client_ids else []
        client_by_id = {c.id: c for c in clients if c.id is not None}

        completed_statuses = {"entregue", "devolucao"}
        completed_routes = [r for r in routes if _sl(getattr(r, "delivery_status", None)) in completed_statuses]
        total_tonnage = float(sum(_sf(getattr(r, "tonnage", 0.0)) for r in routes))
        durations_hours = []
        for r in completed_routes:
            d = route_duration_minutes(r)
            if d and d > 0:
                durations_hours.append(d / 60.0)
        total_hours = sum(durations_hours)
        avg_kgh = (total_tonnage / total_hours) if total_hours > 0 else 0.0

        employee_by_id_all = {e.id: e for e in employees_all if e.id is not None}
        all_emp_ids_with_routes = list({r.employee_id for r in routes if r.employee_id is not None})
        live_buckets = {}
        for emp_id in all_emp_ids_with_routes:
            emp = employee_by_id.get(emp_id) or employee_by_id_all.get(emp_id)
            if not emp:
                continue
            live_buckets[emp_id] = {"employee_name": emp.name, "photo_url": getattr(emp, "photo_url", None), "routes": []}

        for r in routes:
            st = _sl(getattr(r, "delivery_status", None))
            if st not in {"pendente", "iniciada", "entregue", "devolucao"}:
                continue
            bucket = live_buckets.get(r.employee_id)
            if not bucket:
                continue
            d_m = route_duration_minutes(r) or 0
            c = client_by_id.get(r.client_id)
            client_name = (getattr(c, "name", None) or getattr(c, "razao_social", None)) if c else f"Cliente #{r.client_id}"
            oe = iniciada_elapsed_wall_minutes(r, selected_date, now_br)
            rd = {
                "client": client_name,
                "start_time": (r.delivery_started_at or r.start_time or "--:--") if st == "iniciada" else "--:--",
                "duration_mins": d_m,
                "tonnage": _sf(getattr(r, "tonnage", 0.0)),
                "delivery_status": st,
            }
            if oe is not None:
                rd["open_elapsed_minutes"] = oe
            bucket["routes"].append(rd)

        sessions_today = session.exec(
            select(models.DeliverySession)
            .where(models.DeliverySession.date == selected_date_str)
            .where(models.DeliverySession.employee_id.in_(all_emp_ids_with_routes))
        ).all() if all_emp_ids_with_routes else []
        session_closed_by_emp = {s.employee_id: _sl(getattr(s, "status", None)) == "closed" for s in sessions_today}
        session_open_by_emp = {s.employee_id for s in sessions_today if _sl(getattr(s, "status", None)) == "open"}
        session_plate_by_emp = {}
        for s in sessions_today:
            if s.employee_id and _s(getattr(s, "vehicle_plate", None)):
                session_plate_by_emp.setdefault(s.employee_id, _s(getattr(s, "vehicle_plate", None)))
        session_helpers_by_emp = {s.employee_id: _parse_session_helpers(s.helpers_json) for s in sessions_today if getattr(s, "helpers_json", None)}

        for emp_id, bucket in live_buckets.items():
            emp_routes = [r for r in routes if r.employee_id == emp_id]
            bucket["employee_id"] = emp_id
            bucket["total_deliveries"] = len(emp_routes)
            bucket["completed_deliveries"] = len([r for r in emp_routes if _sl(getattr(r, "delivery_status", None)) in ("entregue", "devolucao")])
            bucket["plate"] = next((_s(getattr(r, "delivery_vehicle_plate", None)) or None for r in emp_routes if _s(getattr(r, "delivery_vehicle_plate", None))), None) if emp_routes else None
            if not bucket["plate"] and session_plate_by_emp.get(emp_id):
                bucket["plate"] = session_plate_by_emp[emp_id]
            helper_ids = []
            for r in emp_routes:
                helper_ids.extend(_parse_route_helper_ids(getattr(r, "delivery_helpers_json", None)))
            route_helper_names = list(dict.fromkeys(
                (employee_by_id_all.get(hid).name if employee_by_id_all.get(hid) else None) or f"Ajud. #{hid}"
                for hid in helper_ids if hid
            ))
            bucket["helper_count"] = len(route_helper_names)
            bucket["helper_names"] = route_helper_names[:3]
            if not bucket.get("helper_names") and session_helpers_by_emp.get(emp_id):
                session_helper_names = [str(name).strip() for name in (session_helpers_by_emp.get(emp_id) or []) if str(name or "").strip()]
                bucket["helper_count"] = len(session_helper_names)
                bucket["helper_names"] = session_helper_names[:3]
            bucket["total_kg"] = round(sum(_sf(getattr(r, "tonnage", 0.0)) for r in emp_routes), 2)
            open_routes_count = len([r for r in emp_routes if _sl(getattr(r, "delivery_status", None)) == "iniciada"])
            finished_times = [
                (r.delivery_finished_at or r.end_time or "")
                for r in emp_routes
                if _sl(getattr(r, "delivery_status", None)) in ("entregue", "devolucao") and (r.delivery_finished_at or r.end_time)
            ]
            last_finished_at = max(finished_times, key=lambda t: (t or "00:00")) if finished_times else None
            minutes_without_open = 0
            if open_routes_count == 0 and last_finished_at:
                try:
                    parts = str(last_finished_at).strip().split(":")
                    h, m = int(parts[0]), int(parts[1]) if len(parts) > 1 else 0
                    finished_dt = datetime(now_br.year, now_br.month, now_br.day, h, m, 0, tzinfo=ZoneInfo("America/Sao_Paulo"))
                    minutes_without_open = max(0, int((now_br - finished_dt).total_seconds() // 60))
                except Exception:
                    pass
            bucket["minutes_without_open_client"] = minutes_without_open
            has_delivery_started = any(_sl(getattr(r, "delivery_status", None)) in ("iniciada", "entregue", "devolucao") for r in emp_routes)
            session_started = emp_id in session_open_by_emp
            has_started = has_delivery_started or session_started
            all_delivered = bucket["total_deliveries"] > 0 and bucket["completed_deliveries"] == bucket["total_deliveries"]
            route_ended = session_closed_by_emp.get(emp_id, False)
            if route_ended:
                bucket["route_state"] = "closed"
            elif not has_started:
                bucket["route_state"] = "not_started"
            elif has_started and not has_delivery_started:
                bucket["route_state"] = "route_started"
            elif all_delivered:
                bucket["route_state"] = "all_delivered"
            else:
                bucket["route_state"] = "in_progress"
            bucket["route_ended"] = route_ended
            _emp_ws2 = employee_by_id.get(emp_id) or employee_by_id_all.get(emp_id)
            bucket["work_shift"] = _s(getattr(_emp_ws2, "work_shift", None) or "Manhã")
            bucket.update(
                compute_delivery_projection(
                    bucket,
                    now_br,
                    operation_start_hour=DELIVERY_OPERATION_START_HOUR,
                    operation_end_hour=DELIVERY_OPERATION_END_HOUR,
                    baseline_crew_size=DELIVERY_BASE_CREW_SIZE,
                    attention_buffer_minutes=DELIVERY_ATTENTION_BUFFER_MINUTES,
                )
            )

        def _live_sort_key(x):
            state = x.get("route_state") or "in_progress"
            open_count = (x.get("total_deliveries") or 0) - (x.get("completed_deliveries") or 0)
            alert_level = str(x.get("route_alert_level") or "ok").strip().lower()
            alert_rank = 0 if alert_level == "critico" else 1 if alert_level == "atencao" else 2
            delay = int(x.get("projected_finish_delay_minutes") or 0)
            if state == "closed":
                return (4, 0, 0, 0)
            if state == "not_started":
                return (3, alert_rank, -delay, -open_count)
            if state == "all_delivered":
                return (3, 0, 0, -open_count)
            if state == "route_started":
                return (1, alert_rank, -delay, -open_count)
            return (1, alert_rank, -delay, -open_count)

        live_separation = list(live_buckets.values())
        live_separation.sort(key=_live_sort_key)
        rotas_paradas_count = sum(1 for b in live_separation if (b.get("route_state") or "") == "not_started")
        rotas_ativas_count = sum(1 for b in live_separation if (b.get("route_state") or "") in ("in_progress", "route_started"))
        rotas_concluidas_count = sum(1 for b in live_separation if (b.get("route_state") or "") in ("closed", "all_delivered"))
        _tsa_api = tv_shift_alert_counts(live_separation, now_br)

        routes_devolucao = [r for r in routes if _is_operational_route_devolucao(r)]
        n_dev_dia_tv, n_done_dia_tv = counts_devolucao_rotas_concluidas(routes)
        devolucao_items = []
        dev_clients_by_driver_api: Dict[str, List[str]] = {}
        dev_driver_order_api: List[str] = []
        for r in routes_devolucao:
            c = client_by_id.get(r.client_id)
            emp = employee_by_id.get(r.employee_id)
            c_name = (getattr(c, "name", None) or getattr(c, "razao_social", None)) if c else f"Cliente #{r.client_id}"
            driver_name = emp.name if emp else f"Motorista #{r.employee_id}"
            devolucao_items.append({
                "route_id": r.id,
                "client_name": c_name,
                "fancy_name": getattr(c, "fancy_name", "") if c else "",
                "address": getattr(c, "address", "") if c else "",
                "neighborhood": getattr(c, "neighborhood", "") if c else "",
                "city": getattr(c, "city", "") if c else "",
                "cep": getattr(c, "cep", "") if c else "",
                "kg": round(_sf(getattr(r, "devolucao_volume", None) or getattr(r, "tonnage", 0)), 2),
                "valor": round(_sf(getattr(r, "valor_devolucao", None)), 2),
                "date": getattr(r, "date", selected_date_str),
                "driver_name": driver_name,
            })
            if driver_name not in dev_clients_by_driver_api:
                dev_driver_order_api.append(driver_name)
                dev_clients_by_driver_api[driver_name] = []
            dev_clients_by_driver_api[driver_name].append(c_name)
        items_by_driver_api = [{"driver_name": d, "clients": dev_clients_by_driver_api[d]} for d in dev_driver_order_api]

        devolucao_dia = {
            "count": n_dev_dia_tv,
            "total_kg": round(sum(_sf(getattr(r, "devolucao_volume", None) or getattr(r, "tonnage", 0)) for r in routes_devolucao), 2),
            "total_valor": round(sum(_sf(getattr(r, "valor_devolucao", None)) for r in routes_devolucao), 2),
            "total_entregas": n_done_dia_tv,
            "pct": pct_devolucao_sobre_rotas_concluidas(routes),
            "items_by_driver": items_by_driver_api,
            "items_list": devolucao_items,
        }

        month_start = selected_date.replace(day=1)
        next_month_start = selected_date.replace(year=selected_date.year + 1, month=1, day=1) if selected_date.month == 12 else selected_date.replace(month=selected_date.month + 1, day=1)
        month_start_str = month_start.strftime("%Y-%m-%d")
        month_end_str = (next_month_start - timedelta(days=1)).strftime("%Y-%m-%d")
        from utils.business_calendar import competence_date_str
        window_start = (month_start - timedelta(days=10)).strftime("%Y-%m-%d")
        window_end = (next_month_start + timedelta(days=10)).strftime("%Y-%m-%d")
        routes_month_window = session.exec(
            select(models.Route)
            .where(models.Route.type == "delivery")
            .where(models.Route.date >= window_start)
            .where(models.Route.date <= window_end)
            .where(models.Route.employee_id.in_(employee_ids))
        ).all()
        routes_month = []
        for r in routes_month_window:
            comp = competence_date_str(getattr(r, "date", None)) or str(getattr(r, "date", "") or "")[:10]
            if month_start_str <= comp <= month_end_str:
                routes_month.append(r)
        _, n_done_mes_tv = counts_devolucao_rotas_concluidas(routes_month)
        mes_valor_reg, mes_cnt_reg = _kpi_devolucao_mes_registros(session, month_start_str, month_end_str, employee_ids if employee_ids else None)
        devolucao_mes = {
            "count": mes_cnt_reg,
            "total_entregas": n_done_mes_tv,
            "total_valor": round(mes_valor_reg, 2),
            "pct": pct_devolucao_sobre_rotas_concluidas(routes_month),
        }

        alerts_over_20min = []
        for r in routes:
            if _sl(getattr(r, "delivery_status", None)) != "iniciada" or r.driver_lat_start is None:
                continue
            started_at_str = r.delivery_started_at or r.start_time
            if not started_at_str or _s(started_at_str) in ("", "00:00"):
                continue
            try:
                parts = str(started_at_str).strip().split(":")
                h, m = int(parts[0]), int(parts[1]) if len(parts) > 1 else 0
                started_dt = datetime(selected_date.year, selected_date.month, selected_date.day, h, m, 0, tzinfo=ZoneInfo("America/Sao_Paulo"))
                elapsed_mins = int((now_br - started_dt).total_seconds() // 60)
                if elapsed_mins < 20:
                    continue
                c = client_by_id.get(r.client_id)
                client_name = (getattr(c, "name", None) or getattr(c, "razao_social", None)) if c else f"Cliente #{r.client_id}"
                emp = employee_by_id.get(r.employee_id)
                alerts_over_20min.append({
                    "client_name": client_name,
                    "driver_name": emp.name if emp else f"Motorista #{r.employee_id}",
                    "minutes": elapsed_mins,
                    "started_at": started_at_str,
                    "plate": _s(getattr(r, "delivery_vehicle_plate", None)) or None,
                })
            except Exception:
                continue
        alerts_over_20min.sort(key=lambda x: -x["minutes"])

        date_30d_ago = (now_br.date() - timedelta(days=30)).strftime("%Y-%m-%d")
        devolucoes_30d = session.exec(
            select(models.Devolucao)
            .where(models.Devolucao.data_romaneio >= date_30d_ago)
            .where(models.Devolucao.data_romaneio <= selected_date_str)
            .order_by(desc(models.Devolucao.data_romaneio), desc(models.Devolucao.id))
        ).all()
        client_dev_count = {}
        for d in devolucoes_30d:
            cid = d.client_id
            client_dev_count[cid] = client_dev_count.get(cid, 0) + 1
        pending_today = [
            (r.client_id, r.employee_id)
            for r in routes
            if r.client_id is not None
            and r.employee_id is not None
            and _sl(getattr(r, "delivery_status", None)) not in ("entregue", "devolucao")
        ]
        client_name_today = {c.id: (getattr(c, "name", None) or getattr(c, "razao_social", None) or f"Cliente #{c.id}") for c in clients}
        seen_pair = set()
        clientes_alto_indice = []
        for cid, driver_id in pending_today:
            if (cid, driver_id) in seen_pair or client_dev_count.get(cid, 0) < 2:
                continue
            seen_pair.add((cid, driver_id))
            emp = employee_by_id.get(driver_id)
            clientes_alto_indice.append({
                "client_name": client_name_today.get(cid) or f"Cliente #{cid}",
                "driver_name": emp.name if emp else f"Motorista #{driver_id}",
                "count": client_dev_count[cid],
            })
        clientes_alto_indice.sort(key=lambda x: -x["count"])
        clientes_alto_indice = clientes_alto_indice[:10]

        selected_headcount = sum(1 for e in employees if _sl(getattr(e, "status", None)) not in {"away", "vacation", "sick", "day_off"})
        cost_centers_summary = {}
        for emp in employees_all:
            lbl = cost_center_display_label(emp.cost_center)
            if lbl not in cost_centers_summary:
                cost_centers_summary[lbl] = {"headcount": 0, "target": 0, "away": 0}
            away = 1 if _sl(getattr(emp, "status", None)) in {"away", "vacation", "sick", "day_off"} else 0
            cost_centers_summary[lbl]["headcount"] += max(0, 1 - away)
            cost_centers_summary[lbl]["away"] += away
            cost_centers_summary[lbl]["target"] = cost_centers_summary[lbl]["headcount"]

        payload = {
            "date": selected_date_str,
            "cost_center": selected_cc or "Todos",
            "dashboard": {
                "kpi": {
                    "tonnage": round(total_tonnage, 2),
                    "avg_kgh": round(avg_kgh, 1),
                    "completed_routes_count": len(completed_routes),
                    "headcount": selected_headcount,
                    "target_headcount": selected_headcount,
                    "rotas_paradas": rotas_paradas_count,
                    "rotas_ativas": rotas_ativas_count,
                    "rotas_concluidas": rotas_concluidas_count,
                },
                "alerts": {"clients_over_20min": alerts_over_20min},
                "live_separation": live_separation,
                "devolucao_dia": devolucao_dia,
                "devolucao_mes": devolucao_mes,
                "clientes_alto_indice_devolucao": clientes_alto_indice,
                "cost_centers_summary": cost_centers_summary,
                "tv_shift_alerts": {"atencao": _tsa_api["atencao"], "critico": _tsa_api["critico"]},
                "operational_shift": _tsa_api["operational_shift"],
            },
        }
        return JSONResponse(payload, headers=no_store_headers)
    except Exception as e:
        logger.exception("api_dashboard_tv_data error: %s", e)
        return JSONResponse(
            {"error": "Erro interno ao montar dados da TV.", "detail": _s(e)},
            status_code=500,
            headers=no_store_headers,
        )


@app.get("/api/dashboard/informativo-data", response_class=JSONResponse)
async def api_dashboard_informativo_data(
    request: Request,
    date_ref: Optional[str] = Query(None, alias="date"),
    cost_center: Optional[str] = None,
    session: Session = Depends(get_session),
):
    """Atualização JSON do painel Informativo (aniversários, férias, devolução, avisos, tonelagem)."""
    user = get_current_user(request)
    if not user:
        return JSONResponse({"error": "Não autorizado"}, status_code=401)
    if isinstance(user, dict) and user.get("type") == "employee":
        return JSONResponse({"error": "Não autorizado"}, status_code=401)
    now_br = datetime.now(ZoneInfo("America/Sao_Paulo"))
    selected_date = now_br.date()
    if date_ref:
        try:
            selected_date = datetime.strptime(date_ref, "%Y-%m-%d").date()
        except Exception:
            pass
    selected_date_str = selected_date.strftime("%Y-%m-%d")
    selected_cc = parse_cost_center_filter(cost_center or "Todos")
    employees_all = session.exec(select(models.Employee).where(models.Employee.status != "fired")).all()
    employees = [e for e in employees_all if employee_matches_cost_center(e, selected_cc)]
    employee_ids = list({e.id for e in employees if e.id is not None})
    if not employee_ids:
        empty = _build_informativo_extras(
            session, selected_date, selected_date_str, employees_all, {}, 0, 0, 0.0, 0.0, motorista_ids_scope=None
        )
        return JSONResponse(
            {
                "date": selected_date_str,
                "cost_center": selected_cc or "Todos",
                "informativo": empty,
                "kpi": {"routes_total": 0, "routes_completed": 0, "tonnage_total_kg": 0.0, "tonnage_delivered_kg": 0.0},
            }
        )
    routes = session.exec(
        select(models.Route)
        .where(models.Route.type == "delivery")
        .where(models.Route.date == selected_date_str)
        .where(models.Route.employee_id.in_(employee_ids))
    ).all()
    completed_statuses = {"entregue", "devolucao"}
    completed_routes = [r for r in routes if (r.delivery_status or "").lower() in completed_statuses]
    total_tonnage = float(sum(float(r.tonnage or 0.0) for r in routes))
    delivered_kg = float(sum(float(r.tonnage or 0.0) for r in completed_routes))
    inf = _build_informativo_extras(
        session,
        selected_date,
        selected_date_str,
        employees_all,
        {},
        len(routes),
        len(completed_routes),
        delivered_kg,
        total_tonnage,
        motorista_ids_scope=employee_ids if employee_ids else None,
    )
    return JSONResponse(
        {
            "date": selected_date_str,
            "cost_center": selected_cc or "Todos",
            "informativo": inf,
            "kpi": {
                "routes_total": len(routes),
                "routes_completed": len(completed_routes),
                "tonnage_total_kg": round(total_tonnage, 2),
                "tonnage_delivered_kg": round(delivered_kg, 2),
            },
        }
    )


@app.get("/admin/informativo", response_class=HTMLResponse)
async def admin_informativo_page(
    request: Request,
    session: Session = Depends(get_session),
    user=Depends(require_leader),
):
    rows = session.exec(
        select(models.InformativeBulletin).order_by(models.InformativeBulletin.sort_order, models.InformativeBulletin.id)
    ).all()
    panel_sec = 8
    panel_audio_enabled = False
    panel_audio_url = ""
    panel_audio_playlist = ""
    panel_audio_youtube_url = ""
    panel_audio_volume = 35
    try:
        cfg = session.get(models.InformativePanelConfig, 1)
        if cfg is not None:
            panel_sec = max(4, min(120, int(cfg.carousel_interval_seconds or 8)))
            panel_audio_enabled = bool(getattr(cfg, "audio_enabled", False))
            panel_audio_url = (getattr(cfg, "audio_url", None) or "").strip()
            panel_audio_playlist = (getattr(cfg, "audio_playlist", None) or "").strip()
            panel_audio_youtube_url = (getattr(cfg, "audio_youtube_url", None) or "").strip()
            panel_audio_volume = max(0, min(100, int(getattr(cfg, "audio_volume", 35) or 35)))
    except Exception:
        pass
    dry_year = datetime.now().year
    try:
        qy = request.query_params.get("dry_year")
        if qy:
            dry_year = max(2000, min(2100, int(qy)))
    except (TypeError, ValueError):
        pass
    dr_rows: Dict[int, Dict[str, Optional[float]]] = {m: {} for m in range(1, 13)}
    dr_use_system: Dict[int, bool] = {}
    try:
        dr_db = session.exec(
            select(models.InformativeMonthlyReturn).where(models.InformativeMonthlyReturn.year == dry_year)
        ).all()
        for r in dr_db:
            dr_use_system[r.month] = bool(getattr(r, "use_system_kpi", False))
            dr_rows[r.month] = {
                "pct": r.pct_devolucao,
                "valor": r.valor_devolucao,
                "receita": r.receita,
            }
    except Exception:
        pass
    dr_display: Dict[int, Any] = {}
    for m in range(1, 13):
        row = dr_rows.get(m) or {}
        use_sys = dr_use_system.get(m, False)
        pct_src: Any = row.get("pct")
        valor_src: Any = row.get("valor")
        receita_src: Any = row.get("receita")
        if use_sys:
            sysv = _devolucao_mensal_system_month_values(session, dry_year, m)
            pct_src = sysv.get("pct")
            valor_src = sysv.get("valor")
            receita_src = sysv.get("receita")
        dr_display[m] = {
            "pct": _format_br_pct_form(pct_src),
            "valor": _format_br_money_form(valor_src),
            "receita": _format_br_money_form(receita_src),
            "use_system": use_sys,
        }
    bulletin_admin_rows: List[Dict[str, Any]] = []
    for b in rows:
        disp = resolve_bulletin_display_image(b)
        has_local = _bulletin_has_local_path_record(b)
        if disp and _is_local_informativo_asset_url(disp):
            local_missing = informativo_local_upload_file_missing(disp)
        elif not disp and has_local:
            local_missing = True
        else:
            local_missing = False
        no_image = not disp and not has_local
        bulletin_admin_rows.append(
            {
                "bulletin": b,
                "image_url_resolved": disp,
                "admin_inf_no_image": no_image,
                "local_file_missing": local_missing,
            }
        )
    informativo_has_persistent_uploads = bool(INFORMATIVO_MEDIA_ROOT)
    return templates.TemplateResponse(
        "admin_informativo.html",
        {
            "request": request,
            "bulletins": rows,
            "bulletin_admin_rows": bulletin_admin_rows,
            "user": user,
            "panel_carousel_seconds": panel_sec,
            "panel_audio_enabled": panel_audio_enabled,
            "panel_audio_url": panel_audio_url,
            "panel_audio_playlist": panel_audio_playlist,
            "panel_audio_youtube_url": panel_audio_youtube_url,
            "panel_audio_volume": panel_audio_volume,
            "dry_year": dry_year,
            "dr_rows": dr_rows,
            "dr_display": dr_display,
            "informativo_has_persistent_uploads": informativo_has_persistent_uploads,
        },
    )


