@app.post("/admin/informativo/audio-config")
async def admin_informativo_audio_config(
    session: Session = Depends(get_session),
    user=Depends(require_leader),
    audio_enabled: Optional[str] = Form(None),
    audio_url: str = Form(""),
    audio_playlist: str = Form(""),
    audio_youtube_url: str = Form(""),
    audio_volume: int = Form(35),
    audio_file: Optional[UploadFile] = File(None),
):
    try:
        # Garante migrações aplicadas mesmo sem restart do processo.
        create_db_and_tables()

        def _is_youtube_url(value: Optional[str]) -> bool:
            raw = (value or "").strip().lower()
            if not raw:
                return False
            return ("youtube.com" in raw) or ("youtu.be" in raw)

        def _safe_volume(raw: Any, fallback: int = 35) -> int:
            try:
                return max(0, min(100, int(raw)))
            except (TypeError, ValueError):
                return fallback

        def _normalize_playlist(raw: str, max_total: int = 4000) -> Optional[str]:
            if not raw:
                return None
            unique_items: List[str] = []
            for line in raw.splitlines():
                item = (line or "").strip()
                if item and item not in unique_items:
                    unique_items.append(item[:500])
            if not unique_items:
                return None
            out: List[str] = []
            size = 0
            for item in unique_items:
                extra = len(item) + (1 if out else 0)
                if size + extra > max_total:
                    break
                out.append(item)
                size += extra
            return "\n".join(out) if out else None

        cfg = session.get(models.InformativePanelConfig, 1)
        if cfg is None:
            cfg = models.InformativePanelConfig(id=1, carousel_interval_seconds=8)
            session.add(cfg)

        cfg.audio_enabled = bool(audio_enabled)
        cfg.audio_volume = _safe_volume(audio_volume, fallback=35)
        next_audio_url = (audio_url or "").strip()[:500] or None
        next_youtube_url = (audio_youtube_url or "").strip()[:500] or None
        if not next_youtube_url and _is_youtube_url(next_audio_url):
            # Permite colar URL do YouTube no campo de áudio comum sem erro.
            next_youtube_url = next_audio_url
            next_audio_url = None
        raw_list = (audio_playlist or "").strip()
        normalized_playlist = _normalize_playlist(raw_list, max_total=4000)
        if audio_file and (audio_file.filename or "").strip():
            try:
                next_audio_url = await _save_informativo_audio(audio_file)
            except ValueError:
                return RedirectResponse(url="/admin/informativo?err_audio=1", status_code=303)
        if next_audio_url and normalized_playlist:
            filtered = [u for u in normalized_playlist.splitlines() if u != next_audio_url]
            normalized_playlist = "\n".join(filtered) if filtered else None
        cfg.audio_url = next_audio_url
        cfg.audio_playlist = normalized_playlist
        cfg.audio_youtube_url = next_youtube_url
        session.add(cfg)
        session.commit()
        return RedirectResponse(url="/admin/informativo?saved=audio", status_code=303)
    except Exception:
        logger.exception("Falha ao salvar configuração de áudio do informativo")
        session.rollback()
        return RedirectResponse(url="/admin/informativo?err_audio_cfg=1", status_code=303)


