@app.post("/admin/informativo/{bulletin_id}/update")
async def admin_informativo_update(
    request: Request,
    bulletin_id: int,
    session: Session = Depends(get_session),
    user=Depends(require_leader),
):
    form = await request.form()
    b = session.get(models.InformativeBulletin, bulletin_id)
    if not b:
        raise HTTPException(status_code=404, detail="Aviso não encontrado")
    title = str(form.get("title") or "").strip()
    if not title:
        return RedirectResponse(url=f"/admin/informativo/{bulletin_id}/edit?err=1", status_code=303)
    bulletin_image = form.get("bulletin_image")
    has_new_file = (
        bulletin_image is not None
        and getattr(bulletin_image, "filename", None)
        and str(bulletin_image.filename).strip()
    )
    if has_new_file:
        try:
            b.uploaded_image_path = await _save_informativo_image(bulletin_image)
        except ValueError:
            return RedirectResponse(url=f"/admin/informativo/{bulletin_id}/edit?err_image=1", status_code=303)
    if form.get("clear_external_image"):
        b.image_url = None
    elif form.get("image_url") is not None:
        raw_img = str(form.get("image_url") or "").strip()
        if raw_img:
            b.image_url = _normalize_bulletin_external_url(raw_img)
    b.title = title[:200]
    b.body = str(form.get("body") or "").strip() or None
    link_field = form.get("link_url")
    if link_field is not None:
        b.link_url = str(link_field or "").strip()[:500] or None
    b.sort_order = int(form.get("sort_order") or 0)
    b.updated_at = datetime.now()
    session.add(b)
    session.commit()
    return RedirectResponse(url="/admin/informativo?updated=1", status_code=303)


@app.post("/admin/informativo")
async def admin_informativo_create(
    request: Request,
    session: Session = Depends(get_session),
    user=Depends(require_leader),
    title: str = Form(""),
    body: str = Form(""),
    image_url: str = Form(""),
    bulletin_image: Optional[UploadFile] = File(None),
    link_url: str = Form(""),
    sort_order: int = Form(0),
):
    title = (title or "").strip()
    if not title:
        return RedirectResponse(url="/admin/informativo?err=1", status_code=303)
    ext = _normalize_bulletin_external_url(image_url)
    upl: Optional[str] = None
    if bulletin_image and (bulletin_image.filename or "").strip():
        try:
            upl = await _save_informativo_image(bulletin_image)
        except ValueError:
            return RedirectResponse(url="/admin/informativo?err_image=1", status_code=303)
    elif not ext:
        raw = (image_url or "").strip()[:500]
        if raw:
            upl = _normalize_informativo_image_url(raw) or None
            if upl and not (
                upl.startswith("/static/uploads/informativo/")
                or upl.startswith("/media/informativo/")
            ):
                upl = None
    b = models.InformativeBulletin(
        title=title[:200],
        body=(body or "").strip() or None,
        image_url=ext,
        uploaded_image_path=upl,
        link_url=(link_url or "").strip()[:500] or None,
        sort_order=int(sort_order or 0),
        is_active=True,
        updated_at=datetime.now(),
    )
    session.add(b)
    session.commit()
    return RedirectResponse(url="/admin/informativo", status_code=303)


