@app.get("/mobile/portaria/historico", response_class=HTMLResponse)
async def mobile_portaria_historico_page(
    request: Request,
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
    session: Session = Depends(get_session),
):
    """Histórico de conferências da portaria (log) — versão mobile."""
    user_id = request.session.get("user_id")
    if not user_id:
        return RedirectResponse(url="/mobile/login", status_code=303)
    employee = session.get(models.Employee, int(user_id) if user_id else 0)
    if not employee or not _has_mobile_gatehouse_access(employee):
        return RedirectResponse(url="/mobile/dashboard?error=no_permission", status_code=303)
    today = datetime.now(ZoneInfo("America/Sao_Paulo")).date()
    df = date_from or today.strftime("%Y-%m-%d")
    dt = date_to or df
    if df > dt:
        df, dt = dt, df
    checks = session.exec(
        select(models.PortariaCheck)
        .where(models.PortariaCheck.date >= df)
        .where(models.PortariaCheck.date <= dt)
        .order_by(desc(models.PortariaCheck.porteiro_confirmed_at))
    ).all()
    porteiro_ids = list({pc.porteiro_employee_id for pc in checks if pc.porteiro_employee_id})
    emp_map = {}
    if porteiro_ids:
        emps = session.exec(select(models.Employee).where(models.Employee.id.in_(porteiro_ids))).all()
        emp_map = {e.id: (e.name or "").strip() for e in emps if e.id}
    checklist_by_driver_date: Dict[tuple, bool] = {}
    if hasattr(models, "TranspalletChecklist"):
        chk = session.exec(
            select(models.TranspalletChecklist.employee_id, models.TranspalletChecklist.date)
            .where(models.TranspalletChecklist.date >= df)
            .where(models.TranspalletChecklist.date <= dt)
        ).all()
        for r in chk:
            did = getattr(r, "employee_id", r[0]) if hasattr(r, "employee_id") else r[0]
            d = getattr(r, "date", r[1]) if hasattr(r, "date") else r[1]
            if did and d:
                checklist_by_driver_date[(int(did), str(d))] = True
    devolucoes_by_driver_date: Dict[tuple, list] = {}
    routes_devolucao = session.exec(
        select(models.Route)
        .where(models.Route.type == "delivery")
        .where(models.Route.delivery_status == "devolucao")
        .where(models.Route.date >= df)
        .where(models.Route.date <= dt)
    ).all()
    client_ids_dev = list({r.client_id for r in routes_devolucao if r.client_id})
    client_map_dev = {}
    if client_ids_dev:
        clients_dev = session.exec(select(models.Client).where(models.Client.id.in_(client_ids_dev))).all()
        client_map_dev = {c.id: (c.name or c.razao_social or f"Cliente #{c.id}") for c in clients_dev if c.id}
    for route in routes_devolucao:
        drv = route.employee_id
        dt_r = route.date
        if drv and dt_r:
            key = (int(drv), str(dt_r)[:10])
            cname = client_map_dev.get(route.client_id, f"Cliente #{route.client_id}" if route.client_id else "—")
            lst = devolucoes_by_driver_date.setdefault(key, [])
            if cname and cname not in lst:
                lst.append(str(cname or "—"))
    by_session: Dict[int, Dict[str, Any]] = {}
    for pc in checks:
        sid = pc.delivery_session_id
        if sid not in by_session:
            driver_id = pc.driver_id
            entry_date = pc.date
            dev_list = devolucoes_by_driver_date.get((driver_id, str(entry_date)[:10]), [])
            checklist_done = checklist_by_driver_date.get((driver_id, str(entry_date)[:10]), False)
            by_session[sid] = {
                "driver_id": driver_id,
                "driver_name": pc.driver_name,
                "helpers_text": pc.helpers_text,
                "plate": pc.vehicle_plate,
                "peso_kg": pc.peso_total_kg,
                "valor_total": pc.valor_total,
                "saida_at": None,
                "saida_km": None,
                "saida_porteiro": None,
                "chegada_at": None,
                "chegada_km": None,
                "chegada_porteiro": None,
                "date": entry_date,
                "checklist_done": checklist_done,
                "devolucoes": dev_list,
            }
        data_fmt = fmt_ddmmyyyy(pc.date) if pc.date else "—"
        hora = fmt_hhmm(pc.porteiro_confirmed_at)
        dt_fmt = f"{data_fmt} {hora}" if hora != "—" else data_fmt
        porteiro_name = emp_map.get(pc.porteiro_employee_id, "")
        if pc.check_type == "saida":
            by_session[sid]["saida_at"] = dt_fmt
            by_session[sid]["saida_km"] = pc.km
            by_session[sid]["saida_porteiro"] = porteiro_name
        else:
            by_session[sid]["chegada_at"] = dt_fmt
            by_session[sid]["chegada_km"] = pc.km
            by_session[sid]["chegada_porteiro"] = porteiro_name
    entries = list(by_session.values())
    entries.sort(key=lambda e: (e.get("chegada_at") or e.get("saida_at") or ""), reverse=True)
    return templates.TemplateResponse(
        "mobile/portaria_historico.html",
        {
            "request": request,
            "entries": entries,
            "date_from": df,
            "date_to": dt,
        },
    )


class PortariaConfirmPayload(BaseModel):
    session_id: int
    check_type: str  # saida | chegada
    km_return: Optional[float] = None  # obrigatório para chegada


@app.post("/api/mobile/portaria/confirm", response_class=JSONResponse)
async def api_mobile_portaria_confirm(
    request: Request,
    payload: PortariaConfirmPayload,
    session: Session = Depends(get_session),
):
    """Porteiro confirma saída ou chegada. Registra hora do check-in/check-out."""
    user_id = request.session.get("user_id")
    if not user_id:
        return JSONResponse({"error": "Não autorizado"}, status_code=401)
    employee = session.get(models.Employee, user_id)
    if not employee or not _has_mobile_gatehouse_access(employee):
        return JSONResponse({"error": "Sem permissão para portaria."}, status_code=403)
    if payload.check_type not in ("saida", "chegada"):
        return JSONResponse({"error": "Tipo inválido. Use saida ou chegada."}, status_code=400)
    ds = session.get(models.DeliverySession, payload.session_id)
    if not ds:
        return JSONResponse({"error": "Sessão não encontrada."}, status_code=404)
    existing = session.exec(
        select(models.PortariaCheck).where(
            models.PortariaCheck.delivery_session_id == payload.session_id,
            models.PortariaCheck.check_type == payload.check_type,
        )
    ).first()
    if existing:
        return JSONResponse({"error": "Já confirmado anteriormente."}, status_code=400)
    routes = session.exec(
        select(models.Route)
        .where(models.Route.type == "delivery")
        .where(models.Route.date == ds.date)
        .where(models.Route.employee_id == ds.employee_id)
    ).all()
    peso_kg = sum(float(getattr(r, "tonnage", 0) or getattr(r, "delivery_total_weight", 0) or 0) for r in routes)
    valor_total = sum(float(getattr(r, "valor_financeiro", 0) or 0) for r in routes)
    if payload.check_type == "saida":
        km = float(ds.km_departure or 0)
    else:
        km = payload.km_return if payload.km_return is not None else float(ds.km_return or 0)
        if payload.km_return is not None:
            ds.km_return = float(payload.km_return)
            ds.status = "closed"
            ds.ended_at = datetime.now(ZoneInfo("America/Sao_Paulo"))
            session.add(ds)
    driver = session.get(models.Employee, ds.employee_id)
    driver_name = _emp_name_upper(driver.name) if driver else f"Motorista #{ds.employee_id}"
    emp_map = {int(e.id): _emp_name_upper(e.name) for e in session.exec(select(models.Employee)).all() if e.id}
    helper_ids = set()
    for r in routes:
        helper_ids.update(_parse_route_helper_ids(getattr(r, "delivery_helpers_json", None)))
    helper_ids.discard(ds.employee_id or 0)
    helpers_text = ", ".join(emp_map.get(int(h), f"Ajud. #{h}") for h in helper_ids) if helper_ids else (
        ", ".join(_parse_session_helpers(ds.helpers_json)) if ds.helpers_json else "Sem ajudante"
    )
    pc = models.PortariaCheck(
        delivery_session_id=ds.id,
        check_type=payload.check_type,
        date=ds.date,
        driver_id=ds.employee_id,
        driver_name=driver_name,
        helpers_text=helpers_text,
        vehicle_plate=str(getattr(ds, "vehicle_plate", None) or "").strip().upper() or "",
        km=km,
        peso_total_kg=peso_kg,
        valor_total=valor_total,
        porteiro_confirmed_at=datetime.now(ZoneInfo("America/Sao_Paulo")),
        porteiro_employee_id=int(employee.id),
    )
    session.add(pc)
    session.commit()
    return JSONResponse({"success": True})


@app.get("/mobile/delivery", response_class=HTMLResponse)
async def mobile_delivery_page(request: Request, session: Session = Depends(get_session)):
    """Página de rotas de entregas do colaborador (mobile)."""
    try:
        user = get_current_user(request)
        if not isinstance(user, dict) or user.get("type") != "employee":
            return RedirectResponse(url="/mobile/login", status_code=303)
        employee = session.get(models.Employee, user.get("id"))
        if not employee:
            request.session.pop("user_id", None)
            return RedirectResponse(url="/mobile/login", status_code=303)
        helper_candidates = session.exec(
            select(models.Employee)
            .where(models.Employee.status == "active")
            .where(models.Employee.id != employee.id)
            .order_by(models.Employee.name)
        ).all()
        helpers_eligible_rows = [
            (helper.id, helper.name)
            for helper in helper_candidates
            if _has_mobile_delivery_helper_access(helper)
        ]
        employees_json = json.dumps(
            [{"id": helper_id, "name": _emp_name_upper(helper_name)} for helper_id, helper_name in helpers_eligible_rows],
            ensure_ascii=False
        )
        now_sp_delivery = datetime.now(ZoneInfo("America/Sao_Paulo"))
        month_start = now_sp_delivery.replace(day=1).strftime("%Y-%m-%d")
        month_end = now_sp_delivery.strftime("%Y-%m-%d")
        returns_metrics_delivery = _compute_employee_returns_metrics(session=session, user_id=int(employee.id), date_from=month_start, date_to=month_end)
        returns_alert = _build_returns_alert_payload(returns_metrics_delivery, target_percent=2.0, period_label="Mês atual")
        commercial_sellers_json = json.dumps(_delivery_commercial_sellers_payload(session), ensure_ascii=False)
        _delivery_flags = _build_mobile_hub_access_flags(employee)
        has_delivery_driver_access = bool(_delivery_flags.get("delivery_driver"))
        return templates.TemplateResponse(
            "mobile/delivery.html",
            {
                "request": request,
                "employee": employee,
                "employees_json": employees_json,
                "returns_alert_json": json.dumps(returns_alert, ensure_ascii=False),
                "commercial_sellers_json": commercial_sellers_json,
                "has_delivery_driver_access": has_delivery_driver_access,
            },
        )
    except Exception as e:
        import logging
        logging.getLogger(__name__).warning("mobile_delivery_page error: %s", e, exc_info=True)
        return HTMLResponse(
            content="""<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Indisponível</title></head><body style="font-family:sans-serif;padding:24px;text-align:center;"><p>Serviço temporariamente indisponível. Tente novamente ou use o app offline.</p><p><a href="/mobile/delivery">Recarregar</a></p></body></html>""",
            status_code=503,
        )


@app.get("/mobile/achievements", response_class=HTMLResponse)
async def mobile_achievements_page(request: Request, session: Session = Depends(get_session)):
    """Página de conquistas do colaborador (mobile)."""
    user = get_current_user(request)
    if not isinstance(user, dict) or user.get("type") != "employee":
        return RedirectResponse(url="/mobile/login", status_code=303)
    employee = session.get(models.Employee, user.get("id"))
    if not employee:
        return RedirectResponse(url="/mobile/login", status_code=303)
    total_xp = float(getattr(employee, "total_xp", 0.0) or 0.0)
    gamification = {
        "total_xp": total_xp,
        "progress_percent": min(100, max(0, total_xp / 1000.0 * 100)) if total_xp else 0,
        "level": {"level": 1, "name": "Colaborador", "badge_image": "badge_1.png", "min_xp": 0},
        "next_level": {"name": "Próximo", "min_xp": 1000} if total_xp < 1000 else None,
    }
    all_achievements = session.exec(
        select(
            models.GameAchievement.id,
            models.GameAchievement.name,
            models.GameAchievement.description,
            models.GameAchievement.icon,
            models.GameAchievement.xp_reward,
        ).order_by(models.GameAchievement.xp_reward)
    ).all()
    earned = {ea.achievement_id: ea for ea in session.exec(
        select(models.EmployeeAchievement).where(models.EmployeeAchievement.employee_id == employee.id)).all()}
    achievements_list = []
    for ach in all_achievements:
        ach_id, ach_name, ach_desc, ach_icon, ach_xp_reward = ach
        ea = earned.get(ach_id)
        achievements_list.append({
            "name": ach_name,
            "description": ach_desc or "",
            "icon": ach_icon if ach_icon and not str(ach_icon).startswith("\\U0001f") else "award",
            "xp_reward": ach_xp_reward or 0,
            "unlocked": ea is not None,
            "earned_at": ea.earned_at if ea else None,
        })
    xp_txs = session.exec(
        select(models.GameXPTransaction)
        .where(models.GameXPTransaction.employee_id == employee.id)
        .order_by(models.GameXPTransaction.created_at.desc())
        .limit(100)
    ).all()
    xp_history_full = [{"reason": tx.reason, "created_at": tx.created_at, "amount": tx.amount} for tx in xp_txs]
    total_bonus_xp = sum(tx.amount for tx in xp_txs if tx.amount > 0)
    unlocked_count = len(earned)
    return templates.TemplateResponse("mobile/achievements.html", {
        "request": request,
        "employee": employee,
        "gamification": gamification,
        "achievements": achievements_list,
        "unlocked_count": unlocked_count,
        "total_achievements": len(all_achievements),
        "total_bonus_xp": int(total_bonus_xp),
        "xp_history_full": xp_history_full,
    })


