@app.post("/api/admin/sync-xp-totals")
async def api_sync_xp_totals(request: Request, session: Session = Depends(get_session)):
    try:
        require_login(request)  # Safety
        totals_by_employee: Dict[int, int] = {}
        totals_rows = session.exec(
            select(
                models.GameXPTransaction.employee_id,
                func.coalesce(func.sum(models.GameXPTransaction.amount), 0),
            )
            .where(models.GameXPTransaction.status != "rejected")
            .group_by(models.GameXPTransaction.employee_id)
        ).all()
        for employee_id, total in totals_rows:
            if employee_id is None:
                continue
            totals_by_employee[int(employee_id)] = int(total or 0)

        employees = session.exec(select(models.Employee)).all()
        count = 0
        for emp in employees:
            total = totals_by_employee.get(int(emp.id), 0) if emp.id is not None else 0
            if emp.total_xp != int(total):
                emp.total_xp = int(total)
                session.add(emp)
                count += 1

        if count:
            session.commit()
        return {"success": True, "updated": count}
    except Exception as e:
        return JSONResponse({"success": False, "error": str(e)}, status_code=500)


@app.get("/api/admin/backup", response_class=Response, dependencies=[Depends(require_leader)])
async def api_admin_backup():
    """Cria backup do banco e retorna o arquivo para download."""
    try:
        from backup_service import create_backup
        backup_path, err = create_backup()
        if err:
            return JSONResponse({"success": False, "error": err}, status_code=500)
        if not backup_path or not Path(backup_path).exists():
            return JSONResponse({"success": False, "error": "Backup não foi criado."}, status_code=500)
        filename = Path(backup_path).name
        return FileResponse(
            path=str(backup_path),
            filename=filename,
            media_type="application/octet-stream",
        )
    except Exception as e:
        logger.exception(f"api_admin_backup: {e}")
        return JSONResponse({"success": False, "error": str(e)}, status_code=500)


@app.post("/api/admin/reset-data", response_class=JSONResponse, dependencies=[Depends(require_leader)])
async def api_admin_reset_data(
    request: Request,
    reset_routes: Optional[str] = Form(None),
    reset_xp: Optional[str] = Form(None),
    reset_all: Optional[str] = Form(None),
    session: Session = Depends(get_session),
):
    """Reseta dados operacionais (rotas/presença) e/ou gamificação (XP). Requer confirmação no frontend."""
    try:
        do_routes = (reset_routes or "").strip().lower() == "true"
        do_xp = (reset_xp or "").strip().lower() == "true"
        do_all = (reset_all or "").strip().lower() == "true"
        if not (do_routes or do_xp or do_all):
            return JSONResponse({"success": False, "error": "Nenhuma opção de reset informada."}, status_code=400)
        if do_all:
            do_routes = do_xp = True
        counts = {}
        if do_routes:
            r = session.execute(delete(models.DevolucaoStaging))
            counts["DevolucaoStaging"] = r.rowcount or 0
            r = session.execute(delete(models.DevolucaoImportRowError))
            counts["DevolucaoImportRowError"] = r.rowcount or 0
            r = session.execute(delete(models.Devolucao))
            counts["Devolucao"] = r.rowcount or 0
            r = session.execute(delete(models.DevolucaoImportBatch))
            counts["DevolucaoImportBatch"] = r.rowcount or 0
            r = session.execute(delete(models.DeliverySession))
            counts["DeliverySession"] = r.rowcount or 0
            r = session.execute(delete(models.RouteInsertLog))
            counts["RouteInsertLog"] = r.rowcount or 0
            r = session.execute(delete(models.Route))
            counts["Route"] = r.rowcount or 0
            r = session.execute(delete(models.EmployeeRoutine))
            counts["EmployeeRoutine"] = r.rowcount or 0
            r = session.execute(delete(models.DailyOperation))
            counts["DailyOperation"] = r.rowcount or 0
        if do_xp:
            employees = session.exec(select(models.Employee)).all()
            for emp in employees:
                emp.total_xp = 0
                session.add(emp)
            counts["EmployeesZeroed"] = len(employees)
            r = session.execute(delete(models.GameXPTransaction))
            counts["GameXPTransaction"] = r.rowcount or 0
            r = session.execute(delete(models.EmployeeAchievement))
            counts["EmployeeAchievement"] = r.rowcount or 0
        session.commit()
        return JSONResponse({"success": True, "counts": counts})
    except Exception as e:
        session.rollback()
        logger.exception(f"api_admin_reset_data: {e}")
        return JSONResponse({"success": False, "error": str(e)}, status_code=500)


@app.post("/api/game/manual-xp", dependencies=[Depends(require_leader)])
async def api_manual_xp(payload: ManualXPRequest, request: Request, session: Session = Depends(get_session)):
    """Cria uma transação manual de XP (bonificação/penalidade)."""
    require_login(request)

    emp = session.get(models.Employee, payload.employee_id)
    if not emp:
        return JSONResponse({"success": False, "error": "Colaborador não encontrado."}, status_code=404)

    # Validação básica
    if not payload.reason or not payload.reason.strip():
        return JSONResponse({"success": False, "error": "Informe um motivo (reason)."}, status_code=400)

    try:
        amount = int(payload.amount)
    except Exception:
        return JSONResponse({"success": False, "error": "amount inválido."}, status_code=400)

    if amount == 0:
        return JSONResponse({"success": False, "error": "amount não pode ser 0."}, status_code=400)

    status_val = (payload.status or "confirmed").strip().lower()
    if status_val not in ("confirmed", "provisional"):
        return JSONResponse({"success": False, "error": "status inválido (use confirmed ou provisional)."}, status_code=400)

    now = datetime.now()
    tx = models.GameXPTransaction(
        employee_id=payload.employee_id,
        amount=amount,
        source_type="manual_admin",
        status=status_val,
        reason=f"Ajuste manual | {payload.reason.strip()}",
        created_at=now,
        confirmed_at=now if status_val == "confirmed" else None
    )

    session.add(tx)

    # Atualiza total_xp somente se confirmado
    if status_val == "confirmed":
        emp.total_xp += amount
        session.add(emp)

    session.commit()

    return {
        "success": True,
        "transaction": {
            "id": tx.id,
            "employee_id": tx.employee_id,
            "amount": tx.amount,
            "status": tx.status,
            "reason": tx.reason,
            "created_at": tx.created_at.isoformat()
        }
    }

@app.get("/admin/game", response_class=HTMLResponse)
async def admin_game_dashboard(request: Request, session: Session = Depends(get_session), user=Depends(require_leader)):
    """Manager Dashboard for Gamification Control"""
    today_start = datetime.now().replace(hour=0, minute=0, second=0, microsecond=0)
    pending_rows = session.exec(
        select(
            models.GameXPTransaction.id,
            models.GameXPTransaction.amount,
            models.GameXPTransaction.reason,
            models.GameXPTransaction.created_at,
            models.Employee.name,
            models.GameXPTransaction.employee_id,
        )
        .join(models.Employee)
        .where(models.GameXPTransaction.status == "provisional")
        .order_by(desc(models.GameXPTransaction.created_at))
    ).all()

    pending_list = []
    pending_today = 0
    total_bonus = 0
    total_penalty = 0
    critical_count = 0
    for tx_id, tx_amount, tx_reason, tx_created_at, employee_name, employee_id in pending_rows:
        amount_i = int(tx_amount or 0)
        reason_s = (tx_reason or "").strip()
        created_iso = tx_created_at.isoformat() if tx_created_at else None
        is_today = bool(tx_created_at and tx_created_at >= today_start)
        is_critical = abs(amount_i) >= 150 or any(token in reason_s.lower() for token in ("urgente", "crit", "erro grave"))
        if is_today:
            pending_today += 1
        if amount_i >= 0:
            total_bonus += amount_i
        else:
            total_penalty += abs(amount_i)
        if is_critical:
            critical_count += 1
        pending_list.append({
            "id": tx_id,
            "employee_id": employee_id,
            "employee_name": employee_name or "",
            "amount": amount_i,
            "reason": reason_s,
            "date": tx_created_at.strftime("%d/%m %H:%M") if tx_created_at else "-",
            "created_at": created_iso,
            "is_today": is_today,
            "is_critical": is_critical,
        })

    stats = {
        "total_pending": len(pending_list),
        "pending_today": pending_today,
        "total_bonus": total_bonus,
        "total_penalty": total_penalty,
        "critical_count": critical_count,
    }

    return templates.TemplateResponse("admin_game.html", {
        "request": request,
        "pending_txs": pending_list,
        "stats": stats,
        # History removed from dashboard, moved to exclusive page
    })

