def ensure_route_delivery_columns_widen():
    """Corrige colunas route.* criadas como VARCHAR(5) para HH:MM quando o app grava datetime ISO ou status longos."""
    try:
        if engine.dialect.name != "postgresql":
            return
        inspector = inspect(engine)
        if "route" not in inspector.get_table_names():
            return
        cols = {c["name"]: c for c in inspector.get_columns("route")}

        def varchar_limit(col_name: str):
            if col_name not in cols:
                return None
            t = cols[col_name].get("type")
            if isinstance(t, DateTime):
                return None
            if isinstance(t, String):
                return t.length
            return None

        alters: List[tuple[str, str]] = []

        for name in (
            "delivery_started_at",
            "delivery_finished_at",
            "delivery_canceled_at",
            "delivery_returned_at",
        ):
            lim = varchar_limit(name)
            if lim is not None and lim < 64:
                alters.append((name, f'ALTER TABLE route ALTER COLUMN "{name}" TYPE VARCHAR(64)'))

        lim = varchar_limit("delivery_status")
        if lim is not None and lim < 32:
            alters.append(("delivery_status", 'ALTER TABLE route ALTER COLUMN delivery_status TYPE VARCHAR(32)'))

        lim = varchar_limit("delivery_return_reason")
        if lim is not None and lim < 256:
            alters.append(
                (
                    "delivery_return_reason",
                    "ALTER TABLE route ALTER COLUMN delivery_return_reason TYPE TEXT USING delivery_return_reason::text",
                )
            )

        for col_name, stmt in alters:
            try:
                with engine.connect() as conn:
                    conn.execute(text(stmt))
                    conn.commit()
                logger.info(f"ensure_route_delivery_columns_widen: coluna route.{col_name} ampliada")
            except Exception as ex:
                logger.warning(f"ensure_route_delivery_columns_widen: route.{col_name}: {ex}")
    except Exception as e:
        logger.error(f"ensure_route_delivery_columns_widen: {e}")


def ensure_devolucao_route_id():
    """Adiciona coluna route_id à tabela devolucao para vincular devolução à parada (fechamento automático)."""
    try:
        inspector = inspect(engine)
        tbl = "devolucao"
        if tbl not in inspector.get_table_names():
            return
        cols = {c["name"] for c in inspector.get_columns(tbl)}
        if "route_id" not in cols:
            with engine.connect() as conn:
                conn.execute(text(f"ALTER TABLE {tbl} ADD COLUMN route_id INTEGER"))
                conn.commit()
    except Exception as e:
        logger.error(f"ensure_devolucao_route_id: {e}")


def ensure_devolucao_evitada_schema():
    """Cria tabela devolucaoevitada (registro de devoluções evitadas no BI)."""
    try:
        models.DevolucaoEvitada.__table__.create(bind=engine, checkfirst=True)
    except Exception as e:
        logger.error(f"ensure_devolucao_evitada_schema: {e}")


@app.get("/api/admin/clients", dependencies=[Depends(require_leader)])
async def api_get_admin_clients(session: Session = Depends(get_session)):
    """Get all clients for admin purposes."""
    clients = session.exec(select(models.Client)).all()
    return [client.model_dump() for client in clients]

@app.post("/mobile/route/{route_id}/delete", response_class=JSONResponse)
async def mobile_route_delete(
    request: Request, 
    route_id: int, 
    payload: MobileDeletePayload,
    session: Session = Depends(get_session)
):
    try:
        user_id = request.session.get("user_id")
        if not user_id:
            return JSONResponse({"error": "Não autorizado"}, status_code=401)

        employee = session.get(models.Employee, user_id)
        if not employee:
            return JSONResponse({"error": "Colaborador não encontrado."}, status_code=404)
        
        # Verificar Matrícula para confirmação de segurança
        # Remove zeros a esquerda para comparação flexível se necessário, ou validação exata
        if payload.registration_id.strip() != employee.registration_id.strip():
             return JSONResponse({"error": "Matrícula incorreta. A exclusão requer sua confirmação."}, status_code=403)

        route = session.get(models.Route, route_id)
        if not route:
             return JSONResponse({"error": "Rota não encontrada"}, status_code=404)
             
        if route.employee_id != user_id:
             return JSONResponse({"error": "Não autorizado: Rota pertence a outro colaborador"}, status_code=403)
        
        if route.status == "completed":
             return JSONResponse({"error": "Não é possível excluir uma rota já finalizada."}, status_code=400)

        # Deletar
        session.delete(route)
        session.commit()
        
        return JSONResponse({"success": True})
    except Exception as e:
        logger.exception(f"Error deleting route {route_id}: {e}")
        return JSONResponse({"error": str(e)}, status_code=500)

@app.post("/mobile/route/{route_id}/update", response_class=JSONResponse)
async def mobile_route_update(
    request: Request,
    route_id: int,
    payload: MobileUpdatePayload,
    session: Session = Depends(get_session)
):
    try:
        user_id = request.session.get("user_id")
        if not user_id:
            return JSONResponse({"error": "Não autorizado"}, status_code=401)

        route = session.get(models.Route, route_id)
        if not route:
             return JSONResponse({"error": "Rota não encontrada"}, status_code=404)

        if route.employee_id != user_id:
             return JSONResponse({"error": "Não autorizado"}, status_code=403)

        if route.status == "completed":
             return JSONResponse({"error": "Não é possível editar uma rota já finalizada."}, status_code=400)

        # Atualizar campos se fornecidos
        if payload.client_id:
            client = session.get(models.Client, payload.client_id)
            if not client:
                return JSONResponse({"error": "Cliente inválido"}, status_code=404)
            route.client_id = payload.client_id

        if payload.tonnage is not None:
            if payload.tonnage <= 0:
                 return JSONResponse({"error": "Peso deve ser maior que zero"}, status_code=400)
            route.tonnage = payload.tonnage

        session.add(route)
        session.commit()

        return JSONResponse({"success": True})
    except Exception as e:
        logger.exception(f"Error updating route {route_id}: {e}")
        return JSONResponse({"error": str(e)}, status_code=500)


def _mobile_my_routes_seller_fields(
    session: Session,
    client: Optional[models.Client],
    cache: Dict[int, Tuple[str, str, Optional[str]]],
) -> Tuple[str, str, Optional[str]]:
    """Alinha vendedor ao card de /clients/:id (vendedor_id ou setor/código legado)."""
    if not client:
        return "", "", None
    cid = client.id
    if cid in cache:
        return cache[cid]
    card = vendedor_card_for_client(session, client)
    if not card:
        cache[cid] = ("", "", None)
        return cache[cid]
    seller_name = (card.get("name") or "").strip()
    seller_code = (card.get("seller_code") or "").strip()
    seller_phone_wa = None
    emp_v = session.get(models.Employee, int(card["id"]))
    if emp_v:
        sp_e164, _ = normalize_phone_br(getattr(emp_v, "phone", None))
        if sp_e164:
            seller_phone_wa = "".join(ch for ch in sp_e164 if ch.isdigit()) or None
    cache[cid] = (seller_name, seller_code, seller_phone_wa)
    return cache[cid]


@app.get("/api/mobile/delivery/my-routes", response_class=JSONResponse)
async def api_mobile_delivery_my_routes(
    request: Request,
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
    session: Session = Depends(get_session)
):
    try:
        user_id = request.session.get("user_id")
        if not user_id:
            return JSONResponse({"error": "Não autorizado"}, status_code=401)
        user_id = int(user_id)

        today_str = datetime.now(ZoneInfo("America/Sao_Paulo")).strftime("%Y-%m-%d")
        today_dt = datetime.strptime(today_str, "%Y-%m-%d").date()
        week_ago_str = (today_dt - timedelta(days=7)).strftime("%Y-%m-%d")
        employee = session.get(models.Employee, user_id)
        employee_name = (employee.name or "").strip() if employee else ""

        # Auto-fechamento: encerra sessões abertas de dias anteriores para não travar o dia atual.
        # Regras:
        # - Fecha apenas sessões abertas anteriores a hoje (janela de 7 dias).
        # - Qualquer parada pendente/iniciada/reaberta vira devolução automática.
        try:
            stale_sessions = session.exec(
                select(models.DeliverySession)
                .where(models.DeliverySession.employee_id == user_id)
                .where(models.DeliverySession.date >= week_ago_str)
                .where(models.DeliverySession.date < today_str)
                .where(models.DeliverySession.status == "open")
                .order_by(desc(models.DeliverySession.date), desc(models.DeliverySession.id))
            ).all()
            if stale_sessions:
                now_sp = datetime.now(ZoneInfo("America/Sao_Paulo"))
                for ds_old in stale_sessions:
                    old_pending = session.exec(
                        select(models.Route)
                        .where(models.Route.type == "delivery")
                        .where(models.Route.employee_id == ds_old.employee_id)
                        .where(models.Route.date == ds_old.date)
                        .where(models.Route.delivery_status.in_(["pendente", "iniciada", "reaberta"]))
                    ).all()
                    for r in old_pending:
                        # Regra de ouro: sem devolução registrada = entregue (concluída)
                        r.delivery_status = "entregue"
                        r.delivery_finished_at = now_sp.strftime("%H:%M") if now_sp else None
                        r.delivery_returned_at = None
                        r.delivery_return_reason = None
                        r.delivery_return_photo_url = None
                        r.delivery_return_category = None
                        r.valor_devolucao = None
                        r.devolucao_volume = None
                        session.add(r)
                    ds_old.status = "closed"
                    ds_old.ended_at = now_sp
                    if ds_old.km_return is None and ds_old.km_departure is not None:
                        ds_old.km_return = ds_old.km_departure
                    session.add(ds_old)
                session.commit()
        except Exception as e_autoclose:
            logger.error(f"[DeliveryAutoClose] Falha no fechamento automático para user={user_id}: {e_autoclose}")
            session.rollback()

        # 1. Tenta sessão de hoje (motorista)
        session_open = session.exec(
            select(models.DeliverySession)
            .where(models.DeliverySession.employee_id == user_id)
            .where(models.DeliverySession.date == today_str)
            .where(models.DeliverySession.status == "open")
            .order_by(models.DeliverySession.id.desc())
        ).first()

        is_helper_view = False
        # 2. Se não encontrou, tenta como ajudante em sessões de hoje
        if not session_open and employee_name:
            sessions_today = session.exec(
                select(models.DeliverySession)
                .where(models.DeliverySession.date == today_str)
                .where(models.DeliverySession.status == "open")
            ).all()
            for ds in sessions_today:
                helpers = _parse_session_helpers(ds.helpers_json)
                if any((h or "").strip().lower() == employee_name.lower() for h in helpers):
                    session_open = ds
                    is_helper_view = True
                    break

        def _session_has_pending_routes(sess) -> bool:
            """Só considera sessão órfã se ainda houver paradas pendentes/em andamento."""
            if not sess:
                return False
            pendentes = session.exec(
                select(models.Route)
                .where(models.Route.type == "delivery")
                .where(models.Route.employee_id == sess.employee_id)
                .where(models.Route.date == sess.date)
                .where(models.Route.delivery_status.in_(["pendente", "iniciada", "reaberta"]))
            ).first()
            return pendentes is not None

        # 3. Sessão órfã: busca sessões abertas dos últimos 7 dias APENAS se houver paradas pendentes
        #    (não exibe rota já encerrada para o motorista)
        if not session_open:
            candidates = session.exec(
                select(models.DeliverySession)
                .where(models.DeliverySession.employee_id == user_id)
                .where(models.DeliverySession.date >= week_ago_str)
                .where(models.DeliverySession.date <= today_str)
                .where(models.DeliverySession.status == "open")
                .order_by(desc(models.DeliverySession.date), desc(models.DeliverySession.id))
            ).all()
            for ds in candidates:
                if _session_has_pending_routes(ds):
                    session_open = ds
                    break
        if not session_open and employee_name:
            sessions_recent = session.exec(
                select(models.DeliverySession)
                .where(models.DeliverySession.date >= week_ago_str)
                .where(models.DeliverySession.date <= today_str)
                .where(models.DeliverySession.status == "open")
                .order_by(desc(models.DeliverySession.date), desc(models.DeliverySession.id))
            ).all()
            for ds in sessions_recent:
                helpers = _parse_session_helpers(ds.helpers_json)
                if any((h or "").strip().lower() == employee_name.lower() for h in helpers):
                    if _session_has_pending_routes(ds):
                        session_open = ds
                        is_helper_view = True
                        break

        driver_id = session_open.employee_id if session_open else user_id
        q = (
            select(models.Route)
            .where(models.Route.type == "delivery")
            .where(models.Route.employee_id == driver_id)
            .where(models.Route.delivery_status.in_(["pendente", "iniciada", "reaberta", "entregue", "devolucao"]))
        )
        if date_from or date_to:
            if date_from:
                q = q.where(models.Route.date >= date_from)
            if date_to:
                q = q.where(models.Route.date <= date_to)
        else:
            today_dt = datetime.strptime(today_str, "%Y-%m-%d").date()
            month_start = today_dt.replace(day=1)
            _, last_day = calendar.monthrange(today_dt.year, today_dt.month)
            month_end = today_dt.replace(day=last_day)
            q = q.where(models.Route.date >= month_start.strftime("%Y-%m-%d"))
            q = q.where(models.Route.date <= month_end.strftime("%Y-%m-%d"))
        routes = session.exec(q.order_by(models.Route.date, models.Route.id)).all()
        client_ids = list({r.client_id for r in routes})
        clients = session.exec(select(models.Client).where(models.Client.id.in_(client_ids))).all() if client_ids else []
        client_map = {c.id: c for c in clients}
        seller_fields_cache: Dict[int, Tuple[str, str, Optional[str]]] = {}
        today_routes_for_summary = session.exec(
            select(models.Route)
            .where(models.Route.type == "delivery")
            .where(models.Route.employee_id == driver_id)
            .where(models.Route.date == today_str)
            .where(models.Route.delivery_status.in_(["pendente", "iniciada", "reaberta", "entregue", "devolucao"]))
            .order_by(models.Route.id)
        ).all()
        open_statuses = {"pendente", "iniciada", "reaberta"}
        completed_statuses = {"entregue", "devolucao"}
        today_summary = {
            "total": len(today_routes_for_summary),
            "open": sum(
                1 for route in today_routes_for_summary
                if str(getattr(route, "delivery_status", "") or "").strip().lower() in open_statuses
            ),
            "completed": sum(
                1 for route in today_routes_for_summary
                if str(getattr(route, "delivery_status", "") or "").strip().lower() in completed_statuses
            ),
        }

        payload = []
        grouped = {}
        for r in routes:
            c = client_map.get(r.client_id)
            client_name = (getattr(c, "razao_social", None) or getattr(c, "name", None) or "Cliente") if c else "Cliente"
            client_secondary = (getattr(c, "nome_fantasia", None) or getattr(c, "name", None) or "") if c else ""
            _, phone_normalized, _ = _resolve_client_phone(c)
            client_phone_wa = None
            if phone_normalized and c and _driver_whatsapp_client_phone_ok(c):
                client_phone_wa = "".join(ch for ch in phone_normalized if ch.isdigit()) or None
            seller_name, seller_code, seller_phone_wa = _mobile_my_routes_seller_fields(session, c, seller_fields_cache)
            item = {
                "id": r.id,
                "date": r.date,
                "client_name": str(client_name),
                "client_secondary": str(client_secondary or ""),
                "address": r.delivery_address or "",
                "city": r.delivery_city or "",
                "bairro": r.delivery_neighborhood or "",
                "state": r.delivery_state or "",
                "cep": r.delivery_cep or "",
                "maps_url": _maps_link(r.delivery_address, r.delivery_neighborhood, r.delivery_city, r.delivery_state, r.delivery_cep),
                "weight": _safe_float(r.tonnage),
                "value": _safe_float(r.valor_financeiro),
                "status": (r.delivery_status or "pendente"),
                "started_at": r.delivery_started_at,
                "finished_at": r.delivery_finished_at,
                "returned_at": r.delivery_returned_at,
                "reopen_count": r.delivery_reopen_count or 0,
                "vehicle_plate": r.delivery_vehicle_plate or "",
                "order_number": r.delivery_order_number or "",
                "client_code": r.delivery_client_code or "",
                "client_phone_wa": client_phone_wa,
                "seller_name": seller_name,
                "seller_code": seller_code,
                "seller_phone_wa": seller_phone_wa,
                # Coordenadas para ordenação por proximidade
                "latitude": getattr(c, "latitude", None) if c else None,
                "longitude": getattr(c, "longitude", None) if c else None,
                "tem_coordenadas": bool(c and c.has_valid_coordinates()) if c else False,
                "endereco_completo": c.get_full_address() if c else "",
            }
            payload.append(item)
            grouped.setdefault(r.date, []).append(item)

        # Placas para iniciar sessão devem refletir o planejamento de HOJE
        # (o endpoint /session/start valida apenas as rotas de hoje).
        startable_today = session.exec(
            select(models.Route)
            .where(models.Route.type == "delivery")
            .where(models.Route.employee_id == driver_id)
            .where(models.Route.date == today_str)
            .where(models.Route.delivery_status.in_(["pendente", "iniciada", "reaberta"]))
        ).all()
        assigned_plates = []
        for r in startable_today:
            if r.delivery_vehicle_plate and r.delivery_vehicle_plate not in assigned_plates:
                assigned_plates.append(r.delivery_vehicle_plate)
        if not assigned_plates:
            # fallback visual: mostra a(s) placa(s) de hoje mesmo sem rota startable
            for r in routes:
                if r.date == today_str and r.delivery_vehicle_plate and r.delivery_vehicle_plate not in assigned_plates:
                    assigned_plates.append(r.delivery_vehicle_plate)

        session_date = session_open.date if session_open else None
        day_cards = []
        for d, items in grouped.items():
            if d < today_str and not (session_open and d == session_date):
                continue  # Não mostrar dias passados, exceto o dia da sessão aberta (ex.: reaberta)
            try:
                d_fmt = datetime.strptime(d, "%Y-%m-%d").strftime("%d/%m")
            except Exception:
                d_fmt = d
            day_cards.append({
                "date": d,
                "label": f"Entregas do Dia {d_fmt}",
                "count": len(items),
                "routes": items,
            })
        day_cards.sort(key=lambda x: x["date"])

        driver_name = ""
        if session_open and is_helper_view:
            drv = session.get(models.Employee, session_open.employee_id)
            driver_name = (drv.name or "") if drv else ""
        helper_names = (
            _resolve_delivery_helper_names(
                session,
                _parse_session_helpers(session_open.helpers_json),
            )
            if session_open and getattr(session_open, "helpers_json", None)
            else []
        )
        if not helper_names:
            today_helper_ids: List[int] = []
            for route in routes:
                if route.date != today_str:
                    continue
                today_helper_ids.extend(_parse_route_helper_ids(getattr(route, "delivery_helpers_json", None)))
            ordered_helper_ids = list(dict.fromkeys(int(helper_id) for helper_id in today_helper_ids if helper_id))
            if ordered_helper_ids:
                helper_rows = session.exec(
                    select(models.Employee.id, models.Employee.name)
                    .where(models.Employee.id.in_(ordered_helper_ids))
                ).all()
                helper_map = {
                    int(helper_id): _emp_name_upper(helper_name)
                    for helper_id, helper_name in helper_rows
                    if helper_id is not None and helper_name
                }
                helper_names = [
                    helper_map.get(helper_id) or f"Ajudante #{helper_id}"
                    for helper_id in ordered_helper_ids
                ]
        helper_names = [str(name).strip() for name in helper_names if str(name or "").strip()][:3]

        closed_session_today = None
        if not session_open and not is_helper_view and user_id:
            ds_closed = session.exec(
                select(models.DeliverySession)
                .where(models.DeliverySession.employee_id == user_id)
                .where(models.DeliverySession.date == today_str)
                .where(models.DeliverySession.status == "closed")
                .order_by(desc(models.DeliverySession.id))
            ).first()
            if ds_closed:
                closed_session_today = {
                    "id": ds_closed.id,
                    "vehicle_plate": ds_closed.vehicle_plate or "",
                    "ended_at": _format_hhmm_sao_paulo(ds_closed.ended_at, ds_closed.date),
                }

        return JSONResponse(
            {
                "success": True,
                "date": today_str,
                "assigned_plate": assigned_plates[0] if assigned_plates else "",
                "assigned_plates": assigned_plates,
                "session_open": bool(session_open),
                "is_helper_view": is_helper_view,
                "driver_name": driver_name,
                "helper_names": helper_names,
                "session": {
                    "id": session_open.id if session_open else None,
                    "date": session_open.date if session_open else None,
                    "km_departure": session_open.km_departure if session_open else None,
                    "vehicle_plate": session_open.vehicle_plate if session_open else None,
                    "helpers": _parse_session_helpers(session_open.helpers_json) if session_open and session_open.helpers_json else [],
                    "started_at": _format_hhmm_sao_paulo(
                        session_open.started_at if session_open else None,
                        session_open.date if session_open else None,
                    ),
                } if session_open else None,
                "today_summary": today_summary,
                "routes": payload,
                "day_cards": day_cards,
                "return_reasons": DELIVERY_RETURN_REASONS_FLAT,
                "closed_session_today": closed_session_today,
            },
            headers={"Cache-Control": "no-store, max-age=0", "Pragma": "no-cache"},
        )
    except Exception as e:
        logger.exception("api_mobile_delivery_my_routes error: %s", e)
        # Fallback de segurança: evita 500 em produção e mantém as rotas do dia visíveis
        # enquanto investigamos a causa raiz específica dos dados.
        try:
            user_id = request.session.get("user_id")
            if not user_id:
                return JSONResponse({"error": "Não autorizado"}, status_code=401)
            user_id = int(user_id)
            today_str = datetime.now(ZoneInfo("America/Sao_Paulo")).strftime("%Y-%m-%d")
            routes_today = session.exec(
                select(models.Route)
                .where(models.Route.type == "delivery")
                .where(models.Route.employee_id == user_id)
                .where(models.Route.date == today_str)
                .where(models.Route.delivery_status.in_(["pendente", "iniciada", "reaberta", "entregue", "devolucao"]))
                .order_by(models.Route.id)
            ).all()
            fb_client_ids = list({r.client_id for r in routes_today})
            fb_clients = session.exec(select(models.Client).where(models.Client.id.in_(fb_client_ids))).all() if fb_client_ids else []
            fb_client_map = {c.id: c for c in fb_clients}
            fb_seller_cache: Dict[int, Tuple[str, str, Optional[str]]] = {}
            payload = []
            for r in routes_today:
                c_fb = fb_client_map.get(r.client_id)
                client_name_fb = (
                    (getattr(c_fb, "razao_social", None) or getattr(c_fb, "name", None) or "Cliente")
                    if c_fb
                    else "Cliente"
                )
                client_secondary_fb = (getattr(c_fb, "nome_fantasia", None) or getattr(c_fb, "name", None) or "") if c_fb else ""
                _, phone_norm_fb, _ = _resolve_client_phone(c_fb)
                client_phone_wa_fb = None
                if phone_norm_fb and c_fb and _driver_whatsapp_client_phone_ok(c_fb):
                    client_phone_wa_fb = "".join(ch for ch in phone_norm_fb if ch.isdigit()) or None
                seller_name_fb, seller_code_fb, seller_phone_wa_fb = _mobile_my_routes_seller_fields(
                    session, c_fb, fb_seller_cache
                )
                payload.append({
                    "id": r.id,
                    "date": r.date,
                    "client_name": str(client_name_fb),
                    "client_secondary": str(client_secondary_fb or ""),
                    "address": r.delivery_address or "",
                    "city": r.delivery_city or "",
                    "bairro": r.delivery_neighborhood or "",
                    "state": r.delivery_state or "",
                    "cep": r.delivery_cep or "",
                    "maps_url": _maps_link(r.delivery_address, r.delivery_neighborhood, r.delivery_city, r.delivery_state, r.delivery_cep),
                    "weight": _safe_float(r.tonnage),
                    "value": _safe_float(r.valor_financeiro),
                    "status": (r.delivery_status or "pendente"),
                    "started_at": r.delivery_started_at,
                    "finished_at": r.delivery_finished_at,
                    "returned_at": r.delivery_returned_at,
                    "reopen_count": r.delivery_reopen_count or 0,
                    "vehicle_plate": r.delivery_vehicle_plate or "",
                    "order_number": r.delivery_order_number or "",
                    "client_code": r.delivery_client_code or "",
                    "client_phone_wa": client_phone_wa_fb,
                    "seller_name": seller_name_fb,
                    "seller_code": seller_code_fb,
                    "seller_phone_wa": seller_phone_wa_fb,
                    "latitude": getattr(c_fb, "latitude", None) if c_fb else None,
                    "longitude": getattr(c_fb, "longitude", None) if c_fb else None,
                    "tem_coordenadas": bool(c_fb and c_fb.has_valid_coordinates()) if c_fb else False,
                    "endereco_completo": c_fb.get_full_address() if c_fb else "",
                })
            assigned_plates = sorted({r.delivery_vehicle_plate for r in routes_today if r.delivery_vehicle_plate})
            day_cards = [{
                "date": today_str,
                "label": f"Entregas do Dia {datetime.strptime(today_str, '%Y-%m-%d').strftime('%d/%m')}",
                "count": len(payload),
                "routes": payload,
            }] if payload else []
            open_statuses = {"pendente", "iniciada", "reaberta"}
            completed_statuses = {"entregue", "devolucao"}
            return JSONResponse(
                {
                    "success": True,
                    "date": today_str,
                    "assigned_plate": assigned_plates[0] if assigned_plates else "",
                    "assigned_plates": assigned_plates,
                    "session_open": False,
                    "is_helper_view": False,
                    "driver_name": "",
                    "helper_names": [],
                    "session": None,
                    "today_summary": {
                        "total": len(routes_today),
                        "open": sum(
                            1 for route in routes_today
                            if str(getattr(route, "delivery_status", "") or "").strip().lower() in open_statuses
                        ),
                        "completed": sum(
                            1 for route in routes_today
                            if str(getattr(route, "delivery_status", "") or "").strip().lower() in completed_statuses
                        ),
                    },
                    "routes": payload,
                    "day_cards": day_cards,
                    "return_reasons": DELIVERY_RETURN_REASONS_FLAT,
                    "closed_session_today": None,
                    "warning": "fallback_mode_enabled",
                },
                headers={"Cache-Control": "no-store, max-age=0", "Pragma": "no-cache"},
            )
        except Exception as fallback_error:
            logger.exception("api_mobile_delivery_my_routes fallback error: %s", fallback_error)
            return JSONResponse({"success": False, "error": "Falha ao carregar rotas de entrega."}, status_code=500)


@app.post("/api/mobile/delivery/session/start", response_class=JSONResponse)
async def api_mobile_delivery_session_start(
    request: Request,
    payload: MobileDeliverySessionStartPayload,
    session: Session = Depends(get_session)
):
    user_id = request.session.get("user_id")
    if not user_id:
        return JSONResponse({"error": "Não autorizado"}, status_code=401)
    try:
        user_id_int = int(str(user_id))
    except (TypeError, ValueError):
        return JSONResponse({"error": "Sessão inválida"}, status_code=401)
    today_str = datetime.now(ZoneInfo("America/Sao_Paulo")).strftime("%Y-%m-%d")

    routes = session.exec(
        select(models.Route)
        .where(models.Route.type == "delivery")
        .where(models.Route.employee_id == user_id_int)
        .where(models.Route.date == today_str)
        .where(models.Route.delivery_status.in_(["pendente", "iniciada", "reaberta"]))
    ).all()
    if not routes:
        return JSONResponse({"error": "Sem entregas planejadas para hoje."}, status_code=400)

    assigned_plates = sorted({r.delivery_vehicle_plate for r in routes if r.delivery_vehicle_plate})
    if not assigned_plates:
        return JSONResponse({"error": "Caminhão não definido no planejamento."}, status_code=400)

    if _norm_plate(payload.plate) not in {_norm_plate(p) for p in assigned_plates}:
        return JSONResponse({"error": f"Placa inválida. Placa(s) planejada(s): {', '.join(assigned_plates)}."}, status_code=400)

    existing = session.exec(
        select(models.DeliverySession)
        .where(models.DeliverySession.employee_id == user_id_int)
        .where(models.DeliverySession.date == today_str)
        .where(models.DeliverySession.status == "open")
    ).first()
    if existing:
        return JSONResponse({"error": "Rotina de entrega já iniciada."}, status_code=400)

    helper_names: List[str] = []
    seen_helpers = set()
    for h in (payload.helpers or []):
        clean = (h or "").strip()
        if not clean:
            continue
        key = clean.lower()
        if key in seen_helpers:
            continue
        seen_helpers.add(key)
        helper_names.append(clean)

    new_session = models.DeliverySession(
        date=today_str,
        employee_id=user_id_int,
        status="open",
        vehicle_plate=payload.plate.strip().upper(),
        helpers_json=json.dumps(helper_names),
        km_departure=payload.km_departure,
        started_at=datetime.now(ZoneInfo("America/Sao_Paulo")),
    )
    session.add(new_session)
    _sync_route_delivery_helpers_for_escala(
        session,
        employee_id=user_id_int,
        route_date=today_str,
        vehicle_plate=payload.plate.strip().upper(),
        helper_names=helper_names,
    )
    session.commit()
    try:
        mark_delivery_group_whatsapp_ready(
            session,
            route_date=today_str,
            shift=str(routes[0].shift or "Manhã"),
            employee_id=user_id_int,
            vehicle_plate=payload.plate.strip().upper(),
        )
    except Exception as whatsapp_error:
        logger.warning("api_mobile_delivery_session_start whatsapp ready error: %s", whatsapp_error)
    return JSONResponse({"success": True})


@app.post("/api/mobile/delivery/session/end", response_class=JSONResponse)
async def api_mobile_delivery_session_end(
    request: Request,
    payload: MobileDeliverySessionEndPayload,
    session: Session = Depends(get_session)
):
    try:
        user_id = request.session.get("user_id")
        if not user_id:
            return JSONResponse({"success": False, "error": "Não autorizado"}, status_code=401)
        try:
            user_id = int(user_id)
        except (TypeError, ValueError):
            return JSONResponse({"success": False, "error": "Sessão inválida"}, status_code=401)

        now_sp = datetime.now(ZoneInfo("America/Sao_Paulo"))
        today_str = now_sp.strftime("%Y-%m-%d")
        week_ago_str = (now_sp.date() - timedelta(days=7)).strftime("%Y-%m-%d")
        km = getattr(payload, "km_return", None)
        if km is None or (isinstance(km, (int, float)) and (km != km or km <= 0)):  # NaN or <=0
            return JSONResponse({"success": False, "error": "KM de chegada obrigatório e deve ser maior que zero."}, status_code=400)

        ds = session.exec(
            select(models.DeliverySession)
            .where(models.DeliverySession.employee_id == user_id)
            .where(models.DeliverySession.date == today_str)
            .where(models.DeliverySession.status == "open")
            .order_by(models.DeliverySession.id.desc())
        ).first()

        # Fallback: sessão órfã aberta em dia anterior (ex.: sexta-feira), ainda visível no app.
        if not ds:
            ds = session.exec(
                select(models.DeliverySession)
                .where(models.DeliverySession.employee_id == user_id)
                .where(models.DeliverySession.date >= week_ago_str)
                .where(models.DeliverySession.date <= today_str)
                .where(models.DeliverySession.status == "open")
                .order_by(desc(models.DeliverySession.date), desc(models.DeliverySession.id))
            ).first()
        if not ds:
            return JSONResponse({"success": False, "error": "Nenhuma rota aberta para encerrar (hoje ou pendente recente)."}, status_code=400)
        if km <= 0:
            return JSONResponse({"success": False, "error": "KM de chegada inválido."}, status_code=400)

        pending = session.exec(
            select(models.Route)
            .where(models.Route.type == "delivery")
            .where(models.Route.date == ds.date)
            .where(models.Route.employee_id == user_id)
            .where(models.Route.delivery_status.in_(["pendente", "iniciada", "reaberta"]))
        ).all()
        auto_closed_count = 0
        if pending:
            if ds.date < today_str:
                for r in pending:
                    # Regra de ouro: sem devolução registrada = entregue (concluída)
                    r.delivery_status = "entregue"
                    r.delivery_finished_at = now_sp.strftime("%H:%M") if now_sp else None
                    r.delivery_returned_at = None
                    r.delivery_return_reason = None
                    r.delivery_return_photo_url = None
                    r.delivery_return_category = None
                    r.valor_devolucao = None
                    r.devolucao_volume = None
                    session.add(r)
                    auto_closed_count += 1
            else:
                return JSONResponse(
                    {
                        "success": False,
                        "error": f"Ainda existem entregas em aberto na rota de {ds.date}. Finalize ou registre devolução antes de encerrar.",
                    },
                    status_code=400,
                )

        ds.km_return = km
        ds.status = "closed"
        ds.ended_at = now_sp
        session.add(ds)
        if ds.vehicle_plate:
            try:
                truck = session.exec(
                    select(models.Vehicle)
                    .where(models.Vehicle.placa == ds.vehicle_plate)
                    .where(models.Vehicle.vehicle_type == "caminhao")
                    .where(models.Vehicle.is_active == True)
                ).first()
                if truck:
                    new_km = _safe_float(km)
                    current_km = _safe_float(truck.odometer_km)
                    if truck.odometer_km is None or new_km > current_km:
                        truck.odometer_km = new_km
                        truck.updated_at = ds.ended_at
                        session.add(truck)
            except Exception as vehicle_error:
                logger.error("api_mobile_delivery_session_end vehicle odometer update error: %s", vehicle_error)
        session.commit()
        return JSONResponse(
            {
                "success": True,
                "session_date": ds.date,
                "auto_closed_count": auto_closed_count,
                "message": (
                    f"Rota de {ds.date} encerrada com fechamento tardio. "
                    f"{auto_closed_count} parada(s) pendente(s) foram marcadas como entregues (concluídas)."
                    if auto_closed_count > 0
                    else "Rota encerrada com sucesso."
                ),
            }
        )
    except Exception as e:
        logger.exception("api_mobile_delivery_session_end error: %s", e)
        session.rollback()
        return JSONResponse(
            {
                "success": False,
                "error": "Erro interno ao encerrar rota. Tente novamente.",
                "debug_hint": "session_end_failure"
            },
            status_code=500
        )


@app.post("/api/mobile/delivery/session/reopen", response_class=JSONResponse)
async def api_mobile_delivery_session_reopen(
    request: Request,
    payload: MobileDeliverySessionReopenPayload,
    session: Session = Depends(get_session)
):
    """Reabre rota fechada no mesmo dia, informando o motivo."""
    user_id = request.session.get("user_id")
    if not user_id:
        return JSONResponse({"success": False, "error": "Não autorizado"}, status_code=401)
    try:
        user_id = int(user_id)
    except (TypeError, ValueError):
        return JSONResponse({"success": False, "error": "Sessão inválida"}, status_code=401)
    today_str = datetime.now(ZoneInfo("America/Sao_Paulo")).strftime("%Y-%m-%d")
    reason = (payload.reason or "").strip()
    if not reason:
        return JSONResponse({"success": False, "error": "Informe o motivo da reabertura."}, status_code=400)

    ds = session.exec(
        select(models.DeliverySession)
        .where(models.DeliverySession.employee_id == user_id)
        .where(models.DeliverySession.date == today_str)
        .where(models.DeliverySession.status == "closed")
        .order_by(desc(models.DeliverySession.id))
    ).first()
    if not ds:
        return JSONResponse({"success": False, "error": "Nenhuma rota encerrada hoje para reabrir."}, status_code=400)

    ds.status = "open"
    ds.ended_at = None
    ds.reopen_reason = reason[:512] if reason else None
    session.add(ds)
    session.commit()
    return JSONResponse({"success": True})


@app.post("/api/mobile/delivery/session/update", response_class=JSONResponse)
async def api_mobile_delivery_session_update(
    request: Request,
    payload: MobileDeliverySessionUpdatePayload,
    session: Session = Depends(get_session)
):
    """Atualiza sessão em aberto: ajudantes e/ou KM de saída."""
    user_id = request.session.get("user_id")
    if not user_id:
        return JSONResponse({"success": False, "error": "Não autorizado"}, status_code=401)
    try:
        user_id = int(user_id)
    except (TypeError, ValueError):
        return JSONResponse({"success": False, "error": "Sessão inválida"}, status_code=401)
    today_str = datetime.now(ZoneInfo("America/Sao_Paulo")).strftime("%Y-%m-%d")
    ds = session.exec(
        select(models.DeliverySession)
        .where(models.DeliverySession.employee_id == user_id)
        .where(models.DeliverySession.date == today_str)
        .where(models.DeliverySession.status == "open")
        .order_by(models.DeliverySession.id.desc())
    ).first()
    if not ds:
        return JSONResponse({"success": False, "error": "Nenhuma rota aberta para atualizar."}, status_code=400)
    updated = False
    if payload.helpers is not None:
        helper_names = [(h or "").strip() for h in payload.helpers if (h or "").strip()]
        seen = set()
        unique = []
        for h in helper_names:
            k = h.lower()
            if k not in seen:
                seen.add(k)
                unique.append(h)
        ds.helpers_json = json.dumps(unique, ensure_ascii=False) if unique else None
        updated = True
        _sync_route_delivery_helpers_for_escala(
            session,
            employee_id=user_id,
            route_date=ds.date,
            vehicle_plate=ds.vehicle_plate or "",
            helper_names=unique,
        )
    if payload.km_departure is not None and isinstance(payload.km_departure, (int, float)):
        km = float(payload.km_departure)
        if km > 0:
            ds.km_departure = km
            updated = True
            # Atualizar Vehicle.odometer_km (histórico)
            if ds.vehicle_plate:
                truck = session.exec(
                    select(models.Vehicle)
                    .where(models.Vehicle.placa == ds.vehicle_plate)
                    .where(models.Vehicle.vehicle_type == "caminhao")
                    .where(models.Vehicle.is_active == True)
                ).first()
                if truck and (truck.odometer_km is None or km > float(truck.odometer_km or 0)):
                    truck.odometer_km = km
                    truck.updated_at = datetime.now(ZoneInfo("America/Sao_Paulo"))
                    session.add(truck)
    if updated:
        session.add(ds)
        session.commit()
    return JSONResponse({"success": True})


@app.post("/api/mobile/delivery/location", response_class=JSONResponse)
async def api_mobile_delivery_location(
    request: Request,
    payload: MobileDeliveryLocationPayload,
    session: Session = Depends(get_session),
):
    """Recebe ping de GPS do motorista durante sessão aberta (evita 404 no app)."""
    user_id = request.session.get("user_id")
    if not user_id:
        return JSONResponse({"success": False, "error": "Não autorizado"}, status_code=401)
    try:
        user_id = int(user_id)
    except (TypeError, ValueError):
        return JSONResponse({"success": False, "error": "Sessão inválida"}, status_code=401)
    lat, lon = float(payload.latitude), float(payload.longitude)
    if abs(lat) > 90.0 or abs(lon) > 180.0 or math.isnan(lat) or math.isnan(lon):
        return JSONResponse({"success": False, "error": "Coordenadas inválidas."}, status_code=400)
    plate_norm = _norm_plate(payload.vehicle_plate)
    if len(plate_norm) < 7:
        return JSONResponse({"success": False, "error": "Placa inválida."}, status_code=400)
    today_str = datetime.now(ZoneInfo("America/Sao_Paulo")).strftime("%Y-%m-%d")
    now_sp = datetime.now(ZoneInfo("America/Sao_Paulo"))
    ds = session.exec(
        select(models.DeliverySession)
        .where(models.DeliverySession.employee_id == user_id)
        .where(models.DeliverySession.date == today_str)
        .where(models.DeliverySession.status == "open")
        .order_by(desc(models.DeliverySession.id))
    ).first()
    if not ds:
        return JSONResponse({"success": False, "error": "Sem sessão aberta."}, status_code=400)
    if _norm_plate(ds.vehicle_plate) != plate_norm:
        return JSONResponse({"success": False, "error": "Placa não confere com a sessão."}, status_code=400)
    ds.driver_last_lat = lat
    ds.driver_last_lon = lon
    ds.driver_last_location_at = now_sp
    session.add(ds)
    session.commit()
    return JSONResponse({"success": True}, headers={"Cache-Control": "no-store"})


@app.post("/api/mobile/delivery/route/{route_id}/action", response_class=JSONResponse)
async def api_mobile_delivery_route_action(
    request: Request,
    route_id: int,
    payload: MobileDeliveryActionPayload,
    session: Session = Depends(get_session)
):
    try:
        user_id = request.session.get("user_id")
        if not user_id:
            return JSONResponse({"error": "Não autorizado"}, status_code=401)
        try:
            user_id = int(str(user_id))
        except (TypeError, ValueError):
            return JSONResponse({"error": "Sessão inválida"}, status_code=401)
        route = session.get(models.Route, route_id)
        if not route or route.type != "delivery" or int(route.employee_id or 0) != int(user_id):
            return JSONResponse({"error": "Rota inválida."}, status_code=404)

        today_str = datetime.now(ZoneInfo("America/Sao_Paulo")).strftime("%Y-%m-%d")
        ds = session.exec(
            select(models.DeliverySession)
            .where(models.DeliverySession.employee_id == user_id)
            .where(models.DeliverySession.date == today_str)
            .where(models.DeliverySession.status == "open")
        ).first()
        if not ds:
            return JSONResponse({"error": "Inicie a rotina (placa/KM) antes de operar entregas."}, status_code=400)

        action = (payload.action or "").lower().strip()
        now = datetime.now(ZoneInfo("America/Sao_Paulo")).strftime("%H:%M")
        xp_earned = 0
        if action == "iniciar":
            existing_started = session.exec(
                select(models.Route)
                .where(models.Route.type == "delivery")
                .where(models.Route.date == route.date)
                .where(models.Route.employee_id == user_id)
                .where(models.Route.delivery_status == "iniciada")
                .where(models.Route.id != route.id)
            ).first()
            if existing_started:
                return JSONResponse({"error": "Já existe uma entrega iniciada."}, status_code=400)
            if (route.delivery_status or "").lower() in ("entregue", "devolucao"):
                return JSONResponse({"error": "Rota concluída. Reabra para iniciar novamente."}, status_code=400)
            iniciar_note = None
            client_obj = session.get(models.Client, route.client_id) if route.client_id else None
            client_has_gps = bool(
                client_obj
                and client_obj.latitude is not None
                and client_obj.longitude is not None
                and -90.0 <= float(client_obj.latitude) <= 90.0
                and -180.0 <= float(client_obj.longitude) <= 180.0
            )
            driver_has_gps = payload.latitude is not None and payload.longitude is not None
            if client_has_gps and driver_has_gps:
                dist_m = _haversine_meters(
                    float(payload.latitude), float(payload.longitude),
                    float(client_obj.latitude), float(client_obj.longitude),
                )
                if dist_m > DELIVERY_INICIO_MAX_METROS:
                    ar_ok = False
                    if payload.auth_request_id:
                        ar = session.get(models.DeliveryAuthRequest, payload.auth_request_id)
                        if (
                            ar
                            and ar.route_id == route.id
                            and int(ar.driver_id) == int(user_id)
                            and (ar.status or "").lower() == "approved"
                        ):
                            ar_ok = True
                            iniciar_note = (
                                f"Início autorizado fora do raio (solicitação #{ar.id}, ~{int(dist_m)} m). "
                                f"Motivo: {(ar.motivo or '')[:300]}"
                            )
                    if not ar_ok:
                        return JSONResponse(
                            {
                                "success": False,
                                "error": (
                                    f"Você está a cerca de {int(dist_m)} m do cliente. "
                                    f"Aproxime-se (máximo {int(DELIVERY_INICIO_MAX_METROS)} m) ou solicite autorização ao supervisor."
                                ),
                                "code": "DISTANCE_TOO_FAR",
                                "distancia_metros": round(dist_m, 1),
                            },
                            status_code=400,
                        )
            route.delivery_status = "iniciada"
            route.start_time = now
            if not route.delivery_started_at:
                route.delivery_started_at = now
            if payload.latitude is not None and payload.longitude is not None:
                route.driver_lat_start = payload.latitude
                route.driver_lon_start = payload.longitude
            _append_delivery_event(route, "iniciar", now, iniciar_note)
            try:
                mark_delivery_group_whatsapp_ready(
                    session,
                    route_date=route.date,
                    shift=route.shift or "Manhã",
                    employee_id=int(route.employee_id or 0),
                    vehicle_plate=route.delivery_vehicle_plate or ds.vehicle_plate or "",
                )
            except Exception as whatsapp_error:
                logger.warning("api_mobile_delivery_route_action whatsapp ready error: %s", whatsapp_error)

        elif action == "finalizar":
            if (route.delivery_status or "").lower() != "iniciada":
                return JSONResponse({"error": "Só pode finalizar rota iniciada."}, status_code=400)
            route.delivery_status = "entregue"
            route.status = "completed"
            route.end_time = now
            if not route.delivery_finished_at:
                route.delivery_finished_at = now
            if payload.latitude is not None and payload.longitude is not None:
                route.driver_lat_end = payload.latitude
                route.driver_lon_end = payload.longitude
            route.delivery_return_category = None
            route.delivery_return_reason = None
            route.delivery_return_photo_url = None
            route.delivery_notified_commercial = None
            route.delivery_notified_commercial_name = None
            route.delivery_notified_logistics = None
            route.delivery_notified_logistics_name = None
            _append_delivery_event(route, "finalizar", now)
            # +1 XP por entrega concluída (evita duplicidade por rota)
            reference_id = f"delivery_route:{route.id}"
            existing_xp = session.exec(
                select(models.XPLedger)
                .where(models.XPLedger.employee_id == int(user_id))
                .where(models.XPLedger.transaction_type == "DELIVERY_COMPLETED")
                .where(models.XPLedger.reference_id == reference_id)
            ).first()
            if not existing_xp:
                add_xp_transaction(
                    session=session,
                    employee_id=int(user_id),
                    points=1,
                    type="DELIVERY_COMPLETED",
                    reference_id=reference_id,
                    note=f"Entrega concluída na rota #{route.id}"
                )
                xp_earned = 1

        elif action == "devolucao":
            if (route.delivery_status or "").lower() != "iniciada":
                return JSONResponse({"error": "Inicie a entrega antes de devolver."}, status_code=400)
            if not payload.return_reason:
                return JSONResponse({"error": "Informe o motivo da devolução."}, status_code=400)
            if payload.return_reason not in DELIVERY_RETURN_REASONS_FLAT:
                return JSONResponse({"error": "Motivo de devolução inválido."}, status_code=400)
            if payload.return_notified_commercial is None:
                return JSONResponse({"error": "Informe se avisou o Comercial."}, status_code=400)
            if payload.return_notified_logistics is None:
                return JSONResponse({"error": "Informe se avisou a Logística."}, status_code=400)
            commercial_seller = None
            commercial_name = None
            if payload.return_notified_commercial:
                commercial_seller = _resolve_delivery_commercial_seller(
                    session,
                    payload.return_notified_commercial_employee_id,
                    payload.return_notified_commercial_name,
                )
                if not commercial_seller:
                    return JSONResponse({"error": "Selecione um vendedor do Comercial com código de vendedor cadastrado."}, status_code=400)
                commercial_name = _clean_delivery_contact_name(commercial_seller.name)
            logistics_name = _clean_delivery_contact_name(payload.return_notified_logistics_name)
            if payload.return_notified_logistics and not logistics_name:
                return JSONResponse({"error": "Informe o nome da pessoa da Logística avisada."}, status_code=400)
            if _requires_closed_store_photo(payload.return_reason) and not _normalize_delivery_return_photo_url(
                (payload.return_photo_url or "").strip()
            ):
                return JSONResponse({"error": "Para cliente fechado, anexe a foto do estabelecimento."}, status_code=400)
            route.delivery_status = "devolucao"
            route.status = "completed"
            route.end_time = now
            if not route.delivery_returned_at:
                route.delivery_returned_at = now
            if not route.delivery_finished_at:
                route.delivery_finished_at = now
            route.delivery_return_category = DELIVERY_RETURN_REASON_TO_CATEGORY.get(
                payload.return_reason, "COMERCIAL"
            )
            route.delivery_return_reason = payload.return_reason
            route.delivery_return_photo_url = _normalize_delivery_return_photo_url(
                (payload.return_photo_url or "").strip()
            )
            if payload.latitude is not None and payload.longitude is not None:
                route.driver_lat_end = payload.latitude
                route.driver_lon_end = payload.longitude
            route.delivery_notified_commercial = bool(payload.return_notified_commercial)
            route.delivery_notified_commercial_name = commercial_name if payload.return_notified_commercial else None
            route.delivery_notified_logistics = bool(payload.return_notified_logistics)
            route.delivery_notified_logistics_name = logistics_name if payload.return_notified_logistics else None
            if payload.return_is_partial:
                w = float(payload.return_partial_weight or 0.0)
                v = float(payload.return_partial_value or 0.0)
                if w <= 0 and v <= 0:
                    return JSONResponse({"error": "Para devolução parcial informe peso e/ou valor."}, status_code=400)
                route.devolucao_volume = min(w, float(route.tonnage or 0.0)) if w > 0 else 0.0
                route.valor_devolucao = min(v, float(route.valor_financeiro or 0.0)) if v > 0 else 0.0
            else:
                route.devolucao_volume = route.tonnage or 0.0
                route.valor_devolucao = route.valor_financeiro or 0.0
            note_parts = [payload.return_reason]
            if payload.return_is_partial:
                note_parts.append(f"Parcial | peso={route.devolucao_volume or 0.0:.2f} | valor={route.valor_devolucao or 0.0:.2f}")
            contacts_note = _build_delivery_return_contacts_note(route)
            note_parts.append(contacts_note)
            _append_delivery_event(route, "devolucao", now, note=" | ".join(note_parts))
            try:
                devolucao = sync_route_to_devolucao(session, route, source="MOBILE")
                if devolucao:
                    devolucao.observacao = contacts_note
                    session.add(devolucao)
            except Exception as e:
                logger.warning(f"sync_route_to_devolucao mobile: {e}")
            xp_earned = 0

        elif action == "reabrir":
            if (route.delivery_status or "").lower() not in ("entregue", "devolucao"):
                return JSONResponse({"error": "Somente rotas concluídas podem ser reabertas."}, status_code=400)
            existing_started = session.exec(
                select(models.Route)
                .where(models.Route.type == "delivery")
                .where(models.Route.date == route.date)
                .where(models.Route.employee_id == user_id)
                .where(models.Route.delivery_status == "iniciada")
                .where(models.Route.id != route.id)
            ).first()
            if existing_started:
                return JSONResponse({"error": "Já existe uma entrega iniciada."}, status_code=400)
            if (route.delivery_status or "").lower() == "devolucao":
                session.exec(delete(models.Devolucao).where(models.Devolucao.route_id == route.id))
            route.delivery_status = "reaberta"
            route.status = "pending"
            route.end_time = None
            route.delivery_return_category = None
            route.delivery_return_reason = None
            route.delivery_return_photo_url = None
            route.delivery_notified_commercial = None
            route.delivery_notified_commercial_name = None
            route.delivery_notified_logistics = None
            route.delivery_notified_logistics_name = None
            route.devolucao_volume = None
            route.valor_devolucao = None
            route.delivery_returned_at = None
            route.delivery_finished_at = None
            route.driver_lat_start = None
            route.driver_lon_start = None
            route.driver_lat_end = None
            route.driver_lon_end = None
            route.delivery_reopen_count = (route.delivery_reopen_count or 0) + 1
            _append_delivery_event(route, "reabrir", now)

        else:
            return JSONResponse({"error": "Ação inválida."}, status_code=400)

        session.add(route)
        session.commit()
        return JSONResponse({
            "success": True,
            "action": action,
            "xp_earned": xp_earned,
            "mood": "sad" if action == "devolucao" else ("celebrate" if action == "finalizar" else "neutral"),
        })
    except OperationalError as e:
        session.rollback()
        logger.warning("api_mobile_delivery_route_action DB indisponível route_id=%s: %s", route_id, str(e)[:150])
        return JSONResponse({"success": False, "error": "Banco indisponível. A ação será sincronizada ao conectar."}, status_code=503)
    except Exception as e:
        session.rollback()
        logger.exception("api_mobile_delivery_route_action error route_id=%s action=%s: %s", route_id, getattr(payload, "action", ""), e)
        return JSONResponse({"success": False, "error": "Erro ao processar ação. Tente novamente."}, status_code=500)


@app.post("/api/mobile/delivery/route/{route_id}/return-photo", response_class=JSONResponse)
async def api_mobile_delivery_return_photo_upload(
    route_id: int,
    request: Request,
    file: UploadFile = File(...),
    session: Session = Depends(get_session),
):
    user_id = request.session.get("user_id")
    if not user_id:
        return JSONResponse({"success": False, "error": "Não autorizado."}, status_code=401)
    route = session.get(models.Route, route_id)
    if not route or route.type != "delivery":
        return JSONResponse({"success": False, "error": "Rota inválida."}, status_code=404)
    if int(route.employee_id or 0) != int(user_id):
        return JSONResponse({"success": False, "error": "Acesso negado à rota."}, status_code=403)
    try:
        photo_url = await _save_delivery_return_photo(file, route_id, int(user_id))
        return JSONResponse({"success": True, "photo_url": photo_url})
    except ValueError as ve:
        return JSONResponse({"success": False, "error": str(ve)}, status_code=400)
    except Exception as e:
        logger.warning("upload return photo route_id=%s: %s", route_id, e, exc_info=True)
        return JSONResponse({"success": False, "error": "Erro ao enviar foto. Tente novamente."}, status_code=500)


@app.post("/api/mobile/delivery/sync-batch", response_class=JSONResponse)
async def api_mobile_delivery_sync_batch(
    request: Request,
    body: SyncBatchPayload,
    session: Session = Depends(get_session),
):
    """Sincroniza ações enfileiradas offline (chamado ao reconectar)."""
    try:
        user_id = request.session.get("user_id")
        if not user_id:
            return JSONResponse({"success": False, "error": "Não autorizado", "results": []}, status_code=401)

        try:
            user_id = int(str(user_id))
        except Exception:
            return JSONResponse({"success": False, "error": "ID inválido", "results": []}, status_code=400)

        actions_list = body.actions if body and getattr(body, "actions", None) is not None else []
        today_str = datetime.now(ZoneInfo("America/Sao_Paulo")).strftime("%Y-%m-%d")
        ds = session.exec(
            select(models.DeliverySession)
            .where(models.DeliverySession.employee_id == user_id)
            .where(models.DeliverySession.date == today_str)
            .where(models.DeliverySession.status == "open")
        ).first()
        if not ds:
            return JSONResponse({
                "success": True,
                "results": [
                    {"queue_id": a.get("queue_id"), "success": False, "already_done": False, "error": "Sessão não aberta."}
                    for a in actions_list
                ],
            })

        results = []
        for a in actions_list:
            qid = a.get("queue_id")
            route_id = a.get("route_id")
            act = (a.get("action") or "").lower().strip()
            try:
                if not route_id or not act:
                    results.append({"queue_id": qid, "success": False, "already_done": False, "error": "Dados inválidos."})
                    continue
                route = session.get(models.Route, int(route_id))
                if not route or route.type != "delivery" or int(route.employee_id) != user_id:
                    results.append({"queue_id": qid, "success": False, "already_done": False, "error": "Rota inválida."})
                    continue
                now = datetime.now(ZoneInfo("America/Sao_Paulo")).strftime("%H:%M")
                payload = MobileDeliveryActionPayload(
                    action=act,
                    latitude=a.get("latitude"),
                    longitude=a.get("longitude"),
                    auth_request_id=a.get("auth_request_id"),
                    return_reason=a.get("return_reason"),
                    return_is_partial=bool(a.get("return_is_partial")),
                    return_partial_weight=a.get("return_partial_weight"),
                    return_partial_value=a.get("return_partial_value"),
                    return_notified_commercial=a.get("return_notified_commercial"),
                    return_notified_commercial_employee_id=a.get("return_notified_commercial_employee_id"),
                    return_notified_commercial_name=a.get("return_notified_commercial_name"),
                    return_notified_logistics=a.get("return_notified_logistics"),
                    return_notified_logistics_name=a.get("return_notified_logistics_name"),
                    return_photo_url=a.get("return_photo_url"),
                )
                if act == "iniciar":
                    if (route.delivery_status or "").lower() in ("entregue", "devolucao"):
                        results.append({"queue_id": qid, "success": True, "already_done": True})
                        continue
                    route.delivery_status = "iniciada"
                    route.start_time = now
                    if not route.delivery_started_at:
                        route.delivery_started_at = now
                    if payload.latitude is not None and payload.longitude is not None:
                        route.driver_lat_start = payload.latitude
                        route.driver_lon_start = payload.longitude
                    _append_delivery_event(route, "iniciar", now, None)
                elif act == "finalizar":
                    if (route.delivery_status or "").lower() != "iniciada":
                        results.append({"queue_id": qid, "success": True, "already_done": True})
                        continue
                    route.delivery_status = "entregue"
                    route.status = "completed"
                    route.end_time = now
                    if not route.delivery_finished_at:
                        route.delivery_finished_at = now
                    if payload.latitude is not None and payload.longitude is not None:
                        route.driver_lat_end = payload.latitude
                        route.driver_lon_end = payload.longitude
                    route.delivery_return_photo_url = None
                    _append_delivery_event(route, "finalizar", now)
                elif act == "devolucao":
                    if (route.delivery_status or "").lower() != "iniciada":
                        results.append({"queue_id": qid, "success": True, "already_done": True})
                        continue
                    if not payload.return_reason or payload.return_reason not in DELIVERY_RETURN_REASONS_FLAT:
                        results.append({"queue_id": qid, "success": False, "already_done": False, "error": "Motivo de devolução inválido."})
                        continue
                    if _requires_closed_store_photo(payload.return_reason) and not _normalize_delivery_return_photo_url(
                        (payload.return_photo_url or "").strip()
                    ):
                        results.append({"queue_id": qid, "success": False, "already_done": False, "error": "Para cliente fechado, anexe a foto do estabelecimento."})
                        continue
                    commercial_seller = None
                    commercial_name = None
                    if payload.return_notified_commercial:
                        commercial_seller = _resolve_delivery_commercial_seller(
                            session,
                            payload.return_notified_commercial_employee_id,
                            payload.return_notified_commercial_name,
                        )
                        if not commercial_seller:
                            results.append({"queue_id": qid, "success": False, "already_done": False, "error": "Selecione um vendedor do Comercial com código de vendedor cadastrado."})
                            continue
                        commercial_name = _clean_delivery_contact_name(commercial_seller.name)
                    logistics_name = _clean_delivery_contact_name(payload.return_notified_logistics_name)
                    route.delivery_status = "devolucao"
                    route.status = "completed"
                    route.end_time = now
                    if not route.delivery_returned_at:
                        route.delivery_returned_at = now
                    if not route.delivery_finished_at:
                        route.delivery_finished_at = now
                    route.delivery_return_category = DELIVERY_RETURN_REASON_TO_CATEGORY.get(payload.return_reason, "COMERCIAL")
                    route.delivery_return_reason = payload.return_reason
                    route.delivery_return_photo_url = _normalize_delivery_return_photo_url(
                        (payload.return_photo_url or "").strip()
                    )
                    if payload.latitude is not None and payload.longitude is not None:
                        route.driver_lat_end = payload.latitude
                        route.driver_lon_end = payload.longitude
                    route.delivery_notified_commercial = bool(payload.return_notified_commercial)
                    route.delivery_notified_commercial_name = commercial_name if payload.return_notified_commercial else None
                    route.delivery_notified_logistics = bool(payload.return_notified_logistics)
                    route.delivery_notified_logistics_name = logistics_name if payload.return_notified_logistics else None
                    if payload.return_is_partial:
                        w = float(payload.return_partial_weight or 0.0)
                        v = float(payload.return_partial_value or 0.0)
                        route.devolucao_volume = min(w, float(route.tonnage or 0.0)) if w > 0 else 0.0
                        route.valor_devolucao = min(v, float(route.valor_financeiro or 0.0)) if v > 0 else 0.0
                    else:
                        route.devolucao_volume = route.tonnage or 0.0
                        route.valor_devolucao = route.valor_financeiro or 0.0
                    note_parts = [payload.return_reason]
                    if payload.return_is_partial:
                        note_parts.append(f"Parcial | peso={route.devolucao_volume or 0.0:.2f} | valor={route.valor_devolucao or 0.0:.2f}")
                    contacts_note = _build_delivery_return_contacts_note(route)
                    note_parts.append(contacts_note)
                    _append_delivery_event(route, "devolucao", now, note=" | ".join(note_parts))
                    try:
                        devolucao = sync_route_to_devolucao(session, route, source="MOBILE")
                        if devolucao:
                            devolucao.observacao = contacts_note
                            session.add(devolucao)
                    except Exception as e:
                        logger.warning("sync_route_to_devolucao sync-batch: %s", e)
                elif act == "reabrir":
                    if (route.delivery_status or "").lower() not in ("entregue", "devolucao"):
                        results.append({"queue_id": qid, "success": True, "already_done": True})
                        continue
                    if (route.delivery_status or "").lower() == "devolucao":
                        session.exec(delete(models.Devolucao).where(models.Devolucao.route_id == route.id))
                    route.delivery_status = "reaberta"
                    route.status = "pending"
                    route.end_time = None
                    route.delivery_return_category = None
                    route.delivery_return_reason = None
                    route.delivery_return_photo_url = None
                    route.devolucao_volume = None
                    route.valor_devolucao = None
                    route.delivery_returned_at = None
                    route.delivery_finished_at = None
                    route.delivery_reopen_count = (route.delivery_reopen_count or 0) + 1
                    _append_delivery_event(route, "reabrir", now)
                else:
                    results.append({"queue_id": qid, "success": False, "already_done": False, "error": f"Ação '{act}' não suportada em sync."})
                    continue
                session.add(route)
                session.commit()
                results.append({"queue_id": qid, "success": True, "already_done": False})
            except Exception as e:
                session.rollback()
                logger.warning("sync-batch action error: %s", e, exc_info=True)
                results.append({"queue_id": qid, "success": False, "already_done": False, "error": str(e)[:200]})

        return JSONResponse({"success": True, "results": results})
    except Exception as e:
        logger.exception("api_mobile_delivery_sync_batch error: %s", e)
        return JSONResponse({
            "success": False,
            "error": "Erro ao sincronizar. Tente novamente.",
            "results": [{"queue_id": None, "success": False, "already_done": False, "error": str(e)[:200]}],
        })


@app.post("/api/mobile/delivery/auth-request", response_class=JSONResponse)
async def api_mobile_delivery_auth_request_create(
    request: Request,
    body: MobileDeliveryAuthRequestCreate,
    session: Session = Depends(get_session),
):
    user_id = request.session.get("user_id")
    if not user_id:
        return JSONResponse({"success": False, "error": "Não autorizado"}, status_code=401)
    motivo = (body.motivo or "").strip()
    if len(motivo) < 5:
        return JSONResponse({"success": False, "error": "Informe o motivo (mínimo 5 caracteres)."}, status_code=400)
    route = session.get(models.Route, body.route_id)
    if not route or route.type != "delivery" or int(route.employee_id) != int(user_id):
        return JSONResponse({"success": False, "error": "Rota inválida."}, status_code=404)
    today_str = datetime.now(ZoneInfo("America/Sao_Paulo")).strftime("%Y-%m-%d")
    if str(route.date) != today_str:
        return JSONResponse({"success": False, "error": "Rota não é do dia atual."}, status_code=400)
    st = (route.delivery_status or "").lower()
    if st not in ("pendente", "reaberta"):
        return JSONResponse(
            {"success": False, "error": "Esta parada não está disponível para esta solicitação."},
            status_code=400,
        )
    existing = session.exec(
        select(models.DeliveryAuthRequest).where(
            models.DeliveryAuthRequest.route_id == route.id,
            models.DeliveryAuthRequest.driver_id == int(user_id),
            models.DeliveryAuthRequest.status == "pending",
        )
    ).first()
    if existing:
        return JSONResponse({"success": True, "id": existing.id, "existing": True})
    ar = models.DeliveryAuthRequest(
        route_id=route.id,
        driver_id=int(user_id),
        client_name=((body.client_name or "").strip()[:500] or None),
        distancia_metros=body.distancia_metros,
        motivo=motivo[:2000],
        status="pending",
    )
    session.add(ar)
    session.commit()
    session.refresh(ar)
    return JSONResponse({"success": True, "id": ar.id})


@app.get("/api/mobile/delivery/auth-request/{req_id}", response_class=JSONResponse)
async def api_mobile_delivery_auth_request_poll(
    req_id: int, request: Request, session: Session = Depends(get_session)
):
    user_id = request.session.get("user_id")
    if not user_id:
        return JSONResponse({"error": "Não autorizado"}, status_code=401)
    ar = session.get(models.DeliveryAuthRequest, req_id)
    if not ar or int(ar.driver_id) != int(user_id):
        return JSONResponse({"error": "Não encontrado."}, status_code=404)
    return JSONResponse({
        "id": ar.id,
        "status": ar.status,
        "obs": ar.obs,
        "resolved_at": ar.resolved_at.isoformat() if ar.resolved_at else None,
    })


def _delivery_auth_request_row(session: Session, ar: models.DeliveryAuthRequest) -> Dict[str, Any]:
    emp = session.get(models.Employee, ar.driver_id)
    return {
        "id": ar.id,
        "route_id": ar.route_id,
        "driver_name": emp.name if emp else f"#{ar.driver_id}",
        "client_name": ar.client_name,
        "distancia_metros": ar.distancia_metros,
        "motivo": ar.motivo,
        "status": ar.status,
        "requested_at": ar.requested_at.isoformat() if ar.requested_at else None,
        "resolved_at": ar.resolved_at.isoformat() if ar.resolved_at else None,
        "obs": ar.obs,
    }


@app.get("/api/admin/delivery-auth-requests", response_class=JSONResponse)
async def api_admin_delivery_auth_requests_list(request: Request, session: Session = Depends(get_session)):
    require_leader(request)
    pending = session.exec(
        select(models.DeliveryAuthRequest)
        .where(models.DeliveryAuthRequest.status == "pending")
        .order_by(models.DeliveryAuthRequest.requested_at)
    ).all()
    recent = session.exec(
        select(models.DeliveryAuthRequest)
        .where(models.DeliveryAuthRequest.status != "pending")
        .order_by(desc(models.DeliveryAuthRequest.resolved_at))
        .limit(80)
    ).all()
    return JSONResponse({
        "pending": [_delivery_auth_request_row(session, a) for a in pending],
        "recent": [_delivery_auth_request_row(session, a) for a in recent],
    })


@app.patch("/api/admin/delivery-auth-requests/{req_id}", response_class=JSONResponse)
async def api_admin_delivery_auth_requests_resolve(
    req_id: int,
    request: Request,
    payload: AdminDeliveryAuthResolvePayload,
    session: Session = Depends(get_session),
):
    require_leader(request)
    st = (payload.status or "").lower().strip()
    if st not in ("approved", "denied"):
        return JSONResponse({"error": "Use status approved ou denied."}, status_code=400)
    ar = session.get(models.DeliveryAuthRequest, req_id)
    if not ar:
        return JSONResponse({"error": "Solicitação não encontrada."}, status_code=404)
    if (ar.status or "").lower() != "pending":
        return JSONResponse({"error": "Esta solicitação já foi respondida."}, status_code=400)
    user = get_current_user(request)
    resolver_id = None
    if isinstance(user, dict) and user.get("id") is not None:
        try:
            resolver_id = int(user["id"])
        except (TypeError, ValueError):
            resolver_id = None
    ar.status = "approved" if st == "approved" else "denied"
    ar.resolved_at = datetime.now(ZoneInfo("America/Sao_Paulo"))
    ar.resolved_by = resolver_id
    ar.obs = ((payload.obs or "").strip()[:1000] or None)
    session.add(ar)
    session.commit()
    return JSONResponse({"success": True, "id": ar.id, "status": ar.status})


@app.get("/admin/delivery-auth-requests", response_class=HTMLResponse)
async def admin_delivery_auth_requests_page(request: Request, session: Session = Depends(get_session)):
    require_leader(request)
    user = get_current_user(request)
    return templates.TemplateResponse(
        "admin_delivery_auth_requests.html",
        {"request": request, "user": user},
    )


