@app.get("/clients/{client_id}", response_class=HTMLResponse)
async def client_details(request: Request, client_id: int, session: Session = Depends(get_session)):
    user = require_login(request)
    client = session.get(models.Client, client_id)
    if not client:
        return RedirectResponse(url="/clients")
    client_phone_e164, client_phone_display = normalize_phone_br(getattr(client, "fone_e164", None) or getattr(client, "fone", None))
    client_alt_phone_e164, client_alt_phone_display = normalize_phone_br(getattr(client, "fone_alternativo", None))
        
    # Fetch all routes for this client
    routes = session.exec(
        select(models.Route)
        .where(models.Route.client_id == client_id)
        .order_by(models.Route.date.desc(), models.Route.start_time.desc())
    ).all()
    
    # --- Metrics Logic ---
    total_tonnage = 0.0
    total_duration_secs = 0.0
    count_duration = 0
    
    # Period Stats (tonnage)
    today = datetime.now().date()
    stats_today = 0.0
    stats_week = 0.0
    stats_month = 0.0
    stats_year = 0.0
    # Period Stats (valor financeiro R$)
    valor_today, valor_week, valor_month, valor_year = 0.0, 0.0, 0.0, 0.0
    # Period Stats (devolucao volume ton e valor R$)
    dev_vol_today, dev_vol_week, dev_vol_month, dev_vol_year = 0.0, 0.0, 0.0, 0.0
    valor_dev_today, valor_dev_week, valor_dev_month, valor_dev_year = 0.0, 0.0, 0.0, 0.0

    # Employee Stats
    emp_counter = {}
    
    emp_map = {e.id: e.name for e in session.exec(select(models.Employee)).all()}
    
    history = []
    
    for r in routes:
        t = r.tonnage or 0.0
        total_tonnage += t
        
        # Date Parsing
        try:
            r_date = datetime.strptime(r.date, "%Y-%m-%d").date()
        except:
            continue
            
        # Periods
        if r_date == today:
            stats_today += t
        
        # Week (Start of week usually Monday)
        # Simple iso calendar check
        if r_date.isocalendar()[1] == today.isocalendar()[1] and r_date.year == today.year:
            stats_week += t
            
        if r_date.month == today.month and r_date.year == today.year:
            stats_month += t
            
        if r_date.year == today.year:
            stats_year += t

        vf = getattr(r, "valor_financeiro", None) or 0.0
        dv = getattr(r, "devolucao_volume", None) or 0.0
        vdev = getattr(r, "valor_devolucao", None) or 0.0
        if r_date == today:
            valor_today += vf
            dev_vol_today += dv
            valor_dev_today += vdev
        if r_date.isocalendar()[1] == today.isocalendar()[1] and r_date.year == today.year:
            valor_week += vf
            dev_vol_week += dv
            valor_dev_week += vdev
        if r_date.month == today.month and r_date.year == today.year:
            valor_month += vf
            dev_vol_month += dv
            valor_dev_month += vdev
        if r_date.year == today.year:
            valor_year += vf
            dev_vol_year += dv
            valor_dev_year += vdev

        # Employee Count
        eid = r.employee_id
        if eid not in emp_counter: emp_counter[eid] = {'count': 0, 'tonnage': 0.0}
        emp_counter[eid]['count'] += 1
        emp_counter[eid]['tonnage'] += t
        
        # Duration (por ciclos de entrega quando há reabertura)
        dur_str = None
        prod_kg_h = 0.0
        dur_min = route_duration_minutes(r)
        if dur_min is not None and dur_min > 0:
            diff = float(dur_min) * 60
            total_duration_secs += diff
            count_duration += 1
            dur_str = fmt_br_duracao(max(1, int(round(float(dur_min)))))
            hours = dur_min / 60.0
            # t em kg (coerente com mobile/delivery); produtividade kg/h
            prod_kg_h = round(t / hours, 2) if hours > 0 else 0.0

        # History Row (peso em kg; produtividade kg/h)
        status_raw = (getattr(r, "delivery_status", "") or "").strip().lower()
        operation_type = "devolucao" if status_raw == "devolucao" else "entrega"
        history.append({
            "date_fmt": r_date.strftime("%d/%m/%Y"),
            "shift": r.shift,
            "employee_name": emp_map.get(r.employee_id, "Desconhecido"),
            "operation_type": operation_type,
            "tonnage_kg_fmt": fmt_br_2(t),
            "duration_fmt": dur_str,
            "productivity": prod_kg_h,
            "productivity_fmt": fmt_br_2(prod_kg_h),
        })
        
    # Aggregates (duração em padrão BR; produtividade média em kg/h)
    avg_duration_str = "—"
    avg_prod_kg_h = 0.0
    if count_duration > 0:
        avg_sec = total_duration_secs / count_duration
        avg_duration_str = fmt_br_duracao(max(1, int(round(avg_sec / 60.0))))
        total_hours = total_duration_secs / 3600.0
        if total_hours > 0:
            avg_prod_kg_h = round(total_tonnage / total_hours, 2)
            
    # Top Employee
    top_emp_name = None
    top_emp_count = 0
    if emp_counter:
        best_id = max(emp_counter, key=lambda k: emp_counter[k]["tonnage"])
        top_emp_name = emp_map.get(best_id)
        top_emp_count = emp_counter[best_id]["count"]
        
    # Last Op
    last_op_date = "-"
    last_op_days_ago = 0
    if routes:
        last_r = routes[0] # Sorted desc
        try:
            l_date = datetime.strptime(last_r.date, "%Y-%m-%d").date()
            last_op_date = l_date.strftime("%d/%m/%Y")
            last_op_days_ago = (today - l_date).days
        except:
            pass

    try:
        audit_logs = list(session.exec(
            select(models.ClientAuditLog)
            .where(models.ClientAuditLog.client_id == client_id)
            .order_by(models.ClientAuditLog.changed_at.desc())
            .limit(50)
        ).all())
    except Exception:
        audit_logs = []

    # Rotas concluídas no ano (denominador coerente com % devolução)
    valor_realizado_ano = 0.0
    ton_realizado_ano = 0.0
    for r in routes:
        try:
            rd = datetime.strptime(r.date, "%Y-%m-%d").date()
        except Exception:
            continue
        if rd.year != today.year:
            continue
        st = (r.delivery_status or "").lower()
        if st in ("entregue", "devolucao"):
            valor_realizado_ano += float(getattr(r, "valor_financeiro", None) or 0.0)
            ton_realizado_ano += float(r.tonnage or 0.0)

    # Devoluções (tabela Devolucao) vinculadas ao cliente
    devolucoes_list: List[dict] = []
    devolucoes: List[models.Devolucao] = []
    chart_dev_valor_ano = 0.0
    chart_dev_ton_ano = 0.0
    try:
        devolucoes = list(session.exec(
            select(models.Devolucao)
            .where(models.Devolucao.client_id == client_id)
            .order_by(models.Devolucao.data_romaneio.desc(), models.Devolucao.id.desc())
        ).all())
        motivos = {m.id: m.nome for m in session.exec(select(models.DevolucaoMotivo)).all()}
        resps = {r.id: r.nome for r in session.exec(select(models.DevolucaoResponsabilidade)).all()}
        emp_ids = set()
        for d in devolucoes:
            if d.motorista_id:
                emp_ids.add(d.motorista_id)
            if d.vendedor_id:
                emp_ids.add(d.vendedor_id)
            if d.ajudante_id:
                emp_ids.add(d.ajudante_id)
        if getattr(client, "vendedor_id", None):
            emp_ids.add(client.vendedor_id)
        emp_map = {}
        if emp_ids:
            for e in session.exec(select(models.Employee).where(models.Employee.id.in_(list(emp_ids)))).all():
                emp_map[e.id] = e.name
        for d in devolucoes:
            def _fmt_date(s: Optional[str]) -> str:
                if not s or len(s) < 10:
                    return "-"
                parts = str(s)[:10].split("-")
                return f"{parts[2]}/{parts[1]}/{parts[0]}" if len(parts) == 3 else s

            source_norm = (getattr(d, "source", None) or "").strip().upper()
            vendedor_name = emp_map.get(d.vendedor_id, "-") if d.vendedor_id else "-"
            # Legado: alguns registros mobile/web herdaram vendedor_id = motorista_id.
            # Na ficha do cliente, preferimos o vendedor vinculado ao cadastro do cliente.
            if (
                d.vendedor_id
                and d.motorista_id
                and d.vendedor_id == d.motorista_id
                and source_norm in ("MOBILE", "WEB", "ROTA")
                and getattr(client, "vendedor_id", None)
                and client.vendedor_id != d.motorista_id
            ):
                vendedor_name = emp_map.get(client.vendedor_id, vendedor_name)

            devolucoes_list.append({
                "id": d.id,
                "data_romaneio": d.data_romaneio,
                "data_romaneio_fmt": _fmt_date(d.data_romaneio),
                "data_entrega": d.data_entrega,
                "data_entrega_fmt": _fmt_date(d.data_entrega),
                "valor": float(d.valor or 0),
                "valor_fmt": fmt_br_2(float(d.valor or 0)),
                "motivo": motivos.get(d.motivo_id, "-"),
                "responsabilidade": resps.get(d.responsabilidade_id, "-"),
                "motorista": emp_map.get(d.motorista_id, "-") if d.motorista_id else "-",
                "vendedor": vendedor_name,
                "ajudante": emp_map.get(d.ajudante_id, "-") if d.ajudante_id else "-",
                "acima_300": (d.acima_300 or "NAO").upper() == "SIM",
            })
        # % devolução (este ano): mesma fonte da tabela (Devolucao), não só Route.valor_devolucao
        for d in devolucoes:
            ref = (d.data_entrega or d.data_romaneio or "")[:10]
            try:
                yd = datetime.strptime(ref, "%Y-%m-%d").date().year
            except Exception:
                continue
            if yd != today.year:
                continue
            chart_dev_valor_ano += float(d.valor or 0.0)
            if d.route_id:
                rr = session.get(models.Route, d.route_id)
                if rr and int(rr.client_id or 0) == int(client_id):
                    chart_dev_ton_ano += float(rr.tonnage or 0.0)
    except Exception as e:
        logger.exception(f"client_details devoluções query error: {e}")

    denom_v = valor_realizado_ano if valor_realizado_ano > 0 else valor_year
    denom_t = ton_realizado_ano if ton_realizado_ano > 0 else stats_year
    if denom_v > 0:
        pct_dev_valor = min(100.0, round(100.0 * chart_dev_valor_ano / denom_v, 1))
    elif chart_dev_valor_ano > 0:
        pct_dev_valor = 100.0
    else:
        pct_dev_valor = 0.0
    if denom_t > 0:
        pct_dev_vol = min(100.0, round(100.0 * chart_dev_ton_ano / denom_t, 1))
    elif chart_dev_ton_ano > 0:
        pct_dev_vol = 100.0
    else:
        pct_dev_vol = 0.0

    endereco_display = normalize_address(client.endereco or "") if client.endereco else ""
    try:
        vendedores_list_cd = list_vendedores(session)
    except Exception:
        logger.exception("client_details vendedores list")
        vendedores_list_cd = []
    vendedor_select_id = resolve_vendedor_id_for_select(client, session)
    client_vendedor_card = vendedor_card_for_client(session, client)

    janela_dias_check: set = set()
    try:
        raw_j = (client.janela_dias_semana or "").strip()
        if raw_j:
            parsed = json.loads(raw_j)
            if isinstance(parsed, list):
                janela_dias_check = {str(x).strip().lower() for x in parsed if str(x).strip()}
    except Exception:
        janela_dias_check = set()

    return templates.TemplateResponse("client_details.html", {
        "request": request,
        "user": user,
        "client": client,
        "janela_dias_check": janela_dias_check,
        "endereco_display": endereco_display or client.endereco,
        "audit_logs": audit_logs,
        "stats": {
            "total_tonnage_fmt": fmt_br_2(total_tonnage),
            "avg_duration_fmt": avg_duration_str,
            "last_op_date": last_op_date,
            "last_op_days_ago": last_op_days_ago,
            "top_employee": top_emp_name,
            "top_employee_count": top_emp_count,
            "total_routes": len(routes),
            "avg_tonnage_per_route_fmt": fmt_br_2(total_tonnage / len(routes)) if routes else fmt_br_2(0),
            "avg_productivity_fmt": fmt_br_2(avg_prod_kg_h),
        },
        "periods": {
            "today_fmt": fmt_br_2(stats_today),
            "week_fmt": fmt_br_2(stats_week),
            "month_fmt": fmt_br_2(stats_month),
            "year_fmt": fmt_br_2(stats_year),
        },
        "periods_valor": {
            "today_fmt": f"R$ {fmt_br_2(valor_today)}",
            "week_fmt": f"R$ {fmt_br_2(valor_week)}",
            "month_fmt": f"R$ {fmt_br_2(valor_month)}",
            "year_fmt": f"R$ {fmt_br_2(valor_year)}",
        },
        "periods_devolucao_vol": {
            "today_fmt": fmt_br_2(dev_vol_today),
            "week_fmt": fmt_br_2(dev_vol_week),
            "month_fmt": fmt_br_2(dev_vol_month),
            "year_fmt": fmt_br_2(dev_vol_year),
        },
        "periods_valor_devolucao": {
            "today_fmt": f"R$ {fmt_br_2(valor_dev_today)}",
            "week_fmt": f"R$ {fmt_br_2(valor_dev_week)}",
            "month_fmt": f"R$ {fmt_br_2(valor_dev_month)}",
            "year_fmt": f"R$ {fmt_br_2(max(valor_dev_year, chart_dev_valor_ano))}",
        },
        "chart_devolucao": {
            "pct_volume": pct_dev_vol,
            "pct_valor": pct_dev_valor,
            "valor_dev_ano_fmt": fmt_br_2(chart_dev_valor_ano),
            "ton_dev_ano_fmt": fmt_br_2(chart_dev_ton_ano),
            "valor_base_ano_fmt": fmt_br_2(denom_v),
            "ton_base_ano_fmt": fmt_br_2(denom_t),
        },
        "devolucoes_list": devolucoes_list,
        "history": history,
        "client_groups": list(session.exec(select(models.ClientGroup).order_by(models.ClientGroup.name)).all()),
        "current_client_group": session.get(models.ClientGroup, client.client_group_id) if getattr(client, "client_group_id", None) else None,
        "group_peers": list(session.exec(
            select(models.Client).where(
                models.Client.client_group_id == client.client_group_id,
                models.Client.id != client_id,
            ).order_by(models.Client.name)
        ).all()) if getattr(client, "client_group_id", None) else [],
        "client_phone_input": client_phone_e164 or (client.fone or ""),
        "client_phone_display": client_phone_display or (client.fone or ""),
        "client_phone_api_ready": bool(client_phone_e164),
        "client_alt_phone_input": client_alt_phone_e164 or (client.fone_alternativo or ""),
        "client_alt_phone_display": client_alt_phone_display or (client.fone_alternativo or ""),
        "vendedores_list": vendedores_list_cd,
        "vendedor_select_id": vendedor_select_id,
        "client_vendedor_card": client_vendedor_card,
    })

@app.post("/clients/{client_id}/group", response_class=RedirectResponse)
async def client_set_commercial_group(
    request: Request,
    client_id: int,
    client_group_id: Optional[str] = Form(None),
    new_group_name: Optional[str] = Form(None),
    session: Session = Depends(get_session),
):
    require_login(request)
    client = session.get(models.Client, client_id)
    if not client:
        return RedirectResponse(url="/clients", status_code=status.HTTP_303_SEE_OTHER)
    new_name = (new_group_name or "").strip()
    if new_name:
        existing = session.exec(select(models.ClientGroup).where(models.ClientGroup.name == new_name)).first()
        if existing:
            client.client_group_id = existing.id
        else:
            g = models.ClientGroup(name=new_name)
            session.add(g)
            session.commit()
            session.refresh(g)
            client.client_group_id = g.id
    elif (client_group_id or "").strip().isdigit():
        client.client_group_id = int(client_group_id)
    else:
        client.client_group_id = None
    try:
        client.updated_at = datetime.now()
    except Exception:
        pass
    session.add(client)
    session.commit()
    return RedirectResponse(url=f"/clients/{client_id}", status_code=status.HTTP_303_SEE_OTHER)

def _fill_client_from_import_staging(session: Session, client: models.Client, row: models.ClientImportStaging) -> None:
    client.name = row.name
    client.nb = row.nb
    client.me = row.me
    client.sa = row.sa
    client.visita = row.visita
    client.nome_fantasia = row.nome_fantasia
    client.razao_social = row.razao_social
    client.cnpj_cpf = row.cnpj_cpf
    client.municipio = row.municipio
    client.bairro = row.bairro
    client.endereco = row.endereco
    client.endereco_normalizado = row.endereco_normalizado
    client.fone = row.fone
    client.fone_e164 = row.fone_e164
    client.segmento = row.segmento
    client.status_cliente = row.status_cliente
    vid = resolve_employee_id_by_seller_code(session, row.setor)
    apply_vendedor_to_client(session, client, vid)
    if not vid and row.setor:
        client.setor = (row.setor or "").strip() or None


def _client_import_value_cmp(value: Optional[str]) -> str:
    if value is None:
        return ""
    return str(value).strip()


def _client_import_row_has_changes(session: Session, client: models.Client, row: models.ClientImportStaging) -> bool:
    """Retorna True quando a reimportação muda cadastro ou vínculo de vendedor."""
    fields = (
        "name",
        "nb",
        "me",
        "sa",
        "visita",
        "nome_fantasia",
        "razao_social",
        "cnpj_cpf",
        "municipio",
        "bairro",
        "endereco",
        "endereco_normalizado",
        "fone",
        "fone_e164",
        "segmento",
        "status_cliente",
    )
    for field in fields:
        if _client_import_value_cmp(getattr(client, field, None)) != _client_import_value_cmp(getattr(row, field, None)):
            return True

    new_raw = _client_import_value_cmp(row.setor)
    vid_new = resolve_employee_id_by_seller_code(session, new_raw)
    new_effective = new_raw
    if vid_new:
        emp_new = session.get(models.Employee, vid_new)
        if emp_new and _client_import_value_cmp(emp_new.seller_code):
            new_effective = _client_import_value_cmp(emp_new.seller_code)

    current_card = vendedor_card_for_client(session, client)
    current_effective = ""
    if current_card and _client_import_value_cmp(current_card.get("seller_code")):
        current_effective = _client_import_value_cmp(current_card.get("seller_code"))
    else:
        current_effective = _client_import_value_cmp(client.setor)

    return _norm_seller_code_cmp(current_effective) != _norm_seller_code_cmp(new_effective)


@app.post("/clients/{client_id}/update", response_class=RedirectResponse)
async def update_client(
    request: Request,
    client_id: int,
    name: str = Form(...),
    nb: Optional[str] = Form(None),
    vendedor_id: Optional[str] = Form(None),
    seller_code: Optional[str] = Form(None),
    me: Optional[str] = Form(None),
    sa: Optional[str] = Form(None),
    visita: Optional[str] = Form(None),
    nome_fantasia: Optional[str] = Form(None),
    razao_social: Optional[str] = Form(None),
    cnpj_cpf: Optional[str] = Form(None),
    municipio: Optional[str] = Form(None),
    bairro: Optional[str] = Form(None),
    endereco: Optional[str] = Form(None),
    fone: Optional[str] = Form(None),
    segmento: Optional[str] = Form(None),
    status_cliente: Optional[str] = Form(None),
    status_operacional: Optional[str] = Form(None),
    logradouro: Optional[str] = Form(None),
    numero: Optional[str] = Form(None),
    complemento: Optional[str] = Form(None),
    referencia: Optional[str] = Form(None),
    observacoes_acesso: Optional[str] = Form(None),
    fone_alternativo: Optional[str] = Form(None),
    observacoes_contato: Optional[str] = Form(None),
    janela_dias_semana: Optional[str] = Form(None),
    janela_horario_inicio: Optional[str] = Form(None),
    janela_horario_fim: Optional[str] = Form(None),
    prioridade_logistica: Optional[str] = Form(None),
    lgpd_nao_contatar: Optional[str] = Form(None),
    lgpd_restricao_dados: Optional[str] = Form(None),
    session: Session = Depends(get_session)
):
    require_login(request)
    client = session.get(models.Client, client_id)
    if client:
        vid_eff = parse_vendedor_id_form(vendedor_id)
        sc_fb = _opt_form(seller_code)
        if sc_fb:
            rid = resolve_employee_id_by_seller_code(session, sc_fb)
            if rid:
                vid_eff = rid
        if not vid_eff:
            me_fb = _opt_form(me)
            if me_fb:
                rid_me = resolve_employee_id_by_seller_code(session, me_fb)
                if rid_me:
                    vid_eff = rid_me
        before = _client_snapshot_auditable(client)
        old_address_key, _ = _apply_client_profile_form(
            session,
            client,
            name=name,
            nb=nb,
            vendedor_id=str(vid_eff) if vid_eff else "",
            me=me,
            sa=sa,
            visita=visita,
            nome_fantasia=nome_fantasia,
            razao_social=razao_social,
            cnpj_cpf=cnpj_cpf,
            municipio=municipio,
            bairro=bairro,
            endereco=endereco,
            fone=fone,
            segmento=segmento,
            status_cliente=status_cliente,
            status_operacional=status_operacional,
            logradouro=logradouro,
            numero=numero,
            complemento=complemento,
            referencia=referencia,
            observacoes_acesso=observacoes_acesso,
            fone_alternativo=fone_alternativo,
            observacoes_contato=observacoes_contato,
            janela_dias_semana=janela_dias_semana,
            janela_horario_inicio=janela_horario_inicio,
            janela_horario_fim=janela_horario_fim,
            prioridade_logistica=prioridade_logistica,
            lgpd_nao_contatar=lgpd_nao_contatar,
            lgpd_restricao_dados=lgpd_restricao_dados,
        )
        after = _client_snapshot_auditable(client)
        _append_client_audit_diff(session, int(client_id), before, after, _client_audit_actor(request))
        session.add(client)
        session.commit()
        # Regeocodifica se o endereço mudou
        new_address_key = (client.endereco or "", client.logradouro or "", client.numero or "", client.municipio or "")
        if old_address_key != new_address_key:
            client.geocoding_status = "pending"
            session.add(client)
            session.commit()
            _try_geocode_client(client, session)
    return RedirectResponse(url=f"/clients/{client_id}", status_code=status.HTTP_303_SEE_OTHER)

@app.post("/clients/{client_id}/delete", response_class=RedirectResponse)
async def delete_client(request: Request, client_id: int, session: Session = Depends(get_session)):
    require_login(request)
    client = session.get(models.Client, client_id)
    if client:
        # Cascade Delete: Remove RouteInsertLog and routes first
        # WARN: This removes historical production data for this client!
        route_ids = [r.id for r in session.exec(select(models.Route).where(models.Route.client_id == client_id)).all() if r.id]
        if route_ids:
            session.execute(delete(models.RouteInsertLog).where(models.RouteInsertLog.route_id.in_(route_ids)))
        session.exec(delete(models.Route).where(models.Route.client_id == client_id))
        
        session.delete(client)
        session.commit()
    return RedirectResponse(url="/clients", status_code=status.HTTP_303_SEE_OTHER)


def _load_clients_dataframe(content: bytes, filename: str):
    """Carrega CSV ou Excel em DataFrame."""
    import pandas as pd
    ext = (filename or "").lower()
    if ext.endswith(".csv"):
        try:
            df = pd.read_csv(io.BytesIO(content), encoding="utf-8-sig", sep=None, engine="python")
        except UnicodeDecodeError:
            df = pd.read_csv(io.BytesIO(content), encoding="latin-1", sep=None, engine="python")
    elif ext.endswith(".xlsx"):
        df = pd.read_excel(io.BytesIO(content), engine="openpyxl", header=0)
    elif ext.endswith(".xls"):
        df = pd.read_excel(io.BytesIO(content), engine="xlrd", header=0)
    else:
        raise ValueError("Formato inválido")
    df.columns = [str(c).strip() for c in df.columns]
    return df


def _opt_val(v) -> Optional[str]:
    """Converte valor da planilha em string ou None."""
    import pandas as pd
    if pd.isna(v):
        return None
    s = str(v).strip()
    return s if s else None


@app.post("/clients/import", response_class=RedirectResponse)
async def clients_import(
    request: Request,
    file: UploadFile = File(...),
    session: Session = Depends(get_session)
):
    """Importação com normalização e deduplicação. Redireciona para tela de conflitos se houver duplicados."""
    require_login(request)
    user = request.session.get("username", "")
    if not file.filename or not file.filename.lower().endswith((".xlsx", ".xls", ".csv")):
        return RedirectResponse(url="/clients?error=invalid_file", status_code=status.HTTP_303_SEE_OTHER)
    try:
        import pandas as pd
        content = await file.read()
        df = _load_clients_dataframe(content, file.filename)
        col_map = find_client_col_map(list(df.columns))

        name_col = col_map.get("fantas") or col_map.get("razao_social")
        if name_col is None and len(df.columns) >= 1:
            name_col = df.columns[0]
        if name_col is None:
            return RedirectResponse(url="/clients?error=missing_columns", status_code=status.HTTP_303_SEE_OTHER)

        # Índices para dedup (fone_e164, endereco_normalizado, razao+bairro) + reimportação por NB/CNPJ
        all_clients = list(session.exec(select(models.Client)).all())
        existing_by_fone = {}
        existing_by_endereco = {}
        existing_by_razao_bairro_key = {}
        existing_by_nb: Dict[str, int] = {}
        existing_by_cnpj: Dict[str, int] = {}
        for c in all_clients:
            fe164 = c.fone_e164
            if not fe164 and c.fone:
                fe164, _ = normalize_phone_br(c.fone)
            if fe164:
                existing_by_fone[fe164] = c.id
            eaddr = c.endereco_normalizado or (normalize_address(c.endereco).upper().replace(" ", "") if c.endereco and len(c.endereco) >= 10 else None)
            if eaddr:
                existing_by_endereco[eaddr] = c.id
            rk, bk = normalize_key(c.razao_social or c.name or ""), normalize_key(c.bairro or "")
            if rk and bk:
                existing_by_razao_bairro_key[(rk, bk)] = c.id
            nb_k = norm_nb_key(c.nb)
            if nb_k:
                existing_by_nb[nb_k] = c.id
            ck = norm_cnpj_digits(getattr(c, "cnpj_cpf", None))
            if ck:
                existing_by_cnpj[ck] = c.id
        existing_names = {n[0].strip().lower() for n in session.exec(select(models.Client.name)).all()}
        clients_by_id: Dict[int, models.Client] = {c.id: c for c in all_clients if c.id}

        batch = models.ClientImportBatch(filename=file.filename, created_by=user)
        session.add(batch)
        session.flush()

        rows_clean = []
        rows_conflict = []

        for idx, row in df.iterrows():
            name_raw = row.get(name_col)
            if pd.isna(name_raw):
                continue
            name = _opt_val(name_raw)
            if not name or len(name) < 2:
                continue

            nb = _opt_val(row.get(col_map.get("nb"))) if "nb" in col_map else None
            setor = _opt_val(row.get(col_map.get("setor"))) if "setor" in col_map else None
            me = _opt_val(row.get(col_map.get("me"))) if "me" in col_map else None
            sa = _opt_val(row.get(col_map.get("sa"))) if "sa" in col_map else None
            visita = _opt_val(row.get(col_map.get("visita"))) if "visita" in col_map else None
            nome_fantasia = _opt_val(row.get(col_map.get("fantas"))) if "fantas" in col_map else None
            razao_social = _opt_val(row.get(col_map.get("razao_social"))) if "razao_social" in col_map else None
            municipio = _opt_val(row.get(col_map.get("municipio"))) if "municipio" in col_map else None
            bairro = _opt_val(row.get(col_map.get("bairro"))) if "bairro" in col_map else None
            endereco_raw = _opt_val(row.get(col_map.get("endereco"))) if "endereco" in col_map else None
            fone_raw = _opt_val(row.get(col_map.get("fone"))) if "fone" in col_map else None
            segmento = _opt_val(row.get(col_map.get("segmento"))) if "segmento" in col_map else None
            status_cliente = _opt_val(row.get(col_map.get("status"))) if "status" in col_map else None
            cnpj_cpf = _opt_val(row.get(col_map.get("cnpj_cpf"))) if "cnpj_cpf" in col_map else None

            endereco = normalize_address(endereco_raw) if endereco_raw else None
            endereco_norm = normalize_address(endereco_raw).upper().replace(" ", "") if endereco_raw else None
            fone = fone_raw
            fone_e164 = None
            if fone_raw:
                ip_fone = normalize_import_phone_br(fone_raw)
                if ip_fone.valid and ip_fone.e164 and ip_fone.display:
                    fone_e164 = ip_fone.e164
                    fone = ip_fone.display
                else:
                    fone_e164, fone_amigavel = normalize_phone_br(fone_raw)
                    fone = fone_amigavel or fone_raw
            municipio_key = normalize_key(municipio)
            bairro_key = normalize_key(bairro)
            razao_key = normalize_key(razao_social or name)

            reimport_id: Optional[int] = None
            nb_k = norm_nb_key(nb)
            if nb_k and nb_k in existing_by_nb:
                reimport_id = existing_by_nb[nb_k]
            elif cnpj_cpf:
                cj = norm_cnpj_digits(cnpj_cpf)
                if cj and cj in existing_by_cnpj:
                    reimport_id = existing_by_cnpj[cj]

            # Reimportação: ignora apenas linhas sem mudança real; outros campos também precisam atualizar.
            if reimport_id:
                prev_c = clients_by_id.get(reimport_id)
                if prev_c is not None:
                    probe_row = models.ClientImportStaging(
                        batch_id=batch.id,
                        row_index=int(idx),
                        name=name,
                        nb=nb,
                        setor=setor,
                        me=me,
                        sa=sa,
                        visita=visita,
                        nome_fantasia=nome_fantasia,
                        razao_social=razao_social,
                        cnpj_cpf=cnpj_cpf,
                        municipio=municipio,
                        bairro=bairro,
                        endereco=endereco or endereco_raw,
                        endereco_normalizado=endereco_norm,
                        fone=fone,
                        fone_e164=fone_e164,
                        segmento=segmento,
                        status_cliente=status_cliente,
                    )
                    if not _client_import_row_has_changes(session, prev_c, probe_row):
                        continue

            conflict_type = None
            conflict_client_id = None
            if reimport_id:
                conflict_client_id = reimport_id
            elif fone_e164 and fone_e164 in existing_by_fone:
                conflict_type = "fone"
                conflict_client_id = existing_by_fone.get(fone_e164)
            elif endereco_norm and len(endereco_norm) >= 10 and endereco_norm in existing_by_endereco:
                conflict_type = "endereco"
                conflict_client_id = existing_by_endereco.get(endereco_norm)
            elif razao_key and bairro_key and (razao_key, bairro_key) in existing_by_razao_bairro_key:
                conflict_type = "razao_bairro"
                conflict_client_id = existing_by_razao_bairro_key.get((razao_key, bairro_key))

            if name.lower() in existing_names and not conflict_type and not reimport_id:
                conflict_type = "nome"
                conflict_client_id = None

            staging = models.ClientImportStaging(
                batch_id=batch.id,
                row_index=int(idx),
                name=name,
                nb=nb,
                setor=setor,
                me=me,
                sa=sa,
                visita=visita,
                nome_fantasia=nome_fantasia,
                razao_social=razao_social,
                cnpj_cpf=cnpj_cpf,
                municipio=municipio,
                bairro=bairro,
                endereco=endereco or endereco_raw,
                endereco_normalizado=endereco_norm,
                fone=fone,
                fone_e164=fone_e164,
                segmento=segmento,
                status_cliente=status_cliente,
                municipio_key=municipio_key,
                bairro_key=bairro_key,
                conflict_type=conflict_type,
                conflict_client_id=conflict_client_id,
                action="merge" if reimport_id else ("create" if not conflict_type else "pending"),
            )
            session.add(staging)
            if conflict_type:
                rows_conflict.append(staging)
            else:
                rows_clean.append(staging)

        session.commit()

        if rows_conflict:
            return RedirectResponse(url=f"/clients/import/conflicts/{batch.id}", status_code=status.HTTP_303_SEE_OTHER)

        log_created, log_updated, log_rejected = 0, 0, 0
        for s in rows_clean:
            if s.conflict_client_id:
                c_exist = session.get(models.Client, s.conflict_client_id)
                if not c_exist:
                    log_rejected += 1
                    continue
                old_nm = (c_exist.name or "").strip().lower()
                _fill_client_from_import_staging(session, c_exist, s)
                new_nm = (c_exist.name or "").strip().lower()
                if new_nm != old_nm:
                    if old_nm in existing_names:
                        existing_names.discard(old_nm)
                    existing_names.add(new_nm)
                session.add(c_exist)
                log_updated += 1
                continue
            if s.name.lower() in existing_names:
                log_rejected += 1
                continue
            c = models.Client(
                name=s.name,
                nb=s.nb,
                setor=s.setor,
                me=s.me,
                sa=s.sa,
                visita=s.visita,
                nome_fantasia=s.nome_fantasia,
                razao_social=s.razao_social,
                cnpj_cpf=s.cnpj_cpf,
                municipio=s.municipio,
                bairro=s.bairro,
                endereco=s.endereco,
                endereco_normalizado=s.endereco_normalizado,
                fone=s.fone,
                fone_e164=s.fone_e164,
                segmento=s.segmento,
                status_cliente=s.status_cliente,
            )
            session.add(c)
            session.flush()
            vid_new = resolve_employee_id_by_seller_code(session, s.setor)
            apply_vendedor_to_client(session, c, vid_new)
            if not vid_new and s.setor:
                c.setor = (s.setor or "").strip() or None
            session.add(c)
            existing_names.add(s.name.lower())
            nk = norm_nb_key(c.nb)
            if nk:
                existing_by_nb[nk] = c.id
            ck2 = norm_cnpj_digits(c.cnpj_cpf)
            if ck2:
                existing_by_cnpj[ck2] = c.id
            log_created += 1
        batch.status = "completed"
        batch.log_created = log_created
        batch.log_updated = log_updated
        batch.log_rejected = log_rejected
        session.add(batch)
        session.exec(delete(models.ClientImportStaging).where(models.ClientImportStaging.batch_id == batch.id))
        session.commit()
        return RedirectResponse(
            url=f"/clients?message=import_success&created={log_created}&updated={log_updated}&rejected={log_rejected}",
            status_code=status.HTTP_303_SEE_OTHER
        )
    except ValueError as e:
        return RedirectResponse(url=f"/clients?error=invalid_file", status_code=status.HTTP_303_SEE_OTHER)
    except Exception as e:
        logger.exception(f"Clients import error: {e}")
        return RedirectResponse(url="/clients?error=import_failed", status_code=status.HTTP_303_SEE_OTHER)


def _norm_seller_code_cmp(val: Optional[str]) -> str:
    """Normaliza código de vendedor para comparação (trim, dígitos sem zeros à esquerda)."""
    s = (val or "").strip()
    if not s:
        return ""
    if s.isdigit():
        return s.lstrip("0") or "0"
    return s.casefold()


def _client_import_conflicts_payload(
    session: Session,
    rows: list,
    conflict_map: dict,
) -> tuple[dict, list[dict]]:
    """Resumo e linhas serializáveis para a UI de conflitos (JSON + KPIs + comparativo de vendedor)."""
    conflict_rows = [r for r in rows if r.conflict_type]
    mergeable = sum(1 for r in conflict_rows if r.conflict_client_id and conflict_map.get(r.id))
    clean = len(rows) - len(conflict_rows)
    by_type: dict[str, int] = {}
    for r in conflict_rows:
        k = (r.conflict_type or "outro").strip() or "outro"
        by_type[k] = by_type.get(k, 0) + 1
    summary = {
        "total": len(rows),
        "conflicts": len(conflict_rows),
        "clean": clean,
        "mergeable": mergeable,
        "by_type": by_type,
    }
    out_rows: list[dict] = []
    merge_vendor_diff = 0
    for r in rows:
        c = conflict_map.get(r.id)
        has_merge = bool(r.conflict_client_id and c)
        if has_merge:
            default_action = "merge"
        elif not r.conflict_type:
            default_action = "create"
        else:
            default_action = "create"

        existing_seller_display = ""
        new_raw = (r.setor or "").strip()
        new_resolved_code = ""
        if new_raw:
            vid_new = resolve_employee_id_by_seller_code(session, r.setor)
            if vid_new:
                emp_new = session.get(models.Employee, vid_new)
                if emp_new:
                    new_resolved_code = (emp_new.seller_code or "").strip()
        new_effective = new_resolved_code or new_raw
        seller_codes_differ = False
        if c:
            card = vendedor_card_for_client(session, c)
            if card and (card.get("seller_code") or "").strip():
                existing_seller_display = (card.get("seller_code") or "").strip()
            else:
                existing_seller_display = (c.setor or "").strip()
            prev_eff = existing_seller_display or (c.setor or "").strip()
            seller_codes_differ = _norm_seller_code_cmp(prev_eff) != _norm_seller_code_cmp(new_effective)
            if has_merge and seller_codes_differ:
                merge_vendor_diff += 1

        out_rows.append(
            {
                "id": r.id,
                "row_index": r.row_index,
                "name": r.name or "",
                "nome_fantasia": r.nome_fantasia or "",
                "razao_social": r.razao_social or "",
                "municipio": r.municipio or "",
                "bairro": r.bairro or "",
                "fone": r.fone or "",
                "nb": r.nb or "",
                "setor": r.setor or "",
                "endereco": r.endereco or "",
                "cnpj_cpf": r.cnpj_cpf or "",
                "conflict_type": r.conflict_type,
                "conflict_client_id": r.conflict_client_id,
                "existing_client_id": c.id if c else None,
                "existing_client_name": c.name if c else None,
                "has_merge": has_merge,
                "default_action": default_action,
                "existing_seller_display": existing_seller_display or None,
                "new_seller_raw": new_raw or None,
                "new_seller_resolved": new_resolved_code or None,
                "new_seller_effective": new_effective or None,
                "seller_codes_differ": seller_codes_differ,
            }
        )
    summary["merge_vendor_diff_defaults"] = merge_vendor_diff
    return summary, out_rows


@app.get("/clients/import/conflicts/{batch_id}", response_class=HTMLResponse)
async def clients_import_conflicts(request: Request, batch_id: int, session: Session = Depends(get_session)):
    require_login(request)
    batch = session.get(models.ClientImportBatch, batch_id)
    if not batch or batch.status != "pending":
        return RedirectResponse(url="/clients", status_code=status.HTTP_303_SEE_OTHER)
    rows = session.exec(
        select(models.ClientImportStaging)
        .where(models.ClientImportStaging.batch_id == batch_id)
        .order_by(models.ClientImportStaging.row_index)
    ).all()
    conflict_rows = [r for r in rows if r.conflict_type]
    conflict_map = {}
    for r in conflict_rows:
        if r.conflict_client_id:
            c = session.get(models.Client, r.conflict_client_id)
            if c:
                conflict_map[r.id] = c
    conflict_summary, import_rows_payload = _client_import_conflicts_payload(session, rows, conflict_map)
    import_conflicts_payload = {
        "batch_id": batch.id,
        "filename": batch.filename or "",
        "confirm_path": f"/clients/import/confirm/{batch.id}",
        "rows": import_rows_payload,
    }
    return templates.TemplateResponse(
        "clients_import_conflicts.html",
        {
            "request": request,
            "user": request.session.get("username", ""),
            "batch": batch,
            "rows": rows,
            "conflict_rows": conflict_rows,
            "conflict_map": conflict_map,
            "conflict_summary": conflict_summary,
            "import_conflicts_payload": import_conflicts_payload,
        },
    )


@app.post("/clients/import/confirm/{batch_id}", response_class=RedirectResponse)
async def clients_import_confirm(
    request: Request,
    batch_id: int,
    session: Session = Depends(get_session)
):
    require_login(request)
    batch = session.get(models.ClientImportBatch, batch_id)
    if not batch or batch.status != "pending":
        return RedirectResponse(url="/clients", status_code=status.HTTP_303_SEE_OTHER)
    form = await request.form()
    form_actions = {k.replace("action_", ""): v for k, v in form.items() if k.startswith("action_")}
    log_created, log_updated, log_skipped, log_rejected = 0, 0, 0, 0
    existing_names = {n[0].strip().lower() for n in session.exec(select(models.Client.name)).all()}
    rows = session.exec(
        select(models.ClientImportStaging).where(models.ClientImportStaging.batch_id == batch_id).order_by(models.ClientImportStaging.row_index)
    ).all()
    for row in rows:
        action = form_actions.get(str(row.id), row.action)
        if action == "create" and row.action == "merge" and row.conflict_client_id and not row.conflict_type:
            # Páginas abertas antes da correção enviavam reimportações como "create".
            # No servidor, a fonte da verdade para esses casos é atualizar o cliente vinculado.
            action = "merge"
        if action not in {"create", "merge", "skip"}:
            action = row.action if row.action in {"create", "merge", "skip"} else "skip"
        if action == "skip":
            log_skipped += 1
            continue
        if action == "merge" and row.conflict_client_id:
            client = session.get(models.Client, row.conflict_client_id)
            if client:
                _fill_client_from_import_staging(session, client, row)
                session.add(client)
                log_updated += 1
        elif action == "create":
            if row.name.lower() in existing_names:
                log_rejected += 1
            else:
                c = models.Client(
                    name=row.name,
                    nb=row.nb,
                    setor=row.setor,
                    me=row.me,
                    sa=row.sa,
                    visita=row.visita,
                    nome_fantasia=row.nome_fantasia,
                    razao_social=row.razao_social,
                    cnpj_cpf=row.cnpj_cpf,
                    municipio=row.municipio,
                    bairro=row.bairro,
                    endereco=row.endereco,
                    endereco_normalizado=row.endereco_normalizado,
                    fone=row.fone,
                    fone_e164=row.fone_e164,
                    segmento=row.segmento,
                    status_cliente=row.status_cliente,
                )
                session.add(c)
                session.flush()
                vid_nc = resolve_employee_id_by_seller_code(session, row.setor)
                apply_vendedor_to_client(session, c, vid_nc)
                if not vid_nc and row.setor:
                    c.setor = (row.setor or "").strip() or None
                session.add(c)
                existing_names.add(row.name.lower())
                log_created += 1
    batch.status = "completed"
    batch.log_created = log_created
    batch.log_updated = log_updated
    batch.log_skipped = log_skipped
    batch.log_rejected = log_rejected
    session.add(batch)
    session.exec(delete(models.ClientImportStaging).where(models.ClientImportStaging.batch_id == batch_id))
    session.commit()
    return RedirectResponse(
        url=f"/clients?message=import_confirm&created={log_created}&updated={log_updated}&skipped={log_skipped}&rejected={log_rejected}",
        status_code=status.HTTP_303_SEE_OTHER
    )


