@app.post("/workshop/service-orders/{order_id}/close", response_class=RedirectResponse)
async def workshop_service_order_close(
    request: Request,
    order_id: int,
    resolution_notes: str = Form(default=""),
    parts_cost: Optional[str] = Form(default=None),
    labor_cost: Optional[str] = Form(default=None),
    third_party_cost: Optional[str] = Form(default=None),
    quoted_amount: Optional[str] = Form(default=None),
    approved_amount: Optional[str] = Form(default=None),
    final_amount: Optional[str] = Form(default=None),
    invoice_number: Optional[str] = Form(default=None),
    warranty_notes: Optional[str] = Form(default=None),
    odometer_km: Optional[str] = Form(default=None),
    release_notes: Optional[str] = Form(default=None),
    return_to: Optional[str] = Form(default=None),
    session: Session = Depends(get_session),
):
    user = require_login(request)
    order = session.get(models.WorkshopServiceOrder, order_id)
    if not order:
        return RedirectResponse(url="/workshop/service-orders?message=OS+não+encontrada.&level=error", status_code=status.HTTP_303_SEE_OTHER)
    notes = (resolution_notes or "").strip() or (order.resolution_notes or "").strip()
    if not notes:
        dest = _service_order_return_url(return_to, f"/workshop/service-orders/{order_id}")
        sep = "&" if "?" in dest else "?"
        return RedirectResponse(url=f"{dest}{sep}message=Para+encerrar+a+OS%2C+informe+nota+de+conclusão.&level=error", status_code=status.HTTP_303_SEE_OTHER)
    block_state = (order.vehicle_block_status or "none").strip().lower()
    release_clean = (release_notes or "").strip()
    if block_state in {"preventive", "critical"} and release_clean:
        order.vehicle_block_status = "none"
        order.vehicle_released_at = datetime.now()
        order.vehicle_released_by = format_user_label(user)
        _register_service_order_event(
            session,
            order,
            event_type="vehicle_released",
            title="Veículo liberado",
            description=release_clean,
            new_value="none",
            created_by=format_user_label(user),
        )
    order.resolution_notes = notes
    parts_cost_val = _as_float(_safe_form_text(parts_cost))
    labor_cost_val = _as_float(_safe_form_text(labor_cost))
    third_party_cost_val = _as_float(_safe_form_text(third_party_cost))
    order.parts_cost = parts_cost_val if parts_cost_val > 0 else order.parts_cost
    order.labor_cost = labor_cost_val if labor_cost_val > 0 else order.labor_cost
    order.third_party_cost = third_party_cost_val if third_party_cost_val > 0 else order.third_party_cost
    if _safe_form_text(quoted_amount):
        order.quoted_amount = _as_float(_safe_form_text(quoted_amount))
    if _safe_form_text(approved_amount):
        order.approved_amount = _as_float(_safe_form_text(approved_amount))
    if _safe_form_text(final_amount):
        order.final_amount = _as_float(_safe_form_text(final_amount))
    invoice_value = _safe_form_text(invoice_number)
    if invoice_value:
        order.invoice_number = invoice_value
    warranty_value = _safe_form_text(warranty_notes)
    if warranty_value:
        order.warranty_notes = warranty_value
    odometer_value = _safe_form_text(odometer_km)
    if odometer_value:
        order.odometer_km = _as_float(odometer_value)
    total_cost_calc = _safe_float(order.parts_cost) + _safe_float(order.labor_cost) + _safe_float(order.third_party_cost)
    order.total_cost = total_cost_calc if total_cost_calc > 0 else order.total_cost
    old_status = order.status
    order.status = "closed"
    order.closed_at = datetime.now()
    order.updated_at = datetime.now()
    session.add(order)
    _register_service_order_event(
        session,
        order,
        event_type="closed",
        title="OS encerrada",
        description="Encerramento validado manualmente pela liderança.",
        old_value=old_status,
        new_value="closed",
        created_by=format_user_label(user),
    )
    session.commit()
    dest = _service_order_return_url(return_to, f"/workshop/service-orders/{order_id}")
    sep = "&" if "?" in dest else "?"
    return RedirectResponse(url=f"{dest}{sep}message=OS+encerrada+com+sucesso.&level=success", status_code=status.HTTP_303_SEE_OTHER)


@app.get("/vehicles", response_class=HTMLResponse)
async def vehicles_page(request: Request, session: Session = Depends(get_session)):
    user = require_login(request)
    vehicles = session.exec(select(models.Vehicle).order_by(models.Vehicle.placa)).all()
    total = len(vehicles)
    by_type = {"caminhao": 0, "moto": 0, "carro": 0}
    for v in vehicles:
        t = (v.vehicle_type or "").lower()
        if t in by_type:
            by_type[t] += 1
    pct_c = round(100 * by_type["caminhao"] / total, 1) if total else 0
    pct_m = round(100 * by_type["moto"] / total, 1) if total else 0
    pct_r = round(100 * by_type["carro"] / total, 1) if total else 0
    sold_n = sum(1 for v in vehicles if v.sold_at)
    workshop_n = sum(1 for v in vehicles if v.in_workshop and not v.sold_at)
    operating_n = sum(
        1 for v in vehicles
        if v.is_active and not v.sold_at and not v.in_workshop
    )
    inactive_n = sum(1 for v in vehicles if not v.is_active and not v.sold_at)
    stats = {
        "total": total,
        "caminhao_count": by_type["caminhao"],
        "moto_count": by_type["moto"],
        "carro_count": by_type["carro"],
        "caminhao_pct": pct_c,
        "moto_pct": pct_m,
        "carro_pct": pct_r,
        "operating": operating_n,
        "workshop": workshop_n,
        "sold": sold_n,
        "inactive": inactive_n,
    }
    return templates.TemplateResponse(
        "vehicles.html",
        {"request": request, "user": user, "vehicles": vehicles, "stats": stats},
    )


@app.get("/vehicles/odometer", response_class=HTMLResponse)
async def vehicles_odometer_page(request: Request, session: Session = Depends(get_session)):
    """Painel de frota focado em hodômetro com UX espelhada de colaboradores."""
    user = require_login(request)
    vehicles = list(session.exec(select(models.Vehicle).order_by(models.Vehicle.placa)).all())
    total = len(vehicles)
    by_type = {"caminhao": 0, "moto": 0, "carro": 0}
    for v in vehicles:
        t = (v.vehicle_type or "").lower()
        if t in by_type:
            by_type[t] += 1
    pct_c = round(100 * by_type["caminhao"] / total, 1) if total else 0
    pct_m = round(100 * by_type["moto"] / total, 1) if total else 0
    pct_r = round(100 * by_type["carro"] / total, 1) if total else 0
    stats = {
        "total": total,
        "caminhao_count": by_type["caminhao"],
        "moto_count": by_type["moto"],
        "carro_count": by_type["carro"],
        "caminhao_pct": pct_c,
        "moto_pct": pct_m,
        "carro_pct": pct_r,
        "with_km": sum(1 for v in vehicles if v.odometer_km is not None),
        "without_km": sum(1 for v in vehicles if v.odometer_km is None),
        "updated_7d": sum(
            1
            for v in vehicles
            if getattr(v, "updated_at", None) and v.updated_at >= (datetime.now() - timedelta(days=7))
        ),
        "high_km": sum(1 for v in vehicles if (v.odometer_km or 0) >= 300000),
        "operating": sum(1 for v in vehicles if v.is_active and not v.sold_at and not v.in_workshop),
        "workshop": sum(1 for v in vehicles if v.in_workshop and not v.sold_at),
        "sold": sum(1 for v in vehicles if v.sold_at),
        "inactive": sum(1 for v in vehicles if not v.is_active and not v.sold_at),
    }

    def _v_dict(v: models.Vehicle) -> dict:
        return {
            "id": v.id,
            "placa": v.placa or "",
            "vehicle_type": v.vehicle_type or "",
            "marca": v.marca or "",
            "modelo": v.modelo or "",
            "ano": v.ano or "",
            "renavam": v.renavam or "",
            "crv_number": v.crv_number or "",
            "chassi": v.chassi or "",
            "is_active": bool(v.is_active),
            "in_workshop": bool(v.in_workshop),
            "sold_at": v.sold_at.strftime("%Y-%m-%d") if v.sold_at else None,
            "sale_value": v.sale_value,
            "odometer_km": v.odometer_km,
            "updated_at": v.updated_at.strftime("%Y-%m-%d %H:%M:%S") if getattr(v, "updated_at", None) else None,
            "updated_at_br": fmt_br_datetime(v.updated_at) if getattr(v, "updated_at", None) else "",
        }

    vehicles_json = json.dumps([_v_dict(v) for v in vehicles], ensure_ascii=False)
    qp = request.query_params
    return templates.TemplateResponse(
        "vehicles_odometer.html",
        {
            "request": request,
            "user": user,
            "vehicles": vehicles,
            "stats": stats,
            "vehicles_json": vehicles_json,
            "error": qp.get("error"),
            "success": qp.get("success"),
            "message": qp.get("message"),
            "imported": qp.get("imported"),
            "skipped": qp.get("skipped"),
        },
    )


