@app.post("/api/vehicles/bulk", response_class=JSONResponse)
async def api_vehicles_bulk(
    request: Request,
    body: VehicleBulkBody,
    session: Session = Depends(get_session),
):
    require_login(request)
    if not body.ids:
        return JSONResponse(content={"success": False, "error": "Nenhum veículo selecionado"}, status_code=400)
    updated = 0
    for vid in body.ids:
        v = session.get(models.Vehicle, vid)
        if not v:
            continue
        if body.action == "workshop_on":
            v.in_workshop = True
        elif body.action == "workshop_off":
            v.in_workshop = False
        elif body.action == "activate":
            v.is_active = True
        elif body.action == "deactivate":
            v.is_active = False
        v.updated_at = datetime.now()
        session.add(v)
        updated += 1
    session.commit()
    return {"success": True, "updated": updated}


@app.post("/vehicles/bulk-delete", response_class=RedirectResponse)
async def vehicles_bulk_delete(
    request: Request,
    vehicle_ids: Optional[List[int]] = Form(None),
    session: Session = Depends(get_session),
):
    require_login(request)
    if not vehicle_ids:
        return RedirectResponse(
            url="/vehicles?error=bulk_none",
            status_code=status.HTTP_303_SEE_OTHER,
        )
    removed = 0
    for vid in vehicle_ids:
        vehicle = session.get(models.Vehicle, vid)
        if vehicle:
            session.delete(vehicle)
            removed += 1
    session.commit()
    return RedirectResponse(
        url=f"/vehicles?message=bulk_deleted&removed={removed}",
        status_code=status.HTTP_303_SEE_OTHER,
    )


# --- Route Management ---
# --- Separação de Mercadorias Management ---
def _norm_text(v: Any) -> str:
    if v is None:
        return ""
    s = str(v).strip()
    if not s:
        return ""
    s = unicodedata.normalize("NFD", s)
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    return s.lower().strip()


# Equivalentes para matching de nomes (ex.: planilha "HAMILTON JR" -> cadastro "HAMILTON ... JUNIOR")
_NAME_TOKEN_EQUIVALENTS = {
    "jr": "junior",
    "junior": "junior",
    "filho": "filho",
    "neto": "neto",
    "sobrinho": "sobrinho",
}


def _canonical_name_tokens(text: str) -> set:
    """Tokens normalizados para comparação de nomes; unifica JR/JUNIOR etc."""
    norm = _norm_text(text)
    tokens = set()
    for t in norm.split():
        if not t:
            continue
        tokens.add(_NAME_TOKEN_EQUIVALENTS.get(t, t))
    return tokens


def _norm_plate(v: Any) -> str:
    if v is None:
        return ""
    return "".join(ch for ch in str(v).upper().strip() if ch.isalnum())


def _safe_float(v: Any) -> float:
    """Converte para float; None e NaN viram 0.0."""
    if v is None:
        return 0.0
    try:
        f = float(v)
        return 0.0 if math.isnan(f) else f
    except (TypeError, ValueError):
        return 0.0


def _fmt_br_date(date_str: str) -> str:
    """Converte YYYY-MM-DD para dd/mm/yyyy."""
    if not date_str or len(date_str) < 10:
        return date_str or ""
    try:
        y, m, d = date_str[:10].split("-")
        return f"{d}/{m}/{y}"
    except Exception:
        return date_str


def _fmt_br_float(val: float, decimals: int = 2) -> str:
    """Formata número em padrão BR: 1234.56 -> 1.234,56."""
    if val is None:
        return "0"
    s = f"{float(val):,.{decimals}f}"
    return s.replace(",", "X").replace(".", ",").replace("X", ".")


def _as_str(v: Any) -> Optional[str]:
    if v is None:
        return None
    s = str(v).strip()
    if not s or s.lower() == "nan":
        return None
    return s


def _as_float(v: Any) -> float:
    if v is None:
        return 0.0
    if isinstance(v, (int, float)):
        return float(v)
    s = str(v).strip()
    if not s or s.lower() == "nan":
        return 0.0
    s = s.replace(".", "").replace(",", ".")
    try:
        return float(s)
    except Exception:
        return 0.0


def _maps_link(address: Optional[str], bairro: Optional[str], cidade: Optional[str], estado: Optional[str], cep: Optional[str]) -> str:
    parts = [p for p in [address, bairro, cidade, estado, cep] if p]
    return "https://www.google.com/maps/search/?api=1&query=" + urlencode({"": " ".join(parts)})[1:]


def _maps_link_coords(lat: Optional[float], lon: Optional[float]) -> Optional[str]:
    """Retorna link Google Maps para coordenadas, ou None se inválidas."""
    if lat is None or lon is None:
        return None
    try:
        if -90 <= float(lat) <= 90 and -180 <= float(lon) <= 180:
            return f"https://www.google.com/maps?q={lat},{lon}"
    except (TypeError, ValueError):
        pass
    return None


def _parse_session_helpers(helpers_json: Optional[str]) -> List[str]:
    """Parse helpers_json da sessão para lista de nomes."""
    if not helpers_json:
        return []
    try:
        data = json.loads(helpers_json) if isinstance(helpers_json, str) else helpers_json
        if not isinstance(data, list):
            return []
        return [str(h).strip() for h in data if h]
    except Exception:
        return []


def _parse_route_helper_ids(helpers_json: Optional[str]) -> List[int]:
    """Parse delivery_helpers_json da rota para lista de employee_id."""
    if not helpers_json:
        return []
    try:
        data = json.loads(helpers_json) if isinstance(helpers_json, str) else helpers_json
        if not isinstance(data, list):
            return []
        return [int(x) for x in data if x is not None and str(x).strip().isdigit()]
    except Exception:
        return []


def _get_delivery_allowed_plates(
    session: Session,
    employee_id: int,
    date_ref: Optional[str] = None,
) -> List[str]:
    """
    Retorna placas de caminhão liberadas para o colaborador (motorista ou ajudante) na data.
    Fonte de verdade: rotas de entrega planejadas.
    """
    date_str = date_ref or datetime.now(ZoneInfo("America/Sao_Paulo")).strftime("%Y-%m-%d")
    routes = session.exec(
        select(models.Route)
        .where(models.Route.type == "delivery")
        .where(models.Route.date == date_str)
        .where(models.Route.delivery_status.in_(["pendente", "iniciada", "reaberta", "entregue", "devolucao"]))
    ).all()

    allowed = set()
    for r in routes:
        plate = (r.delivery_vehicle_plate or "").strip().upper()
        if not plate:
            continue
        helper_ids = _parse_route_helper_ids(getattr(r, "delivery_helpers_json", None))
        if int(r.employee_id or 0) == int(employee_id) or int(employee_id) in helper_ids:
            allowed.add(plate)
    return sorted(allowed)


