@app.post("/separacao/delivery/reassign", response_class=RedirectResponse)
async def reassign_delivery_stop(
    request: Request,
    route_id: int = Form(...),
    new_employee_id: int = Form(...),
    new_vehicle_plate: str = Form(...),
    date: str = Form(...),
    shift: str = Form("Manhã"),
    session: Session = Depends(get_session),
):
    require_login(request)
    route = session.get(models.Route, route_id)
    if not route or route.type != "delivery":
        feedback_encoded = urlencode({
            "delivery_feedback": "Entrega não encontrada para reatribuição.",
            "delivery_feedback_level": "error",
        })
        return RedirectResponse(url=f"/separacao?date={date}&shift={shift}&{feedback_encoded}", status_code=303)

    err = _validate_delivery_assignment(
        session=session,
        date=route.date,
        employee_id=new_employee_id,
        vehicle_plate=new_vehicle_plate,
        exclude_route_id=route.id,
        ignore_employee_id=route.employee_id,
    )
    if err:
        feedback_encoded = urlencode({"delivery_feedback": err, "delivery_feedback_level": "error"})
        return RedirectResponse(url=f"/separacao?date={date}&shift={shift}&{feedback_encoded}", status_code=303)

    old_employee_id = route.employee_id
    route.employee_id = new_employee_id
    route.delivery_vehicle_plate = new_vehicle_plate
    _transfer_route_xp_on_driver_change(session, route, old_employee_id, new_employee_id)
    session.add(route)
    session.commit()

    feedback_encoded = urlencode({"delivery_feedback": "Cliente movido para outra entrega.", "delivery_feedback_level": "success"})
    return RedirectResponse(url=f"/separacao?date={date}&shift={shift}&{feedback_encoded}", status_code=303)


@app.post("/separacao/delivery/reassign-group", response_class=RedirectResponse)
async def reassign_delivery_group(
    request: Request,
    source_employee_id: int = Form(...),
    source_vehicle_plate: str = Form(""),
    new_employee_id: int = Form(...),
    new_vehicle_plate: str = Form(...),
    helper_ids: Optional[List[int]] = Form(None),
    date: str = Form(...),
    shift: str = Form("Manhã"),
    session: Session = Depends(get_session),
):
    require_login(request)
    # Buscar nomes para logs mais legíveis
    source_emp = session.get(models.Employee, source_employee_id)
    new_emp = session.get(models.Employee, new_employee_id)
    source_name = source_emp.name if source_emp else f"ID={source_employee_id}"
    new_name = new_emp.name if new_emp else f"ID={new_employee_id}"

    normalized_helper_ids: List[int] = []
    seen_helpers = set()
    for helper_id in (helper_ids or []):
        if helper_id == new_employee_id:
            continue
        if helper_id in seen_helpers:
            continue
        seen_helpers.add(helper_id)
        normalized_helper_ids.append(helper_id)
    helpers_json = json.dumps(normalized_helper_ids) if normalized_helper_ids else None
    
    logger.info(f"ðŸâ€â€ž Tentativa de troca de motorista: {source_name} → {new_name}, Caminhão: {new_vehicle_plate}, Data: {date}")
    
    source_plate_norm = _norm_plate(source_vehicle_plate)
    rows = session.exec(
        select(models.Route)
        .where(models.Route.type == "delivery")
        .where(models.Route.date == date)
        .where(models.Route.employee_id == source_employee_id)
    ).all()
    if source_plate_norm:
        rows = [r for r in rows if _norm_plate(r.delivery_vehicle_plate) == source_plate_norm]
    if not rows:
        logger.warning(f"âÅ' Nenhuma entrega encontrada para {source_name} na data {date}")
        feedback_encoded = urlencode({"delivery_feedback": "Nenhuma entrega encontrada para o motorista.", "delivery_feedback_level": "error"})
        return RedirectResponse(url=f"/separacao?date={date}&shift={shift}&{feedback_encoded}", status_code=303)

    logger.info(f"[>] Encontradas {len(rows)} entregas para transferir")

    err = _validate_delivery_assignment(
        session=session,
        date=date,
        employee_id=new_employee_id,
        vehicle_plate=new_vehicle_plate,
        ignore_employee_id=source_employee_id,
    )
    if err:
        logger.error(f"âÅ' Validação falhou: {err}")
        feedback_encoded = urlencode({"delivery_feedback": err, "delivery_feedback_level": "error"})
        return RedirectResponse(url=f"/separacao?date={date}&shift={shift}&{feedback_encoded}", status_code=303)

    for r in rows:
        old_eid = r.employee_id
        r.employee_id = new_employee_id
        r.delivery_vehicle_plate = new_vehicle_plate
        r.delivery_helpers_json = helpers_json
        _transfer_route_xp_on_driver_change(session, r, old_eid, new_employee_id)
        session.add(r)
    session.commit()

    logger.info("info log")
    feedback_encoded = urlencode({"delivery_feedback": f"Transferência concluída em {len(rows)} parada(s).", "delivery_feedback_level": "success"})
    return RedirectResponse(url=f"/separacao?date={date}&shift={shift}&{feedback_encoded}", status_code=303)


@app.post("/separacao/delivery/reopen", response_class=RedirectResponse)
async def reopen_delivery_route(
    request: Request,
    route_id: int = Form(...),
    date: str = Form(...),
    shift: str = Form("Manhã"),
    session: Session = Depends(get_session),
):
    require_login(request)
    route = session.get(models.Route, route_id)
    if not route or route.type != "delivery":
        feedback_encoded = urlencode({"delivery_feedback": "Entrega não encontrada.", "delivery_feedback_level": "error"})
        return RedirectResponse(url=f"/separacao?date={date}&shift={shift}&{feedback_encoded}", status_code=303)

    if (route.delivery_status or "").lower() not in ("entregue", "devolucao"):
        feedback_encoded = urlencode({"delivery_feedback": "Somente rotinas concluídas podem ser reabertas.", "delivery_feedback_level": "error"})
        return RedirectResponse(url=f"/separacao?date={date}&shift={shift}&{feedback_encoded}", status_code=303)

    started_rows = session.exec(
        select(models.Route)
        .where(models.Route.type == "delivery")
        .where(models.Route.date == route.date)
        .where(models.Route.employee_id == route.employee_id)
        .where(models.Route.delivery_status == "iniciada")
        .where(models.Route.id != route.id)
    ).all()
    route_plate_norm = _norm_plate(route.delivery_vehicle_plate)
    already_started = next(
        (r for r in started_rows if _norm_plate(r.delivery_vehicle_plate) == route_plate_norm),
        None,
    )
    if already_started:
        feedback_encoded = urlencode({
            "delivery_feedback": "Motorista já possui rotina iniciada. Finalize antes de reabrir outra.",
            "delivery_feedback_level": "error",
        })
        return RedirectResponse(url=f"/separacao?date={date}&shift={shift}&{feedback_encoded}", status_code=303)

    now = datetime.now(ZoneInfo("America/Sao_Paulo")).strftime("%H:%M")
    route.delivery_status = "reaberta"
    route.status = "pending"
    route.end_time = None
    route.driver_lat_start = None
    route.driver_lon_start = None
    route.driver_lat_end = None
    route.driver_lon_end = None
    route.delivery_reopen_count = (route.delivery_reopen_count or 0) + 1
    _append_delivery_event(route, "reabrir", now, note=f"Reabertura #{route.delivery_reopen_count}")
    session.add(route)
    session.commit()

    feedback_encoded = urlencode({"delivery_feedback": "Rotina reaberta com sucesso.", "delivery_feedback_level": "success"})
    return RedirectResponse(url=f"/separacao?date={date}&shift={shift}&{feedback_encoded}", status_code=303)


@app.get("/api/delivery/clients/search", response_class=JSONResponse)
async def api_delivery_clients_search(
    request: Request,
    q: str = "",
    limit: int = 20,
    session: Session = Depends(get_session),
):
    """Busca clientes por nome, NB, nome fantasia ou endereço para inclusão manual em rota."""
    require_login(request)
    q = (q or "").strip()
    if len(q) < 2:
        return []
    try:
        pat = f"%{q}%"
        stmt = (
            select(models.Client)
            .where(
                or_(
                    models.Client.name.ilike(pat),
                    models.Client.nome_fantasia.ilike(pat),
                    models.Client.razao_social.ilike(pat),
                    models.Client.nb.ilike(pat),
                    models.Client.endereco.ilike(pat),
                    models.Client.endereco_normalizado.ilike(pat),
                    models.Client.logradouro.ilike(pat),
                    models.Client.bairro.ilike(pat),
                    models.Client.municipio.ilike(pat),
                )
            )
            .order_by(models.Client.name)
            .limit(limit)
        )
        rows = list(session.exec(stmt).all())
        out = []
        for c in rows:
            end = (getattr(c, "endereco", None) or getattr(c, "logradouro", None) or "")
            if getattr(c, "numero", None):
                end = f"{end} {c.numero}".strip()
            if getattr(c, "bairro", None):
                end = f"{end} - {c.bairro}".strip()
            if getattr(c, "municipio", None):
                end = f"{end} {c.municipio}/MG".strip()
            out.append({
                "id": c.id,
                "name": getattr(c, "name", None) or "",
                "nome_fantasia": getattr(c, "nome_fantasia", None) or "",
                "nb": getattr(c, "nb", None) or "",
                "endereco": end or "",
                "display": f"{getattr(c, 'name', None) or ''} | NB: {getattr(c, 'nb', None) or '-'} | {getattr(c, 'nome_fantasia', None) or ''}".strip(),
            })
        return out
    except Exception as e:
        logger.exception(f"api_delivery_clients_search: {e}")
        return []


@app.post("/separacao/delivery/add-stop", response_class=RedirectResponse)
async def delivery_add_stop(
    request: Request,
    employee_id: int = Form(...),
    vehicle_plate: str = Form(...),
    date: str = Form(...),
    shift: str = Form("Manhã"),
    client_id: int = Form(...),
    tonnage: float = Form(0.0),
    valor_financeiro: Optional[float] = Form(None),
    delivery_order_number: Optional[str] = Form(None),
    date_from: Optional[str] = Form(None),
    date_to: Optional[str] = Form(None),
    session: Session = Depends(get_session),
):
    """Adiciona uma parada manual à rota de entrega (cliente manual)."""
    require_login(request)
    df, dt = (date_from or "").strip(), (date_to or "").strip()
    if df and dt and df != dt:
        redirect_base = f"/separacao?date_from={df}&date_to={dt}&shift={shift}"
    else:
        redirect_base = f"/separacao?date={date}&shift={shift}"

    client = session.get(models.Client, client_id)
    if not client:
        feedback_encoded = urlencode({"delivery_feedback": "Cliente não encontrado.", "delivery_feedback_level": "error"})
        return RedirectResponse(url=f"{redirect_base}&{feedback_encoded}", status_code=303)
    emp = session.get(models.Employee, employee_id)
    if not emp:
        feedback_encoded = urlencode({"delivery_feedback": "Motorista não encontrado.", "delivery_feedback_level": "error"})
        return RedirectResponse(url=f"{redirect_base}&{feedback_encoded}", status_code=303)
    if not getattr(emp, "mobile_access_separation", False):
        feedback_encoded = urlencode({
            "delivery_feedback": "Motorista sem Entregas habilitado no cadastro.",
            "delivery_feedback_level": "error",
        })
        return RedirectResponse(url=f"{redirect_base}&{feedback_encoded}", status_code=303)

    now = datetime.now(ZoneInfo("America/Sao_Paulo"))
    addr = (client.endereco or client.logradouro or "")
    if client.numero:
        addr = f"{addr} {client.numero}".strip()
    route = models.Route(
        date=date,
        shift=shift,
        employee_id=employee_id,
        client_id=client_id,
        start_time="00:00",
        end_time=None,
        tonnage=float(tonnage or 0.0),
        valor_financeiro=float(valor_financeiro) if valor_financeiro is not None else None,
        type="delivery",
        delivery_status="pendente",
        delivery_vehicle_plate=vehicle_plate.strip().upper(),
        delivery_order_number=(delivery_order_number or "").strip() or None,
        delivery_client_code=client.nb,
        delivery_address=addr or None,
        delivery_neighborhood=client.bairro,
        delivery_city=client.municipio,
        delivery_state=None,
        delivery_cep=None,
    )
    session.add(route)
    session.flush()
    log_entry = models.RouteInsertLog(
        route_id=route.id,
        client_id=client_id,
        route_date=date,
        shift=shift,
        inserted_at=now,
        source="admin_manual",
        created_by=request.session.get("username") or str(request.session.get("user_id") or ""),
    )
    session.add(log_entry)
    session.commit()
    feedback_encoded = urlencode({"delivery_feedback": f"Cliente {client.name} adicionado à rota.", "delivery_feedback_level": "success"})
    return RedirectResponse(url=f"{redirect_base}&{feedback_encoded}", status_code=303)


@app.post("/separacao/delivery/remove-stop", response_class=RedirectResponse)
async def delivery_remove_stop(
    request: Request,
    route_id: int = Form(...),
    date: str = Form(...),
    shift: str = Form("Manhã"),
    date_from: Optional[str] = Form(None),
    date_to: Optional[str] = Form(None),
    session: Session = Depends(get_session),
):
    """Remove uma parada de entrega da rota (exclui o registro da parada)."""
    require_login(request)
    df, dt = (date_from or "").strip(), (date_to or "").strip()
    if df and dt and df != dt:
        redirect_base = f"/separacao?date_from={df}&date_to={dt}&shift={shift}"
    else:
        redirect_base = f"/separacao?date={date}&shift={shift}"

    route = session.get(models.Route, route_id)
    if not route or route.type != "delivery":
        feedback_encoded = urlencode({"delivery_feedback": "Parada não encontrada.", "delivery_feedback_level": "error"})
        return RedirectResponse(url=f"{redirect_base}&{feedback_encoded}", status_code=303)

    st = (route.delivery_status or "").lower() or "pendente"
    session.exec(delete(models.Devolucao).where(models.Devolucao.route_id == route_id))
    session.exec(delete(models.DeliveryAuthRequest).where(models.DeliveryAuthRequest.route_id == route_id))
    session.exec(delete(models.RouteInsertLog).where(models.RouteInsertLog.route_id == route_id))
    session.exec(delete(models.DeliveryWhatsAppItem).where(models.DeliveryWhatsAppItem.route_id == route_id))
    session.delete(route)
    session.commit()

    msg = f"Cliente removido da rota ({st})."
    feedback_encoded = urlencode({"delivery_feedback": msg, "delivery_feedback_level": "success"})
    return RedirectResponse(url=f"{redirect_base}&{feedback_encoded}", status_code=303)


@app.post("/separacao/delivery/session/start", response_class=RedirectResponse)
async def separacao_delivery_session_start(
    request: Request,
    employee_id: int = Form(...),
    vehicle_plate: str = Form(...),
    date: str = Form(...),
    shift: str = Form("Manhã"),
    plate: str = Form(...),
    km_departure: float = Form(...),
    session: Session = Depends(get_session),
):
    """Inicia a rota de entrega pela web (coordenador), como no mobile."""
    require_login(request)
    redirect_base = f"/separacao?date={date}&shift={shift}"
    form = await request.form()
    helper_ids_list = [int(x) for x in form.getlist("helper_ids") if str(x).strip().isdigit()]

    plate_clean = (plate or "").strip().upper()
    if not plate_clean or len(plate_clean) < 7:
        feedback_encoded = urlencode({"delivery_feedback": "Placa inválida.", "delivery_feedback_level": "error"})
        return RedirectResponse(url=f"{redirect_base}&{feedback_encoded}", status_code=303)
    if not km_departure or km_departure <= 0:
        feedback_encoded = urlencode({"delivery_feedback": "KM de saída inválido.", "delivery_feedback_level": "error"})
        return RedirectResponse(url=f"{redirect_base}&{feedback_encoded}", status_code=303)

    routes = session.exec(
        select(models.Route)
        .where(models.Route.type == "delivery")
        .where(models.Route.employee_id == employee_id)
        .where(models.Route.date == date)
        .where(models.Route.delivery_status.in_(["pendente", "iniciada", "reaberta"]))
    ).all()
    routes = list(routes)
    if not routes:
        feedback_encoded = urlencode({"delivery_feedback": "Sem entregas planejadas para este motorista/data.", "delivery_feedback_level": "error"})
        return RedirectResponse(url=f"{redirect_base}&{feedback_encoded}", status_code=303)

    assigned_plates = sorted({r.delivery_vehicle_plate for r in routes if r.delivery_vehicle_plate})
    if assigned_plates and _norm_plate(plate_clean) not in {_norm_plate(p) for p in assigned_plates}:
        feedback_encoded = urlencode({
            "delivery_feedback": f"Placa inválida. Placa(s) planejada(s): {', '.join(assigned_plates)}.",
            "delivery_feedback_level": "error",
        })
        return RedirectResponse(url=f"{redirect_base}&{feedback_encoded}", status_code=303)

    existing = session.exec(
        select(models.DeliverySession)
        .where(models.DeliverySession.employee_id == employee_id)
        .where(models.DeliverySession.date == date)
        .where(models.DeliverySession.status == "open")
    ).first()
    if existing:
        feedback_encoded = urlencode({"delivery_feedback": "Rotina já iniciada para este motorista.", "delivery_feedback_level": "error"})
        return RedirectResponse(url=f"{redirect_base}&{feedback_encoded}", status_code=303)

    emp_map = {e.id: e for e in session.exec(select(models.Employee)).all()}
    helper_names: List[str] = []
    normalized_helper_ids: List[int] = []
    seen = set()
    for hid in helper_ids_list:
        try:
            h = int(hid)
        except (TypeError, ValueError):
            continue
        if h == employee_id or h in seen:
            continue
        seen.add(h)
        normalized_helper_ids.append(h)
        emp = emp_map.get(h)
        if emp and (emp.name or "").strip():
            helper_names.append(emp.name.strip())

    new_session = models.DeliverySession(
        date=date,
        employee_id=employee_id,
        status="open",
        vehicle_plate=plate_clean,
        helpers_json=json.dumps(helper_names),
        km_departure=float(km_departure),
        started_at=datetime.now(ZoneInfo("America/Sao_Paulo")),
    )
    session.add(new_session)
    _sync_route_delivery_helpers_for_escala(
        session,
        employee_id=employee_id,
        route_date=date,
        vehicle_plate=plate_clean,
        helper_ids=normalized_helper_ids,
    )
    session.commit()
    try:
        mark_delivery_group_whatsapp_ready(
            session,
            route_date=date,
            shift=shift,
            employee_id=employee_id,
            vehicle_plate=plate_clean,
        )
    except Exception as whatsapp_error:
        logger.warning("separacao_delivery_session_start whatsapp ready error: %s", whatsapp_error)

    driver_name = emp_map.get(employee_id)
    driver_label = driver_name.name if driver_name else f"Motorista #{employee_id}"
    feedback_encoded = urlencode({"delivery_feedback": f"Rota iniciada: {driver_label}.", "delivery_feedback_level": "success"})
    return RedirectResponse(url=f"{redirect_base}&{feedback_encoded}", status_code=303)


@app.post("/separacao/delivery/reopen-route", response_class=RedirectResponse)
async def reopen_delivery_route_all(
    request: Request,
    date: str = Form(...),
    shift: str = Form("Manhã"),
    employee_id: int = Form(...),
    session: Session = Depends(get_session),
):
    """Reabre toda a rota do motorista: todas as paradas entregues/devolução voltam para reaberta."""
    require_login(request)
    now = datetime.now(ZoneInfo("America/Sao_Paulo")).strftime("%H:%M")

    routes = session.exec(
        select(models.Route)
        .where(models.Route.type == "delivery")
        .where(models.Route.date == date)
        .where(models.Route.shift == shift)
        .where(models.Route.employee_id == employee_id)
        .where(models.Route.delivery_status.in_(["entregue", "devolucao"]))
    ).all()
    routes = list(routes)
    if not routes:
        feedback_encoded = urlencode({"delivery_feedback": "Nenhuma parada finalizada para reabrir.", "delivery_feedback_level": "error"})
        return RedirectResponse(url=f"/separacao?date={date}&shift={shift}&{feedback_encoded}", status_code=303)

    started_rows = session.exec(
        select(models.Route)
        .where(models.Route.type == "delivery")
        .where(models.Route.date == date)
        .where(models.Route.employee_id == employee_id)
        .where(models.Route.delivery_status == "iniciada")
    ).all()
    route_plate = _norm_plate(routes[0].delivery_vehicle_plate)
    if any(_norm_plate(r.delivery_vehicle_plate) == route_plate for r in started_rows):
        feedback_encoded = urlencode({
            "delivery_feedback": "Motorista já possui rotina iniciada. Finalize antes de reabrir.",
            "delivery_feedback_level": "error",
        })
        return RedirectResponse(url=f"/separacao?date={date}&shift={shift}&{feedback_encoded}", status_code=303)

    for route in routes:
        route.delivery_status = "reaberta"
        route.status = "pending"
        route.end_time = None
        route.delivery_finished_at = None
        route.delivery_returned_at = None
        route.driver_lat_start = None
        route.driver_lon_start = None
        route.driver_lat_end = None
        route.driver_lon_end = None
        route.delivery_reopen_count = (route.delivery_reopen_count or 0) + 1
        _append_delivery_event(route, "reabrir", now, note=f"Reabertura em massa #{route.delivery_reopen_count}")
        session.add(route)
    session.commit()

    feedback_encoded = urlencode({"delivery_feedback": f"Rota reaberta: {len(routes)} parada(s).", "delivery_feedback_level": "success"})
    return RedirectResponse(url=f"/separacao?date={date}&shift={shift}&{feedback_encoded}", status_code=303)


@app.post("/separacao/delivery/finish-all-routes", response_class=RedirectResponse)
async def finish_all_delivery_routes(
    request: Request,
    date: str = Form(None),
    date_from: Optional[str] = Form(None),
    date_to: Optional[str] = Form(None),
    shift: str = Form("Manhã"),
    session: Session = Depends(get_session),
):
    """Finaliza em massa todas as rotas do período/turno: paradas com devolução ficam devolução; demais ficam entregue."""
    require_login(request)
    df = date_from or date
    dt = date_to or date or df
    if not df:
        df = datetime.now().strftime("%Y-%m-%d")
    if not dt:
        dt = df
    if df > dt:
        df, dt = dt, df
    redirect_url = f"/separacao?date_from={df}&date_to={dt}&shift={shift}"
    now = datetime.now(ZoneInfo("America/Sao_Paulo")).strftime("%H:%M")

    routes = session.exec(
        select(models.Route)
        .where(models.Route.type == "delivery")
        .where(models.Route.date >= df)
        .where(models.Route.date <= dt)
        .where(models.Route.shift == shift)
    ).all()

    delivered_count = 0
    returned_count = 0
    return_value_total = 0.0
    total_planned = 0.0
    route_ids = [r.id for r in routes]

    devolucao_by_route: dict[int, list] = {}
    if route_ids:
        devolucoes = session.exec(
            select(models.Devolucao).where(models.Devolucao.route_id.in_(route_ids))
        ).all()
        for d in devolucoes:
            if d.route_id:
                devolucao_by_route.setdefault(d.route_id, []).append(d)

    for route in routes:
        st = (route.delivery_status or "").lower()
        if st in ("entregue", "devolucao"):
            continue
        if st in ("cancelada",):
            continue

        has_devolucao = (
            st == "devolucao"
            or route.valor_devolucao
            or (route.id and route.id in devolucao_by_route)
        )
        total_planned += float(route.valor_financeiro or 0.0)

        if has_devolucao:
            route.delivery_status = "devolucao"
            route.status = "completed"
            returned_count += 1
            val = float(route.valor_devolucao or route.valor_financeiro or 0.0)
            if not route.valor_devolucao and route.id and route.id in devolucao_by_route:
                val = sum(float(d.valor or 0) for d in devolucao_by_route[route.id])
            route.valor_devolucao = val
            return_value_total += val
        else:
            route.delivery_status = "entregue"
            route.status = "completed"
            delivered_count += 1

        # Horários só vêm do mobile; fechamento em massa não cria timestamps
        _append_delivery_event(
            route,
            "finalizar" if not has_devolucao else "devolucao",
            now,
            note="Fechamento em massa" if not has_devolucao else "Devolução (fechamento em massa)",
        )
        session.add(route)

    session.commit()
    total = delivered_count + returned_count
    rate = (return_value_total / total_planned * 100) if total_planned else 0.0
    feedback = f"Todas as rotas finalizadas: {delivered_count} entregues, {returned_count} devoluções (R$ {return_value_total:,.2f}, {rate:.1f}% dev.)"
    feedback_encoded = urlencode({"delivery_feedback": feedback, "delivery_feedback_level": "success"})
    return RedirectResponse(url=redirect_url + f"&{feedback_encoded}", status_code=303)


