@app.post("/events/{event_id}/update_vacation")
async def update_vacation_event(
    event_id: int,
    request: Request,
    start_date: str = Form(...),
    end_date: str = Form(...),
    session: Session = Depends(get_session)
):
    require_login(request)
    event = session.get(models.Event, event_id)
    if not event or event.type != 'ferias_hist':
        raise HTTPException(status_code=404, detail="Evento de férias não encontrado")
        emp = session.get(models.Employee, event.employee_id)
    if not emp:
        raise HTTPException(status_code=404, detail="Colaborador não encontrado")
    try:
        # Update Employee Dates
        v_start = datetime.strptime(start_date, "%Y-%m-%d")
        v_end = datetime.strptime(end_date, "%Y-%m-%d")
        # Update Event Text (BR Format)
        fmt_start = v_start.strftime("%d/%m/%Y")
        fmt_end = v_end.strftime("%d/%m/%Y")
        event.text = f"Férias Agendadas: {fmt_start} a {fmt_end}"
        session.add(event)
        
        emp.vacation_start = v_start
        emp.vacation_end = v_end
        
        # Re-eval Status
        today = datetime.now()
        check_start = v_start.replace(hour=0, minute=0, second=0, microsecond=0)
        check_end = v_end.replace(hour=23, minute=59, second=59, microsecond=999)
        
        if check_start <= today <= check_end:
            emp.status = 'vacation'
        else:
            if emp.status == 'vacation':
                emp.status = 'active'
                
        session.add(emp)
        session.commit()
    except ValueError:
        raise HTTPException(status_code=400, detail="Data inválida")
        
    return RedirectResponse(url=f"/employees/{emp.id}", status_code=status.HTTP_303_SEE_OTHER)
class MobileAdminStartPayload(BaseModel):
    registration_id: str
    client_id: int
    tonnage: Optional[float] = 0.0

@app.post("/mobile/admin/start-route")
async def mobile_admin_start_route(
    payload: MobileAdminStartPayload,
    request: Request,
    session: Session = Depends(get_session)
):
    try:
        # Check if logged in user is leader
        user_id = request.session.get("user_id")
        if not user_id:
            # Fallback for Web Admin testing on mobile view
            auth_user_id = request.session.get("auth_user_id")
            if auth_user_id:
                # If logged in as User, try to find linked Employee
                user = session.get(models.User, auth_user_id)
                if user and user.employee_id:
                    user_id = user.employee_id
                else:
                    return JSONResponse({"error": "Usuário web sem colaborador vinculado"}, status_code=403)
            else:
                return JSONResponse({"error": "Não autorizado"}, status_code=401)
            
        try:
            user_id = int(str(user_id))
        except:
             return JSONResponse({"error": "ID de usuário inválido"}, status_code=400)
            
        current_emp = session.get(models.Employee, user_id)
        if not current_emp:
             return JSONResponse({"error": "Líder não encontrado"}, status_code=403)
             
        if not getattr(current_emp, "mobile_access_admin_start", False):
             return JSONResponse({"error": "Sem permissão de líder"}, status_code=403)

        # Find Target Employee
        target_emp = session.exec(select(models.Employee).where(models.Employee.registration_id == payload.registration_id)).first()
        if not target_emp:
            return JSONResponse({"error": "Matrícula não encontrada"}, status_code=404)
            
        # Verify Client Existence (Prevent FK Error)
        client = session.get(models.Client, payload.client_id)
        if not client:
             return JSONResponse({"error": "Cliente não encontrado"}, status_code=404)

        # 1. Create Routine if needed (Safely)
        today_str = datetime.now().strftime("%Y-%m-%d")
        
        routine = session.exec(select(models.EmployeeRoutine).where(
            models.EmployeeRoutine.employee_id == target_emp.id,
            models.EmployeeRoutine.date == today_str
        )).first()
        
        if not routine:
            try:
                routine = models.EmployeeRoutine(
                    employee_id=target_emp.id,
                    date=today_str,
                    shift=target_emp.work_shift or "Manhã",
                    start_time=datetime.now(ZoneInfo("America/Sao_Paulo")).strftime("%H:%M"),
                    routine="present",
                    status="open"
                )
                session.add(routine)
                session.commit()
                session.refresh(routine)
            except Exception as e:
                # Ignore duplicate key if it was created in parallel
                session.rollback()
                routine = session.exec(select(models.EmployeeRoutine).where(
                    models.EmployeeRoutine.employee_id == target_emp.id,
                    models.EmployeeRoutine.date == today_str
                )).first()


        # 2. Create Route (entrega) para aparecer em /mobile/delivery e na listagem admin
        new_route = models.Route(
            employee_id=target_emp.id,
            client_id=payload.client_id,
            date=today_str,
            shift=target_emp.work_shift or "Manhã",
            start_time=datetime.now(ZoneInfo("America/Sao_Paulo")).strftime("%H:%M"),
            status="pending",
            type="delivery",
            delivery_status="pendente",
            tonnage=payload.tonnage or 0.0,
        )
        session.add(new_route)
        
        # 4. Log
        log = models.Event(
            type="routine_change",
            text=f"Rota iniciada via Mobile (Líder {current_emp.name}) para {target_emp.name}",
            category="processo",
            sector="expedicao",
            impact="low",
            employee_id=target_emp.id,
            timestamp=datetime.now(ZoneInfo("America/Sao_Paulo"))
        )
        session.add(log)
        
        session.commit()
        return JSONResponse({"success": True})
        
    except Exception as e:
        import traceback
        traceback.print_exc()
        return JSONResponse({"error": f"Erro interno: {str(e)}"}, status_code=500)

@app.post("/employees/{emp_id}/update")
async def update_employee(
    emp_id: int,
    request: Request,
    name: str = Form(...),
    registration_id: str = Form(...),
    seller_code: str = Form(None),
    phone: str = Form(None),
    role: str = Form(...),
    work_shift: Optional[str] = Form(None),
    cost_center: str = Form(...),
    admission_date: str = Form(None),
    birthday: str = Form(None),
    work_days: List[str] = Form(None),
    work_schedule: str = Form(None),
    mobile_access_separation: bool = Form(False),
    mobile_access_checklist: bool = Form(False),
    mobile_access_admin_start: bool = Form(False),
    mobile_access_returns: bool = Form(False),
    mobile_access_helper: bool = Form(False),
    mobile_access_gatehouse: bool = Form(False),
    mobile_access_escala: bool = Form(False),
    vacation_start: str = Form(None),
    vacation_end: str = Form(None),
    session: Session = Depends(get_session)
):
    require_login(request)
    emp = session.get(models.Employee, emp_id)
    if emp:
        ws_in = (work_shift or "").strip() if work_shift is not None else ""
        work_shift_resolved = ws_in or (emp.work_shift or "Manhã")
        # Log Shift Change
        if emp.work_shift != work_shift_resolved:
            session.add(models.Event(
                text=f"Troca de Turno: {emp.work_shift} para {work_shift_resolved}",
                type="alteracao_cadastro",
                category="pessoas",
                employee_id=emp.id
            ))
                    # Log Role Change
        role_norm = (role or "").strip().upper()
        if emp.role != role_norm:
            session.add(models.Event(
                text=f"Alteração de Cargo: {emp.role} para {role_norm}",
                type="alteracao_cadastro",
                category="pessoas",
                employee_id=emp.id
            ))
        # Log Cost Center Change
        if emp.cost_center != cost_center:
            session.add(models.Event(
                text=f"Alteração de Centro de Custo: {emp.cost_center} -> {cost_center}",
                type="alteracao_cadastro",
                category="pessoas",
                employee_id=emp.id
            ))
            
        emp.name = (name or "").strip().upper()
        emp.registration_id = registration_id
        emp.seller_code = seller_code.strip() if seller_code else None
        phone_e164, _ = normalize_phone_br(phone)
        emp.phone = phone_e164[3:] if (phone_e164 and len(phone_e164) >= 13) else None
        emp.role = (role or "").strip().upper()
        emp.work_shift = work_shift_resolved
        emp.cost_center = cost_center
        emp.work_schedule = work_schedule
        emp.mobile_access_separation = mobile_access_separation
        emp.mobile_access_checklist = mobile_access_checklist
        emp.mobile_access_admin_start = mobile_access_admin_start
        emp.mobile_access_returns = mobile_access_returns
        emp.mobile_access_helper = mobile_access_helper
        emp.mobile_access_gatehouse = mobile_access_gatehouse
        emp.mobile_access_escala = mobile_access_escala
        emp.mobile_access = bool(
            mobile_access_separation
            or mobile_access_checklist
            or mobile_access_admin_start
            or mobile_access_returns
            or mobile_access_helper
            or mobile_access_gatehouse
            or mobile_access_escala
        )

        # Update Work Days
        if work_days:
             emp.work_days = json.dumps(work_days)
        else:
             # Check if it was sent as empty list (cleared) or not sent?
             # If form sends checkboxes, unchecked usually means not sent.
             # We should assume if the list is None/Empty but the request is an Update,
             # we might want to clear it? Or default?
             # Logic: If Form is present in request but empty... FastAPI makes it None usually.
             # Let's save a default "all days" or empty list if explicitly cleared?
             # Ideally if user unchecks all, we receive empty list.
             # BUT: FastAPI Form(None) defaults to None if key missing.
             # If key exists but empty values?
             # For safety: If update comes, we can overwrite. But checkboxes not checked simply don't send keys.
             # This is tricky with pure HTML forms.
             # If the frontend always sends at least one, we are good.
             # If we want to allow clearing all, we need a hidden input or assume None = Clear?
             # Let's assume if updated, we overwrite. If None, maybe don't change?
             # Actually, simpler: if work_days is None, it means NO checkbox checked (or key missing).
             # We should probably clear it if we want to support unchecking all.
             # However, to be safe against accidental clears if form is incomplete:
             # Let's only update if we have data OR if we explicitly handle "clear".
             # For now, let's just update if present. To allow "clearing", user usually leaves one checked.
             # To truly support clearing all, we'd need a hidden input with same name or JS handling.
             # Given the snippet, let's just save valid list if provided.
             pass
        
        # Actually, standard behavior for checkboxes: NOT sent if unchecked.
        # So verifying if we can differentiate "not submitted" vs "unchecked all".
        # We can't easily. But since this is a dedicated update form, we can assume
        # if the user submits the form, they see the checkboxes.
        # If work_days is None, it likely means they unchecked everything.
        # So let's save empty list "[]" if work_days is None? 
        # But wait, we set default Form(None).
        # Let's check how add_employee does it:
        # work_days_json = '["Monday"...]' # Default
        # if work_days: work_days_json = json.dumps(work_days)
        
        # Here: we want to UPDATE.
        # If work_days received (List[str]), we dump it.
        # If None, it means no box checked. Should we clear it? 
        # Yes, usually "Edit" means "Current State".
        # So: emp.work_days = json.dumps(work_days if work_days else [])
        
        if work_days is not None:
             emp.work_days = json.dumps(work_days)
        else:
             # Checkboxes not checked -> None
             emp.work_days = "[]"
        
        if admission_date:
            try:
                emp.admission_date = datetime.strptime(admission_date, "%Y-%m-%d")
            except:
                pass
                
        if birthday:
            try:
                emp.birthday = datetime.strptime(birthday, "%Y-%m-%d")
            except:
                pass
        
        # Processar férias programadas
        if vacation_start and vacation_end:
            try:
                v_start = datetime.strptime(vacation_start, "%Y-%m-%d")
                v_end = datetime.strptime(vacation_end, "%Y-%m-%d")
                
                # Validar datas
                if v_start <= v_end:
                    old_v_start = emp.vacation_start
                    old_v_end = emp.vacation_end
                    
                    emp.vacation_start = v_start
                    emp.vacation_end = v_end
                    
                    # Verificar se hoje está dentro do período de férias
                    today = datetime.now()
                    if v_start <= today <= v_end:
                        emp.status = 'vacation'
                    elif emp.status == 'vacation' and today > v_end:
                        # Férias acabaram, voltar para ativo
                        emp.status = 'active'
                    
                    # Log se houve alteração
                    if old_v_start != v_start or old_v_end != v_end:
                        session.add(models.Event(
                            text=f"Férias programadas: {v_start.strftime('%d/%m/%Y')} a {v_end.strftime('%d/%m/%Y')}",
                            type="ferias",
                            category="pessoas",
                            employee_id=emp.id
                        ))
            except Exception as e:
                print(f"Erro ao processar férias: {e}")
        elif vacation_start == "" and vacation_end == "":
            # Se ambos foram limpos, limpar as férias
            if emp.vacation_start or emp.vacation_end:
                emp.vacation_start = None
                emp.vacation_end = None
                if emp.status == 'vacation':
                    emp.status = 'active'
                session.add(models.Event(
                    text="Férias canceladas/removidas",
                    type="ferias",
                    category="pessoas",
                    employee_id=emp.id
                ))
                
        session.add(emp)
        session.commit()
        
    return RedirectResponse(url="/employees", status_code=status.HTTP_303_SEE_OTHER)
@app.post("/settings/targets")
async def update_targets(
    request: Request,
    session: Session = Depends(get_session)
):
    require_login(request)
    form_data = await request.form()
        # Iterate over form keys to find target_{shift}
    for key, value in form_data.items():
        if key.startswith("target_"):
            shift_name = key.replace("target_", "")
            try:
                val = int(value)
                # Check if exists
                stmt = select(models.HeadcountTarget).where(models.HeadcountTarget.shift_name == shift_name)
                target = session.exec(stmt).first()
                if target:
                    target.target_value = val
                    session.add(target)
                else:
                    new_target = models.HeadcountTarget(shift_name=shift_name, target_value=val)
                    session.add(new_target)
            except ValueError:
                pass
        session.commit()
    return RedirectResponse(url="/employees", status_code=status.HTTP_303_SEE_OTHER)
import pandas as pd
from fastapi import UploadFile, File
import io

from services.fechamento_ponto_parser import parse_fechamento_ponto_excel


def _normalize_name_for_match(s: str) -> str:
    s = unicodedata.normalize("NFKD", (s or ""))
    s = "".join(c for c in s if not unicodedata.combining(c))
    s = " ".join((s or "").split()).strip().upper()
    return s


def _apply_occurrence_entries(session: Session, pending_entries: list) -> dict:
    """Aplica pending_entries (rotinas + eventos). Retorna stats {total, success, errors}."""
    stats = {"total": 0, "success": 0, "errors": []}
    if not pending_entries:
        return stats
    involved_ids = {e["employee"].id for e in pending_entries}
    dates = [e["date_obj"] for e in pending_entries]
    min_date = min(dates).strftime("%Y-%m-%d")
    max_date = max(dates).strftime("%Y-%m-%d")
    existing_routines = session.exec(
        select(models.EmployeeRoutine)
        .where(models.EmployeeRoutine.employee_id.in_(involved_ids))
        .where(models.EmployeeRoutine.date >= min_date)
        .where(models.EmployeeRoutine.date <= max_date)
    ).all()
    routine_map = {(r.employee_id, r.date): r for r in existing_routines}
    for entry in pending_entries:
        stats["total"] += 1
        emp = entry["employee"]
        iso_date = entry["iso_date"]
        if entry.get("routine_type"):
            key = (emp.id, iso_date)
            if key in routine_map:
                routine_map[key].routine = entry["routine_type"]
                session.add(routine_map[key])
            else:
                shift_val = (getattr(emp, "work_shift", None) or "").strip() or "Manhã"
                r = models.EmployeeRoutine(
                    date=iso_date, shift=shift_val, employee_id=emp.id, routine=entry["routine_type"]
                )
                session.add(r)
                routine_map[key] = r
        ts = entry["date_obj"]
        if isinstance(ts, datetime) and ts.tzinfo is None:
            ts = ts.replace(tzinfo=ZoneInfo("America/Sao_Paulo"))
        elif isinstance(ts, datetime):
            ts = ts.replace(hour=8, minute=0)
        new_event = models.Event(
            timestamp=ts,
            text=f"Importação em Massa: {entry.get('raw_occ', '')}",
            type=entry.get("event_type", "outros"),
            category="import",
            employee_id=emp.id,
        )
        session.add(new_event)
        stats["success"] += 1
    session.commit()
    return stats


class BulkImportData(pydantic.BaseModel):
    raw_text: str

@app.post("/api/import/occurrences")
async def import_occurrences(
    data: BulkImportData,
    session: Session = Depends(get_session)
):
    """
    Importa ocorrências (Faltas/Atestados) a partir de texto copiado do Excel.
    Formato esperado: Matricula | Nome(Ignorado) | Data | Ocorrência
    """
    lines = data.raw_text.strip().split('\n')
    stats = {"total": 0, "success": 0, "errors": []}
    
    # Pre-fetch all active employees for validation
    employees = session.exec(select(models.Employee)).all()
    emp_map = {str(e.registration_id): e for e in employees}
    

    # Parse all lines first to gather requirements
    pending_entries = []
    
    # 1. First Pass: Parse and Validate Basic Format
    for line in lines:
        parts = line.split('\t')
        if len(parts) < 4:
            continue
            
        reg_id = parts[0].strip()
        date_str = parts[2].strip()
        occurrence_raw = parts[3].strip()
        
        # Validate Employee
        employee = emp_map.get(reg_id)
        if not employee:
            stats['errors'].append(f"Matrícula {reg_id}: Colaborador não encontrado")
            continue
            
        # Validate Date
        try:
            start_date_obj = datetime.strptime(date_str, "%d/%m/%Y")
            iso_date = start_date_obj.strftime("%Y-%m-%d") # Base date
        except:
             try:
                 start_date_obj = datetime.strptime(date_str, "%Y-%m-%d")
                 iso_date = start_date_obj.strftime("%Y-%m-%d")
             except:
                stats['errors'].append(f"Matrícula {reg_id}: Data inválida ({date_str})")
                continue
                
        # CHECK FOR MULTI-DAY RANGE (If occurrence_raw is actually a Date)
        end_date_obj = None
        is_multi_day = False
        try:
            # Try parsing occurrence_raw as date
            candidate_end = occurrence_raw
            try:
                end_date_obj = datetime.strptime(candidate_end, "%d/%m/%Y")
            except:
                end_date_obj = datetime.strptime(candidate_end, "%Y-%m-%d")
            
            # If successful, it's a multi-day certificate!
            is_multi_day = True
            occurrence_raw = "Atestado (Multi-Dias)" # Force type
            
        except:
            # Not a date, standard processing
            end_date_obj = start_date_obj # Single day
            is_multi_day = False

        
        # Loop for Days (Single or Multi)
        current_loop_date = start_date_obj
        while current_loop_date <= end_date_obj:
            loop_iso = current_loop_date.strftime("%Y-%m-%d")
            
            # Determine Types
            if is_multi_day:
                routine_type, event_type = "sick", "atestado"
                occ_label = f"Atestado ({start_date_obj.strftime('%d/%m')} a {end_date_obj.strftime('%d/%m')})"
            else:
                # Standard Logic
                occ_lower = occurrence_raw.lower()
                routine_type, event_type = None, None
                occ_label = occurrence_raw
                
                if "falta" in occ_lower:
                    routine_type, event_type = "absent", "falta"
                elif "atestado" in occ_lower:
                    routine_type, event_type = "sick", "atestado"
                elif "suspensão" in occ_lower or "suspensao" in occ_lower:
                    routine_type, event_type = "absent", "suspension"
                elif "advertência" in occ_lower or "advertencia" in occ_lower:
                    routine_type, event_type = None, "advertencia"
                else:
                    stats['errors'].append(f"Matrícula {reg_id}: Ocorrência desconhecida ({occurrence_raw})")
                    break # Skip this line entirely if error
            
            pending_entries.append({
                "employee": employee,
                "iso_date": loop_iso,
                "date_obj": current_loop_date,
                "routine_type": routine_type,
                "event_type": event_type,
                "raw_occ": occ_label
            })
            
            current_loop_date += timedelta(days=1)
        
    if not pending_entries:
        return stats

    apply_stats = _apply_occurrence_entries(session, pending_entries)
    stats["total"] = apply_stats["total"]
    stats["success"] = apply_stats["success"]
    return stats


class BulkCostCenterPayload(pydantic.BaseModel):
    selected_roles: List[str] = []
    selected_center: str = "Exemplar"  # Centro para as funções selecionadas
    others_center: str = "Souza Pinto"  # Centro para os demais
    exemplar_roles: List[str] = []  # Retrocompatível, mapeia para selected_roles


@app.post("/api/employees/bulk-cost-center-all", response_class=JSONResponse)
async def api_bulk_cost_center_all(
    request: Request,
    center: str = Form("Souza Pinto"),
    session: Session = Depends(get_session),
):
    """Coloca todos os colaboradores (incluindo sem preenchimento) no centro informado."""
    require_login(request)
    val = (center or "Souza Pinto").strip()
    employees = session.exec(select(models.Employee).where(models.Employee.replaced_by.is_(None))).all()
    count = 0
    for e in employees:
        if (e.cost_center or "").strip() != val:
            e.cost_center = val
            session.add(e)
            count += 1
    session.commit()
    return JSONResponse({
        "success": True,
        "message": f"Todos os colaboradores atualizados para {val}. {count} alterados.",
        "count": count,
    })


@app.post("/api/employees/bulk-cost-center", response_class=JSONResponse)
async def api_bulk_cost_center(
    request: Request,
    payload: BulkCostCenterPayload,
    session: Session = Depends(get_session),
):
    """
    Atualiza centro de custo em massa por funções.
    - selected_roles: funções selecionadas
    - selected_center: centro para os selecionados (Exemplar ou Souza Pinto)
    - others_center: centro para os demais
    """
    require_login(request)
    roles = payload.selected_roles or payload.exemplar_roles
    selected_set = {(r or "").strip().upper() for r in roles if (r or "").strip()}
    selected_center = (payload.selected_center or "Exemplar").strip()
    others = (payload.others_center or ("Souza Pinto" if selected_center == "Exemplar" else "Exemplar")).strip()
    employees = session.exec(select(models.Employee).where(models.Employee.replaced_by.is_(None))).all()
    count_selected, count_others = 0, 0
    for e in employees:
        role_norm = (e.role or "").strip().upper()
        if role_norm in selected_set:
            if (e.cost_center or "").strip() != selected_center:
                e.cost_center = selected_center
                session.add(e)
                count_selected += 1
        else:
            if (e.cost_center or "").strip() != others:
                e.cost_center = others
                session.add(e)
                count_others += 1
    session.commit()
    return JSONResponse({
        "success": True,
        "message": f"Atualizado: {count_selected} para {selected_center}, {count_others} para {others}.",
        "count_selected": count_selected,
        "count_others": count_others,
    })


class BulkCostCenterFromFilePayload(pydantic.BaseModel):
    others_center: str = "Souza Pinto"


@app.post("/api/employees/bulk-cost-center-from-file", response_class=JSONResponse)
async def api_bulk_cost_center_from_file(
    request: Request,
    file: UploadFile = File(...),
    file_center: str = Form("Exemplar"),  # Centro para nomes da planilha
    others_center: str = Form("Souza Pinto"),  # Centro para os demais
    session: Session = Depends(get_session),
):
    """
    Colaboradores da planilha (Fechamento de Ponto ou similar) recebem file_center.
    Os demais recebem others_center.
    """
    require_login(request)
    contents = await file.read()
    if len(contents) > 10 * 1024 * 1024:
        return JSONResponse({"success": False, "error": "Arquivo muito grande."}, status_code=400)
    try:
        parsed = parse_fechamento_ponto_excel(contents, file.filename or "")
    except Exception:
        import pandas as pd
        try:
            df = pd.read_excel(io.BytesIO(contents), header=None, nrows=500)
            names_from_sheet = set()
            for _, row in df.iterrows():
                for v in row.values:
                    s = (str(v) or "").strip()
                    if s and len(s) > 5 and not s.replace(".", "").replace(",", "").replace(" ", "").isdigit():
                        names_from_sheet.add(s)
            parsed = [{"nome": n} for n in names_from_sheet]
        except Exception as e:
            return JSONResponse({"success": False, "error": f"Erro ao ler arquivo: {str(e)}"}, status_code=400)
    file_names = {_normalize_name_for_match(item.get("nome", "")) for item in parsed if (item.get("nome") or "").strip()}
    file_names_compact = {"".join(c for c in n if c.isalnum()) for n in file_names}
    employees = session.exec(select(models.Employee).where(models.Employee.replaced_by.is_(None))).all()
    count_file, count_others = 0, 0
    file_center_val = (file_center or "Exemplar").strip()
    others_val = (others_center or "Souza Pinto").strip()
    if file_center_val == others_val:
        others_val = "Exemplar" if file_center_val == "Souza Pinto" else "Souza Pinto"
    for e in employees:
        n = _normalize_name_for_match(e.name)
        compact = "".join(c for c in n if c.isalnum())
        if n in file_names or compact in file_names_compact:
            if (e.cost_center or "").strip() != file_center_val:
                e.cost_center = file_center_val
                session.add(e)
                count_file += 1
        else:
            if (e.cost_center or "").strip() != others_val:
                e.cost_center = others_val
                session.add(e)
                count_others += 1
    session.commit()
    return JSONResponse({
        "success": True,
        "message": f"Da planilha → {file_center_val}: {count_file}. Demais → {others_val}: {count_others}.",
        "count_file": count_file,
        "count_others": count_others,
    })


@app.post("/api/import/occurrences-from-fechamento")
async def import_occurrences_from_fechamento(
    request: Request,
    file: UploadFile = File(...),
    session: Session = Depends(get_session),
):
    """
    Importa ocorrências (Faltas/Atestados) a partir do arquivo Excel "Fechamento de Ponto".
    Lê todas as abas mensais, identifica colunas por cabeçalho, parseia formatos de data
    e gera um lançamento por dia. Cruza FUNCIONÁRIO com colaboradores cadastrados.
    """
    require_login(request)
    MAX_SIZE = 10 * 1024 * 1024
    contents = await file.read()
    if len(contents) > MAX_SIZE:
        return JSONResponse({"success": False, "error": "Arquivo muito grande (máx 10MB)."}, status_code=400)
    ext = (file.filename or "").lower()
    if ext and not (ext.endswith(".xls") or ext.endswith(".xlsx")):
        return JSONResponse({"success": False, "error": "Envie um arquivo Excel (.xls ou .xlsx)."}, status_code=400)

    try:
        parsed = parse_fechamento_ponto_excel(contents, file.filename or "")
    except Exception as e:
        return JSONResponse({"success": False, "error": f"Erro ao ler o arquivo: {str(e)}"}, status_code=400)

    employees = session.exec(select(models.Employee)).all()
    emp_by_name = {}
    for e in employees:
        if not (e.name or "").strip():
            continue
        n = _normalize_name_for_match(e.name)
        emp_by_name[n] = e
        compact = "".join(c for c in n if c.isalnum())
        if compact and compact not in emp_by_name:
            emp_by_name[compact] = e
        parts = [p for p in n.split() if len(p) > 1]
        if len(parts) >= 2:
            first_last = f"{parts[0]}_{parts[-1]}"
            if first_last not in emp_by_name:
                emp_by_name[first_last] = e

    def find_employee(nome: str):
        n = _normalize_name_for_match(nome)
        if n in emp_by_name:
            return emp_by_name[n]
        compact = "".join(c for c in n if c.isalnum())
        if compact in emp_by_name:
            return emp_by_name[compact]
        parts = [p for p in n.split() if len(p) > 1]
        if len(parts) >= 2:
            first_last = f"{parts[0]}_{parts[-1]}"
            if first_last in emp_by_name:
                return emp_by_name[first_last]
        return None

    pending_entries = []
    stats = {"total": 0, "success": 0, "errors": [], "skipped_unknown": 0, "sample_unknown": set()}

    for item in parsed:
        nome = (item.get("nome") or "").strip()
        if not nome:
            continue
        emp = find_employee(nome)
        if not emp:
            stats["skipped_unknown"] += 1
            if len(stats["sample_unknown"]) < 10:
                stats["sample_unknown"].add(nome)
            continue
        d = item.get("data")
        if not d:
            continue
        occ = (item.get("ocorrencia") or "").strip()
        routine_type = "absent" if "falta" in occ.lower() else "sick"
        event_type = "falta" if "falta" in occ.lower() else "atestado"
        if isinstance(d, datetime):
            day = d.date()
        elif isinstance(d, date):
            day = d
        else:
            continue
        brt = ZoneInfo("America/Sao_Paulo")
        date_obj = datetime.combine(day, time(8, 0), tzinfo=brt)
        iso_date = day.strftime("%Y-%m-%d")
        pending_entries.append({
            "employee": emp,
            "iso_date": iso_date,
            "date_obj": date_obj,
            "routine_type": routine_type,
            "event_type": event_type,
            "raw_occ": occ,
        })

    if not pending_entries:
        hint = ""
        if stats["sample_unknown"]:
            hint = f" Exemplos não encontrados: {', '.join(list(stats['sample_unknown'])[:5])}. Cadastre esses colaboradores antes de importar."
        return JSONResponse({
            "ok": True,
            "success": True,
            "imported_count": 0,
            "message": f"Nenhuma ocorrência para importar. {stats['skipped_unknown']} registros ignorados (colaborador não cadastrado).{hint}",
            "total": 0,
            "skipped_unknown": stats["skipped_unknown"],
            "sample_unknown": list(stats["sample_unknown"])[:15],
        })

    apply_stats = _apply_occurrence_entries(session, pending_entries)
    hint = ""
    if stats["skipped_unknown"] > 0 and stats["sample_unknown"]:
        hint = f" Exemplos ignorados (nome não bate com cadastro): {', '.join(list(stats['sample_unknown'])[:5])}. Cadastre-os ou ajuste o nome."
    return JSONResponse({
        "ok": True,
        "success": True,
        "imported_count": apply_stats["success"],
        "message": f"Importadas {apply_stats['success']} ocorrências. {stats['skipped_unknown']} ignorados (não cadastrados).{hint}",
        "total": apply_stats["total"],
        "skipped_unknown": stats["skipped_unknown"],
        "sample_unknown": list(stats["sample_unknown"])[:15],
    })


@app.post("/employees/import")

async def import_employees(
    request: Request,
    file: UploadFile = File(...),
    session: Session = Depends(get_session)
):
    require_login(request)
    import pandas as pd
    import io
    import unicodedata

    def normalize_text(value: str) -> str:
        value = unicodedata.normalize("NFKD", str(value or ""))
        value = "".join(ch for ch in value if not unicodedata.combining(ch))
        return value.strip().lower()

    def pick_column(columns, *candidates):
        normalized = {normalize_text(col): col for col in columns}
        for candidate in candidates:
            key = normalize_text(candidate)
            if key in normalized:
                return normalized[key]
        # Fallback: match parcial (ex.: "registration id", "matrícula colaborador")
        candidate_keys = [normalize_text(c) for c in candidates]
        for norm_col, original_col in normalized.items():
            compact_col = norm_col.replace(" ", "").replace(".", "")
            for ck in candidate_keys:
                compact_ck = ck.replace(" ", "").replace(".", "")
                if compact_ck and (compact_ck in compact_col or compact_col in compact_ck):
                    return original_col
        return None

    def pick_column_contains(columns, *substrings):
        """Retorna primeira coluna cujo nome contém um dos substrings."""
        for col in columns:
            n = normalize_text(str(col))
            for s in substrings:
                if normalize_text(s) in n:
                    return col
        return None

    content = await file.read()
    try:
        excel = pd.ExcelFile(io.BytesIO(content))
        sheet_names = excel.sheet_names or [0]

        # Prioridade para a aba Souza Pinto quando existir.
        target_sheet = None
        for s in sheet_names:
            if normalize_text(s) == "souza pinto":
                target_sheet = s
                break
        if target_sheet is None:
            target_sheet = sheet_names[0]

        # Detecta cabeçalho nos primeiros registros.
        df_temp = pd.read_excel(io.BytesIO(content), sheet_name=target_sheet, header=None, nrows=10)
        header_row = 0
        expected_headers = {
            "matricula", "matrícula", "registration", "registration id", "registro",
            "colaborador", "nome funcionario", "nome", "nome cargo", "turno", "cargo", "funcao", "função",
            "id empregado", "id. empregado", "codigo", "código"
        }
        for idx, row in df_temp.iterrows():
            row_values = {normalize_text(v) for v in row.values if pd.notna(v)}
            if row_values & expected_headers:
                header_row = idx
                break

        df = pd.read_excel(io.BytesIO(content), sheet_name=target_sheet, header=header_row)
        df.columns = df.columns.astype(str).str.strip()

        # Se as colunas parecem genéricas (Unnamed ou 0,1,2), tentar achar linha de cabeçalho
        col_names_str = [str(c).lower() for c in df.columns]
        if all(c in ("unnamed: 0", "0", "1", "2", "unnamed") or c.startswith("unnamed") or c.isdigit() for c in col_names_str):
            df_temp2 = pd.read_excel(io.BytesIO(content), sheet_name=target_sheet, header=None, nrows=15)
            for idx in range(min(10, len(df_temp2))):
                row_strs = [normalize_text(str(v)) for v in df_temp2.iloc[idx].values]
                if any("matricula" in r or "matrícula" in r or "empregado" in r or "nome completo" in r or "colaborador" in r for r in row_strs):
                    df = pd.read_excel(io.BytesIO(content), sheet_name=target_sheet, header=idx)
                    df.columns = df.columns.astype(str).str.strip()
                    break

        col_registration = pick_column(
            df.columns,
            "Matrícula", "Matricula", "Registration", "Registration ID",
            "Registro", "Registro ID", "ID", "ID Empregado", "ID. Empregado",
            "Código", "Codigo", "Código do Funcionário", "Codigo do Funcionario",
            "Nº Funcionário", "Nº Funcionario", "Numero Funcionario"
        )
        if not col_registration:
            col_registration = pick_column_contains(
                df.columns, "empregado", "matricula", "matrícula", "codigo", "código", "registro", "id"
            )
        col_name = pick_column(df.columns, "Colaborador", "Nome Funcionário", "Nome Funcionario", "Nome")
        col_role = pick_column(df.columns, "Cargo", "Nome Cargo", "Função", "Funcao")
        col_cost_center = pick_column(df.columns, "Centro de Custo")
        col_shift = pick_column(df.columns, "Turno")
        col_admission = pick_column(df.columns, "Data Admissão", "Admissão", "Admissao", "Adminissão", "Adminissao")
        col_birthday = pick_column(df.columns, "Data Nascimento", "Nascimento", "Data de Nascimento")

        if not col_registration:
            # Fallback adicional: usar primeira coluna que pareça ser matrícula (alto % numérico)
            for c in df.columns:
                sample = df[c].dropna().astype(str).head(50).tolist()
                if not sample:
                    continue
                numeric_like = 0
                for v in sample:
                    compact = "".join(ch for ch in v if ch.isdigit())
                    if compact and len(compact) >= 3:
                        numeric_like += 1
                if numeric_like >= max(3, int(len(sample) * 0.6)):
                    col_registration = c
                    break
        if not col_registration:
            # Último recurso: qualquer coluna com pelo menos 2 valores numéricos (ex.: IDs)
            for c in df.columns:
                sample = df[c].dropna().astype(str).head(100).tolist()
                numeric_like = sum(1 for v in sample if len("".join(ch for ch in v if ch.isdigit())) >= 2)
                if numeric_like >= max(2, int(len(sample) * 0.3)):
                    col_registration = c
                    break

        if not col_registration:
            raise ValueError(
                "Coluna de matrícula não encontrada no arquivo. "
                f"Colunas detectadas: {', '.join([str(c) for c in df.columns])}"
            )

        count = 0 
        seen_registration = set()
        for _, row in df.iterrows():
            # Validation
            reg_id = str(row.get(col_registration, "")).strip()
            if not reg_id or reg_id.lower() == "nan" or reg_id.strip() == "":
                continue
            if reg_id in seen_registration:
                continue
            seen_registration.add(reg_id)

            # Check exist
            existing = session.exec(select(models.Employee).where(models.Employee.registration_id == reg_id)).first()
            if not existing:
                # Parse Dates
                admission = None
                if col_admission and pd.notna(row.get(col_admission)):
                    try:
                        admission = pd.to_datetime(row[col_admission], errors="coerce", dayfirst=True)
                        if pd.isna(admission):
                            admission = None
                        else:
                            admission = admission.to_pydatetime()
                    except:
                        pass
                        
                bday = None
                if col_birthday and pd.notna(row.get(col_birthday)):
                    try:
                        bday = pd.to_datetime(row[col_birthday], errors="coerce", dayfirst=True)
                        if pd.isna(bday):
                            bday = None
                        else:
                            bday = bday.to_pydatetime()
                    except:
                        pass
                        
                # Shift
                shift_raw = str(row.get(col_shift, "Manhã")) if col_shift else "Manhã"
                if pd.isna(shift_raw) or shift_raw.strip() == "" or shift_raw.lower() == "nan":
                    shift_raw = "Manhã"
                    
                # Normalize specific cases to match System options (Manhã, Tarde, Noite)
                shift_clean = shift_raw.strip().title() # Converts NOITE -> Noite
                
                if "Manha" in shift_clean or "Manhã" in shift_clean:
                    shift_val = "Manhã"
                elif "Tarde" in shift_clean:
                    shift_val = "Tarde"
                elif "Noite" in shift_clean:
                    shift_val = "Noite"
                else:
                    shift_val = shift_clean # Fallback (e.g. ADM)

                # Auto-assign Schedule
                default_schedule = None
                s_lower = (shift_val or "").lower()
                if "manhã" in s_lower or "manha" in s_lower:
                    default_schedule = "05:00 - 13:20"
                elif "tarde" in s_lower:
                    default_schedule = "12:00 - 20:20"
                elif "noite" in s_lower:
                    default_schedule = "18:00 - 06:00"

                name_raw = (str(row.get(col_name, "Sem Nome")).strip() if col_name else "Sem Nome") or "Sem Nome"
                emp = models.Employee(
                    name=name_raw.upper(),
                    registration_id=reg_id.strip(),
                    role=(str(row.get(col_role, "Operador")).strip() or "Operador").upper(),
                    work_shift=str(shift_val).strip(),
                    cost_center=str(row.get(col_cost_center, target_sheet)).strip() if col_cost_center else str(target_sheet),
                    admission_date=admission,
                    birthday=bday,
                    work_schedule=default_schedule,
                    status="active"
                )
                session.add(emp)
                count += 1
                
        session.commit()
    except Exception as e:
        print(f"Import Error: {e}")
        return RedirectResponse(url=f"/employees?error=Erro na importação: {str(e)}", status_code=status.HTTP_303_SEE_OTHER)
        
    return RedirectResponse(url=f"/employees?success={count} colaboradores importados com sucesso.", status_code=status.HTTP_303_SEE_OTHER)
@app.exception_handler(HTTPException)
async def auth_exception_handler(request: Request, exc: HTTPException):
    if exc.status_code == status.HTTP_307_TEMPORARY_REDIRECT or exc.status_code == status.HTTP_303_SEE_OTHER:
        return RedirectResponse(url="/login", status_code=status.HTTP_303_SEE_OTHER)
    # For other HTTP exceptions, let them propagate or return JSON?
    # Default behavior: return JSON or HTML error page.
    # We should let FastAPI handle others, but since we are overriding the handler...
    return JSONResponse(
        status_code=exc.status_code,
        content={"detail": exc.detail},
    )

# --- People Intelligence Helper ---
def get_people_intelligence_metrics(session: Session, cost_center: Optional[str], start_date: Optional[str], end_date: Optional[str], status_filter: Optional[List[str]] = None):
    # 1. Overview Data
    # Se status_filter não for fornecido, usa comportamento padrão (excluindo demitidos)
    if status_filter and len(status_filter) > 0:
        # Filtro personalizado de status
        employees = session.exec(
            select(models.Employee)
            .where(col(models.Employee.status).in_(status_filter))
            .where(models.Employee.replaced_by.is_(None))
        ).all()
    else:
        # Comportamento padrão: excluir demitidos
        employees = session.exec(
            select(models.Employee)
            .where(models.Employee.status != "fired")
            .where(models.Employee.replaced_by.is_(None))
        ).all()

    # Cost center options (empresa) - antes do filtro
    cost_center_options = ["Todos"]
    cost_center_options.extend(sorted({
        cost_center_display_label(e.cost_center)
        for e in employees
        if cost_center_display_label(e.cost_center) and cost_center_display_label(e.cost_center) != "Sem Centro"
    }))
    if any(cost_center_display_label(e.cost_center) == "Sem Centro" for e in employees):
        cost_center_options.append("Sem Centro")

    # Filter by Empresa (cost_center)
    selected_cc = parse_cost_center_filter(cost_center)
    if selected_cc:
        employees = [e for e in employees if employee_matches_cost_center(e, selected_cc)]
    
    total_headcount = len(employees)
    employee_ids = {e.id for e in employees}
    
    # Fetch Events with Filters
    today = datetime.now()
    
    # Date range filter (flexible: can be month, year,  or custom range)
    end_exclusive_events: datetime
    if start_date and end_date:
        try:
            d_start = date.fromisoformat(str(start_date)[:10])
            d_end = date.fromisoformat(str(end_date)[:10])
            start_dt = datetime.combine(d_start, time.min)
            end_dt = datetime.combine(d_end, time.min)
            # Incluir o dia final inteiro nos timestamps (end_date às 23:59:59)
            end_exclusive_events = datetime.combine(d_end, time.min) + timedelta(days=1)
        except Exception:
            # Fallback to current month
            start_dt = datetime(today.year, today.month, 1)
            if today.month == 12:
                end_dt = datetime(today.year + 1, 1, 1)
            else:
                end_dt = datetime(today.year, today.month + 1, 1)
            end_exclusive_events = end_dt
    else:
        # Default: Current Year to Date
        start_dt = datetime(today.year, 1, 1)
        end_dt = today
        end_exclusive_events = end_dt + timedelta(days=1)

    events = session.exec(
        select(models.Event)
        .where(models.Event.timestamp >= start_dt)
        .where(models.Event.timestamp < end_exclusive_events)
        .where(col(models.Event.type).in_(['falta', 'atestado', 'advertencia', 'afastamento']))
    ).all()
    
    # Filter events by employee_ids (shift filter) for context if needed, 
    # BUT for Metrics (KPIs) we will use EmployeeRoutine table to count DAYS lost.
    # This is more accurate for "Taxa de Absenteísmo" (Man-Days).
    
    # Fetch Routines for the period
    routines = session.exec(
        select(models.EmployeeRoutine)
        .where(models.EmployeeRoutine.date >= start_dt.strftime("%Y-%m-%d"))
        .where(models.EmployeeRoutine.date <= end_dt.strftime("%Y-%m-%d"))
    ).all()
    
    # Filter routines for selected shift employees
    routines = [r for r in routines if r.employee_id in employee_ids]
    
    # Agrupar por dia único (employee_id + date) para evitar contagem duplicada
    # Cada dia pode ter até 3 registros (Manhã, Tarde, Noite)
    unique_days = {}  # (emp_id, date) -> routine_type (prioridade: absent > sick > away)
    for r in routines:
        key = (r.employee_id, str(r.date))
        r_type = r.routine
        # Normalizar tipos
        if r_type in ['absent', 'falta']:
            normalized = 'falta'
        elif r_type in ['sick', 'atestado']:
            normalized = 'atestado'
        elif r_type in ['away', 'afastado']:
            normalized = 'afastamento'
        else:
            continue  # Ignorar outros tipos (present, vacation, etc.)
        
        # Se já existe um registro para esse dia, manter o de maior prioridade
        if key not in unique_days:
            unique_days[key] = normalized
        else:
            # Prioridade: falta > atestado > afastamento
            priority = {'falta': 3, 'atestado': 2, 'afastamento': 1}
            if priority.get(normalized, 0) > priority.get(unique_days[key], 0):
                unique_days[key] = normalized

    # Eventos (ex.: importação em massa) podem existir sem EmployeeRoutine; o resumo da ficha
    # já considera isso — aqui alinhamos People Intelligence ao mesmo critério.
    period_lo = start_dt.strftime("%Y-%m-%d")
    period_hi = end_dt.strftime("%Y-%m-%d")
    tz_sp = ZoneInfo("America/Sao_Paulo")

    def _event_day_key(ev: models.Event) -> Optional[str]:
        ts = getattr(ev, "timestamp", None)
        if not ts:
            return None
        try:
            if getattr(ts, "tzinfo", None):
                ts = ts.astimezone(tz_sp)
            return ts.strftime("%Y-%m-%d")
        except Exception:
            try:
                return ts.strftime("%Y-%m-%d")
            except Exception:
                return None

    filtered_for_abs = [e for e in events if e.employee_id in employee_ids]
    for e in filtered_for_abs:
        et = (e.type or "").lower().strip()
        if et not in ("falta", "atestado", "afastamento"):
            continue
        empid = e.employee_id
        if not empid:
            continue
        day_key = _event_day_key(e)
        if not day_key or day_key < period_lo or day_key > period_hi:
            continue
        rkey = (empid, day_key)
        if rkey in unique_days:
            continue
        if et == "falta":
            unique_days[rkey] = "falta"
        elif et == "atestado":
            unique_days[rkey] = "atestado"
        else:
            unique_days[rkey] = "afastamento"

    # Contadores gerais (Dias ÚNICOS)
    total_absences = sum(1 for v in unique_days.values() if v == 'falta')
    total_sick = sum(1 for v in unique_days.values() if v == 'atestado')
    total_away = sum(1 for v in unique_days.values() if v == 'afastamento')
    
    # 2. Rankings (Top Offenders - by UNIQUE DAYS)
    emp_stats = {}
    
    # Initial population from employees list (to blank fill)
    for emp in employees:
         emp_stats[emp.id] = {'falta': 0, 'atestado': 0, 'advertencia': 0, 'afastamento': 0, 'name': emp.name, 'sector': emp.cost_center or "Geral", 'tenure_months': 0}
         if emp.admission_date:
                delta = datetime.now() - emp.admission_date
                emp_stats[emp.id]['tenure_months'] = int(delta.days / 30)

    # Count unique days per employee
    for (emp_id, day), routine_type in unique_days.items():
        if emp_id not in emp_stats:
            continue
        emp_stats[emp_id][routine_type] += 1
            
    # Include Events only for "Advertencia" (which is an event, not a routine status)
    filtered_events = [e for e in events if e.employee_id in employee_ids]
    for e in filtered_events:
        if e.type == 'advertencia':
             if e.employee_id in emp_stats:
                  emp_stats[e.employee_id]['advertencia'] += 1
    
    # Flatten to ranking list
    ranking_data = []
    for eid, stats in emp_stats.items():
        stats['employee_id'] = eid
        # Only add if they have something relevant? Or keep all for denominator?
        # Only add if > 0 events/days?
        # For Top lists we sort.
        ranking_data.append(stats)
            
    # Sorts - Only show employees with actual data
    top_absent = sorted([r for r in ranking_data if r['falta'] > 0], key=lambda x: x['falta'], reverse=True)
    top_sick = sorted([r for r in ranking_data if r['atestado'] > 0], key=lambda x: x['atestado'], reverse=True)
    top_away = sorted([r for r in ranking_data if r['afastamento'] > 0], key=lambda x: x['afastamento'], reverse=True)
    
    # Define Map for later use
    emp_map = {e.id: e for e in employees}

    # 3. Sector Analysis
    sector_stats = {}
    for item in ranking_data:
        sec = item['sector']
        if sec not in sector_stats:
            sector_stats[sec] = {'falta': 0, 'atestado': 0, 'headcount': 0}
        sector_stats[sec]['falta'] += item['falta']
        sector_stats[sec]['atestado'] += item['atestado']
        
    # Calc Headcount per sector for Rate
    for emp in employees:
        sec = emp.cost_center or "Geral"
        if sec not in sector_stats:
             sector_stats[sec] = {'falta': 0, 'atestado': 0, 'headcount': 0}
        sector_stats[sec]['headcount'] += 1
        
    sector_list = []
    for sec, stats in sector_stats.items():
        if stats['headcount'] > 0:
            stats['name'] = sec
            # Risk Index = Days Lost / Headcount
            stats['risk_index'] = round((stats['falta'] + stats['atestado']) / stats['headcount'], 2)
            sector_list.append(stats)
            
    sector_list.sort(key=lambda x: x['risk_index'], reverse=True)
    
    # 4. Calculate PRESENCE (Accurate Method: Sum of Expected Days)
    days_in_period = (end_dt - start_dt).days
    
    total_expected_work_days_global = 0
    emp_expected_days_map = {}
    
    for emp in employees:
        calc_start = start_dt
        if emp.admission_date:
            try:
                if emp.admission_date.replace(tzinfo=None) > start_dt.replace(tzinfo=None):
                    calc_start = emp.admission_date.replace(tzinfo=None)
            except:
                pass
        
        ex_days = calculate_expected_work_days(
            emp.work_days or '[]',
            calc_start,
            end_dt,
            vacation_start=emp.vacation_start,
            vacation_end=emp.vacation_end
        )
        emp_expected_days_map[emp.id] = ex_days
        total_expected_work_days_global += ex_days
        
    theoretical_attendance = total_expected_work_days_global if total_expected_work_days_global > 0 else 1
    total_events = total_absences + total_sick
    presence_rate = round((1 - (total_events / theoretical_attendance)) * 100, 1) if theoretical_attendance > 0 else 100
    
    # 5. Chronic Offenders (High Operational Risk)
    # Employees with high combined falta + atestado that disrupt operations
    chronic_offenders = []
    for item in ranking_data:
        combined_events = item['falta'] + item['atestado']
        if combined_events >= 3:  # Threshold: 3+ events in period
            item['combined_events'] = combined_events
            item['risk_score'] = round((combined_events / days_in_period) * 100, 1) if days_in_period > 0 else 0
            
            # Use pre-calculated expected days
            emp = emp_map.get(item['employee_id'])
            if emp:
                item['expected_work_days'] = emp_expected_days_map.get(item['employee_id'], 0)
                item['actual_work_days'] = max(0, item['expected_work_days'] - combined_events)
                item['utilization_rate'] = round(
                    (item['actual_work_days'] / item['expected_work_days']) * 100, 1
                ) if item['expected_work_days'] > 0 else 0
            else:
                # Fallback if employee not found
                item['expected_work_days'] = 0
                item['actual_work_days'] = 0
                item['utilization_rate'] = 0
            
            chronic_offenders.append(item)
    
    # Sort by combined events
    chronic_offenders.sort(key=lambda x: x['combined_events'], reverse=True)
    
    return {
        "overview": {
            "headcount": total_headcount,
            "total_absences": total_absences,
            "total_sick": total_sick,
            "total_away": total_away,
            "avg_absence_per_emp": round(total_absences / total_headcount, 2) if total_headcount > 0 else 0,
            "presence_rate": presence_rate,
            "chronic_count": len(chronic_offenders)
        },
        "top_absent": top_absent,
        "top_sick": top_sick,
        "top_away": top_away,
        "sectors": sector_list,
        "chronic_offenders": chronic_offenders,
        "emp_map": emp_map,
        "start_date": start_dt.strftime("%Y-%m-%d"),
        "end_date": end_dt.strftime("%Y-%m-%d"),
        "cost_center_options": cost_center_options,
    }

# --- People Intelligence Route ---
@app.get("/people-intelligence", response_class=HTMLResponse)
async def people_intelligence_page(
    request: Request,
    cost_center: Optional[str] = "Todos",
    start_date: Optional[str] = None,
    end_date: Optional[str] = None,
    q: Optional[str] = None,
    status_view: str = Query(default="all"),
    event_type: str = Query(default="all"),
    sort: str = Query(default="risk"),
    dir: str = Query(default="desc"),
    page: int = 1,
    per_page: int = 50,
    session: Session = Depends(get_session)
):
    user = require_login(request)
    data = get_people_intelligence_metrics(session, cost_center, start_date, end_date)

    search_term = (q or "").strip().lower()
    status_view = (status_view or "all").strip().lower()
    event_type = (event_type or "all").strip().lower()
    sort_key = (sort or "risk").strip().lower()
    sort_dir = (dir or "desc").strip().lower()
    page = max(1, int(page or 1))
    per_page = min(max(25, int(per_page or 50)), 200)

    if status_view not in {"all", "critical", "attention", "stable"}:
        status_view = "all"
    if event_type not in {"all", "falta", "atestado", "afastamento"}:
        event_type = "all"
    if sort_key not in {"risk", "combined", "name", "sector", "presence"}:
        sort_key = "risk"
    if sort_dir not in {"asc", "desc"}:
        sort_dir = "desc" if sort_key in {"risk", "combined"} else "asc"

    def _status_from_risk(combined: int, risk_score: float) -> tuple:
        if risk_score >= 10 or combined >= 8:
            return "critical", "Crítico", "critical"
        if risk_score >= 5 or combined >= 4:
            return "attention", "Atenção", "alert"
        return "stable", "Estável", "ok"

    rows_by_id: dict = {}
    for item in data.get("chronic_offenders") or []:
        falta = int(item.get("falta", 0) or 0)
        atestado = int(item.get("atestado", 0) or 0)
        afastamento = int(item.get("afastamento", 0) or 0)
        combined = int(item.get("combined_events", falta + atestado + afastamento) or 0)
        risk_score = float(item.get("risk_score", 0) or 0)
        utilization_rate = float(item.get("utilization_rate", 0) or 0)
        presence_rate = max(0.0, min(100.0, utilization_rate))
        sk, sl, st = _status_from_risk(combined, risk_score)
        eid = item.get("employee_id")
        if not eid:
            continue
        rows_by_id[eid] = {
            "employee_id": eid,
            "name": (item.get("name") or "-").strip() or "-",
            "sector": (item.get("sector") or "Não informado").strip() or "Não informado",
            "falta": falta,
            "atestado": atestado,
            "afastamento": afastamento,
            "combined_events": combined,
            "risk_score": round(risk_score, 1),
            "presence_rate": round(presence_rate, 1),
            "utilization_rate": round(utilization_rate, 1),
            "tenure_months": int(item.get("tenure_months", 0) or 0),
            "status_key": sk,
            "status_label": sl,
            "status_tone": st,
        }

    # Crônicos usam limiar 3+ dias (falta+atestado). Incluir também quem tem 1–2 dias
    # (ex.: importação pontual), senão a lista fica só nos “piores” quando há algum crônico.
    merged_tops: dict = {}
    for bucket, key in ((data.get("top_absent", []), "falta"), (data.get("top_sick", []), "atestado"), (data.get("top_away", []), "afastamento")):
        for item in bucket:
            eid = item.get("employee_id")
            if not eid or eid in rows_by_id:
                continue
            row = merged_tops.setdefault(eid, {
                "employee_id": eid,
                "name": (item.get("name") or "-").strip() or "-",
                "sector": (item.get("sector") or "Não informado").strip() or "Não informado",
                "falta": 0,
                "atestado": 0,
                "afastamento": 0,
                "tenure_months": int(item.get("tenure_months", 0) or 0),
            })
            row[key] = max(int(row.get(key, 0) or 0), int(item.get(key, 0) or 0))

    for row in merged_tops.values():
        row["combined_events"] = int(row["falta"] + row["atestado"] + row["afastamento"])
        row["risk_score"] = round(row["combined_events"] * 1.2, 1)
        row["presence_rate"] = max(0.0, round(100.0 - (row["combined_events"] * 2.5), 1))
        row["utilization_rate"] = row["presence_rate"]
        sk, sl, st = _status_from_risk(row["combined_events"], row["risk_score"])
        row["status_key"], row["status_label"], row["status_tone"] = sk, sl, st
        rows_by_id[row["employee_id"]] = row

    rows = list(rows_by_id.values())

    def _matches(row: dict) -> bool:
        if status_view != "all" and row["status_key"] != status_view:
            return False
        if event_type != "all" and int(row.get(event_type, 0) or 0) <= 0:
            return False
        if search_term:
            blob = f"{row.get('name', '')} {row.get('sector', '')}".lower()
            if search_term not in blob:
                return False
        return True

    filtered_rows = [row for row in rows if _matches(row)]

    sort_map = {
        "risk": lambda x: float(x.get("risk_score", 0)),
        "combined": lambda x: int(x.get("combined_events", 0)),
        "name": lambda x: (x.get("name", "") or "").lower(),
        "sector": lambda x: (x.get("sector", "") or "").lower(),
        "presence": lambda x: float(x.get("presence_rate", 0)),
    }
    filtered_rows.sort(key=sort_map.get(sort_key, sort_map["risk"]), reverse=(sort_dir == "desc"))

    total_count = len(filtered_rows)
    total_pages = max(1, math.ceil(total_count / per_page)) if total_count else 1
    if page > total_pages:
        page = total_pages
    offset = max(0, (page - 1) * per_page)
    paged_rows = filtered_rows[offset: offset + per_page]

    def _href(**overrides):
        params = {
            "cost_center": cost_center or "Todos",
            "start_date": data["start_date"],
            "end_date": data["end_date"],
            "q": q or "",
            "status_view": status_view if status_view != "all" else "",
            "event_type": event_type if event_type != "all" else "",
            "sort": sort_key,
            "dir": sort_dir,
            "page": page,
            "per_page": per_page,
        }
        for k, v in overrides.items():
            params[k] = v
        clean = {k: v for k, v in params.items() if v not in (None, "", [])}
        return "/people-intelligence" + ("?" + urlencode(clean) if clean else "")

    sort_links = {}
    for key in ["risk", "combined", "name", "sector", "presence"]:
        default_dir = "desc" if key in {"risk", "combined"} else "asc"
        next_dir = ("asc" if sort_dir == "desc" else "desc") if sort_key == key else default_dir
        sort_links[key] = _href(sort=key, dir=next_dir, page=1)

    critical_count = sum(1 for r in filtered_rows if r["status_key"] == "critical")
    attention_count = sum(1 for r in filtered_rows if r["status_key"] == "attention")
    stable_count = sum(1 for r in filtered_rows if r["status_key"] == "stable")
    avg_presence = round(sum(float(r.get("presence_rate", 0) or 0) for r in filtered_rows) / max(1, len(filtered_rows)), 1)

    return templates.TemplateResponse("people_intelligence.html", {
        "request": request,
        "user": user,
        "current_cost_center": cost_center or "Todos",
        "cost_center_options": data.get("cost_center_options", ["Todos"]),
        "start_date": data["start_date"],
        "end_date": data["end_date"],
        "overview": data["overview"],
        "top_absent": data["top_absent"][:10],
        "top_sick": data["top_sick"][:10],
        "sectors": data["sectors"],
        "chronic_offenders": data["chronic_offenders"][:10],
        "emp_map": data["emp_map"],
        "all_absent": data["top_absent"],
        "all_sick": data["top_sick"],
        "all_away": data["top_away"],
        "rows": paged_rows,
        "rows_full": filtered_rows[:500],
        "filters": {
            "q": q or "",
            "status_view": status_view,
            "event_type": event_type,
            "sort": sort_key,
            "dir": sort_dir,
            "page": page,
            "per_page": per_page,
        },
        "links": {
            "all": _href(status_view="", page=1),
            "critical": _href(status_view="critical", page=1),
            "attention": _href(status_view="attention", page=1),
            "stable": _href(status_view="stable", page=1),
            "clear": "/people-intelligence",
            "report": "/people-intelligence/report?" + urlencode({
                "cost_center": cost_center or "Todos",
                "start_date": data["start_date"],
                "end_date": data["end_date"],
            }),
            "prev": _href(page=(page - 1 if page > 1 else 1)),
            "next": _href(page=(page + 1 if page < total_pages else total_pages)),
        },
        "sort_links": sort_links,
        "pagination": {
            "page": page,
            "per_page": per_page,
            "total_count": total_count,
            "total_pages": total_pages,
            "has_prev": page > 1,
            "has_next": page < total_pages,
            "page_start": (offset + 1) if total_count else 0,
            "page_end": offset + len(paged_rows),
        },
        "kpis": {
            "total_monitorados": len(filtered_rows),
            "critical_count": critical_count,
            "attention_count": attention_count,
            "stable_count": stable_count,
            "avg_presence": avg_presence,
        },
        "message": request.query_params.get("message"),
        "level": request.query_params.get("level"),
    })

