@app.post("/api/vacation-planning/import-workbook")
async def api_vacation_planning_import_workbook(
    request: Request,
    file: UploadFile = File(...),
    interpretation: str = Form("acquisition_end"),
    update_admission: str = Form("true"),
    session: Session = Depends(get_session),
):
    """
    Importa planilha de férias (Excel).

    Dois formatos são detectados automaticamente:

    - Controle de vencimento: COLABORADOR, FUNÇÃO e colunas de período com datas.
      Atualiza ``EmployeeVacationProfile.acquisition_period_end`` e, opcionalmente,
      ``Employee.admission_date``.

    - Programação de gozo: COLABORADOR com colunas de início e fim das férias
      (ex.: «Férias Início» / «Férias Fim»). Cria entradas aprovadas em
      ``VacationScheduleEntry`` para o planejamento.
    """
    user = require_leader(request)
    raw = await file.read()
    if len(raw) > 8 * 1024 * 1024:
        raise HTTPException(status_code=400, detail="Arquivo acima de 8 MB.")
    if not raw:
        raise HTTPException(status_code=400, detail="Arquivo vazio.")

    inter = (interpretation or "acquisition_end").strip().lower()
    if inter not in ("acquisition_end", "concessive_deadline"):
        inter = "acquisition_end"
    ua = str(update_admission).lower() in ("1", "true", "yes", "on")

    fn = file.filename or "planilha.xls"
    uid = user.get("id") if isinstance(user, dict) else None
    try:
        result = import_vacation_workbook(
            session,
            file_bytes=raw,
            filename=fn,
            interpretation=inter,
            update_admission=ua,
            approved_by_user_id=uid if isinstance(uid, int) else None,
        )
    except Exception as exc:
        raise HTTPException(status_code=400, detail=f"Falha ao ler planilha: {exc}") from exc

    if not result.get("ok"):
        raise HTTPException(status_code=400, detail=result.get("error") or "Importação inválida.")
    return JSONResponse(content=jsonable_encoder(result))


@app.get("/smart-flow/load", response_class=JSONResponse, dependencies=[Depends(require_leader)])
async def smart_flow_load(request: Request, shift: str = "Manhã", date: Optional[str] = None, session: Session = Depends(get_session)):
    try:
        now_br = datetime.now(ZoneInfo("America/Sao_Paulo"))
        if not date:
            date = get_effective_shift_date(shift, now_br).strftime("%Y-%m-%d")
        else:
            date = normalize_shift_date(date, shift, now_br)

        # Get Sector Config
        sector_config_db = session.exec(select(models.SectorConfiguration).where(models.SectorConfiguration.shift_name == shift)).first()
        sector_config = {}
        if sector_config_db and sector_config_db.config_json:
            sector_config = sector_config_db.config_json
            if isinstance(sector_config, str):
                try:
                    sector_config = json.loads(sector_config)
                except:
                    sector_config = {}
        
        # Default sectors if empty
        if not sector_config or not isinstance(sector_config, dict) or "sectors" not in sector_config:
            sector_config = {
                "sectors": [
                    { "key": "recebimento", "label": "Recebimento", "target": 0, "subsectors": ["Doca 1", "Doca 2", "Paletização"] },
                    { "key": "camara_fria", "label": "Câmara Fria", "target": 0, "subsectors": ["Armazenagem", "Abastecimento"] },
                    { "key": "selecao", "label": "Seleção", "target": 0, "subsectors": ["Linha 1", "Linha 2"] },
                    { "key": "expedicao", "label": "Expedição", "target": 0, "subsectors": ["Separação", "Carregamento"] }
                ]
            }

        # Get Operation
        daily_op = session.exec(
            select(models.DailyOperation)
            .where(models.DailyOperation.date == date)
            .where(models.DailyOperation.shift == shift)
        ).first()

        employees_log = {}
        manual_tonnage = 0
        
        if daily_op:
            employees_log = daily_op.attendance_log or {}
            manual_tonnage = daily_op.tonnage or 0

        return {
            "employees_log": employees_log,
            "sector_config": sector_config.get("sectors", []),
            "manual_tonnage": manual_tonnage
        }
    except Exception as e:
        logger.error(f"Error in smart_flow_load: {e}")
        return JSONResponse(content={"error": str(e)}, status_code=500)


