@app.get("/api/gm/locations-realtime", response_class=JSONResponse)
async def api_gm_locations_realtime(request: Request, session: Session = Depends(get_session)):
    """Última posição por motorista: pings recentes + fallback da rota (GPS ao iniciar parada)."""
    require_gerente(request)
    try:
        tz = ZoneInfo("America/Sao_Paulo")
        now_sp = datetime.now(tz)
        today_str = now_sp.strftime("%Y-%m-%d")
        cutoff = (now_sp - timedelta(hours=72)).replace(tzinfo=None)

        stmt = (
            select(models.VehicleLocation)
            .where(models.VehicleLocation.timestamp >= cutoff)
            .order_by(models.VehicleLocation.employee_id, desc(models.VehicleLocation.id))
        )
        rows = list(session.exec(stmt).all())
        latest_by_emp: Dict[int, models.VehicleLocation] = {}
        for loc in rows:
            if loc.employee_id not in latest_by_emp:
                latest_by_emp[loc.employee_id] = loc

        out_map: Dict[int, Dict[str, Any]] = {}
        for eid, loc in latest_by_emp.items():
            out_map[eid] = {
                "employee_id": eid,
                "driver_name": "",
                "plate": (loc.plate or "").strip().upper() or "—",
                "lat": loc.latitude,
                "lng": loc.longitude,
                "timestamp": loc.timestamp.isoformat() if loc.timestamp else None,
                "position_source": "ping",
            }

        # Rotas com parada em andamento hoje: o app já grava driver_lat_start ao tocar "Iniciar" (sem depender do ping).
        route_rows = list(
            session.exec(
                select(models.Route)
                .where(models.Route.type == "delivery")
                .where(models.Route.date == today_str)
                .where(models.Route.delivery_status.in_(["iniciada", "reaberta"]))
                .order_by(desc(models.Route.id))
            ).all()
        )
        route_by_emp: Dict[int, models.Route] = {}
        for r in route_rows:
            if r.employee_id not in route_by_emp:
                route_by_emp[r.employee_id] = r

        for eid, route in route_by_emp.items():
            if eid in out_map:
                continue
            lat = route.driver_lat_start
            lng = route.driver_lon_start
            if lat is None or lng is None:
                continue
            plate = (route.delivery_vehicle_plate or "").strip().upper()
            if len(plate.replace(" ", "").replace("-", "")) < 7:
                ds = session.exec(
                    select(models.DeliverySession)
                    .where(models.DeliverySession.employee_id == eid)
                    .where(models.DeliverySession.date == today_str)
                    .where(models.DeliverySession.status == "open")
                ).first()
                if ds and (ds.vehicle_plate or "").strip():
                    plate = (ds.vehicle_plate or "").strip().upper()
            if not plate:
                plate = "—"
            out_map[eid] = {
                "employee_id": eid,
                "driver_name": "",
                "plate": plate,
                "lat": float(lat),
                "lng": float(lng),
                "timestamp": None,
                "position_source": "parada",
            }

        if not out_map:
            return []

        emp_ids = list(out_map.keys())
        employees = session.exec(select(models.Employee).where(models.Employee.id.in_(emp_ids))).all()
        name_by_id = {e.id: (e.name or "").strip() for e in employees if e.id is not None}
        for eid in out_map:
            out_map[eid]["driver_name"] = name_by_id.get(eid, "")

        return list(out_map.values())
    except Exception as e:
        logger.exception("api_gm_locations_realtime: %s", e)
        return []

@app.post("/api/mobile/location", response_class=JSONResponse)
async def api_mobile_post_location(request: Request, session: Session = Depends(get_session)):
    """Recebe a localização de um motorista vinda do App mobile."""
    try:
        user_id = request.session.get("user_id")
        if not user_id:
            return JSONResponse({"error": "Não autorizado"}, status_code=401)
        user_id = int(user_id)

        body = await request.json()
        employee_id = body.get("employee_id")
        plate = body.get("plate")
        lat = body.get("latitude")
        lng = body.get("longitude")
        
        if not all([employee_id, plate, lat, lng]):
            return JSONResponse({"error": "Dados incompletos"}, status_code=400)
        if int(employee_id) != user_id:
            return JSONResponse({"error": "Não autorizado"}, status_code=403)
            
        ts_sp = datetime.now(ZoneInfo("America/Sao_Paulo")).replace(tzinfo=None)
        loc = models.VehicleLocation(
            employee_id=int(employee_id),
            plate=str(plate).strip().upper(),
            latitude=float(lat),
            longitude=float(lng),
            timestamp=ts_sp,
        )
        session.add(loc)
        session.commit()
        return {"success": True}
    except Exception as e:
        logger.error(f"Erro ao salvar localização: {e}")
        return JSONResponse({"error": str(e)}, status_code=500)


@app.get("/api/operational/routes")
async def api_operational_routes(
    start_date: Optional[str] = None,
    end_date: Optional[str] = None,
    search: Optional[str] = None,
    sort_by: Optional[str] = 'date',
    status: Optional[str] = None,
    session: Session = Depends(get_session)
):
    try:
        query = select(models.Route, models.Employee.name, models.Client.name).join(models.Employee).join(models.Client)
        
        # Filtering
        if start_date:
            query = query.where(models.Route.date >= start_date)
        if end_date:
            query = query.where(models.Route.date <= end_date)
            
        if status:
            query = query.where(models.Route.status == status)
            
        if search:
            search_pattern = f"%{search}%"
            query = query.where(
                or_(
                    models.Employee.name.ilike(search_pattern),
                    models.Client.name.ilike(search_pattern),
                    models.Route.date.ilike(search_pattern)
                )
            )

        # Sorting
        # Simple Logic: Only Sort by Date desc by default
        query = query.order_by(desc(models.Route.date), desc(models.Route.id))
        
        results = session.exec(query).all()
        
        # Prepare Response
        now_br = datetime.now(ZoneInfo("America/Sao_Paulo"))

        data = []
        for r, emp_name, client_name in results:
            s_time = r.start_time
            e_time = r.end_time
            
            # Strategy: If time is in the future relative to NOW, assume it's UTC and subtract 3h.
            # Additional Context: If route is 'pending' or 'completed', it CANNOT be in the future.
            # NEW Context: If Start > End (and End exists), likely Start is UTC and End is Local.
            
            def clean_time_str(time_val):
                if time_val is None: return None
                time_str = ""
                # Handle datetime.time
                if isinstance(time_val, (time, type(datetime.now(ZoneInfo("America/Sao_Paulo")).time()))):
                    time_str = time_val.strftime("%H:%M:%S")
                else:
                    time_str = str(time_val).strip()
                
                try:
                    clean = time_str.split(".")[0]
                    parts = clean.split(":")
                    if len(parts) >= 2:
                        return f"{parts[0]}:{parts[1]}"
                    return clean
                except:
                    return time_str

            s_time = clean_time_str(s_time)
            e_time = clean_time_str(e_time)

            data.append({
                "id": r.id,
                "date": r.date,
                "employee_name": emp_name,
                "employee_id": r.employee_id,
                "client_name": client_name,
                "client_id": r.client_id,
                "start_time": s_time,
                "end_time": e_time,
                "tonnage": r.tonnage,
                "status": r.status
            })
            
            # Calculate Duration
            duration_str = "-"
            if s_time and e_time:
                try:
                    # Parse HH:MM (returned by heuristic)
                    s = datetime.strptime(s_time, "%H:%M")
                    e = datetime.strptime(e_time, "%H:%M")
                    diff = (e - s).total_seconds()
                    if diff < 0: diff += 86400 # Handle overnight if needed
                    
                    dh = int(diff // 3600)
                    dm = int((diff % 3600) // 60)
                    duration_str = f"{dh:02d}:{dm:02d}"
                except:
                    pass
            
            data[-1]["duration"] = duration_str
            
            # Est. XP (Approx 100 XP per 1500kg) com tolerância a tonnage nulo/inválido
            try:
                ton = float(r.tonnage or 0.0)
            except (TypeError, ValueError):
                ton = 0.0
            est_xp = int((max(0.0, ton) / 1500.0) * 100)
            data[-1]["est_xp"] = est_xp
            
        return {"routes": data}
        
    except Exception as e:
        logger.exception("Error fetching routes")
        return JSONResponse({"error": str(e)}, status_code=500)

class RouteUpdateModel(BaseModel):
    tonnage: Optional[float] = None
    start_time: Optional[str] = None
    end_time: Optional[str] = None
    status: Optional[str] = None

@app.put("/api/operational/routes/{route_id}")
async def api_update_route(
    route_id: int, 
    payload: RouteUpdateModel, 
    session: Session = Depends(get_session)
):
    try:
        route = session.get(models.Route, route_id)
        if not route:
            return JSONResponse({"error": "Rota não encontrada"}, status_code=404)
            
        if payload.tonnage is not None:
            route.tonnage = payload.tonnage
        if payload.start_time is not None:
            route.start_time = payload.start_time
        if payload.end_time is not None:
            route.end_time = payload.end_time
        if payload.status is not None:
            route.status = payload.status
            
        session.add(route)
        session.commit()
        
        # Recalculate Daily XP
        try:
            calculate_daily_xp(session, route.date)
        except Exception as e:
            logger.error(f"Error recalculating XP on update: {e}")
            
        return {"success": True}
    except Exception as e:
        logger.exception(f"Error updating route {route_id}")
        return JSONResponse({"error": str(e)}, status_code=500)

@app.delete("/api/operational/routes/{route_id}")
async def api_delete_route(route_id: int, session: Session = Depends(get_session)):
    try:
        route = session.get(models.Route, route_id)
        if not route:
            return JSONResponse({"error": "Rota não encontrada"}, status_code=404)
        
        target_date = route.date # Save date before delete
        session.delete(route)
        session.commit()
        
        # Recalculate Daily XP
        try:
            calculate_daily_xp(session, target_date)
        except Exception as e:
            logger.error(f"Error recalculating XP on delete: {e}")

        return {"success": True}
    except Exception as e:
        logger.exception(f"Error deleting route {route_id}")
        return JSONResponse({"error": str(e)}, status_code=500)

