@app.get("/mobile/admin/routes", response_class=HTMLResponse)
async def mobile_admin_routes_page(
    request: Request,
    session: Session = Depends(get_session)
):
    """Página de gestão de rotas para líderes"""
    user_id = request.session.get("user_id")
    if not user_id:
        return RedirectResponse(url="/mobile/login", status_code=303)
    
    try:
        user_id = int(str(user_id))
    except:
        return RedirectResponse(url="/mobile/login", status_code=303)
    
    employee = session.get(models.Employee, user_id)
    if not employee or not employee.mobile_access:
        return RedirectResponse(url="/mobile/login?error=access_revoked", status_code=303)
    
    if not getattr(employee, "mobile_access_admin_start", False):
        return RedirectResponse(url="/mobile/dashboard?error=no_permission", status_code=303)
    
    return templates.TemplateResponse(
        "mobile/admin_routes.html",
        {
            "request": request,
            "employee": employee
        }
    )


@app.get("/api/mobile/admin/routes")
async def api_list_admin_routes(
    request: Request,
    session: Session = Depends(get_session)
):
    """API para listar rotas ativas e colaboradores sem rota"""
    def _safe_s(v: Any) -> str:
        return str(v or "").strip()

    def _safe_l(v: Any) -> str:
        return _safe_s(v).lower()

    def _safe_i(v: Any) -> Optional[int]:
        try:
            if v is None:
                return None
            return int(str(v).strip())
        except Exception:
            return None

    def _json_safe(v: Any) -> Any:
        if isinstance(v, float):
            return v if math.isfinite(v) else 0.0
        if isinstance(v, list):
            return [_json_safe(x) for x in v]
        if isinstance(v, tuple):
            return [_json_safe(x) for x in v]
        if isinstance(v, dict):
            return {k: _json_safe(val) for k, val in v.items()}
        return v

    user_id = request.session.get("user_id")
    if not user_id:
        return JSONResponse({"error": "Não autorizado"}, status_code=401)
    
    try:
        user_id = int(str(user_id))
    except Exception:
        return JSONResponse({"error": "ID inválido"}, status_code=400)
    
    current_emp = session.get(models.Employee, user_id)
    if not current_emp or not getattr(current_emp, "mobile_access_admin_start", False):
        return JSONResponse({"error": "Sem permissão"}, status_code=403)
    
    today = datetime.now(ZoneInfo("America/Sao_Paulo")).strftime("%Y-%m-%d")
    
    try:
        # Todas as rotas de entrega do dia da operação
        all_routes_today_raw = session.exec(
            select(models.Route)
            .where(models.Route.type == "delivery")
            .where(models.Route.date == today)
            .order_by(models.Route.employee_id, models.Route.start_time, models.Route.id)
        ).all()
        
        # Filtro de segurança: garante estritamente YYYY-MM-DD do dia da operação,
        # mesmo se houver divergência de tipo/formato vindo do banco.
        all_routes_today = [
            r for r in all_routes_today_raw
            if str(getattr(r, "date", "") or "").strip()[:10] == today
        ]
        
        all_emp_ids_with_routes = list({r.employee_id for r in all_routes_today if r.employee_id})
        helper_ids_from_routes = set()
        for r in all_routes_today:
            helper_ids_from_routes.update(_parse_route_helper_ids(getattr(r, "delivery_helpers_json", None)))
        sessions_today = session.exec(
            select(models.DeliverySession).where(models.DeliverySession.date == today)
            .where(models.DeliverySession.employee_id.in_(all_emp_ids_with_routes))
        ).all() if all_emp_ids_with_routes else []
        helper_ids_from_sessions = set()
        for s in sessions_today:
            if getattr(s, "helpers_json", None):
                for h in _parse_session_helpers(s.helpers_json):
                    if h and str(h).strip().isdigit():
                        helper_ids_from_sessions.add(int(str(h).strip()))
        all_emp_ids_to_load = list(set(all_emp_ids_with_routes) | helper_ids_from_routes | helper_ids_from_sessions)
        employee_by_id_all = {e.id: e for e in session.exec(select(models.Employee).where(models.Employee.id.in_(all_emp_ids_to_load))).all() if e.id} if all_emp_ids_to_load else {}
        
        client_ids = list({r.client_id for r in all_routes_today if r.client_id is not None})
        clients = session.exec(select(models.Client).where(models.Client.id.in_(client_ids))).all() if client_ids else []
        client_by_id = {c.id: c for c in clients if c.id is not None}
        
        live_buckets = {}
        for emp_id in all_emp_ids_with_routes:
            emp = employee_by_id_all.get(emp_id)
            if not emp:
                continue
            live_buckets[emp_id] = {"employee_name": emp.name, "routes": []}
        
        for r in all_routes_today:
            st = _safe_l(getattr(r, "delivery_status", None))
            if st not in {"iniciada", "entregue", "devolucao", "pendente"}:
                continue
            bucket = live_buckets.get(r.employee_id)
            if not bucket:
                continue
            d_m = route_duration_minutes(r) or 0
            c = client_by_id.get(r.client_id)
            client_name = (getattr(c, "name", None) or getattr(c, "razao_social", None)) if c else f"Cliente #{r.client_id}"
            finished_at = (r.delivery_finished_at or r.end_time or "") if st in ("entregue", "devolucao") else None
            bucket["routes"].append({
                "client": client_name,
                "start_time": r.delivery_started_at or r.start_time or "--:--",
                "finished_at": finished_at,
                "duration_mins": d_m,
                "tonnage": float(r.tonnage or 0.0),
                "delivery_status": st,
            })
        
        session_closed_by_emp = {s.employee_id: _safe_l(getattr(s, "status", None)) == "closed" for s in sessions_today}
        session_open_by_emp = {s.employee_id for s in sessions_today if _safe_l(getattr(s, "status", None)) == "open"}
        session_plate_by_emp = {}
        for s in sessions_today:
            if s.employee_id and _safe_s(getattr(s, "vehicle_plate", None)):
                session_plate_by_emp.setdefault(s.employee_id, _safe_s(getattr(s, "vehicle_plate", None)))
        session_helpers_by_emp = {s.employee_id: _parse_session_helpers(s.helpers_json) for s in sessions_today if getattr(s, "helpers_json", None)}
        
        now_br = datetime.now(ZoneInfo("America/Sao_Paulo"))
        alerts_over_20min = []
        for r in all_routes_today:
            if _safe_l(getattr(r, "delivery_status", None)) != "iniciada":
                continue
            started_at_str = r.delivery_started_at or r.start_time
            if not started_at_str or _safe_s(started_at_str) in ("", "00:00"):
                continue
            try:
                parts = str(started_at_str).strip().split(":")
                h, m = int(parts[0]), int(parts[1]) if len(parts) > 1 else 0
                started_dt = datetime(now_br.year, now_br.month, now_br.day, h, m, 0, tzinfo=ZoneInfo("America/Sao_Paulo"))
                elapsed_mins = int((now_br - started_dt).total_seconds() // 60)
                if elapsed_mins < 20:
                    continue
                c = client_by_id.get(r.client_id)
                client_name = (getattr(c, "name", None) or getattr(c, "razao_social", None)) if c else f"Cliente #{r.client_id}"
                emp = employee_by_id_all.get(r.employee_id)
                alerts_over_20min.append({
                    "client_name": client_name,
                    "driver_name": emp.name if emp else f"Motorista #{r.employee_id}",
                    "driver_id": r.employee_id,
                    "minutes": elapsed_mins,
                    "start_time": started_at_str,
                })
            except Exception:
                continue
        alerts_over_20min.sort(key=lambda x: -x["minutes"])
        
        for emp_id, bucket in live_buckets.items():
            emp_routes = [r for r in all_routes_today if r.employee_id == emp_id]
            bucket["employee_id"] = emp_id
            operational_emp_routes = [
                r for r in emp_routes
                if _safe_l(getattr(r, "delivery_status", None)) in ("iniciada", "entregue", "devolucao", "pendente")
            ]
            # Mantém o contador coerente com os clientes exibidos no card.
            bucket["total_deliveries"] = len(operational_emp_routes)
            bucket["completed_deliveries"] = len([
                r for r in operational_emp_routes
                if _safe_l(getattr(r, "delivery_status", None)) in ("entregue", "devolucao")
            ])
            bucket["plate"] = next((_safe_s(getattr(r, "delivery_vehicle_plate", None)) or None for r in emp_routes if _safe_s(getattr(r, "delivery_vehicle_plate", None))), None) if emp_routes else None
            if not bucket["plate"] and session_plate_by_emp.get(emp_id):
                bucket["plate"] = session_plate_by_emp[emp_id]
            helper_ids = []
            for r in emp_routes:
                helper_ids.extend(_parse_route_helper_ids(getattr(r, "delivery_helpers_json", None)))
            session_helpers = session_helpers_by_emp.get(emp_id) or []
            for h in session_helpers:
                if h and str(h).strip().isdigit():
                    helper_ids.append(int(str(h).strip()))
            resolved = list(dict.fromkeys(
                (employee_by_id_all.get(hid).name if employee_by_id_all.get(hid) else None) or f"Ajud. #{hid}"
                for hid in helper_ids if hid
            ))
            session_names = [str(h).strip() for h in session_helpers if h and str(h).strip() and not str(h).strip().isdigit()]
            all_helper_names = resolved if resolved else session_names
            bucket["helper_count"] = len(all_helper_names)
            bucket["helper_names"] = all_helper_names[:3]
            bucket["total_kg"] = round(sum(float(r.tonnage or 0.0) for r in operational_emp_routes), 2)
            open_routes_count = len([r for r in bucket["routes"] if _safe_l(r.get("delivery_status")) == "iniciada"])
            bucket["open_routes_count"] = open_routes_count
            finished_times = [
                rt["finished_at"] for rt in bucket["routes"]
                if _safe_l(rt.get("delivery_status")) in ("entregue", "devolucao") and rt.get("finished_at")
            ]
            last_finished_at = max(finished_times, key=lambda t: (t or "00:00")) if finished_times else None
            minutes_without_open = 0
            if open_routes_count == 0 and last_finished_at:
                try:
                    parts = str(last_finished_at).strip().split(":")
                    h, m = int(parts[0]), int(parts[1]) if len(parts) > 1 else 0
                    finished_dt = datetime(now_br.year, now_br.month, now_br.day, h, m, 0, tzinfo=ZoneInfo("America/Sao_Paulo"))
                    minutes_without_open = max(0, int((now_br - finished_dt).total_seconds() // 60))
                except Exception:
                    pass
            bucket["minutes_without_open_client"] = minutes_without_open
            has_delivery_started = any(_safe_l(getattr(r, "delivery_status", None)) in ("iniciada", "entregue", "devolucao") for r in emp_routes)
            session_started = emp_id in session_open_by_emp
            has_started = has_delivery_started or session_started
            all_delivered = bucket["total_deliveries"] > 0 and bucket["completed_deliveries"] == bucket["total_deliveries"]
            route_ended = session_closed_by_emp.get(emp_id, False)
            alerts_for_driver = [a for a in (alerts_over_20min or []) if a.get("driver_id") == emp_id]
            has_over_20 = len(alerts_for_driver) > 0
            if route_ended:
                bucket["route_state"] = "closed"
            elif not has_started:
                bucket["route_state"] = "not_started"
            elif has_started and not has_delivery_started:
                bucket["route_state"] = "route_started"
            elif has_over_20:
                bucket["route_state"] = "over_20_min"
            elif all_delivered:
                # Só considerar "entregues/concluída" quando sessão realmente encerrada.
                # Se ainda não encerrou, mantém em andamento para evitar falso positivo.
                bucket["route_state"] = "in_progress"
            else:
                bucket["route_state"] = "in_progress"
            bucket.update(
                compute_delivery_projection(
                    bucket,
                    now_br,
                    operation_start_hour=DELIVERY_OPERATION_START_HOUR,
                    operation_end_hour=DELIVERY_OPERATION_END_HOUR,
                    baseline_crew_size=DELIVERY_BASE_CREW_SIZE,
                    attention_buffer_minutes=DELIVERY_ATTENTION_BUFFER_MINUTES,
                )
            )
        
        def _live_sort_key(x):
            state = x.get("route_state") or "in_progress"
            open_count = (x.get("total_deliveries") or 0) - (x.get("completed_deliveries") or 0)
            alert_level = str(x.get("route_alert_level") or "ok").strip().lower()
            alert_rank = 0 if alert_level == "critico" else 1 if alert_level == "atencao" else 2
            delay = int(x.get("projected_finish_delay_minutes") or 0)
            if state == "closed":
                return (4, 0, 0, 0)
            if state == "not_started":
                return (3, alert_rank, -delay, -open_count)
            if state == "all_delivered":
                return (3, 0, 0, -open_count)
            if state == "over_20_min":
                return (0, alert_rank, -delay, -open_count)  # prioridade: mostrar primeiro
            if state == "route_started":
                return (1, alert_rank, -delay, -open_count)
            return (1, alert_rank, -delay, -open_count)
        
        # Painel de operação mobile: mostrar todas as rotas do dia da operação.
        # (não filtrar apenas "iniciada", para não ocultar motoristas/rotas do dia)
        live_separation = list(live_buckets.values())
        live_separation.sort(key=_live_sort_key)
        
        rotas_paradas_count = sum(1 for b in live_separation if (b.get("route_state") or "") == "not_started")
        rotas_ativas_count = sum(
            1 for b in live_separation if (b.get("route_state") or "") in ("in_progress", "route_started", "over_20_min")
        )
        rotas_concluidas_count = sum(
            1 for b in live_separation if (b.get("route_state") or "") in ("closed", "all_delivered")
        )
        open_deliveries_total = sum(
            (b.get("total_deliveries") or 0) - (b.get("completed_deliveries") or 0)
            for b in live_separation
        )
        completed_deliveries_total = sum(
            (b.get("completed_deliveries") or 0)
            for b in live_separation
        )
        open_routes_total = rotas_paradas_count + rotas_ativas_count
        
        routes_devolucao = [r for r in all_routes_today if normalized_delivery_status(r) == "devolucao"]
        n_dev_adm, _n_done_adm = counts_devolucao_rotas_concluidas(all_routes_today)
        devolucao_items = []
        for r in routes_devolucao:
            c = client_by_id.get(r.client_id)
            emp = employee_by_id_all.get(r.employee_id)
            c_name = (getattr(c, "name", None) or getattr(c, "razao_social", None)) if c else f"Cliente #{r.client_id}"
            devolucao_items.append({
                "client_name": c_name,
                "driver_name": emp.name if emp else f"Motorista #{r.employee_id}",
            })
        devolucao_dia = {
            "count": n_dev_adm,
            "pct": pct_devolucao_sobre_rotas_concluidas(all_routes_today),
            "items_list": devolucao_items,
        }
        
        date_30d_ago = (now_br.date() - timedelta(days=30)).strftime("%Y-%m-%d")
        clientes_alto_indice = []
        try:
            devolucoes_30d = session.exec(
                select(models.Devolucao)
                .where(models.Devolucao.data_romaneio >= date_30d_ago)
                .where(models.Devolucao.data_romaneio <= today)
                .order_by(desc(models.Devolucao.data_romaneio), desc(models.Devolucao.id))
            ).all()
            client_dev_count = {}
            for d in devolucoes_30d:
                cid = d.client_id
                client_dev_count[cid] = client_dev_count.get(cid, 0) + 1
            pending_today = [
                (r.client_id, r.employee_id)
                for r in all_routes_today
                if r.client_id is not None
                and r.employee_id is not None
                and _safe_l(getattr(r, "delivery_status", None)) not in ("entregue", "devolucao")
            ]
            client_name_today = {
                c.id: (getattr(c, "name", None) or getattr(c, "razao_social", None) or f"Cliente #{c.id}")
                for c in clients
            }
            seen_pair = set()
            for cid, driver_id in pending_today:
                if (cid, driver_id) in seen_pair or client_dev_count.get(cid, 0) < 2:
                    continue
                seen_pair.add((cid, driver_id))
                emp = employee_by_id_all.get(driver_id)
                clientes_alto_indice.append({
                    "client_name": client_name_today.get(cid) or f"Cliente #{cid}",
                    "driver_name": emp.name if emp else f"Motorista #{driver_id}",
                    "count": client_dev_count[cid],
                })
            clientes_alto_indice.sort(key=lambda x: -x["count"])
            clientes_alto_indice = clientes_alto_indice[:10]
        except Exception:
            pass
        
        employees_with_route = set(all_emp_ids_with_routes)
        all_active_employees = session.exec(
            select(models.Employee).where(models.Employee.status == "active", models.Employee.mobile_access == True)
        ).all()
        four_days_ago = (datetime.now(ZoneInfo("America/Sao_Paulo")) - timedelta(days=4)).strftime("%Y-%m-%d")
        recent_route_employees = session.exec(
            select(models.Route.employee_id).where(models.Route.type == "delivery")
            .where(models.Route.date >= four_days_ago).where(models.Route.date <= today).distinct()
        ).all()
        recent_employee_ids = set()
        for r in recent_route_employees:
            if isinstance(r, (int, float)):
                parsed = _safe_i(r)
                if parsed is not None:
                    recent_employee_ids.add(parsed)
            elif hasattr(r, "employee_id"):
                parsed = _safe_i(getattr(r, "employee_id", None))
                if parsed is not None:
                    recent_employee_ids.add(parsed)
            elif isinstance(r, (list, tuple)) and len(r) > 0:
                parsed = _safe_i(r[0])
                if parsed is not None:
                    recent_employee_ids.add(parsed)
        
        employees_without_route = []
        for emp in all_active_employees:
            if emp.id not in employees_with_route and emp.id in recent_employee_ids:
                employees_without_route.append({
                    "id": emp.id,
                    "name": str(emp.name or ""),
                    "registration_id": str(getattr(emp, "registration_id", "") or ""),
                    "shift": str(getattr(emp, "work_shift", "Manhã") or "Manhã")
                })
        
        payload = {
            "success": True,
            "live_separation": live_separation,
            "employees_without_route": employees_without_route,
            "devolucao_dia": devolucao_dia,
            "alerts": {"clients_over_20min": alerts_over_20min},
            "clientes_alto_indice_devolucao": clientes_alto_indice,
            "kpi": {
                "rotas_paradas": rotas_paradas_count,
                "rotas_ativas": rotas_ativas_count,
                "rotas_concluidas": rotas_concluidas_count,
                # "Abertas" no card mobile deve representar quantidade de rotas abertas
                # (não o total de entregas pendentes).
                "abertas": open_routes_total,
                "entregas_pendentes": open_deliveries_total,
                "entregas_concluidas": completed_deliveries_total,
            },
        }
        return JSONResponse(_json_safe(payload), headers={
            "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
            "Pragma": "no-cache",
            "Expires": "0",
        })
    except Exception as e:
        logger.exception("api_list_admin_routes error: %s", e)
        return JSONResponse(
            {
                "success": False,
                "error": "Erro interno ao carregar rotas do painel mobile.",
                "detail": _safe_s(e),
            },
            status_code=500,
            headers={
                "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
                "Pragma": "no-cache",
                "Expires": "0",
            },
        )


@app.post("/api/mobile/admin/routes/{route_id}/edit")
async def api_edit_admin_route(
    route_id: int,
    payload: RouteEditPayload,
    request: Request,
    session: Session = Depends(get_session)
):
    """API para editar uma rota"""
    try:
        user_id = request.session.get("user_id")
        if not user_id:
            return JSONResponse({"error": "Não autorizado"}, status_code=401)
        
        try:
            user_id = int(str(user_id))
        except:
            return JSONResponse({"error": "ID inválido"}, status_code=400)
        
        current_emp = session.get(models.Employee, user_id)
        if not current_emp or not getattr(current_emp, "mobile_access_admin_start", False):
            return JSONResponse({"error": "Sem permissão"}, status_code=403)
        
        # Validar justificativa
        if not payload.reason or len(payload.reason.strip()) < 5:
            return JSONResponse({"error": "Justificativa obrigatória (mínimo 5 caracteres)"}, status_code=400)
        
        # Buscar rota
        route = session.get(models.Route, route_id)
        if not route:
            return JSONResponse({"error": "Rota não encontrada"}, status_code=404)
        
        # Validar colaborador
        target_emp = session.get(models.Employee, payload.employee_id)
        if not target_emp:
            return JSONResponse({"error": "Colaborador não encontrado"}, status_code=404)
        
        # Validar cliente
        client = session.get(models.Client, payload.client_id)
        if not client:
            return JSONResponse({"error": "Cliente não encontrado"}, status_code=404)
        
        # Registrar alterações
        old_emp = session.get(models.Employee, route.employee_id)
        old_client = session.get(models.Client, route.client_id)
        
        changes = []
        if route.employee_id != payload.employee_id:
            changes.append(f"Colaborador: {old_emp.name if old_emp else 'N/A'} → {target_emp.name}")
        if route.client_id != payload.client_id:
            changes.append(f"Cliente: {old_client.name if old_client else 'N/A'} → {client.name}")
        if route.tonnage != payload.tonnage:
            changes.append(f"Tonelagem: {route.tonnage} → {payload.tonnage}")
        
        # Atualizar rota
        route.employee_id = payload.employee_id
        route.client_id = payload.client_id
        route.tonnage = payload.tonnage
        session.add(route)
        
        # Log de auditoria
        log = models.Event(
            type="route_edit",
            text=f"Rota #{route_id} editada por {current_emp.name}. Alterações: {'; '.join(changes)}. Justificativa: {payload.reason}",
            category="processo",
            sector="expedicao",
            impact="medium",
            employee_id=route.employee_id,
            timestamp=datetime.now(ZoneInfo("America/Sao_Paulo"))
        )
        session.add(log)
        
        session.commit()
        return JSONResponse({"success": True, "message": "Rota editada com sucesso"})
        
    except Exception as e:
        logger.exception("Error editing route")
        return JSONResponse({"error": f"Erro interno: {str(e)}"}, status_code=500)


@app.post("/api/mobile/admin/routes/{route_id}/delete")
async def api_delete_admin_route(
    route_id: int,
    payload: RouteDeletePayload,
    request: Request,
    session: Session = Depends(get_session)
):
    """API para excluir uma rota"""
    try:
        user_id = request.session.get("user_id")
        if not user_id:
            return JSONResponse({"error": "Não autorizado"}, status_code=401)
        
        try:
            user_id = int(str(user_id))
        except:
            return JSONResponse({"error": "ID inválido"}, status_code=400)
        
        current_emp = session.get(models.Employee, user_id)
        if not current_emp or not getattr(current_emp, "mobile_access_admin_start", False):
            return JSONResponse({"error": "Sem permissão"}, status_code=403)
        
        # Validar justificativa
        if not payload.reason or len(payload.reason.strip()) < 5:
            return JSONResponse({"error": "Justificativa obrigatória (mínimo 5 caracteres)"}, status_code=400)
        
        # Buscar rota
        route = session.get(models.Route, route_id)
        if not route:
            return JSONResponse({"error": "Rota não encontrada"}, status_code=404)
        
        # Guardar informações para log
        emp = session.get(models.Employee, route.employee_id)
        client = session.get(models.Client, route.client_id)
        
        # Log de auditoria
        log = models.Event(
            type="route_delete",
            text=f"Rota #{route_id} excluída por {current_emp.name}. Colaborador: {emp.name if emp else 'N/A'}, Cliente: {client.name if client else 'N/A'}. Justificativa: {payload.reason}",
            category="processo",
            sector="expedicao",
            impact="high",
            employee_id=route.employee_id,
            timestamp=datetime.now(ZoneInfo("America/Sao_Paulo"))
        )
        session.add(log)
        
        # Excluir rota
        session.delete(route)
        session.commit()
        
        return JSONResponse({"success": True, "message": "Rota excluída com sucesso"})
        
    except Exception as e:
        logger.exception("Error deleting route")
        return JSONResponse({"error": f"Erro interno: {str(e)}"}, status_code=500)


# =============================================================================
# ROTAS: /admin/substitutions — Histórico de Substituições
# =============================================================================

def _resolve_admin_period(period: str = "all", start_date: Optional[str] = None, end_date: Optional[str] = None) -> tuple[str, datetime, datetime]:
    now_br = datetime.now(ZoneInfo("America/Sao_Paulo"))

    if period == "month":
        dt_start = now_br.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        dt_end = now_br
    elif period == "quarter":
        dt_start = (now_br - timedelta(days=90)).replace(hour=0, minute=0, second=0, microsecond=0)
        dt_end = now_br
    elif period == "year":
        dt_start = now_br.replace(month=1, day=1, hour=0, minute=0, second=0, microsecond=0)
        dt_end = now_br
    elif period == "custom" and start_date and end_date:
        try:
            dt_start = datetime.strptime(start_date, "%Y-%m-%d")
            dt_end = datetime.strptime(end_date, "%Y-%m-%d").replace(hour=23, minute=59, second=59)
        except ValueError:
            dt_start = datetime(2000, 1, 1)
            dt_end = now_br
            period = "all"
    else:
        dt_start = datetime(2000, 1, 1)
        dt_end = now_br
        period = "all"

    dt_start_naive = dt_start.replace(tzinfo=None) if getattr(dt_start, "tzinfo", None) else dt_start
    dt_end_naive = dt_end.replace(tzinfo=None) if getattr(dt_end, "tzinfo", None) else dt_end
    return period, dt_start_naive, dt_end_naive


def _build_substitutions_query(
    session: Session,
    start_dt: datetime,
    end_dt: datetime,
    reason: str = "all",
    shift: str = "all",
):
    query = (
        select(models.SubstitutionHistory)
        .where(models.SubstitutionHistory.substitution_date >= start_dt)
        .where(models.SubstitutionHistory.substitution_date <= end_dt)
    )

    if reason in {"fired", "away"}:
        query = query.where(models.SubstitutionHistory.reason == reason)

    if shift and shift != "all":
        query = query.where(models.SubstitutionHistory.shift == shift)

    return query.order_by(desc(models.SubstitutionHistory.substitution_date))


@app.get("/admin/substitutions", response_class=HTMLResponse)
async def admin_substitutions_page(
    request: Request,
    period: str = "all",
    start_date: Optional[str] = None,
    end_date: Optional[str] = None,
    reason: str = "all",
    shift: str = "all",
    session: Session = Depends(get_session),
):
    try:
        user = require_admin(request)
    except Exception:
        try:
            user = require_game_master(request, session)
        except Exception:
            return RedirectResponse(url="/login", status_code=303)

    period, dt_start, dt_end = _resolve_admin_period(period, start_date, end_date)
    substitutions = session.exec(
        _build_substitutions_query(session, dt_start, dt_end, reason=reason, shift=shift)
    ).all()

    total = len(substitutions)
    by_fired = len([sub for sub in substitutions if sub.reason == "fired"])
    by_away = len([sub for sub in substitutions if sub.reason == "away"])

    monthly_stats: Dict[str, Dict[str, int]] = {}
    for sub in substitutions:
        label = sub.substitution_date.strftime("%m/%Y")
        bucket = monthly_stats.setdefault(label, {"total": 0, "fired": 0, "away": 0})
        bucket["total"] += 1
        if sub.reason == "fired":
            bucket["fired"] += 1
        elif sub.reason == "away":
            bucket["away"] += 1

    return templates.TemplateResponse("admin_substitutions.html", {
        "request": request,
        "user": user,
        "substitutions": substitutions,
        "total": total,
        "by_fired": by_fired,
        "by_away": by_away,
        "monthly_stats": monthly_stats,
        "current_period": period,
        "current_reason": reason,
        "current_shift": shift,
        "current_start_date": start_date or "",
        "current_end_date": end_date or "",
    })


@app.get("/admin/substitutions/export")
async def admin_substitutions_export(
    request: Request,
    period: str = "all",
    start_date: Optional[str] = None,
    end_date: Optional[str] = None,
    reason: str = "all",
    shift: str = "all",
    session: Session = Depends(get_session),
):
    try:
        require_admin(request)
    except Exception:
        try:
            require_game_master(request, session)
        except Exception:
            return RedirectResponse(url="/login", status_code=303)

    period, dt_start, dt_end = _resolve_admin_period(period, start_date, end_date)
    substitutions = session.exec(
        _build_substitutions_query(session, dt_start, dt_end, reason=reason, shift=shift)
    ).all()

    output = io.StringIO()
    writer = csv.writer(output)
    writer.writerow([
        "Data",
        "Hora",
        "Colaborador anterior",
        "Matricula anterior",
        "Novo colaborador",
        "Matricula nova",
        "Motivo",
        "Turno",
        "Setor",
        "Observacoes",
    ])
    for sub in substitutions:
        writer.writerow([
            sub.substitution_date.strftime("%d/%m/%Y"),
            sub.substitution_date.strftime("%H:%M"),
            sub.original_employee_name,
            sub.original_registration_id,
            sub.new_employee_name,
            sub.new_registration_id,
            "Demissão" if sub.reason == "fired" else "Afastamento",
            sub.shift or "",
            sub.sector or "",
            sub.observations or "",
        ])

    filename = f"substituicoes_{datetime.now(ZoneInfo('America/Sao_Paulo')).strftime('%Y%m%d_%H%M%S')}.csv"
    headers = {"Content-Disposition": f'attachment; filename="{filename}"'}
    return Response(content=output.getvalue(), media_type="text/csv; charset=utf-8", headers=headers)


@app.post("/admin/substitutions/edit")
async def admin_substitutions_edit(
    request: Request,
    id: int = Form(...),
    substitution_date: str = Form(...),
    reason: str = Form(...),
    shift: Optional[str] = Form(None),
    sector: Optional[str] = Form(None),
    observations: Optional[str] = Form(None),
    session: Session = Depends(get_session),
):
    try:
        user = require_admin(request)
    except Exception:
        try:
            user = require_game_master(request, session)
        except Exception:
            return RedirectResponse(url="/login", status_code=303)

    substitution = session.get(models.SubstitutionHistory, id)
    if not substitution:
        raise HTTPException(status_code=404, detail="Substituição não encontrada")

    try:
        parsed_date = datetime.strptime(substitution_date, "%Y-%m-%d")
    except ValueError:
        raise HTTPException(status_code=400, detail="Data inválida")

    substitution.substitution_date = parsed_date
    substitution.reason = reason if reason in {"fired", "away"} else substitution.reason
    substitution.shift = (shift or "").strip() or None
    substitution.sector = (sector or "").strip() or None
    substitution.observations = (observations or "").strip() or None
    session.add(substitution)
    session.commit()

    logger.info(f"[Substitutions] Registro {id} atualizado por {format_user_label(user)}")
    return RedirectResponse(url="/admin/substitutions", status_code=303)


# =============================================================================
# ROTAS: /admin/turnover-analysis — Análise de Turnover e Rotatividade
# =============================================================================

def _compute_turnover_metrics(session: Session, start_date_dt, end_date_dt, shift_filter: str = "all"):
    """
    Calcula todas as métricas de turnover para o período informado.
    Retorna um dict com: metrics, by_shift, by_role, by_age, by_sector, by_tenure,
    monthly_trend, recent_exits, insights.
    """
    from collections import defaultdict

    now_br = datetime.now(ZoneInfo("America/Sao_Paulo"))

    # ---- 1) Buscar colaboradores que saíram (fired ou away) no período ----
    all_fired_away = session.exec(
        select(models.Employee).where(
            models.Employee.status.in_(["fired", "away"])
        )
    ).all()

    # Filtrar pelo período usando termination_date ou, se não existir, admission_date como fallback
    exits_in_period = []
    for emp in all_fired_away:
        exit_dt = emp.termination_date
        if exit_dt is None:
            # Sem data de saída: consideramos pendente mas inclui no período "all" por segurança
            exits_in_period.append(emp)
            continue
        if start_date_dt <= exit_dt <= end_date_dt:
            exits_in_period.append(emp)

    # Filtro por turno
    if shift_filter and shift_filter != "all":
        exits_in_period = [e for e in exits_in_period if e.work_shift == shift_filter]

    # ---- 2) Total de colaboradores (headcount médio) ----
    all_employees = session.exec(select(models.Employee)).all()
    total_ever = len([e for e in all_employees if e.status not in ["day_off"]])
    active_count = len([e for e in all_employees if e.status == "active"])
    avg_headcount = max(active_count + len(exits_in_period), 1)

    total_exits = len(exits_in_period)
    fired_count = len([e for e in exits_in_period if e.status == "fired"])
    away_count = len([e for e in exits_in_period if e.status == "away"])

    # Taxa de Turnover = (saídas / média do quadro) * 100
    turnover_rate = (total_exits / avg_headcount) * 100 if avg_headcount > 0 else 0.0

    # ---- 3) Tempo médio de permanência (meses) ----
    tenure_months_list = []
    for emp in exits_in_period:
        if emp.admission_date and emp.termination_date:
            delta = emp.termination_date - emp.admission_date
            months = delta.days / 30.44
            tenure_months_list.append(months)
    avg_tenure_months = sum(tenure_months_list) / len(tenure_months_list) if tenure_months_list else 0.0

    # ---- 4) Tempo médio de substituição (dias) ----
    sub_histories = session.exec(
        select(models.SubstitutionHistory)
        .where(models.SubstitutionHistory.substitution_date >= start_date_dt)
        .where(models.SubstitutionHistory.substitution_date <= end_date_dt)
    ).all()

    replacement_days_list = []
    for sh in sub_histories:
        original_emp = session.get(models.Employee, sh.original_employee_id)
        if original_emp and original_emp.termination_date and sh.substitution_date:
            delta = sh.substitution_date - original_emp.termination_date
            if delta.days >= 0:
                replacement_days_list.append(delta.days)
    avg_replacement_days = sum(replacement_days_list) / len(replacement_days_list) if replacement_days_list else 0.0

    # ---- 5) Agrupamentos ----

    def safe_rate(exits, total):
        if total == 0:
            return 0.0
        return (exits / total) * 100

    # Por turno
    by_shift: dict = defaultdict(lambda: {"exits": 0, "total": 0, "rate": 0.0})
    for sh_name in ["Manhã", "Tarde", "Noite"]:
        shift_total = len([e for e in all_employees if e.work_shift == sh_name and e.status != "day_off"])
        shift_exits = len([e for e in exits_in_period if e.work_shift == sh_name])
        by_shift[sh_name] = {"exits": shift_exits, "total": shift_total, "rate": safe_rate(shift_exits, shift_total)}

    # Por função
    by_role: dict = defaultdict(lambda: {"exits": 0, "total": 0, "rate": 0.0})
    for emp in all_employees:
        role = (emp.role or "Não Informado").strip()
        by_role[role]["total"] = by_role[role].get("total", 0) + 1
    for emp in exits_in_period:
        role = (emp.role or "Não Informado").strip()
        by_role[role]["exits"] = by_role[role].get("exits", 0) + 1
    for role in by_role:
        by_role[role]["rate"] = safe_rate(by_role[role].get("exits", 0), by_role[role].get("total", 0))

    # Por faixa etária
    def age_range(birthday):
        if not birthday:
            return "Não informado"
        age = (now_br.replace(tzinfo=None) - birthday).days // 365
        if age < 25:
            return "Menos de 25"
        elif age < 35:
            return "25-34"
        elif age < 45:
            return "35-44"
        elif age < 55:
            return "45-54"
        else:
            return "55+"

    by_age: dict = defaultdict(lambda: {"exits": 0, "total": 0, "rate": 0.0})
    for emp in all_employees:
        ar = age_range(emp.birthday)
        by_age[ar]["total"] = by_age[ar].get("total", 0) + 1
    for emp in exits_in_period:
        ar = age_range(emp.birthday)
        by_age[ar]["exits"] = by_age[ar].get("exits", 0) + 1
    for ar in by_age:
        by_age[ar]["rate"] = safe_rate(by_age[ar].get("exits", 0), by_age[ar].get("total", 0))

    # Por setor/centro de custo
    by_sector: dict = defaultdict(lambda: {"exits": 0, "total": 0, "rate": 0.0})
    for emp in all_employees:
        sector = (emp.cost_center or "Não Informado").strip()
        by_sector[sector]["total"] = by_sector[sector].get("total", 0) + 1
    for emp in exits_in_period:
        sector = (emp.cost_center or "Não Informado").strip()
        by_sector[sector]["exits"] = by_sector[sector].get("exits", 0) + 1
    for sector in by_sector:
        by_sector[sector]["rate"] = safe_rate(by_sector[sector].get("exits", 0), by_sector[sector].get("total", 0))

    # Por tempo de casa
    def tenure_bucket(admission_date, termination_date):
        if not admission_date:
            return "Não informado"
        end = termination_date or now_br.replace(tzinfo=None)
        months = (end - admission_date).days / 30.44
        if months < 6:
            return "0-6 meses"
        elif months < 12:
            return "6-12 meses"
        elif months < 24:
            return "1-2 anos"
        elif months < 60:
            return "2-5 anos"
        elif months < 120:
            return "5-10 anos"
        else:
            return "10+ anos"

    by_tenure: dict = defaultdict(lambda: {"exits": 0, "total": 0, "rate": 0.0})
    for emp in all_employees:
        bucket = tenure_bucket(emp.admission_date, emp.termination_date)
        by_tenure[bucket]["total"] = by_tenure[bucket].get("total", 0) + 1
    for emp in exits_in_period:
        bucket = tenure_bucket(emp.admission_date, emp.termination_date)
        by_tenure[bucket]["exits"] = by_tenure[bucket].get("exits", 0) + 1
    for bucket in by_tenure:
        by_tenure[bucket]["rate"] = safe_rate(by_tenure[bucket].get("exits", 0), by_tenure[bucket].get("total", 0))

    # ---- 6) Evolução mensal ----
    monthly_trend: dict = {}
    # Iterar mês a mês no período
    cur = start_date_dt.replace(day=1)
    while cur <= end_date_dt:
        month_end = (cur.replace(day=28) + timedelta(days=4)).replace(day=1) - timedelta(days=1)
        month_end = min(month_end, end_date_dt)
        label = cur.strftime("%b/%y")
        month_exits = [e for e in exits_in_period if e.termination_date and cur <= e.termination_date <= month_end]
        month_fired = len([e for e in month_exits if e.status == "fired"])
        month_away = len([e for e in month_exits if e.status == "away"])
        month_total_exits = len(month_exits)
        monthly_trend[label] = {
            "exits": month_total_exits,
            "fired": month_fired,
            "away": month_away,
            "rate": safe_rate(month_total_exits, avg_headcount),
        }
        # Avançar para próximo mês
        cur = (cur.replace(day=28) + timedelta(days=4)).replace(day=1)

    # ---- 7) Últimas saídas (enriquecidas para tabela) ----
    recent_exits_data = []
    exits_sorted = sorted(
        exits_in_period,
        key=lambda e: e.termination_date or datetime(2000, 1, 1),
        reverse=True
    )
    for emp in exits_sorted:
        # Tempo de permanência em meses
        tenure_m = 0
        if emp.admission_date:
            end_ref = emp.termination_date or now_br.replace(tzinfo=None)
            tenure_m = int((end_ref - emp.admission_date).days / 30.44)

        # Calcular idade
        age_val = None
        if emp.birthday:
            age_val = (now_br.replace(tzinfo=None) - emp.birthday).days // 365

        # Data de saída formatada
        if emp.termination_date:
            exit_date_str = emp.termination_date.strftime("%d/%m/%Y")
            exit_date_pending = False
        else:
            exit_date_str = "—"
            exit_date_pending = True

        recent_exits_data.append({
            "id": emp.id,
            "name": emp.name,
            "registration_id": emp.registration_id,
            "role": emp.role or "—",
            "work_shift": emp.work_shift or "—",
            "status": emp.status,
            "age": age_val,
            "tenure_months": tenure_m,
            "exit_date": exit_date_str,
            "exit_date_pending": exit_date_pending,
            "cost_center": emp.cost_center or "—",
        })

    # ---- 8) Insights automáticos ----
    insights = []
    if turnover_rate > 20:
        insights.append({"type": "danger", "message": f"Taxa de turnover de {turnover_rate:.1f}% está muito acima do ideal (< 10%). Ação imediata recomendada."})
    elif turnover_rate > 10:
        insights.append({"type": "warning", "message": f"Taxa de turnover de {turnover_rate:.1f}% está acima do ideal. Monitore de perto."})
    else:
        insights.append({"type": "info", "message": f"Taxa de turnover de {turnover_rate:.1f}% dentro do esperado (< 10%)."})

    if avg_replacement_days > 30:
        insights.append({"type": "warning", "message": f"Tempo médio de substituição de {avg_replacement_days:.0f} dias é alto. Revise o processo de recrutamento."})

    # Turno com maior turnover
    worst_shift = max(by_shift.items(), key=lambda x: x[1]["rate"], default=(None, None))
    if worst_shift[0] and worst_shift[1]["rate"] > 10:
        insights.append({"type": "warning", "message": f"Turno {worst_shift[0]} tem o maior turnover: {worst_shift[1]['rate']:.1f}%."})

    metrics = {
        "turnover_rate": turnover_rate,
        "total_exits": total_exits,
        "fired_count": fired_count,
        "away_count": away_count,
        "avg_headcount": avg_headcount,
        "avg_replacement_days": avg_replacement_days,
        "avg_tenure_months": avg_tenure_months,
    }

    return {
        "metrics": metrics,
        "by_shift": dict(by_shift),
        "by_role": dict(by_role),
        "by_age": dict(by_age),
        "by_sector": dict(by_sector),
        "by_tenure": dict(by_tenure),
        "monthly_trend": monthly_trend,
        "recent_exits": recent_exits_data,
        "insights": insights,
    }


@app.get("/admin/turnover-analysis", response_class=HTMLResponse)
async def admin_turnover_analysis_page(
    request: Request,
    period: str = "all",
    start_date: Optional[str] = None,
    end_date: Optional[str] = None,
    shift: str = "all",
    session: Session = Depends(get_session)
):
    """Página de Análise de Turnover e Rotatividade."""
    try:
        user = require_admin(request)
    except Exception:
        try:
            user = require_game_master(request, session)
        except Exception:
            return RedirectResponse(url="/login", status_code=303)

    now_br = datetime.now(ZoneInfo("America/Sao_Paulo"))

    # ---- Resolver período ----
    if period == "month":
        dt_start = now_br.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        dt_end = now_br
    elif period == "quarter":
        dt_start = (now_br - timedelta(days=90)).replace(hour=0, minute=0, second=0, microsecond=0)
        dt_end = now_br
    elif period == "semester":
        dt_start = (now_br - timedelta(days=180)).replace(hour=0, minute=0, second=0, microsecond=0)
        dt_end = now_br
    elif period == "year":
        dt_start = now_br.replace(month=1, day=1, hour=0, minute=0, second=0, microsecond=0)
        dt_end = now_br
    elif period == "custom" and start_date and end_date:
        try:
            dt_start = datetime.strptime(start_date, "%Y-%m-%d")
            dt_end = datetime.strptime(end_date, "%Y-%m-%d").replace(hour=23, minute=59, second=59)
        except ValueError:
            dt_start = datetime(2000, 1, 1)
            dt_end = now_br
    else:
        # "all" — desde o início
        dt_start = datetime(2000, 1, 1)
        dt_end = now_br
        period = "all"

    # Remover tzinfo para comparação com campos naive do banco
    dt_start_naive = dt_start.replace(tzinfo=None) if hasattr(dt_start, "tzinfo") else dt_start
    dt_end_naive = dt_end.replace(tzinfo=None) if hasattr(dt_end, "tzinfo") else dt_end

    data = _compute_turnover_metrics(session, dt_start_naive, dt_end_naive, shift_filter=shift)

    return templates.TemplateResponse("admin_turnover_analysis.html", {
        "request": request,
        "user": user,
        "current_period": period,
        "current_start_date": start_date or "",
        "current_end_date": end_date or "",
        "current_shift": shift,
        "gemini_available": gemini_client is not None,
        **data,
    })


@app.post("/admin/turnover-analysis/ai-report", response_class=JSONResponse)
async def admin_turnover_ai_report(request: Request, session: Session = Depends(get_session)):
    """Gera parecer executivo de turnover usando IA (Gemini)."""
    try:
        user = require_admin(request)
    except Exception:
        try:
            user = require_game_master(request, session)
        except Exception:
            return JSONResponse({"error": "Acesso negado"}, status_code=403)

    if not gemini_client:
        return JSONResponse({"error": "IA não configurada. Adicione GEMINI_API_KEY."}, status_code=503)

    try:
        body = await request.json()
    except Exception:
        body = {}

    period = body.get("period", "all")
    start_date = body.get("start_date", "")
    end_date = body.get("end_date", "")

    now_br = datetime.now(ZoneInfo("America/Sao_Paulo"))

    if period == "custom" and start_date and end_date:
        try:
            dt_start = datetime.strptime(start_date, "%Y-%m-%d")
            dt_end = datetime.strptime(end_date, "%Y-%m-%d").replace(hour=23, minute=59, second=59)
        except ValueError:
            dt_start = datetime(2000, 1, 1)
            dt_end = now_br
    elif period == "month":
        dt_start = now_br.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        dt_end = now_br
    elif period == "quarter":
        dt_start = now_br - timedelta(days=90)
        dt_end = now_br
    elif period == "semester":
        dt_start = now_br - timedelta(days=180)
        dt_end = now_br
    elif period == "year":
        dt_start = now_br.replace(month=1, day=1, hour=0, minute=0, second=0, microsecond=0)
        dt_end = now_br
    else:
        dt_start = datetime(2000, 1, 1)
        dt_end = now_br

    dt_start_naive = dt_start.replace(tzinfo=None) if hasattr(dt_start, "tzinfo") else dt_start
    dt_end_naive = dt_end.replace(tzinfo=None) if hasattr(dt_end, "tzinfo") else dt_end

    data = _compute_turnover_metrics(session, dt_start_naive, dt_end_naive)
    metrics = data["metrics"]

    input_json = {
        "periodo": period,
        "total_saidas": metrics["total_exits"],
        "demissoes": metrics["fired_count"],
        "afastamentos": metrics["away_count"],
        "taxa_turnover_pct": round(metrics["turnover_rate"], 2),
        "media_quadro": metrics["avg_headcount"],
        "tempo_medio_substituicao_dias": round(metrics["avg_replacement_days"], 1),
        "permanencia_media_meses": round(metrics["avg_tenure_months"], 1),
        "por_turno": {k: {"saidas": v["exits"], "total": v["total"], "taxa_pct": round(v["rate"], 1)} for k, v in data["by_shift"].items()},
        "por_funcao_top5": dict(list(sorted(data["by_role"].items(), key=lambda x: x[1]["exits"], reverse=True))[:5]),
        "insights_automaticos": [i["message"] for i in data["insights"]],
    }

    prompt = f"""Você é um especialista em RH e gestão de pessoas. 
Analise os dados de turnover da empresa e gere um parecer executivo em português (pt-BR),
com linguagem clara, profissional e objetiva.

DADOS DE ENTRADA (JSON):
{__import__('json').dumps(input_json, ensure_ascii=False, indent=2)}

O parecer deve conter:
1. Resumo executivo (2-3 linhas com a situação geral)
2. Análise dos principais indicadores
3. Pontos de atenção críticos
4. Recomendações práticas (máximo 4 recomendações)
5. Conclusão

Use linguagem direta. Evite jargões desnecessários. Todo o texto em pt-BR."""

    try:
        response = gemini_client.models.generate_content(
            model="gemini-2.0-flash",
            contents=prompt,
        )
        report_text = response.text or ""
        logger.info(f"[TurnoverAI] Parecer gerado com sucesso. Período: {period}")
        return JSONResponse({"report": report_text, "input": input_json})
    except Exception as e:
        logger.exception("Erro ao gerar parecer de turnover via Gemini")
        return JSONResponse({"error": f"Falha na IA: {str(e)}"}, status_code=500)


@app.post("/admin/turnover-analysis/update-dates", response_class=JSONResponse)
async def admin_turnover_update_dates(request: Request, session: Session = Depends(get_session)):
    """Salva datas de saída (termination_date) para colaboradores pendentes."""
    try:
        user = require_admin(request)
    except Exception:
        try:
            user = require_game_master(request, session)
        except Exception:
            return JSONResponse({"error": "Acesso negado"}, status_code=403)

    try:
        form = await request.form()
    except Exception:
        return JSONResponse({"error": "Falha ao ler formulário"}, status_code=400)

    updated = 0
    errors = []
    for key, value in form.items():
        if not key.startswith("date_"):
            continue
        registration_id = key[5:]  # remove "date_"
        date_str = str(value).strip()
        if not date_str:
            continue
        try:
            new_date = datetime.strptime(date_str, "%Y-%m-%d")
        except ValueError:
            errors.append(f"Data inválida para {registration_id}: {date_str}")
            continue

        emp = session.exec(
            select(models.Employee).where(models.Employee.registration_id == registration_id)
        ).first()
        if not emp:
            errors.append(f"Colaborador não encontrado: {registration_id}")
            continue

        emp.termination_date = new_date
        session.add(emp)
        updated += 1

    if updated > 0:
        session.commit()
        logger.info(f"[TurnoverDates] {updated} datas de saída atualizadas por {user if isinstance(user, str) else getattr(user, 'username', 'admin')}")

    if errors:
        return JSONResponse({"success": updated > 0, "updated": updated, "errors": errors})
    return JSONResponse({"success": True, "updated": updated})


@app.post("/admin/turnover-analysis/fix-dates", response_class=JSONResponse)
async def admin_turnover_fix_dates(request: Request, session: Session = Depends(get_session)):
    """
    Corrige automaticamente datas de saída: busca no histórico de substituições
    a data do evento de demissão/afastamento e preenche termination_date.
    """
    try:
        user = require_admin(request)
    except Exception:
        try:
            user = require_game_master(request, session)
        except Exception:
            return JSONResponse({"error": "Acesso negado"}, status_code=403)

    # Buscar colaboradores sem termination_date
    pending_emps = session.exec(
        select(models.Employee).where(
            models.Employee.status.in_(["fired", "away"]),
            models.Employee.termination_date == None
        )
    ).all()

    fixed = 0
    for emp in pending_emps:
        # Tentar encontrar no SubstitutionHistory
        sub = session.exec(
            select(models.SubstitutionHistory)
            .where(models.SubstitutionHistory.original_employee_id == emp.id)
            .order_by(models.SubstitutionHistory.substitution_date)
        ).first()

        if sub and sub.substitution_date:
            emp.termination_date = sub.substitution_date
            session.add(emp)
            fixed += 1

    if fixed > 0:
        session.commit()
        logger.info(f"[TurnoverFixDates] {fixed} datas corrigidas automaticamente")

    return JSONResponse({"success": True, "fixed": fixed})
